#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define a structure for records
typedef struct {
    int key;
    long offset;
} record;

void allocate_memory(int num_records, int min_key, int max_key, long min_offset, long max_offset) {
    // Allocate memory for the arrays of offsets and keys
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));

    // Initialize the arrays with random values within the given range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Allocate memory for the array of records
    record *records = malloc(num_records * sizeof(record));

    // Initialize each record with a random value within the given range and a pointer to the corresponding key and offset
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Free the memory allocated for the arrays of offsets and keys
    free(offsets);
    free(keys);
}
```
This function takes in four parameters: `num_records`, `min_key`, `max_key`, and `min_offset`, `max_offset`. It allocates memory for two arrays: one for `long` offsets and one for `int` keys. It then initializes these arrays with random values within the given range using the `rand()` function from the `<stdlib.h>` header file.

Next, it allocates memory for an array of `record` structures, where each record contains a single `int` value and two pointers: one to the corresponding key in the `int` keys array and one to the nearest matching offset in the `long` offsets array. It initializes each record with a random value within the given range and sets the pointers to the corresponding values in the arrays of offsets and keys.

