#define OPTION_COUNT 4
#define OPTION_OUTPUT 5

// define structure to hold command line options and their values
struct option_t {
    int opt;
    char *arg;
};

// function to parse command line arguments and handle options
void parse_args(int argc, char **argv) {
    // initialize variables for parsing command line arguments
    int c;
    char *optstring = "hvmco:";
    struct option_t options[] = {
        {OPTION_HELP, NULL},
        {OPTION_VERSION, NULL},
        {OPTION_MANPAGE, NULL},
        {OPTION_COUNT, NULL},
        {OPTION_OUTPUT, NULL}
    };

    // loop through command line arguments and handle options
    while ((c = getopt_long(argc, argv, optstring, options, NULL)) != -1) {
        switch (c) {
            case OPTION_HELP:
                printf("Usage: %s [options] input_file\n", argv[0]);
                printf("\n");
                printf("Options:\n");
                printf("  -h, --help                    Display this usage information.\n");
                printf("  -v, --version                 Print the version number of the program.\n");
                printf("  -m, --manpage                 Display a detailed manpage.\n");
                printf("  -c, --count <word>            Count the occurrences of a specific word provided via stdin.\n");
                printf("  -o, --output <file>           Specify an output file to write the results to instead of stdout.\n");
                break;
            case OPTION_VERSION:
                printf("%s version %d.%d\n", argv[0], VERSION_MAJOR, VERSION_MINOR);
                break;
            case OPTION_MANPAGE:
                // display detailed manpage here
                break;
            case OPTION_COUNT:
                // handle counting of specific word provided via stdin
                break;
            case OPTION_OUTPUT:
                // handle output file specified via command line option
                break;
        }
    }
}

// function to read input file and count number of lines and words
void process_file(char *filename) {
    // open input file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }

    // initialize variables for counting lines and words
    int line_count = 0;
    int word_count = 0;

    // read input file line by line and count number of lines and words
    char buffer[BUFSIZ];
    while (read(fd, buffer, BUFSIZ) > 0) {
        line_count++;
        char *token = strtok(buffer, " ");
        while (token != NULL) {
            word_count++;
            token = strtok(NULL, " ");
        }
    }

    // close input file
    close(fd);

    // print number of lines and words to stdout or output file specified via command line option
    if (strcmp(options[OPTION_OUTPUT].arg, "-") == 0) {
        printf("Number of lines: %d\n", line_count);
        printf("Number of words: %d\n", word_count);
    } else {
        FILE *output = fopen(options[OPTION_OUTPUT].arg, "w");
        if (output == NULL) {
            perror("Error opening output file");
            exit(EXIT_FAILURE);
        }
        fprintf(output, "Number of lines: %d\n", line_count);
        fprintf(output, "Number of words: %d\n", word_count);
        fclose(output);
    }
}

// function to handle multiple input files simultaneously if needed
void process_files(char **filenames) {
    // initialize variables for handling multiple input files
    int num_files = 0;
    pthread_t *threads = NULL;
    void **thread_args = NULL;

    // loop through input files and create threads to handle each file
    while (filenames[num_files] != NULL) {
        // allocate memory for thread arguments
        thread_args = realloc(thread_args, sizeof(void *) * (num_files + 1));
        if (thread_args == NULL) {
            perror("Error allocating memory for thread arguments");
            exit(EXIT_FAILURE);
        }

        // allocate memory for threads
        threads = realloc(threads, sizeof(pthread_t) * (num_files + 1));
        if (threads == NULL) {
            perror("Error allocating memory for threads");
            exit(EXIT_FAILURE);
        }

        // create thread to handle input file
        thread_args[num_files] = filenames[num_files];
        pthread_create(&threads[num_files], NULL, process_file, thread_args[num_files]);

        num_files++;
    }

    // join threads to wait for completion of each file
    int i;
    for (i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main(int argc, char **argv) {
    // parse command line arguments and handle options
    parse_args(argc, argv);

    // handle multiple input files if needed
    process_files(argv + optind);

    return 0;
}
