#include <stdio.h>
#include <stdlib.h>

// Function to read a list of integers from standard input
int* read_integers(int* num_ints) {
  // Allocate memory for the array
  *num_ints = 0;
  int* arr = NULL;

  // Read each integer from standard input and add it to the array
  while (1) {
    int input;
    if (scanf("%d", &input) != 1) {
      break;
    }
    *num_ints += 1;
    arr = realloc(arr, (*num_ints) * sizeof(int));
    arr[*num_ints - 1] = input;
  }

  // If no integers were provided, print an error message and exit
  if (*num_ints == 0) {
    printf("No integers provided.\n");
    return NULL;
  }

  // Return the array of integers
  return arr;
}

// Function to find the largest integer in an array
int largest(int* arr, int num_ints) {
  int largest = INT_MIN;
  for (int i = 0; i < num_ints; i++) {
    if (arr[i] > largest) {
      largest = arr[i];
    }
  }
  return largest;
}

// Function to calculate the average of an array of integers
double average(int* arr, int num_ints) {
  double sum = 0.0;
  for (int i = 0; i < num_ints; i++) {
    sum += arr[i];
  }
  return sum / num_ints;
}

// Main function to read integers, find the largest and calculate the average
int main() {
  int* arr = NULL;
  int num_ints = 0;

  // Read the list of integers from standard input
  arr = read_integers(&num_ints);

  // If no integers were provided, print an error message and exit
  if (arr == NULL) {
    return 1;
  }

  // Find the largest integer in the array
  int largest = largest(arr, num_ints);

  // Calculate the average of all integers in the array
  double avg = average(arr, num_ints);

  // Print the results
  printf("Largest integer: %d\n", largest);
  printf("Average: %.2f\n", avg);

  // Free the memory allocated for the array
  free(arr);

  return 0;
}
```
This code uses a helper function `read_integers` to read a list of integers from standard input and store them in an array. The `largest` function is used to find the largest integer in the array, and the `average` function is used to calculate the average of all integers in the array. The `main` function reads the list of integers using `read_integers`, finds the largest integer using `largest`, calculates the average using `average`, and prints the results. The program gracefully handles invalid input by checking for a null pointer returned by `read_integers`.']

