// Define the structure for holding the token information
typedef struct {
  char *access_token;
  int expires_in;
  char *token_type;
  char *refresh_token;
} TokenInfo;

// Define the function to verify the token
bool verifyToken(const char *json) {
  // Parse the JSON object and extract the required fields
  json_object *root = json_tokener_parse(json);
  json_object *access_token = json_object_object_get(root, "access_token");
  json_object *expires_in = json_object_object_get(root, "expires_in");
  json_object *token_type = json_object_object_get(root, "token_type");
  json_object *refresh_token = json_object_object_get(root, "refresh_token");

  // Check if all required fields are present and have the correct type
  if (!access_token || !expires_in || !token_type) {
    return false;
  }

  // Check if the token is valid by verifying its expiration time
  int expires = json_object_get_int(expires_in);
  if (expires <= 0) {
    return false;
  }

  // Check if the token type is supported
  const char *token_type_str = json_object_get_string(token_type);
  if (!strcmp(token_type_str, "Bearer")) {
    return false;
  }

  // If a refresh token is present, check its validity as well
  if (refresh_token) {
    json_object *refresh_expires = json_object_object_get(refresh_token, "expires");
    int refresh_expires_int = json_object_get_int(refresh_expires);
    if (refresh_expires_int <= 0) {
      return false;
    }
  }

  // If all checks passed, the token is valid
  return true;
}

// Define the function to encrypt the access token using DES
void encryptToken(const char *token, const char *key, int mode, int type) {
  // Create a new EVP_CIPHER structure for the chosen cipher
  EVP_CIPHER *cipher = NULL;
  if (!strcmp(type, "DES")) {
    cipher = EVP_des_cbc();
  } else if (!strcmp(type, "3DES")) {
    cipher = EVP_des_ede_cbc();
  } else if (!strcmp(mode, "EDE3")) {
    cipher = EVP_des_ede3_cbc();
  } else if (!strcmp(mode, "CFB")) {
    cipher = EVP_des_cfb();
  } else {
    // If the mode or type is not supported, return an error
    printf("Error: Unsupported cipher mode or type\n");
    return;
  }

  // Create a new DES key from the given key string
  DES_cblock key_block;
  DES_key_schedule schedule;
  DES_set_key_unchecked(&key_block, &schedule);

  // Encrypt the access token using the chosen cipher and key
  int len = strlen(token);
  unsigned char *encrypted = (unsigned char *)malloc(len + 1);
  EVP_EncryptUpdate(cipher, encrypted, &len, (unsigned char *)token, len);

  // Print the encrypted access token
  printf("Encrypted access token: %s\n", encrypted);

  // Free the allocated memory and return
  free(encrypted);
}

// Define the function to decrypt the access token using DES
void decryptToken(const char *token, const char *key, int mode, int type) {
  // Create a new EVP_CIPHER structure for the chosen cipher
  EVP_CIPHER *cipher = NULL;
  if (!strcmp(type, "DES")) {
    cipher = EVP_des_cbc();
  } else if (!strcmp(type, "3DES")) {
    cipher = EVP_des_ede_cbc();
  } else if (!strcmp(mode, "EDE3")) {
    cipher = EVP_des_ede3_cbc();
  } else if (!strcmp(mode, "CFB")) {
    cipher = EVP_des_cfb();
  } else {
    // If the mode or type is not supported, return an error
    printf("Error: Unsupported cipher mode or type\n");
    return;
  }

  // Create a new DES key from the given key string
  DES_cblock key_block;
  DES_key_schedule schedule;
  DES_set_key_unchecked(&key_block, &schedule);

  // Decrypt the access token using the chosen cipher and key
  int len = strlen(token);
  unsigned char *decrypted = (unsigned char *)malloc(len + 1);
  EVP_DecryptUpdate(cipher, decrypted, &len, (unsigned char *)token, len);

  // Print the decrypted access token
  printf("Decrypted access token: %s\n", decrypted);

  // Free the allocated memory and return
  free(decrypted);
}
