// Structure to hold information about a hash function or cipher
typedef struct {
    const char* name;
    EVP_MD* (*func)(void);
    int param1;
    int param2;
} HashCipherInfo;

// Function to return a dynamic list of available cryptographic hash functions and block ciphers
HashCipherInfo** getAvailableHashCiphers(void) {
    // Get the number of available hash functions and block ciphers
    int num_hashes = EVP_get_digest_type_nids();
    int num_ciphers = EVP_get_cipher_nids();

    // Allocate memory for the list of hash functions and block ciphers
    HashCipherInfo** list = malloc(sizeof(HashCipherInfo*) * (num_hashes + num_ciphers));
    if (!list) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize the hash functions and block ciphers
    int i = 0;
    for (i = 0; i < num_hashes; ++i) {
        const EVP_MD* md = EVP_get_digestbynid(EVP_get_digest_type_nids()[i]);
        if (!md) {
            continue;
        }
        list[i] = malloc(sizeof(HashCipherInfo));
        if (!list[i]) {
            printf("Error: Memory allocation failed\n");
            return NULL;
        }
        list[i]->name = md->md_type;
        list[i]->func = EVP_get_digestbyname;
        list[i]->param1 = 0;
        list[i]->param2 = 0;
    }
    for (i = 0; i < num_ciphers; ++i) {
        const EVP_CIPHER* cipher = EVP_get_cipherbynid(EVP_get_cipher_nids()[i]);
        if (!cipher) {
            continue;
        }
        list[num_hashes + i] = malloc(sizeof(HashCipherInfo));
        if (!list[num_hashes + i]) {
            printf("Error: Memory allocation failed\n");
            return NULL;
        }
        list[num_hashes + i]->name = cipher->cipher_type;
        list[num_hashes + i]->func = EVP_get_cipherbyname;
        list[num_hashes + i]->param1 = 0;
        list[num_hashes + i]->param2 = 0;
    }

    // Log the availability checks and initialization errors
    for (i = 0; i < num_hashes + num_ciphers; ++i) {
        if (!list[i]) {
            printf("Error: Initialization failed for %s\n", EVP_get_digestbynid(EVP_get_digest_type_nids()[i])->md_type);
        } else {
            printf("Available hash/cipher: %s\n", list[i]->name);
        }
    }

    return list;
}
