#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for the thread pool
typedef struct {
    int num_threads; // Number of worker threads in the pool
    int max_queue_size; // Maximum size of the task queue
    sem_t *task_queue; // Semaphore for the task queue
    pthread_mutex_t *lock; // Mutex for synchronizing access to the task queue
} thread_pool_t;

// Define the function that will be executed by each worker thread
void* worker(void* arg) {
    thread_pool_t* pool = (thread_pool_t*)arg;
    while (1) {
        // Wait for a task to become available in the queue
        sem_wait(pool->task_queue);
        // Acquire the lock to access the task queue
        pthread_mutex_lock(pool->lock);
        // Get the next task from the queue
        void* task = pool->task_queue;
        // Release the lock and continue executing the task
        pthread_mutex_unlock(pool->lock);
        // Execute the task
        (*(void(*)())task)();
    }
}

// Define the function to add a new task to the queue
int add_task(thread_pool_t* pool, void(*task)()) {
    // Acquire the lock to access the task queue
    pthread_mutex_lock(pool->lock);
    // Add the task to the end of the queue
    sem_post(pool->task_queue);
    // Release the lock and return
    pthread_mutex_unlock(pool->lock);
}

// Define the function to remove a task from the queue
int remove_task(thread_pool_t* pool, void(*task)()) {
    // Acquire the lock to access the task queue
    pthread_mutex_lock(pool->lock);
    // Remove the first task from the queue
    sem_wait(pool->task_queue);
    // Release the lock and return
    pthread_mutex_unlock(pool->lock);
}

// Define the function to start the thread pool
int start_pool(thread_pool_t* pool) {
    // Create a new thread for each worker thread in the pool
    for (int i = 0; i < pool->num_threads; i++) {
        pthread_create(&pool->threads[i], NULL, worker, pool);
    }
}

// Define the function to stop the thread pool
int stop_pool(thread_pool_t* pool) {
    // Signal all threads to exit
    for (int i = 0; i < pool->num_threads; i++) {
        pthread_cancel(&pool->threads[i]);
    }
}
