void insert_unique(std::vector<std::unique_ptr<int>>& vec, int val, int index) {
    if (index >= 0 && index < vec.size()) {
        // Insert the value at the specified index
        vec[index] = std::make_unique<int>(val);
    } else {
        // Append the value to the end of the vector
        vec.push_back(std::make_unique<int>(val));
    }

    // Ensure that no two adjacent elements point to the same integer value
    for (int i = 0; i < vec.size() - 1; ++i) {
        if (*vec[i] == *vec[i + 1]) {
            vec[i].reset();
        }
    }
}
