namespace MatrixMultiplication {
    class Multiplier {
        private:
            int m_, n_, k_;
            std::vector<double> a_, b_, c_;

        public:
            Multiplier(int m, int n, int k) : m_(m), n_(n), k_(k) {
                a_.resize(m * k);
                b_.resize(k * n);
                c_.resize(m * n);
            }

            ~Multiplier() {}

            void multiply(const std::vector<double>& a, const std::vector<double>& b) {
                if (a.size() != m_ || b.size() != n_) {
                    throw std::invalid_argument("Matrix dimensions do not match");
                }

                cblas_dgemm(CblasRowMajor, CblasNoTrans, CblasNoTrans, m_, n_, k_, 1.0, a_.data(), m_, b_.data(), k_, 0.0, c_.data(), m_);
            }
    };
}
```
