function manageStream(stream) {
  const graph = new Graph();
  let paused = false;

  stream.on('data', data => {
    if (paused) {
      return;
    }

    // Add a random number of vertices and edges to the graph
    for (let i = 0; i < Math.floor(Math.random() * 10); i++) {
      const vertex = new Vertex();
      graph.addVertex(vertex);

      for (let j = 0; j < Math.floor(Math.random() * 10); j++) {
        const edge = new Edge(vertex, graph.getRandomVertex());
        graph.addEdge(edge);
      }
    }

    // Set random properties on the vertices and edges using standard library functions
    for (const vertex of graph.vertices) {
      vertex.setProperty('name', Math.random().toString(36).substring(2));
    }

    for (const edge of graph.edges) {
      edge.setProperty('weight', Math.random() * 10);
    }
  });

  stream.on('pause', () => {
    paused = true;
  });

  stream.on('resume', () => {
    paused = false;
  });
}
