function copyBytes(dataChunks, byteCount) {
  // Create a new buffer to store the copied data
  const copiedData = Buffer.allocUnsafe(byteCount);

  // Keep track of the number of bytes copied so far
  let bytesCopied = 0;

  // Loop through each chunk of data and copy the specified number of bytes
  for (const chunk of dataChunks) {
    const chunkSize = Math.min(chunk.length, byteCount - bytesCopied);
    chunk.copy(copiedData, bytesCopied, 0, chunkSize);
    bytesCopied += chunkSize;
  }

  // Return the copied data in a new buffer
  return copiedData;
}
```
