import java.util.*;

public class SessionCounter {
    public static void main(String[] args) {
        List<LogEntry> logs = new ArrayList<>();
        // populate logs with data from a file or other source

        Map<Long, UserSession> sessionsByUserId = new HashMap<>();
        long totalSessions = 0;
        double totalSessionLength = 0.0;

        for (LogEntry log : logs) {
            long userId = log.getUserId();
            long timestamp = log.getTimestamp();

            UserSession session = sessionsByUserId.get(userId);
            if (session == null) {
                session = new UserSession();
                sessionsByUserId.put(userId, session);
            }

            session.addLogEntry(log);
            totalSessions++;
            totalSessionLength += log.getDuration();
        }

        System.out.println("Unique Sessions: " + sessionsByUserId.size());
        System.out.println("Average Session Length: " + (totalSessionLength / totalSessions));
    }
}

class UserSession {
    private List<LogEntry> logEntries = new ArrayList<>();

    public void addLogEntry(LogEntry log) {
        logEntries.add(log);
    }

    public long getDuration() {
        return logEntries.get(logEntries.size() - 1).getTimestamp() - logEntries.get(0).getTimestamp();
    }
}

class LogEntry {
    private long userId;
    private long timestamp;

    public LogEntry(long userId, long timestamp) {
        this.userId = userId;
        this.timestamp = timestamp;
    }

    public long getUserId() {
        return userId;
    }

    public long getTimestamp() {
        return timestamp;
    }
}
