import java.io.IOException;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;

public class ConnectionPool {
    private static final int MAX_CONNECTIONS = 10;
    private static final int CONNECTION_TIMEOUT = 5000; // 5 seconds

    private AsynchronousChannelGroup channelGroup;
    private List<AsynchronousSocketChannel> connections;

    public ConnectionPool() {
        this.channelGroup = AsynchronousChannelGroup.withFixedThreadPool(MAX_CONNECTIONS, Executors.defaultThreadFactory());
        this.connections = new ArrayList<>();
    }

    public CompletableFuture<AsynchronousSocketChannel> getConnection() {
        if (connections.isEmpty()) {
            return createNewConnection();
        } else {
            return CompletableFuture.completedFuture(connections.remove(0));
        }
    }

    private CompletableFuture<AsynchronousSocketChannel> createNewConnection() {
        try {
            AsynchronousSocketChannel channel = AsynchronousSocketChannel.open(channelGroup);
            channel.connect(new InetSocketAddress("localhost", 8080)).get(); // replace with actual host and port
            return CompletableFuture.completedFuture(channel);
        } catch (IOException | InterruptedException e) {
            return CompletableFuture.failedFuture(e);
        }
    }

    public void releaseConnection(AsynchronousSocketChannel channel) {
        if (!connections.contains(channel)) {
            connections.add(channel);
        }
    }
}
