import datetime
from typing import Dict

class SessionCache:
    def __init__(self):
        self.session_cache = {}
        self.profile_cache = {}

    def check_session(self, session_token: str) -> bool:
        if session_token not in self.session_cache:
            return False

        expiration_time = self.session_cache[session_token]["expires"]
        current_time = datetime.datetime.now()

        if current_time > expiration_time:
            del self.session_cache[session_token]
            return False

        return True

    def invalidate_session(self, session_token: str) -> None:
        del self.session_cache[session_token]

    def generate_new_session(self) -> Dict[str, str]:
        new_session = {
            "token": str(uuid.uuid4()),
            "expires": datetime.datetime.now() + datetime.timedelta(minutes=30),
        }
        self.session_cache[new_session["token"]] = new_session
        return new_session

    def verify_secure_cookie(self, secure_cookie: str) -> bool:
        if secure_cookie not in self.profile_cache:
            return False

        expiration_time = self.profile_cache[secure_cookie]["expires"]
        current_time = datetime.datetime.now()

        if current_time > expiration_time:
            del self.profile_cache[secure_cookie]
            return False

        return True

    def set_secure_cookie(self, secure_token: str) -> None:
        new_secure_token = {
            "token": secure_token,
            "expires": datetime.datetime.now() + datetime.timedelta(minutes=30),
        }
        self.profile_cache[new_secure_token["token"]] = new_secure_token

    def retrieve_user_profile(self, user_id: int) -> Dict[str, str]:
        if user_id not in self.profile_cache:
            profile = get_user_profile(user_id)
            self.profile_cache[user_id] = profile
        else:
            profile = self.profile_cache[user_id]

        return profile
```
