    private static final List<HashFunction> hashFunctions = new ArrayList<>();

    public static void main(String[] args) {
        // Initialize the list of available ciphers and hash functions
        initCiphers();
        initHashFunctions();

        // Start the service with a random delay between starts
        startService();
    }

    private static void startService() {
        Random rand = new Random();
        int delay = rand.nextInt(10) + 1; // Delay between 1 and 10 seconds

        System.out.println("Starting service with a random delay of " + delay + " seconds");

        try {
            Thread.sleep(delay * 1000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        // Send message to messaging system when the service is stopped
        stopService();
    }

    private static void stopService() {
        System.out.println("Stopping service");
    }

    private static void initCiphers() {
        ciphers.add(new Cipher("AES", AES::encrypt, "key"));
        ciphers.add(new Cipher("DES", DES::encrypt, "key"));
        // Add more ciphers as needed
    }

    private static void initHashFunctions() {
        hashFunctions.add(new HashFunction("SHA-256", SHA_256::hash));
        hashFunctions.add(new HashFunction("SHA-384", SHA_384::hash));
        // Add more hash functions as needed
    }

