use std::time;
use std::process::Command;
use rustc_driver::catch_with_exit_code;
use rustc_driver::early_error;
use std::sync::SyncLazy;

static LOGGING_HOOK: SyncLazy<LoggingHook> = SyncLazy::new(|| LoggingHook::new());

fn compile() -> i32 {
    let start = time::Instant::now();
    let mut process = Command::new("rustc")
        .arg("--log-hook")
        .arg(LOGGING_HOOK.get().as_ref())
        .spawn()
        .unwrap();
    let resident_set_size_before = get_resident_set_size(&process);
    process.wait().unwrap();
    let resident_set_size_after = get_resident_set_size(&process);
    let elapsed = start.elapsed();
    LOGGING_HOOK.get().log(elapsed, resident_set_size_before, resident_set_size_after);
    process.exit_code()
}

struct LoggingHook {
    logger: Logger,
}

impl LoggingHook {
    fn new() -> Self {
        Self {
            logger: Logger::new(),
        }
    }

    fn log(&self, elapsed: time::Duration, resident_set_size_before: u64, resident_set_size_after: u64) {
        self.logger.log(elapsed, resident_set_size_before, resident_set_size_after);
    }
}

struct Logger {
    start_time: time::Instant,
    resident_set_size_before: u64,
    resident_set_size_after: u64,
}

impl Logger {
    fn new() -> Self {
        Self {
            start_time: time::Instant::now(),
            resident_set_size_before: 0,
            resident_set_size_after: 0,
        }
    }

    fn log(&mut self, elapsed: time::Duration, resident_set_size_before: u64, resident_set_size_after: u64) {
        self.start_time = time::Instant::now();
        self.resident_set_size_before = resident_set_size_before;
        self.resident_set_size_after = resident_set_size_after;
    }
}
