['```php
function updateClinicStatus($clinicId) {
    // Start transaction
    $conn->beginTransaction();

    try {
        // Update status table
        $statusQuery = "UPDATE status SET status = 'active' WHERE clinic_id = :clinicId";
        $stmt = $conn->prepare($statusQuery);
        $stmt->bindParam(':clinicId', $clinicId, PDO::PARAM_INT);
        $stmt->execute();

        // Update last modified IP address table
        $ipAddressQuery = "UPDATE last_modified_ip SET ip_address = :ipAddress WHERE clinic_id = :clinicId";
        $stmt = $conn->prepare($ipAddressQuery);
        $stmt->bindParam(':ipAddress', $_SERVER['REMOTE_ADDR'], PDO::PARAM_STR);
        $stmt->bindParam(':clinicId', $clinicId, PDO::PARAM_INT);
        $stmt->execute();

        // Update last modified date table
        $dateQuery = "UPDATE last_modified_date SET date = NOW() WHERE clinic_id = :clinicId";
        $stmt = $conn->prepare($dateQuery);
        $stmt->bindParam(':clinicId', $clinicId, PDO::PARAM_INT);
        $stmt->execute();

        // Commit transaction
        $conn->commit();

        return "Successfully updated clinic status";
    } catch (PDOException $e) {
        // Rollback transaction
        $conn->rollBack();

        return "Error updating clinic status: " . $e->getMessage();
    }
}
