};

class Octree {
 public:
  Octree(int featureSize, int maxDataCapacity) : featureSize_(featureSize), maxDataCapacity_(maxDataCapacity) {}

  void initialize() {
    root_ = new OctreeNode();
    root_->featureSize = featureSize_;
    root_->data.reserve(maxDataCapacity_);
  }

  void addData(const std::vector<int>& data) {
