    addDataRecursive(root_, data);
  }

  void updateData(const std::vector<int>& data, int index) {
    // Update data in the octree recursively
    updateDataRecursive(root_, data, index);
  }

  void removeData(int index) {
    // Remove data from the octree recursively
    removeDataRecursive(root_, index);
  }

 private:
  int featureSize_;
  int maxDataCapacity_;
  OctreeNode* root_;

  void addDataRecursive(OctreeNode* node, const std::vector<int>& data) {
    // Check if the node has children
    if (node->children.empty()) {
      // If not, create children and add data to them
      for (int i = 0; i < 8; ++i) {
        OctreeNode* child = new OctreeNode();
        child->featureSize = featureSize_;
        child->data.reserve(maxDataCapacity_);
        node->children.push_back(child);
      }
    }

    // Add data to the appropriate child node
    int childIndex = getChildIndex(node, data);
    addDataRecursive(node->children[childIndex], data);
  }

  void updateDataRecursive(OctreeNode* node, const std::vector<int>& data, int index) {
    // Check if the node has children
    if (node->children.empty()) {
      // If not, create children and add data to them
      for (int i = 0; i < 8; ++i) {
        OctreeNode* child = new OctreeNode();
        child->featureSize = featureSize_;
        child->data.reserve(maxDataCapacity_);
        node->children.push_back(child);
      }
    }

    // Update data in the appropriate child node
    int childIndex = getChildIndex(node, data);
    updateDataRecursive(node->children[childIndex], data, index);
  }

  void removeDataRecursive(OctreeNode* node, int index) {
    // Check if the node has children
    if (node->children.empty()) {
      // If not, return
      return;
    }

    // Remove data from the appropriate child node
    int childIndex = getChildIndex(node, index);
    removeDataRecursive(node->children[childIndex], index);
  }

  int getChildIndex(OctreeNode* node, const std::vector<int>& data) {
    // Calculate the child index based on the data
    int childIndex = 0;
    for (int i = 0; i < featureSize_; ++i) {
      if (data[i] > node->featureSize / 2) {
        childIndex += pow(2, featureSize_ - i - 1);
      }
    }
    return childIndex;
  }

  int getChildIndex(OctreeNode* node, int index) {
    // Calculate the child index based on the data
    int childIndex = 0;
    for (int i = 0; i < featureSize_; ++i) {
      if (index % pow(2, featureSize_ - i - 1) > node->featureSize / 2) {
        childIndex += pow(2, featureSize_ - i - 1);
      }
    }
    return childIndex;
  }
};
