        strategy.lastUsedTime = std::chrono::system_clock::now();

        // Check if the cooldown has expired, and if so, select a new attack move
        if (std::chrono::duration_cast<std::chrono::seconds>(strategy.lastUsedTime - strategy.lastUsedTime).count() >= MAX_TOTAL_COOLDOWN) {
            // Select a new attack move based on external data source
            AttackMove newMove = getNewAttackMoveFromExternalSource();

            // Update the current move and last used time
