using System;
using System.Collections.Generic;
using UnityEngine;

public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;
    private bool inclusiveMin;
    private bool inclusiveMax;
    private Logger logger;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.inclusiveMin = true;
        this.inclusiveMax = true;
        logger = new Logger();

        if (minValue > maxValue)
        {
            logger.LogError("Invalid range: minValue must be less than or equal to maxValue");
            return;
        }
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return UnityEngine.Random.Range(minValue, maxValue).ToInt();
    }

    public Vector3 GetRandomVector3()
    {
        float x = UnityEngine.Random.Range(minValue, maxValue);
        float y = UnityEngine.Random.Range(minValue, maxValue);
        float z = UnityEngine.Random.Range(minValue, maxValue);
        return new Vector3(x, y, z);
    }

    public void ResetRange()
    {
        minValue = 0;
        maxValue = 100;
        inclusiveMin = true;
        inclusiveMax = true;
    }

    public override string ToString()
    {
        return $"Random value range: [{minValue}, {maxValue}]";
    }
}
