char* truncate_string(const char* input, size_t limit, bool truncate) {
    // Check if the input string is longer than the size limit
    if (strlen(input) > limit) {
        // If the truncation flag is set, truncate the string to fit within the size limit
        if (truncate) {
            char* output = malloc(limit + 1);
            if (!output) {
                // Handle memory allocation failure
                return NULL;
            }
            strncpy(output, input, limit);
            output[limit] = '\0';
            return output;
        } else {
            // If the truncation flag is not set, return NULL
            return NULL;
        }
    } else {
        // If the input string does not exceed the size limit, append a slash to the end of it
        char* output = malloc(strlen(input) + 2);
        if (!output) {
            // Handle memory allocation failure
            return NULL;
        }
        strcpy(output, input);
        output[strlen(input)] = '/';
        output[strlen(input) + 1] = '\0';
        return output;
    }
}
