#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>

#define MAXFIELDS 10

int main(int argc, char *argv[]) {
    FILE *file = fopen(argv[1], "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", argv[1]);
        return 1;
    }

    // Process each line of the file
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Split the line into fields based on spaces
        char **fields = strtok(line, " ");
        int numFields = 0;
        while (fields[numFields] != NULL) {
            numFields++;
            fields = strtok(NULL, " ");
        }

        // Calculate the average of the last two numeric fields and append it as a new field
        if (numFields >= 3) {
            char *lastField = fields[numFields - 1];
            char *penultimateField = fields[numFields - 2];
            double sum = atof(lastField) + atof(penultimateField);
            double average = sum / 2.0;
            char *newField = malloc(sizeof(char) * MAXFIELDS);
            sprintf(newField, "%f", average);
            fields[numFields] = newField;
        } else {
            // Treat all existing fields as non-numeric and concatenate them with a comma
            char *concatenatedFields = malloc(sizeof(char) * MAXFIELDS);
            for (int i = 0; i < numFields; i++) {
                if (i > 0) {
                    strcat(concatenatedFields, ",");
                }
                strcat(concatenatedFields, fields[i]);
            }
            fields[numFields] = concatenatedFields;
        }

        // Output the processed line in a comma-separated format
        for (int i = 0; i < numFields; i++) {
            if (i > 0) {
                printf(",");
            }
            printf("%s", fields[i]);
        }
        printf("\n");

        // Free the dynamically allocated memory for this line
        free(line);
    }

    fclose(file);
    return 0;
}
