// Custom struct to hold TIFF metadata and cipher object pointer
typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    AES_KEY *cipher_key;
} tiff_metadata_t;

// Function to parse TIFF file and extract metadata
int parseTIFFAndEncrypt(const char* tiff_filepath, const char* crypt_op) {
    // Open TIFF file for reading
    FILE *tiff_file = fopen(tiff_filepath, "rb");
    if (tiff_file == NULL) {
        printf("Error: unable to open TIFF file %s\n", tiff_filepath);
        return -1;
    }

    // Read TIFF header and check for supported bits per sample value
    unsigned char tiff_header[4];
    if (fread(tiff_header, 1, 4, tiff_file) != 4) {
        printf("Error: unable to read TIFF header\n");
        fclose(tiff_file);
        return -2;
    }
    int bits_per_sample = (int)tiff_header[1];
    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        printf("Error: unsupported bits per sample value %d\n", bits_per_sample);
        fclose(tiff_file);
        return -3;
    }

    // Read TIFF image data and extract metadata
    unsigned char *image_data = NULL;
    size_t image_size = 0;
    if (fseek(tiff_file, 0, SEEK_END) != 0) {
        printf("Error: unable to seek to end of TIFF file\n");
        fclose(tiff_file);
        return -4;
    }
    long file_size = ftell(tiff_file);
    if (fseek(tiff_file, 0, SEEK_SET) != 0) {
        printf("Error: unable to seek back to beginning of TIFF file\n");
        fclose(tiff_file);
        return -5;
    }
    image_data = (unsigned char *)malloc(file_size);
    if (image_data == NULL) {
        printf("Error: unable to allocate memory for TIFF image data\n");
        fclose(tiff_file);
        return -6;
    }
    if (fread(image_data, 1, file_size, tiff_file) != file_size) {
        printf("Error: unable to read TIFF image data\n");
        fclose(tiff_file);
        return -7;
    }
    int samples_per_pixel = (int)image_data[1];
    int extra_samples = 0;
    if (bits_per_sample == 16) {
        extra_samples = (int)image_data[3];
    }

    // Initialize cipher object using OpenSSL library
    AES_KEY *cipher_key = NULL;
    int ret = AES_set_encrypt_key(crypt_op, &cipher_key);
    if (ret != 0) {
        printf("Error: unable to set cipher key\n");
        fclose(tiff_file);
        return -8;
    }

    // Clean up and return struct with metadata and cipher object pointer
    free(image_data);
    fclose(tiff_file);
    tiff_metadata_t *metadata = (tiff_metadata_t *)malloc(sizeof(tiff_metadata_t));
    metadata->bits_per_sample = bits_per_sample;
    metadata->samples_per_pixel = samples_per_pixel;
    metadata->extra_samples = extra_samples;
    metadata->cipher_key = cipher_key;
    return 0;
}
```
