char* modify_filename(const char* filename) {
    // Get the directory path and file name from the input filename
    const char* dir_path = strrchr(filename, '/');
    if (dir_path == NULL) {
        return NULL;
    }
    size_t dir_len = strlen(dir_path);
    const char* file_name = dir_path + 1;

    // Determine the number of digits to append based on the directory path length
    int num_digits = (dir_len > 10) ? 10 : dir_len;

    // Allocate memory for the new filename
    char* new_filename = malloc(strlen(file_name) + num_digits + 5);
    if (new_filename == NULL) {
        return NULL;
    }

    // Construct the new filename using sprintf and strcat
    sprintf(new_filename, "%s%d.txt", file_name, num_digits);

    // Handle any potential errors during memory allocation and string manipulation
    if (strlen(new_filename) > 256) {
        free(new_filename);
        return NULL;
    }

    return new_filename;
}
