#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/err.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

// Custom logging mechanism
#define LOG_INFO(msg) printf("[INFO] %s\n", msg)
#define LOG_ERROR(msg) printf("[ERROR] %s\n", msg)

// Cryptographic key management
struct crypt_key {
    unsigned char *key;
    size_t len;
};

struct crypt_key_manager {
    struct crypt_key current_key;
    pthread_mutex_t mutex;
};

void init_crypt_key_manager(struct crypt_key_manager *mgr) {
    mgr->current_key.key = NULL;
    mgr->current_key.len = 0;
    pthread_mutex_init(&mgr->mutex, NULL);
}

void set_crypt_key(struct crypt_key_manager *mgr, const unsigned char *key, size_t len) {
    pthread_mutex_lock(&mgr->mutex);
    if (mgr->current_key.key != NULL) {
        free(mgr->current_key.key);
    }
    mgr->current_key.key = malloc(len);
    memcpy(mgr->current_key.key, key, len);
    mgr->current_key.len = len;
    pthread_mutex_unlock(&mgr->mutex);
}

void get_crypt_key(struct crypt_key_manager *mgr, unsigned char **key, size_t *len) {
    pthread_mutex_lock(&mgr->mutex);
    *key = mgr->current_key.key;
    *len = mgr->current_key.len;
    pthread_mutex_unlock(&mgr->mutex);
}

// Cryptographic operation functions
void aes_encrypt(const unsigned char *plaintext, size_t plaintext_len, const struct crypt_key *key, unsigned char **ciphertext, size_t *ciphertext_len) {
    AES_KEY aes_key;
    AES_set_encrypt_key(key->key, key->len * 8, &aes_key);
    *ciphertext_len = plaintext_len + AES_BLOCK_SIZE;
    *ciphertext = malloc(*ciphertext_len);
    AES_cbc_encrypt(plaintext, *ciphertext, plaintext_len, &aes_key, NULL, AES_ENCRYPT);
}

void aes_decrypt(const unsigned char *ciphertext, size_t ciphertext_len, const struct crypt_key *key, unsigned char **plaintext, size_t *plaintext_len) {
    AES_KEY aes_key;
    AES_set_decrypt_key(key->key, key->len * 8, &aes_key);
    *plaintext_len = ciphertext_len - AES_BLOCK_SIZE;
    *plaintext = malloc(*plaintext_len);
    AES_cbc_encrypt(ciphertext, *plaintext, *plaintext_len, &aes_key, NULL, AES_DECRYPT);
}

void camellia_encrypt(const unsigned char *plaintext, size_t plaintext_len, const struct crypt_key *key, unsigned char **ciphertext, size_t *ciphertext_len) {
    CAMELLIA_KEY camellia_key;
    CAMELLIA_set_encrypt_key(key->key, key->len * 8, &camellia_key);
    *ciphertext_len = plaintext_len + CAMELLIA_BLOCK_SIZE;
    *ciphertext = malloc(*ciphertext_len);
    CAMELLIA_cbc_encrypt(plaintext, *ciphertext, plaintext_len, &camellia_key, NULL, CAMELLIA_ENCRYPT);
}

void camellia_decrypt(const unsigned char *ciphertext, size_t ciphertext_len, const struct crypt_key *key, unsigned char **plaintext, size_t *plaintext_len) {
    CAMELLIA_KEY camellia_key;
    CAMELLIA_set_decrypt_key(key->key, key->len * 8, &camellia_key);
    *plaintext_len = ciphertext_len - CAMELLIA_BLOCK_SIZE;
    *plaintext = malloc(*plaintext_len);
    CAMELLIA_cbc_encrypt(ciphertext, *plaintext, *plaintext_len, &camellia_key, NULL, CAMELLIA_DECRYPT);
}

void md5_hash(const unsigned char *data, size_t data_len, unsigned char **hash) {
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, data, data_len);
    MD5_Final(*hash, &ctx);
}

void sha1_hash(const unsigned char *data, size_t data_len, unsigned char **hash) {
    SHA_CTX ctx;
    SHA1_Init(&ctx);
    SHA1_Update(&ctx, data, data_len);
    SHA1_Final(*hash, &ctx);
}

void sha256_hash(const unsigned char *data, size_t data_len, unsigned char **hash) {
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, data, data_len);
    SHA256_Final(*hash, &ctx);
}

void rsa_encrypt(const unsigned char *plaintext, size_t plaintext_len, const struct crypt_key *key, unsigned char **ciphertext, size_t *ciphertext_len) {
    RSA *rsa = RSA_new();
    BIGNUM *bn = BN_bin2bn(key->key, key->len, NULL);
    RSA_set0_key(rsa, bn, NULL, NULL);
    *ciphertext_len = plaintext_len;
    *ciphertext = malloc(*ciphertext_len);
    int ret = RSA_public_encrypt(plaintext_len, plaintext, *ciphertext, rsa, RSA_PKCS1_PADDING);
    if (ret < 0) {
        LOG_ERROR("RSA encryption failed");
    }
    RSA_free(rsa);
}

void rsa_decrypt(const unsigned char *ciphertext, size_t ciphertext_len, const struct crypt_key *key, unsigned char **plaintext, size_t *plaintext_len) {
    RSA *rsa = RSA_new();
    BIGNUM *bn = BN_bin2bn(key->key, key->len, NULL);
    RSA_set0_key(rsa, bn, NULL, NULL);
    *plaintext_len = ciphertext_len;
    *plaintext = malloc(*plaintext_len);
    int ret = RSA_private_decrypt(ciphertext_len, ciphertext, *plaintext, rsa, RSA_PKCS1_PADDING);
    if (ret < 0) {
        LOG_ERROR("RSA decryption failed");
    }
    RSA_free(rsa);
}

// Error handling and resource management
void handle_error(const char *msg) {
    LOG_ERROR(msg);
    exit(1);
}

void free_resources(unsigned char **ciphertext, size_t *ciphertext_len, unsigned char **plaintext, size_t *plaintext_len) {
    if (*ciphertext != NULL) {
        free(*ciphertext);
        *ciphertext = NULL;
    }
    if (*plaintext != NULL) {
        free(*plaintext);
        *plaintext = NULL;
    }
}

// Main function
int main(int argc, char **argv) {
    // Initialize cryptographic key manager
    struct crypt_key_manager mgr;
    init_crypt_key_manager(&mgr);

    // Set cryptographic key
    set_crypt_key(&mgr, "my secret key", strlen("my secret key"));

    // Encrypt data using AES
    unsigned char *plaintext = "hello world";
    size_t plaintext_len = strlen(plaintext);
    unsigned char *ciphertext;
    size_t ciphertext_len;
    aes_encrypt(plaintext, plaintext_len, &mgr.current_key, &ciphertext, &ciphertext_len);
    LOG_INFO("Encrypted data: %s", ciphertext);
    free_resources(&ciphertext, &ciphertext_len, NULL, NULL);

    // Decrypt data using AES
    unsigned char *decrypted_data;
    size_t decrypted_data_len;
    aes_decrypt(ciphertext, ciphertext_len, &mgr.current_key, &decrypted_data, &decrypted_data_len);
    LOG_INFO("Decrypted data: %s", decrypted_data);
    free_resources(&decrypted_data, &decrypted_data_len, NULL, NULL);

    // Encrypt data using Camellia
    unsigned char *camellia_plaintext = "hello world";
    size_t camellia_plaintext_len = strlen(camellia_plaintext);
    unsigned char *camellia_ciphertext;
    size_t camellia_ciphertext_len;
    camellia_encrypt(camellia_plaintext, camellia_plaintext_len, &mgr.current_key, &camellia_ciphertext, &camellia_ciphertext_len);
    LOG_INFO("Encrypted data: %s", camellia_ciphertext);
    free_resources(&camellia_ciphertext, &camellia_ciphertext_len, NULL, NULL);

    // Decrypt data using Camellia
    unsigned char *camellia_decrypted_data;
    size_t camellia_decrypted_data_len;
    camellia_decrypt(camellia_ciphertext, camellia_ciphertext_len, &mgr.current_key, &camellia_decrypted_data, &camellia_decrypted_data_len);
    LOG_INFO("Decrypted data: %s", camellia_decrypted_data);
    free_resources(&camellia_decrypted_data, &camellia_decrypted_data_len, NULL, NULL);

    // Hash data using MD5
    unsigned char *md5_data = "hello world";
    size_t md5_data_len = strlen(md5_data);
    unsigned char *md5_hash;
    md5_hash(md5_data, md5_data_len, &md5_hash);
    LOG_INFO("MD5 hash: %s", md5_hash);
    free_resources(&md5_hash, NULL, NULL, NULL);

    // Hash data using SHA1
    unsigned char *sha1_data = "hello world";
    size_t sha1_data_len = strlen(sha1_data);
    unsigned char *sha1_hash;
    sha1_hash(sha1_data, sha1_data_len, &sha1_hash);
    LOG_INFO("SHA1 hash: %s", sha1_hash);
    free_resources(&sha1_hash, NULL, NULL, NULL);

    // Hash data using SHA256
    unsigned char *sha256_data = "hello world";
    size_t sha256_data_len = strlen(sha256_data);
    unsigned char *sha256_hash;
    sha256_hash(sha256_data, sha256_data_len, &sha256_hash);
    LOG_INFO("SHA256 hash: %s", sha256_hash);
    free_resources(&sha256_hash, NULL, NULL, NULL);

