    unsigned char *rsa_ciphertext;
    size_t rsa_ciphertext_len;
    rsa_encrypt(rsa_plaintext, rsa_plaintext_len, &mgr.current_key, &rsa_ciphertext, &rsa_ciphertext_len);
    LOG_INFO("Encrypted data: %s", rsa_ciphertext);
