#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>

int run_command(char* command, int timeout) {
    pid_t child_pid;
    int status;
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Fork a new process to execute the command
    if ((child_pid = fork()) == 0) {
        // Child process: execute the command and exit
        system(command);
        exit(EXIT_SUCCESS);
    } else if (child_pid < 0) {
        // Error forking a new process
        perror("fork");
        return -1;
    }

    // Parent process: wait for the command to complete or timeout
    while (waitpid(child_pid, &status, WNOHANG) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) - start > timeout) {
            // Command timed out
            kill(child_pid, SIGKILL);
            perror("timeout");
            return -1;
        }
    }

    // Check if the command completed successfully or encountered resource constraints
    if (WIFEXITED(status)) {
        // Command exited normally
        printf("Command exited with status %d\n", WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        // Command was terminated by a signal
        perror("signal");
        return -1;
    } else if (WIFSTOPPED(status)) {
        // Command was stopped by a signal
        perror("stopped");
        return -1;
    } else {
        // Unknown exit status
        printf("Unknown exit status %d\n", status);
        return -1;
    }

    // Log the execution details and resource usage metrics
    log_execution(command, start, end, status);

    // Return the exit status of the command
    return WEXITSTATUS(status);
}

void log_execution(char* command, struct timespec start, struct timespec end, int status) {
    // Log the execution details to a file or database
    printf("Command: %s\n", command);
    printf("Start time: %ld.%09ld\n", start.tv_sec, start.tv_nsec);
    printf("End time: %ld.%09ld\n", end.tv_sec, end.tv_nsec);
    printf("Exit status: %d\n", status);
}
```
This code defines a function `run_command` that takes a command string and a timeout period as input, and runs the command in the background using the `fork` and `wait` system calls. The function ensures that the command completes within the specified timeout period or encounters resource constraints, and logs an error message if either of these conditions occur.

The function first forks a new process to execute the command using the `fork` system call. If the fork is successful, the child process executes the command using the `system` function and exits with a success status code. The parent process waits for the child process to complete or timeout using the `waitpid` system call.

If the command times out or encounters resource constraints, the function kills the child process using the `kill` system call and logs an error message. If the command completes successfully, the function logs the execution details and resource usage metrics using the `log_execution` function. The `log_execution` function takes the command string, start and end times, and exit status as input and logs them to a file or database.

The function returns the exit status of the command if it completes successfully, or -1 if it encounters an error or timeout.']

