EVP_CIPHER* decrypt(const std::string& message, const std::string& operation) {
    // Decode the Base64-encoded message
    std::string decodedMessage = base64_decode(message);

    // Create an EVP_CIPHER structure for the chosen cipher
    EVP_CIPHER* cipher;

    // Select the appropriate cipher based on the operation
    if (operation == "decryption") {
        // Triple DES encryption with a given key and initialization vector (IV)
        cipher = EVP_des_ede3_cbc();
    } else if (operation == "validation") {
        // JSON object parser for the access token response
        Json::Value root;

        // Parse the decrypted message as a JSON object
        Json::Reader reader;
        bool parsingSuccessful = reader.parse(decodedMessage, root);

        // Verify that the JSON object contains the required fields and values for a valid OAuth2 access token response
        if (parsingSuccessful && root["access_token"].isString() && root["expires_in"].isNumeric() && root["token_type"].isString()) {
            // Select the appropriate cipher based on the refresh token field
            if (root.isMember("refresh_token")) {
                cipher = EVP_des_ede3_cbc();
            } else {
                cipher = EVP_des_ecb();
            }
        } else {
            // Return null encryption for testing purposes
            cipher = EVP_des_null();
        }
    } else {
        // Return null encryption for testing purposes
        cipher = EVP_des_null();
    }

    return cipher;
}
