using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization.Formatters.Binary;

public static CustomDataStructure LoadData(string filePath)
{
    try
    {
        using (var stream = new FileStream(filePath, FileMode.Open))
        {
            var compressionType = GetCompressionType(stream);
            if (compressionType == CompressionType.GZip)
            {
                using (var gzipStream = new GZipStream(stream, CompressionMode.Decompress))
                {
                    return DeserializeData(gzipStream);
                }
            }
            else if (compressionType == CompressionType.ZIP)
            {
                using (var zipArchive = new ZipArchive(stream, ZipArchiveMode.Read))
                {
                    var entry = zipArchive.Entries[0];
                    using (var entryStream = entry.Open())
                    {
                        return DeserializeData(entryStream);
                    }
                }
            }
            else
            {
                throw new Exception("Unsupported compression type");
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error loading data: {ex.Message}");
        return null;
    }
}

private static CompressionType GetCompressionType(Stream stream)
{
    var magicNumber = new byte[2];
    if (stream.Read(magicNumber, 0, 2) != 2)
    {
        throw new Exception("Invalid file format");
    }

    if (magicNumber[0] == 0x1f && magicNumber[1] == 0x8b)
    {
        return CompressionType.GZip;
    }
    else if (magicNumber[0] == 0x50 && magicNumber[1] == 0x4b)
    {
        return CompressionType.ZIP;
    }
    else
    {
        throw new Exception("Unsupported compression type");
    }
}

private static CustomDataStructure DeserializeData(Stream stream)
{
    var formatter = new BinaryFormatter();
    return (CustomDataStructure)formatter.Deserialize(stream);
}
