public class SerializationHelper {
    private static final Logger logger = Logger.getLogger(SerializationHelper.class.getName());

    public static <T> T deserializeObject(byte[] data, Class<T> clazz) throws IOException, ClassNotFoundException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            T obj = (T) ois.readObject();
            logger.info("Deserialized object of class " + clazz.getName());
            return obj;
        } catch (IOException | ClassNotFoundException e) {
            logger.severe("Failed to deserialize object: " + e.getMessage());
            throw new RuntimeException("Failed to deserialize object", e);
        }
    }
}
