char* executeShellCommandWithSizeLimit(const char* command, size_t size_limit, bool truncate) {
    // Create a custom memory manager to handle dynamic memory allocation
    CustomMemoryManager* mm = createCustomMemoryManager();

    // Execute the shell command and capture its output
    FILE* fp = popen(command, "r");
    if (fp == NULL) {
        perror("Failed to execute shell command");
        return NULL;
    }

    char buffer[BUFSIZ];
    size_t total_size = 0;
    while (fgets(buffer, BUFSIZ, fp)) {
        // Check if the output exceeds the size limit
        if (total_size + strlen(buffer) > size_limit) {
            if (truncate) {
                // Truncate the output to fit within the size limit
                buffer[size_limit - total_size] = '\0';
            } else {
                // Output exceeds the size limit and truncation is not allowed, return NULL
                pclose(fp);
                return NULL;
            }
        }

        // Append a slash to the end of the output string if necessary
        if (total_size > 0 && buffer[strlen(buffer) - 1] != '/') {
            strcat(buffer, "/");
        }

        total_size += strlen(buffer);
    }

    // Close the file pointer and return the output string
    pclose(fp);
    char* output = (char*)mm->allocate(total_size + 1);
    memcpy(output, buffer, total_size);
    output[total_size] = '\0';
    return output;
}
