const { spawn } = require('child_process');
const { Graph, Vertex, Edge } = require('graph-db');

async function addRandomVerticesAndEdges(graph) {
  // Generate a random number of vertices and edges
  const numVertices = Math.floor(Math.random() * 10) + 5;
  const numEdges = Math.floor(Math.random() * 20) + 10;

  // Add the vertices to the graph
  for (let i = 0; i < numVertices; i++) {
    const vertex = new Vertex();
    vertex.setProperty('name', `Vertex ${i}`);
    graph.addVertex(vertex);
  }

  // Add the edges to the graph
  for (let i = 0; i < numEdges; i++) {
    const edge = new Edge();
    edge.setProperty('weight', Math.random() * 10);
    graph.addEdge(edge);
  }

  // Execute a shell command to output the results to the browser
  const childProcess = spawn('echo', ['Hello, world!']);
  childProcess.stdout.on('data', (data) => {
    console.log(`Received data from child process: ${data}`);
  });
  childProcess.stderr.on('data', (data) => {
    console.error(`Received error data from child process: ${data}`);
  });
  childProcess.on('close', (code) => {
    console.log(`Child process exited with code ${code}`);
  });
}
