use std::{env, fs};
use tokio::{task, sync::mpsc};
use serde_json::Value;

#[tokio::main]
async fn main() {
    // Parse command line arguments
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} config.json", args[0]);
        return;
    }

    // Load configuration from JSON file
    let config_path = &args[1];
    let config_str = fs::read_to_string(config_path).unwrap();
    let config: Value = serde_json::from_str(&config_str).unwrap();

    // Initialize logging system with configuration settings
    let log_level = config["log_level"].as_str().unwrap();
    let log_file = config["log_file"].as_str().unwrap();
    let logger = Logger::new(log_level, log_file);

    // Initialize task channel for graceful shutdown
    let (task_sender, task_receiver) = mpsc::channel::<()>(1024);

    // Spawn background tasks with configuration settings
    for task in config["tasks"].as_array().unwrap() {
        let task_name = task["name"].as_str().unwrap();
        let task_config = task["config"].clone();
        let task_sender = task_sender.clone();
        task::spawn(async move {
            // Initialize task with configuration settings
            let mut task = Task::new(task_name, task_config);

            // Run task until termination signal is received
            loop {
                match task_receiver.recv().await {
                    Some(_) => break,
                    None => {}
                }
                task.run().await;
            }
        });
    }

    // Wait for termination signal and send shutdown signal to tasks
    let mut term_signal = tokio::signal::ctrl_c();
    term_signal.recv().await;
    task_sender.send(()).unwrap();
}
```
This code uses the `tokio` library for asynchronous programming, and the `serde_json` library for parsing JSON configuration files. It also uses the `mpsc` channel for graceful shutdown of background tasks.

The program first parses command line arguments to get the path to the JSON configuration file. It then loads the configuration from the JSON file using the `serde_json` library, and initializes a logging system with the configured log level and log file.

Next, it spawns background tasks for each task in the configuration file using the `tokio::task::spawn` function. Each task is initialized with its own configuration settings, and runs until it receives a termination signal from the main thread. The main thread waits for a termination signal using the `tokio::signal::ctrl_c` function, and sends a shutdown signal to all background tasks through the `mpsc` channel.

The program handles potential race conditions and deadlocks by using asynchronous programming with the `async/await` syntax, and by using the `mpsc` channel for graceful shutdown of background tasks. It also optimizes performance by minimizing blocking operations.']

