use std::env;
use std::fs;
use std::path::PathBuf;

fn manage_project(project: &str, version: &str) -> Result<(), String> {
    // Check if the project directory already exists
    let project_dir = PathBuf::from(format!("{}/{}", env::var("PROJECTS_DIR").unwrap(), project));
    if fs::metadata(&project_dir).is_ok() {
        return Err(format!("Project '{}' already exists.", project));
    }

    // Create the project directory and set the environment variable
    let mut env = env::vars();
    if !env.contains_key("PROJECTS_DIR") {
        env.insert("PROJECTS_DIR".to_string(), "projects".to_string());
    }
    fs::create_dir(&project_dir).map_err(|e| e.to_string())?;
    env::set_var("PROJECT_DIR", project_dir);

    // List all existing projects in the directory tree and return their names and versions
    let mut projects = Vec::new();
    for entry in fs::read_dir(&env::var("PROJECTS_DIR").unwrap()).map_err(|e| e.to_string())? {
        let path = entry.unwrap().path();
        if path.is_dir() {
            projects.push((path.file_name().unwrap().to_str().unwrap(), ""));
        }
    }
    Ok(projects)
}
```
