// Define a struct to represent a transaction
struct Transaction {
    int id;
    time_t timestamp;
    double value;
};

// Define a struct to represent the metrics
struct Metrics {
    long totalCount;
    double averageValue;
    double maxWeightedSum;
};

// Define a function to filter and process transactions
void processTransactions(struct Transaction* transactions, int numTransactions) {
    // Initialize the metrics structure
    struct Metrics metrics = {0, 0.0, -INFINITY};

    // Iterate over each transaction
    for (int i = 0; i < numTransactions; i++) {
        struct Transaction* transaction = &transactions[i];

        // Filter transactions based on their age relative to the specified time window
        if (transaction->timestamp > time(NULL) - 3) {
            continue;
        }

        // Track the number of transactions that occurred within the last 3 seconds
        metrics.totalCount++;

        // Calculate a weighted sum for each transaction using a dynamic weight function
        double weight = fabs(transaction->timestamp - time(NULL)) / 3.0;
        metrics.maxWeightedSum = max(metrics.maxWeightedSum, weight * transaction->value);

        // Update the average transaction value and maximum weighted sum
        metrics.averageValue += transaction->value;
    }

    // Return the transaction ID associated with the maximum weighted sum and the total count of transactions processed since the last reset
    return (struct Transaction) {
        .id = -1,
        .timestamp = time(NULL),
        .value = metrics.maxWeightedSum
    };
}

// Define a function to periodically reset metrics and clear transaction history
void resetMetrics() {
    // Reset the metrics structure
    struct Metrics metrics = {0, 0.0, -INFINITY};

    // Clear the transaction history
    for (int i = 0; i < numTransactions; i++) {
        transactions[i] = NULL;
    }
}

// Define a function to integrate with an external logging service
void logMetrics(struct Metrics metrics) {
    // Log the transaction details and metrics at specified intervals
    printf("Total count: %ld\n", metrics.totalCount);
    printf("Average value: %.2f\n", metrics.averageValue);
    printf("Max weighted sum: %.2f\n", metrics.maxWeightedSum);
}
