    EVP_EncryptInit_ex(ctx, ENCRYPTION_MODE, NULL, key, iv);
    EVP_EncryptUpdate(ctx, encrypted, &len, (unsigned char*)input, strlen(input));
    EVP_EncryptFinal_ex(ctx, encrypted + len, &len);
    EVP_CIPHER_CTX_free(ctx);
}

// Define the function to decrypt text inputs using AES-256-GCM
