    if (ctx == NULL) {
        printf("Error: unable to create cipher context\n");
        return;
    }
    int len = strlen(input);
    unsigned char* decrypted = malloc(len + AES_BLOCK_SIZE);
    memset(decrypted, 0, len + AES_BLOCK_SIZE);
    EVP_DecryptInit_ex(ctx, DECRYPTION_MODE, NULL, key, iv);
    EVP_DecryptUpdate(ctx, decrypted, &len, (unsigned char*)input, strlen(input));
    EVP_DecryptFinal_ex(ctx, decrypted + len, &len);
    EVP_CIPHER_CTX_free(ctx);
}
