const fetchBooks = async () => {
  const response = await fetch('https://api.example.com/old_testament_books');
  return response.json();
};

const analyzeText = (text) => {
  // Initialize cache for frequently accessed data
  const bookCache = new Map();

  // Split the text into individual words
  const words = text.split(' ');

  // Iterate over each word in the text
  words.forEach((word) => {
    // Check if the word is a valid book name
    if (bookCache.has(word)) {
      // Increment the count for the book name
      bookCache.set(word, bookCache.get(word) + 1);
    } else {
      // Fetch the list of Old Testament books from the API
      const books = await fetchBooks();

      // Check if the word is a valid book name in the API response
      if (books.includes(word)) {
        // Add the word to the cache and set its count to 1
        bookCache.set(word, 1);
      } else {
        // Ignore the word as it is not a valid book name
      }
    }
  });

  // Return an object containing the names of the books found and their counts
  return Object.fromEntries(bookCache);
};
```
