import os
import re
import threading
import logging
from typing import List, Dict
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives.serialization import load_pem_private_key
from cryptography.exceptions import InvalidSignature

class CryptographicLibrary:
    def __init__(self, key_file: str):
        self.key_file = key_file
        self.keys = {}
        self.ciphers = {
            "AES": algorithms.AES,
            "Camellia": algorithms.Camellia,
            "MD5": hashes.MD5,
            "SHA1": hashes.SHA1,
            "SHA256": hashes.SHA256,
            "RSA": padding.OAEP
        }
        self.digests = {
            "MD5": hashes.MD5,
            "SHA1": hashes.SHA1,
            "SHA256": hashes.SHA256
        }

    def load_keys(self):
        with open(self.key_file, "r") as f:
            for line in f:
                key = line.strip()
                if not key:
                    continue
                self.keys[key] = load_pem_private_key(
                    data=key.encode(),
                    password=None,
                    backend=default_backend()
                )

    def get_cipher(self, algorithm: str):
        return Cipher(
            algorithms.AES(self.keys[algorithm]),
            modes.CBC(b"\x00" * 16),
            backend=default_backend()
        )

    def encrypt(self, data: bytes, algorithm: str) -> bytes:
        cipher = self.get_cipher(algorithm)
        return cipher.encryptor().update(data) + cipher.encryptor().finalize()

    def decrypt(self, data: bytes, algorithm: str) -> bytes:
        cipher = self.get_cipher(algorithm)
        return cipher.decryptor().update(data) + cipher.decryptor().finalize()

    def sign(self, data: bytes, algorithm: str) -> bytes:
        digest = self.digests[algorithm]()
        signature = self.keys[algorithm].sign(data, digest)
        return signature

    def verify(self, data: bytes, signature: bytes, algorithm: str) -> bool:
        try:
            self.keys[algorithm].verify(data, signature, self.digests[algorithm]())
            return True
        except InvalidSignature:
            return False

class CryptographicFunction:
    def __init__(self, library: CryptographicLibrary):
        self.library = library

    def encrypt_file(self, filepath: str, algorithm: str) -> bytes:
        with open(filepath, "rb") as f:
            data = f.read()
        return self.library.encrypt(data, algorithm)

    def decrypt_file(self, filepath: str, algorithm: str) -> bytes:
        with open(filepath, "rb") as f:
            data = f.read()
        return self.library.decrypt(data, algorithm)

    def sign_file(self, filepath: str, algorithm: str) -> bytes:
        with open(filepath, "rb") as f:
            data = f.read()
        return self.library.sign(data, algorithm)

    def verify_file(self, filepath: str, signature: bytes, algorithm: str) -> bool:
        with open(filepath, "rb") as f:
            data = f.read()
        return self.library.verify(data, signature, algorithm)

def sort_lines(lines: List[str]) -> List[str]:
    return sorted(lines)

def extract_sequence_number(line: str) -> int:
    match = re.search(r"^(\d+)", line)
    if match:
        return int(match.group(1))
    else:
        raise ValueError("Invalid sequence number")

def read_file(filepath: str, sort=True) -> List[str]:
    with open(filepath, "r") as f:
        lines = [line.strip() for line in f]
    if sort:
        return sort_lines(lines)
    else:
        return lines

def write_file(filepath: str, data: List[str]) -> None:
    with open(filepath, "w") as f:
        for line in data:
            f.write(line + "\n")

def handle_exceptions(func):
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            logging.error(f"Exception occurred in {func.__name__}: {e}")
            raise e
    return wrapper

@handle_exceptions
def main():
    library = CryptographicLibrary("keys.pem")
    library.load_keys()
    cryptographic_function = CryptographicFunction(library)
    filepath = "data.txt"
    algorithm = "AES"
    data = read_file(filepath, sort=False)
    encrypted_data = cryptographic_function.encrypt_file(filepath, algorithm)
    decrypted_data = cryptographic_function.decrypt_file(filepath, algorithm)
    signature = cryptographic_function.sign_file(filepath, algorithm)
    verified = cryptographic_function.verify_file(filepath, signature, algorithm)
    print("Encryption:", encrypted_data)
    print("Decryption:", decrypted_data)
    print("Signature:", signature)
    print("Verified:", verified)

if __name__ == "__main__":
    main()
