// Define the function to calculate the MD5 hash of a file's contents
string md5Hash(const string& filePath) {
    // Open the file for reading
    ifstream file(filePath, ios::binary);

    // Check if the file was successfully opened
    if (!file.is_open()) {
        cerr << "Error: unable to open file " << filePath << endl;
        return "";
    }

    // Calculate the MD5 hash of the file's contents
    string md5 = "";
    try {
        MD5_CTX ctx;
        MD5Init(&ctx);
        char buffer[1024];
        while (file.read(buffer, 1024)) {
            MD5Update(&ctx, buffer, file.gcount());
        }
        MD5Final(&ctx);
        md5 = MD5DigestToStr(ctx.digest);
    } catch (const invalid_argument& e) {
        // Treat any invalid argument exceptions as a non-numeric field and return 0
        cerr << "Error: unable to calculate MD5 hash" << endl;
        md5 = "";
    }

    // Close the file
    file.close();

    // Return the MD5 hash
    return md5;
}

