            if (*ctx == NULL) {
                printf("Error: Failed to allocate memory for hash function\n");
                return 0;
            }
            EVP_MD* md = hashes[i].func();
            if (md == NULL) {
                printf("Error: Failed to initialize hash function\n");
                free(*ctx);
                *ctx = NULL;
                return 0;
            }
            EVP_MD_CTX_init((EVP_MD_CTX*)*ctx, md);
            found = true;
            break;
        }
    }
    if (!found) {
        for (int i = 0; i < num_ciphers; ++i) {
            if (!strcmp(name, ciphers[i].name)) {
                *ctx = malloc(sizeof(EVP_CIPHER_CTX));
                if (*ctx == NULL) {
                    printf("Error: Failed to allocate memory for cipher function\n");
                    return 0;
                }
                EVP_CIPHER* c = ciphers[i].func();
                if (c == NULL) {
                    printf("Error: Failed to initialize cipher function\n");
                    free(*ctx);
                    *ctx = NULL;
                    return 0;
                }
                EVP_CIPHER_CTX_init((EVP_CIPHER_CTX*)*ctx, c, NULL, NULL, params);
                found = true;
                break;
            }
        }
    }
    if (!found) {
        printf("Error: Cryptographic function not found\n");
        return 0;
    }
    return 1;
}

// Function to clean up a hash or cipher function context
void cleanup_cryptographic_function(void* ctx) {
    if (ctx == NULL) {
        printf("Error: Context is null\n");
        return;
    }
    EVP_MD_CTX_cleanup((EVP_MD_CTX*)ctx);
    free(ctx);
}
