#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>

// Define the maximum number of records that can be generated
#define MAX_RECORDS 1000000

// Define the maximum number of ranges that can be used for generating random numbers
#define MAX_RANGES 5

// Define the maximum number of digits in the filename extension
#define MAX_DIGITS 6

// Define the file type to use in the filename extension
#define FILE_TYPE ".txt"

// Define the minimum and maximum values for each range
int ranges[MAX_RANGES][2];

// Define the weights for each range
float weights[MAX_RANGES];

// Define the number of records generated so far
int numRecords = 0;

// Define the record array
struct Record {
    int value;
    int key;
    long offset;
};
Record records[MAX_RECORDS];

// Define the filename to use for output
char filename[256];

void generateRecords(int numRanges, int *rangeBounds, float *rangeWeights) {
    // Initialize the ranges and weights
    for (int i = 0; i < numRanges; i++) {
        ranges[i][0] = rangeBounds[i];
        ranges[i][1] = rangeBounds[i + 1];
        weights[i] = rangeWeights[i];
    }

    // Initialize the record array and filename
    numRecords = 0;
    memset(records, 0, sizeof(records));
    sprintf(filename, "output_%d", numRecords);

    // Generate records until the maximum number of records is reached
    while (numRecords < MAX_RECORDS) {
        // Calculate the random number using the ranges and weights
        int randomNumber = 0;
        for (int i = 0; i < numRanges; i++) {
            randomNumber += (rand() % (ranges[i][1] - ranges[i][0])) * weights[i];
        }

        // Calculate the corresponding key and offset
        int key = randomNumber % 1000000;
        long offset = randomNumber % 1000000000;

        // Add the record to the array
        records[numRecords].value = randomNumber;
        records[numRecords].key = key;
        records[numRecords].offset = offset;
        numRecords++;

        // Update the filename extension with the new number of records
        sprintf(filename, "output_%d", numRecords);
    }
}

void writeRecordsToFile() {
    // Open the file for writing
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Write the records to the file
    for (int i = 0; i < numRecords; i++) {
        fprintf(file, "%d,%d,%ld\n", records[i].value, records[i].key, records[i].offset);
    }

    // Close the file
    fclose(file);
}

int main() {
    // Initialize the ranges and weights
    int rangeBounds[] = {0, 1000000, 2000000, 3000000, 4000000};
    float rangeWeights[] = {0.5, 0.25, 0.125, 0.125};

    // Generate the records
    generateRecords(4, rangeBounds, rangeWeights);

    // Write the records to a file
    writeRecordsToFile();

    return 0;
}
