#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* construct_email(const char* email) {
    // Parse the local part and domain name from the input email address
    const char* local_part = strchr(email, '@');
    const char* domain = strtok(local_part + 1, "@");

    // Determine the number of subdomains in the domain name
    int num_subdomains = 0;
    while (domain != NULL) {
        ++num_subdomains;
        domain = strtok(NULL, ".");
    }

    // Calculate the length of the unique identifier based on the number of subdomains
    int id_length = num_subdomains > 3 ? num_subdomains - 3 : 0;

    // Allocate memory for the new email address
    char* new_email = malloc(strlen(local_part) + id_length + strlen(domain) + 1);
    if (new_email == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for new email address\n");
        return NULL;
    }

    // Construct the new email address by appending the unique identifier to the local part and domain name
    strcpy(new_email, local_part);
    char* id = malloc(id_length + 1);
    for (int i = 0; i < id_length; ++i) {
        id[i] = 'a' + i % 26;
    }
    id[id_length] = '\0';
    strcat(new_email, id);
    strcat(new_email, domain);

    // Free the memory allocated for the unique identifier
    free(id);

    return new_email;
}
