#include <openssl/des.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>

// Define regular expressions for term extraction
const char* TERM_REGEX = "\\b(term1|term2|term3)\\b";
const char* PUNCTUATION_REGEX = "[^a-zA-Z0-9]";

// Function to perform cryptographic cipher operations using DES algorithm
EVP_CIPHER* get_cipher(int mode, int key_size) {
  // Initialize EVP_CIPHER structure for chosen cipher and key size
  EVP_CIPHER* cipher = NULL;
  switch (mode) {
    case ECB:
      cipher = EVP_des_ecb();
      break;
    case EDE:
      cipher = EVP_des_ede();
      break;
    case EDE3:
      cipher = EVP_des_ede3();
      break;
    case CFB:
      cipher = EVP_des_cfb();
      break;
  }
  if (key_size == 128) {
    cipher->key_len = DES_KEY_SIZE;
  } else if (key_size == 192) {
    cipher->key_len = DES3_KEY_SIZE;
  } else {
    return NULL;
  }
  return cipher;
}

// Function to perform encryption and decryption operations using cryptographic ciphers
int encrypt_decrypt(const unsigned char* plaintext, int plaintext_len, const unsigned char* key, int key_len, EVP_CIPHER* cipher, int mode) {
  // Initialize cipher context and set encryption/decryption mode
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL) <= 0) {
    return -1;
  }
  if (mode == ECB || mode == CFB) {
    EVP_CIPHER_CTX_set_padding(ctx, 0);
  }

  // Perform encryption/decryption operation on plaintext
  int ciphertext_len = 0;
  unsigned char* ciphertext = NULL;
  if (mode == ENCRYPT) {
    ciphertext_len = plaintext_len + EVP_CIPHER_CTX_block_size(ctx);
    ciphertext = OPENSSL_malloc(ciphertext_len);
    int len = 0;
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) <= 0) {
      return -1;
    }
    ciphertext_len = len;
  } else {
    ciphertext_len = plaintext_len + EVP_CIPHER_CTX_block_size(ctx);
    ciphertext = OPENSSL_malloc(ciphertext_len);
    int len = 0;
    if (EVP_DecryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) <= 0) {
      return -1;
    }
    ciphertext_len = len;
  }

  // Free resources and return result
  EVP_CIPHER_CTX_free(ctx);
  return ciphertext_len;
}

// Function to perform term extraction from encrypted text using regular expressions
int extract_terms(const unsigned char* ciphertext, int ciphertext_len, const char* terms[], int num_terms) {
  // Initialize regular expression engine and compile regular expressions
  regex_t re;
  regcomp(&re, TERM_REGEX, REG_EXTENDED | REG_ICASE);
  for (int i = 0; i < num_terms; i++) {
    regcomp(&re, terms[i], REG_EXTENDED | REG_ICASE);
  }

  // Perform regular expression matching on encrypted text
  int matches = 0;
  for (int i = 0; i < ciphertext_len; i++) {
    regmatch_t match[1];
    if (regexec(&re, ciphertext + i, 1, match, 0) == 0) {
      matches++;
    }
  }

  // Free resources and return result
  regfree(&re);
  return matches;
}

// Function to perform term extraction from decrypted text using regular expressions
int extract_terms(const unsigned char* plaintext, int plaintext_len, const char* terms[], int num_terms) {
  // Initialize regular expression engine and compile regular expressions
  regex_t re;
  regcomp(&re, TERM_REGEX, REG_EXTENDED | REG_ICASE);
  for (int i = 0; i < num_terms; i++) {
    regcomp(&re, terms[i], REG_EXTENDED | REG_ICASE);
  }

  // Perform regular expression matching on decrypted text
  int matches = 0;
  for (int i = 0; i < plaintext_len; i++) {
    regmatch_t match[1];
    if (regexec(&re, plaintext + i, 1, match, 0) == 0) {
      matches++;
    }
  }

  // Free resources and return result
  regfree(&re);
  return matches;
}
