#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdbool.h>
#include <sqlite3.h>

// Custom memory manager
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);
}

// Function to send data to the database server and process the state object
DataTableReader* sendDataAndProcessState(byte* data, char* filePath, size_t sizeLimit, bool truncate) {
    // Open the file stream for reading
    FILE* fp = fopen(filePath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return NULL;
    }

    // Load the state object from the file stream
    State* state = custom_malloc(sizeof(State));
    if (fread(state, sizeof(State), 1, fp) != 1) {
        fprintf(stderr, "Failed to read state object: %s\n", strerror(errno));
        fclose(fp);
        return NULL;
    }

    // Close the file stream
    if (fclose(fp) == EOF) {
        fprintf(stderr, "Failed to close file stream: %s\n", strerror(errno));
        custom_free(state);
        return NULL;
    }

    // Check if the state object is an instance of MoSTState
    if (strcmp(state->type, "MoSTState") != 0) {
        fprintf(stderr, "Invalid state object type: %s\n", state->type);
        custom_free(state);
        return NULL;
    }

    // Send the byte array to the database server
    sqlite3* db = sqlite3_open("database.db", &err);
    if (db == NULL) {
        fprintf(stderr, "Failed to open database: %s\n", err);
        custom_free(state);
        return NULL;
    }

    // Prepare the SQL query
    char* sql = "INSERT INTO data VALUES (?);";
    sqlite3_stmt* stmt = sqlite3_prepare_v2(db, sql, -1, &err);
    if (stmt == NULL) {
        fprintf(stderr, "Failed to prepare SQL query: %s\n", err);
        custom_free(state);
        return NULL;
    }

    // Bind the byte array to the SQL query
    sqlite3_bind_blob(stmt, 1, data, sizeLimit, SQLITE_STATIC);

    // Execute the SQL query and get the result
    int rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        fprintf(stderr, "Failed to execute SQL query: %s\n", err);
        custom_free(state);
        return NULL;
    }

    // Get the result of the query as a DataTableReader object
    DataTableReader* reader = sqlite3_column_table_reader(stmt, 0);
    if (reader == NULL) {
        fprintf(stderr, "Failed to get result of SQL query: %s\n", err);
        custom_free(state);
        return NULL;
    }

    // Clean up the memory
    sqlite3_finalize(stmt);
    sqlite3_close(db);
    custom_free(state);

    return reader;
}
