    size_t max_size; // maximum pool size
    void* data[]; // array of pointers to allocated memory blocks
};

void init_memory_pool(struct memory_pool* pool, size_t initial_size) {
    pool->size = initial_size;
    pool->max_size = initial_size * 2;
    for (int i = 0; i < initial_size; i++) {
        pool->data[i] = malloc(sizeof(void*) * initial_size);
    }
}

void* allocate_memory(struct memory_pool* pool, size_t size) {
    if (pool->size >= pool->max_size) {
        // resize the pool if necessary
        pool->max_size = pool->max_size * 2;
        for (int i = 0; i < pool->size; i++) {
            pool->data[i] = realloc(pool->data[i], sizeof(void*) * pool->max_size);
        }
    }
    void* data = malloc(sizeof(void*) * size);
    pool->data[pool->size++] = data;
    return data;
}

void deallocate_memory(struct memory_pool* pool, void* data) {
    for (int i = 0; i < pool->size; i++) {
        if (pool->data[i] == data) {
            free(data);
            pool->size--;
            return;
        }
    }
}

