// Define the record structure
struct Record {
  int value;
};

// Define the memory pool class
class MemoryPool {
 public:
  // Constructor
  MemoryPool(size_t size) : size_(size), records_(new std::vector<Record>(size)) {}

  // Destructor
  ~MemoryPool() { delete records_; }

  // Allocate a record from the pool
  Record* allocate() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (free_.empty()) {
      return nullptr;
    }
    auto record = free_.back();
    free_.pop_back();
    allocated_.push_back(record);
    return record;
  }

  // Deallocate a record to the pool
  void deallocate(Record* record) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = std::find(allocated_.begin(), allocated_.end(), record);
    if (it != allocated_.end()) {
      free_.push_back(*it);
      allocated_.erase(it);
    }
  }

 private:
  // The size of the memory pool
  size_t size_;

  // The vector of records
  std::vector<Record>* records_;

  // The list of free records
  std::list<Record*> free_;

  // The list of allocated records
  std::list<Record*> allocated_;

  // The mutex to protect the pool
  std::mutex mutex_;
};

// Define the object reuse strategy class
class ObjectReuseStrategy {
 public:
  // Constructor
  ObjectReuseStrategy(size_t size) : size_(size), records_(new std::vector<Record>(size)) {}

  // Destructor
  ~ObjectReuseStrategy() { delete records_; }

  // Allocate a record from the pool
  Record* allocate() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (free_.empty()) {
      return nullptr;
    }
    auto record = free_.back();
    free_.pop_back();
    allocated_.push_back(record);
    return record;
  }

  // Deallocate a record to the pool
  void deallocate(Record* record) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = std::find(allocated_.begin(), allocated_.end(), record);
    if (it != allocated_.end()) {
      free_.push_back(*it);
      allocated_.erase(it);
    }
  }

 private:
  // The size of the memory pool
  size_t size_;

  // The vector of records
  std::vector<Record>* records_;

  // The list of free records
  std::list<Record*> free_;

  // The list of allocated records
  std::list<Record*> allocated_;

  // The mutex to protect the pool
  std::mutex mutex_;
};

// Define the memory management class
class MemoryManagement {
 public:
  // Constructor
  MemoryManagement(size_t size) : size_(size), records_(new std::vector<Record>(size)) {}

  // Destructor
  ~MemoryManagement() { delete records_; }

  // Allocate a record from the pool
  Record* allocate() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (free_.empty()) {
