    *offsets = (long**)malloc(sizeof(long*) * MEMORY_POOL_SIZE);

    // Initialize arrays with default values
    memset(*keys, 0, sizeof(int) * MEMORY_POOL_SIZE);
    memset(*offsets, 0, sizeof(long*) * MEMORY_POOL_SIZE);
