void populateTemperatures(const char *filename, double **temperature) {
    // Open the CSV file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Read the first line of the file to get the number of readings
    char *line = NULL;
    size_t len = 0;
    ssize_t read = getline(&line, &len, file);
    if (read == -1) {
        printf("Error: unable to read from file %s\n", filename);
        fclose(file);
        return;
    }

    // Parse the number of readings from the first line
    int numReadings = atoi(line);

    // Read each line of the file and populate the temperature array
    for (int i = 0; i < numReadings; i++) {
        read = getline(&line, &len, file);
        if (read == -1) {
            printf("Error: unable to read from file %s\n", filename);
            fclose(file);
            return;
        }

        // Parse the temperature value from the line
        double temp = atof(line);

        // Add the temperature value to the array
        (*temperature)[i] = temp;
    }

    // Close the file
    fclose(file);
}

// Function to handle malformed entries in the CSV file
void handleMalformedEntries(const char *filename, double **temperature) {
    // Open the CSV file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

