        fclose(file);
        return;
    }

    // Parse the number of readings from the first line
    int numReadings = atoi(line);

    // Read each line of the file and check for malformed entries
    for (int i = 0; i < numReadings; i++) {
        read = getline(&line, &len, file);
        if (read == -1) {
            printf("Error: unable to read from file %s\n", filename);
            fclose(file);
            return;
        }

        // Check for malformed entries in the line
        char *token = strtok(line, ",");
        while (token != NULL) {
            if (!isdigit(token[0])) {
                printf("Error: malformed entry found in file %s\n", filename);
                fclose(file);
                return;
            }
            token = strtok(NULL, ",");
        }
    }

    // Close the file
    fclose(file);
}
