// Function to send a byte array to a database server and return a DataTableReader object containing the result of the query
DataTableReader* execute_query(byte* data) {
    // Initialize a SQLite3 database connection
    sqlite3* db = NULL;
    int rc = sqlite3_open("example.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to open database: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

    // Prepare a statement for the query
    sqlite3_stmt* stmt = NULL;
    rc = sqlite3_prepare_v2(db, "SELECT * FROM example WHERE data = ?", -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

    // Bind the byte array as a parameter for the query
    rc = sqlite3_bind_blob(stmt, 1, data, strlen((char*)data), SQLITE_STATIC);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to bind parameter: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

    // Execute the query and retrieve the result as a DataTableReader object
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_ROW) {
        fprintf(stderr, "Failed to execute query: %s\n", sqlite3_errmsg(db));
        return NULL;
    }

    // Create a DataTableReader object from the result set
    DataTableReader* reader = (DataTableReader*)malloc(sizeof(DataTableReader));
    reader->data = stmt->data;
    reader->num_rows = stmt->num_rows;

    // Close the database connection and free any allocated memory
    sqlite3_finalize(stmt);
    sqlite3_close(db);
    free(data);

    return reader;
}
