    int num_keys = num_records * sizeof(int);
    int num_values = num_records * sizeof(Record);
    int total_size = num_offsets + num_keys + num_values;

    // Check for memory usage limits
    if (total_size > 10000000) {
        return NULL;
    }

    // Allocate the memory for the data structures
    void* data = malloc(total_size);
    if (!data) {
        return NULL;
    }

    // Initialize the arrays of long integers, int keys, and records
    long* offsets = (long*)data;
    int* keys = (int*)(offsets + num_records);
