        for (int j = 0; j < i; j++) {
            if (keys[j] == key) {
                duplicate = true;
                break;
            }
        }

        // If the key is not a duplicate, use it
        if (!duplicate) {
            keys[i] = key;
        } else {
            // If the key is a duplicate, generate a new one
            while (true) {
                int new_key = generate_random(key_min, key_max);
                duplicate = false;
                for (int j = 0; j < i; j++) {
                    if (keys[j] == new_key) {
                        duplicate = true;
                        break;
                    }
                }
                if (!duplicate) {
                    keys[i] = new_key;
                    break;
                }
            }
        }

        // Initialize the value within the specified range
        values[i].value = generate_random(value_min, value_max);
    }

    return data;
}

// Define a function to free the allocated memory for the arrays of long integers, int keys, and records
