void processRecordsAndLog(char* input, sqlite3* db) {
    // Initialize arrays for offsets, keys, and records
    long* offsets = (long*)malloc(sizeof(long) * 10);
    int* keys = (int*)malloc(sizeof(int) * 10);
    record* records = (record*)malloc(sizeof(record) * 10);

    // Initialize random number generator for generating random values
    srand(time(NULL));

