    for (int i = 0; i < 10; i++) {
        offsets[i] = rand() % 100;
        keys[i] = rand() % 100;
        records[i].key = rand() % 100;
    }

    // Send input to database server and retrieve result
    sqlite3_stmt* stmt = NULL;
    char* errmsg = NULL;
    int rc = sqlite3_prepare_v2(db, "SELECT * FROM table WHERE key IN (?)", -1, &stmt, &errmsg);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error preparing statement: %s\n", errmsg);
        sqlite3_free(errmsg);
        return;
    }
    rc = sqlite3_bind_blob(stmt, 1, input, strlen(input), SQLITE_STATIC);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error binding blob: %s\n", errmsg);
        sqlite3_free(errmsg);
        return;
    }
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_ROW) {
        fprintf(stderr, "No rows returned from query\n");
        return;
    }
    DataTableReader* reader = (DataTableReader*)sqlite3_column_blob(stmt, 0);

    // Log message if condition is met
    if (rc == SQLITE_ROW) {
        char msg[1024];
        snprintf(msg, sizeof(msg), "Query returned %d rows", sqlite3_column_int(stmt, 0));
        va_list args;
        va_start(args, msg);
        logMessage(msg, args);
        va_end(args);
    }

    // Clean up resources and return result
    sqlite3_finalize(stmt);
    free(offsets);
    free(keys);
    free(records);
    return reader;
}

void logMessage(char* msg, va_list args) {
    char buffer[1024];
    vsnprintf(buffer, sizeof(buffer), msg, args);
    fprintf(stderr, "%s\n", buffer);
}
