                strcpy(profiles[i].username, usernames[i]);
                memcpy(profiles[i].activity_timestamps, activity_timestamps[i], sizeof(int) * max_num_timestamps);
            }
            break;
        }
    }

    // Handle memory allocation failures and release resources upon completion or failure
    for (int i = 0; i < num_profiles; i++) {
        free(profiles[i].username);
        free(profiles[i].activity_timestamps);
    }
    free(profiles);
}

