    SensorReading reading;
    struct Node* next;
} Node;

// Define a function to allocate memory for the linked list
Node* alloc_node() {
    return (Node*) malloc(sizeof(Node));
}

// Define a function to initialize the linked list
void init_list(Node** head) {
    *head = NULL;
}

