void add_node(Node** head, SensorReading reading) {
    Node* new_node = alloc_node();
    new_node->reading = reading;
    new_node->next = *head;
    *head = new_node;
}

// Define a function to retrieve the last node in the linked list
Node* get_last_node(Node** head) {
    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    return current;
}

// Define a function to remove the last node in the linked list
void remove_last_node(Node** head) {
    Node* current = *head;
    while (current->next != NULL && current->next->next != NULL) {
        current = current->next;
    }
    if (current->next == NULL) {
        free(current);
        *head = NULL;
    } else {
        Node* last_node = get_last_node(head);
        free(last_node);
        current->next = NULL;
    }
}

// Define a function to retrieve the number of nodes in the linked list
int count_nodes(Node** head) {
    int count = 0;
    Node* current = *head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

