        printf("Latitude: %.2f\n", current->reading.latitude);
        printf("Longitude: %.2f\n", current->reading.longitude);
        printf("Temperature: %.2f\n", current->reading.temperature);
        printf("Humidity: %.2f\n", current->reading.humidity);
        printf("Pressure: %.2f\n", current->reading.pressure);
        current = current->next;
    }
}

// Define a function to retrieve the average temperature from the linked list
double get_avg_temperature(Node** head) {
    double sum = 0;
    int count = 0;
    Node* current = *head;
    while (current != NULL) {
        sum += current->reading.temperature;
        count++;
        current = current->next;
    }
    return sum / count;
}

// Define a function to retrieve the standard deviation of temperatures from the linked list
double get_stddev_temperature(Node** head) {
    double avg = get_avg_temperature(head);
    double sum = 0;
    int count = 0;
    Node* current = *head;
    while (current != NULL) {
        sum += pow((current->reading.temperature - avg), 2);
        count++;
        current = current->next;
    }
    return sqrt(sum / count);
}

