void process_file(char* input_filename, char* output_filename, char* rules) {
    // Open the input file and read its contents into a buffer
    FILE* input_file = fopen(input_filename, "rb");
    if (input_file == NULL) {
        printf("Error: unable to open input file\n");
        return;
    }
    fseek(input_file, 0, SEEK_END);
    long file_size = ftell(input_file);
    rewind(input_file);
    char* buffer = (char*)malloc(file_size * sizeof(char));
    if (buffer == NULL) {
        printf("Error: unable to allocate memory for input file\n");
        fclose(input_file);
        return;
    }
    size_t bytes_read = fread(buffer, 1, file_size, input_file);
    if (bytes_read < file_size) {
        printf("Error: unable to read entire input file\n");
        free(buffer);
        fclose(input_file);
        return;
    }
    fclose(input_file);

    // Parse the contents of the buffer and generate an output file based on the rules
    long* offset_array = (long*)malloc(sizeof(long) * 100);
    int* key_array = (int*)malloc(sizeof(int) * 100);
    record* record_array = (record*)malloc(sizeof(record) * 100);
