    entry->value = value;
    entry->next = NULL;
    if (bucket->head == NULL) {
        bucket->head = entry;
    } else {
        bucket->tail->next = entry;
    }
    bucket->size++;
}

void hashMap_removeEntry(hashMap_t* map, char* key) {
    if (map->size == 0) {
        return;
    }
    int bucketIndex = hashMap_getBucketIndex(key);
    hashMapBucket_t* bucket = &map->buckets[bucketIndex];
    hashMapEntry_t* current = bucket->head;
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            break;
        }
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    hashMapEntry_t* previous = current->previous;
    if (current == bucket->head) {
        bucket->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
    bucket->size--;
}
