#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    char identifier[256]; // truncate if exceeds 255 characters
} Record;

// Define the dataset structure
typedef struct {
    long *offset_array;
    int *key_array;
    Record *record_array;
    size_t record_count;
    size_t max_records;
    pthread_mutex_t mutex; // for thread safety
} Dataset;

// Initialize the dataset with a maximum number of records
void init_dataset(Dataset *ds, size_t max_records) {
    ds->offset_array = malloc(max_records * sizeof(long));
    ds->key_array = malloc(max_records * sizeof(int));
    ds->record_array = malloc(max_records * sizeof(Record));
    ds->record_count = 0;
    ds->max_records = max_records;
    pthread_mutex_init(&ds->mutex, NULL);
}

// Add a new record to the dataset
void add_record(Dataset *ds, int key, long offset) {
    // Acquire lock for thread safety
    pthread_mutex_lock(&ds->mutex);

    // Check if there is space available in the array
    if (ds->record_count >= ds->max_records) {
        // Release lock and return
        pthread_mutex_unlock(&ds->mutex);
        return;
    }

    // Add new record to the arrays
    ds->offset_array[ds->record_count] = offset;
    ds->key_array[ds->record_count] = key;
    Record *record = &ds->record_array[ds->record_count];
    record->key = key;
    strncpy(record->identifier, "Record ", 256); // truncate if exceeds 255 characters
    ds->record_count++;

    // Release lock
    pthread_mutex_unlock(&ds->mutex);
}

// Get the number of records in the dataset
size_t get_record_count(Dataset *ds) {
    return ds->record_count;
}

// Get the total memory usage of the dataset
size_t get_memory_usage(Dataset *ds) {
    return sizeof(long) * ds->max_records + sizeof(int) * ds->max_records + sizeof(Record) * ds->max_records;
}

// Get the average memory per record in the dataset
size_t get_average_memory_per_record(Dataset *ds) {
    return get_memory_usage(ds) / ds->record_count;
}

// Free the dataset and its arrays
void free_dataset(Dataset *ds) {
    pthread_mutex_destroy(&ds->mutex);
    free(ds->offset_array);
    free(ds->key_array);
    free(ds->record_array);
}
