```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a record in the dataset
typedef struct {
    long offset;
    int key;
    char identifier[256]; // truncated to 255 characters
    void* metadata; // user-defined data
} Record;

// Define the linked list node for storing records
typedef struct Node {
    Record record;
    struct Node* next;
} Node;

// Define the dataset structure
typedef struct {
    int num_records;
    size_t total_memory;
    double average_memory_per_record;
    Node* head; // linked list of records
    pthread_mutex_t mutex; // mutex for thread safety
} Dataset;

// Define the metadata schema
typedef struct {
    char* key;
    void* value;
} Metadata;

// Function to initialize a new dataset
void init_dataset(Dataset* dataset) {
    dataset->num_records = 0;
    dataset->total_memory = 0;
    dataset->average_memory_per_record = 0.0;
    dataset->head = NULL;
    pthread_mutex_init(&dataset->mutex, NULL);
}

// Function to add a new record to the dataset
void add_record(Dataset* dataset, long offset, int key, char* identifier, void* metadata) {
    // Allocate memory for the new record
    Record* new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for new record\n");
        return;
    }

    // Initialize the new record
    new_record->offset = offset;
    new_record->key = key;
    strncpy(new_record->identifier, identifier, 256);
    new_record->metadata = metadata;

    // Add the new record to the linked list
    pthread_mutex_lock(&dataset->mutex);
    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for new node\n");
        return;
    }
    node->record = *new_record;
    node->next = dataset->head;
    dataset->head = node;
    dataset->num_records++;
    dataset->total_memory += sizeof(Record);
    dataset->average_memory_per_record = (double)dataset->total_memory / dataset->num_records;
    pthread_mutex_unlock(&dataset->mutex);
}

// Function to remove a record from the dataset
void remove_record(Dataset* dataset, long offset) {
    // Find the node corresponding to the given offset
    Node* node = dataset->head;
    while (node != NULL && node->record.offset != offset) {
        node = node->next;
    }

    // If the node was found, remove it from the linked list and free its memory
    if (node != NULL) {
        pthread_mutex_lock(&dataset->mutex);
        Node* prev_node = dataset->head;
        while (prev_node->next != node) {
            prev_node = prev_node->next;
        }
        prev_node->next = node->next;
        free(node);
        dataset->num_records--;
        dataset->total_memory -= sizeof(Record);
        dataset->average_memory_per_record = (double)dataset->total_memory / dataset->num_records;
        pthread_mutex_unlock(&dataset->mutex);
    }
}

// Function to update a record in the dataset
void update_record(Dataset* dataset, long offset, int key, char* identifier, void* metadata) {
    // Find the node corresponding to the given offset
    Node* node = dataset->head;
    while (node != NULL && node->record.offset != offset) {
        node = node->next;
    }

    // If the node was found, update its record and metadata
    if (node != NULL) {
        pthread_mutex_lock(&dataset->mutex);
        node->record.key = key;
        strncpy(node->record.identifier, identifier, 256);
        node->record.metadata = metadata;
        pthread_mutex_unlock(&dataset->mutex);
    }
}

// Function to retrieve a record from the dataset
Record* get_record(Dataset* dataset, long offset) {
    // Find the node corresponding to the given offset
    Node* node = dataset->head;
    while (node != NULL && node->record.offset != offset) {
        node = node->next;
    }

    // If the node was found, return its record
    if (node != NULL) {
        pthread_mutex_lock(&dataset->mutex);
        Record* record = malloc(sizeof(Record));
        *record = node->record;
        pthread_mutex_unlock(&dataset->mutex);
        return record;
    } else {
        return NULL;
    }
}

// Function to export the dataset to a file
void export_dataset(Dataset* dataset, char* filename) {
    // Open the output file for writing
    FILE* outfile = fopen(filename, "w");
    if (outfile == NULL) {
        fprintf(stderr, "Error: failed to open output file\n");
        return;
    }

    // Write the header line with the number of records and total memory usage
    fprintf(outfile, "%d %zu\n", dataset->num_records, dataset->total_memory);

    // Iterate over each record in the linked list and write its data to the file
    Node* node = dataset->head;
    while (node != NULL) {
        Record* record = &node->record;
        fprintf(outfile, "%ld %d %s", record->offset, record->key, record->identifier);
        if (record->metadata != NULL) {
            fprintf(outfile, " %p", record->metadata);
        }
        fprintf(outfile, "\n");
        node = node->next;
    }

    // Close the output file
    fclose(outfile);
}
