// Function to securely store and manage the derived key and IV between sessions, using file-based storage with appropriate access controls
void store_key_iv(const char* password, const unsigned char* key, const unsigned char* iv) {
    // Define a path for storing the key and IV
    char* key_path = "./key.bin";
    char* iv_path = "./iv.bin";

    // Open the file for writing in binary mode
    FILE* key_file = fopen(key_path, "wb");
    if (!key_file) {
        printf("Error: Failed to open key file\n");
        return;
    }
    FILE* iv_file = fopen(iv_path, "wb");
    if (!iv_file) {
        printf("Error: Failed to open IV file\n");
        return;
    }

    // Write the key and IV to the files
    size_t key_length = KEY_LENGTH;
    size_t iv_length = IV_LENGTH;
    if (fwrite(key, 1, key_length, key_file) != key_length || fwrite(iv, 1, iv_length, iv_file) != iv_length) {
        printf("Error: Failed to write key and IV to files\n");
        return;
    }

    // Close the files
    fclose(key_file);
    fclose(iv_file);
}

// Function to securely delete the key and IV from memory after they are no longer needed, ensuring that no trace of the sensitive data remains
void delete_key_iv(const unsigned char* key, const unsigned char* iv) {
    // Zero out the key and IV in memory
    memset(key, 0, KEY_LENGTH);
    memset(iv, 0, IV_LENGTH);

    // Flush memory contents to disk at regular intervals to prevent transient data recovery attacks
    if (fflush(NULL) != 0) {
        printf("Error: Failed to flush memory contents to disk\n");
        return;
    }
}

// Function to handle potential errors during key derivation, IV generation, and storage, providing detailed error messages for debugging purposes
void handle_errors() {
    // Handle resource exhaustion and disk I/O failures
    if (errno == ENOMEM || errno == ENOSPC) {
        printf("Error: Insufficient resources to perform key derivation or IV generation\n");
        return;
    } else if (errno == EIO) {
        printf("Error: Disk I/O error during key derivation or IV generation\n");
        return;
    }

    // Handle unexpected resource leaks, including memory leaks and open file handles
    if (errno == ENOMEM || errno == EBADF) {
        printf("Error: Unexpected resource leak during key derivation or IV generation\n");
        return;
    }
}
