// Define the function to manage multiple dynamically allocated data structures
void manage_data(int num_entries) {
    // Allocate memory for an array of struct data_entry pointers
    struct data_entry **entries = malloc(num_entries * sizeof(struct data_entry));

    // Check if allocation was successful
    if (entries == NULL) {
        printf("Error: Failed to allocate memory for entries\n");
        return;
    }

    // Initialize the buffer and timestamp for each struct data_entry
    for (int i = 0; i < num_entries; i++) {
        entries[i] = malloc(sizeof(struct data_entry));
        if (entries[i] == NULL) {
            printf("Error: Failed to allocate memory for entry %d\n", i);
            return;
        }
        entries[i]->buffer = malloc(256 * sizeof(char));
        if (entries[i]->buffer == NULL) {
            printf("Error: Failed to allocate memory for buffer of entry %d\n", i);
            return;
        }
        entries[i]->timestamp = time(NULL);
        srand(entries[i]->timestamp);
        entries[i]->metadata = malloc(sizeof(struct metadata));
        if (entries[i]->metadata == NULL) {
            printf("Error: Failed to allocate memory for metadata of entry %d\n", i);
            return;
        }
    }

    // Initialize the value and metrics array for each struct data_entry
    for (int i = 0; i < num_entries; i++) {
        entries[i]->metadata->value = rand() / (float)RAND_MAX;
        int size = entries[i]->timestamp % 100;
        entries[i]->metadata->metrics = malloc(size * sizeof(double));
        if (entries[i]->metadata->metrics == NULL) {
            printf("Error: Failed to allocate memory for metrics of entry %d\n", i);
            return;
        }
        for (int j = 0; j < size; j++) {
            entries[i]->metadata->metrics[j] = rand() / (double)RAND_MAX * 200 - 100;
        }
    }

    // Fill each double element in the metrics array with a random floating-point number between -100.0 and 100.0
    for (int i = 0; i < num_entries; i++) {
        int size = entries[i]->timestamp % 100;
        for (int j = 0; j < size; j++) {
            entries[i]->metadata->metrics[j] = rand() / (double)RAND_MAX * 200 - 100;
        }
    }

    // Free the memory allocated for each struct data_entry
    for (int i = 0; i < num_entries; i++) {
        free(entries[i]->buffer);
        free(entries[i]->metadata->metrics);
        free(entries[i]);
    }

    // Free the memory allocated for the array of struct data_entry pointers
    free(entries);
}

// Helper function to verify that all allocations were successful by checking the presence of NULL pointers and ensuring that no out-of-bounds access occurs during initialization
void check_allocations() {
    // Check if any of the allocated memory is NULL
    for (int i = 0; i < num_entries; i++) {
        if (entries[i] == NULL) {
            printf("Error: Failed to allocate memory for entry %d\n", i);
            return;
        }
        if (entries[i]->buffer == NULL) {
            printf("Error: Failed to allocate memory for buffer of entry %d\n", i);
            return;
        }
        if (entries[i]->metadata == NULL) {
            printf("Error: Failed to allocate memory for metadata of entry %d\n", i);
            return;
        }
    }
