int allocate_memory(record **records, long **offsets, int **keys) {
    // Allocate memory for record array with initial capacity of 1000 elements
    *records = (record *)malloc(sizeof(record) * 1000);
    if (*records == NULL) {
        log_error("Failed to allocate memory for records");
        return -1;
    }

    // Allocate memory for offset array with initial capacity of 10,000 elements
    *offsets = (long *)malloc(sizeof(long) * 10000);
    if (*offsets == NULL) {
        log_error("Failed to allocate memory for offsets");
        free(*records);
        return -2;
    }

    // Allocate memory for key array with initial capacity of 5,000 unique values
    *keys = (int *)malloc(sizeof(int) * 5000);
    if (*keys == NULL) {
        log_error("Failed to allocate memory for keys");
        free(*records);
        free(*offsets);
        return -3;
    }

    // Initialize record array with random values within specified range
    srand(time(NULL));
    for (int i = 0; i < 1000; i++) {
        (*records)[i].int_field = rand() % 100 + 1;
        (*records)[i].status = 'U';
    }

    // Initialize offset array with initial capacity of 10,000 elements
    for (int i = 0; i < 10000; i++) {
        (*offsets)[i] = 0;
    }

    // Initialize key array with initial capacity of 5,000 unique values
    for (int i = 0; i < 5000; i++) {
        (*keys)[i] = rand() % 100 + 1;
    }

    return 0;
}

