void update_records(record *records, int num_records) {
    // Update status for each record based on condition
    for (int i = 0; i < num_records; i++) {
        if ((*records)[i].int_field > 50) {
            (*records)[i].status = 'A';
        } else {
            (*records)[i].status = 'U';
        }
    }
}

