void manage_config(config_data_t* config) {
    // Check for invalid input parameters
    if (config == NULL || config->num_configs <= 0 || config->num_offsets <= 0 || config->num_keys <= 0) {
        return;
    }

    // Allocate memory for the configuration structures and offsets
    config->configs = malloc(sizeof(config_setting_t) * config->num_configs);
    config->offsets = malloc(sizeof(offset_key_t) * config->num_offsets);
    config->keys = malloc(sizeof(char*) * config->num_keys);

