    for (int i = 0; i < config->num_configs; i++) {
        config->configs[i].name = malloc(sizeof(char) * 10);
        config->configs[i].default_value = 0;
        config->configs[i].current_value = 0;
        config->configs[i].type = 0;
    }
    for (int i = 0; i < config->num_offsets; i++) {
        config->offsets[i].offset = 0;
        config->offsets[i].key = malloc(sizeof(char) * 10);
    }
    for (int i = 0; i < config->num_keys; i++) {
        config->keys[i] = malloc(sizeof(char) * 10);
    }

    // Check for memory allocation failures
    if (config->configs == NULL || config->offsets == NULL || config->keys == NULL) {
        return;
    }

    // Initialize the configuration settings and offsets
    for (int i = 0; i < config->num_configs; i++) {
        strcpy(config->configs[i].name, "");
        config->configs[i].default_value = 0;
        config->configs[i].current_value = 0;
        config->configs[i].type = 0;
    }
    for (int i = 0; i < config->num_offsets; i++) {
        config->offsets[i].offset = 0;
        strcpy(config->offsets[i].key, "");
    }
    for (int i = 0; i < config->num_keys; i++) {
        strcpy(config->keys[i], "");
    }

    // Initialize the synchronization mechanisms
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Define the function to update the configuration settings
    void update_config(config_data_t* config, int index, int value) {
        // Check for invalid input parameters
        if (config == NULL || index < 0 || index >= config->num_configs || value < 0) {
            return;
        }

        // Acquire the lock on the configuration settings
        pthread_mutex_lock(&mutex);

        // Update the current value of the configuration setting
        config->configs[index].current_value = value;

        // Release the lock on the configuration settings
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to validate and update the current value based on specific conditions related to the default and current values, as well as the type of setting
    void validate_update(config_data_t* config, int index) {
        // Check for invalid input parameters
        if (config == NULL || index < 0 || index >= config->num_configs) {
            return;
        }

        // Acquire the lock on the configuration settings
        pthread_mutex_lock(&mutex);

        // Validate and update the current value based on specific conditions related to the default and current values, as well as the type of setting
        if (config->configs[index].type == 0) { // Integer
            if (config->configs[index].default_value < config->configs[index].current_value) {
                config->configs[index].current_value = config->configs[index].default_value;
            } else if (config->configs[index].default_value > config->configs[index].current_value) {
                config->configs[index].current_value = config->configs[index].default_value;
            }
        } else if (config->configs[index].type == 1) { // String
            if (strcmp(config->configs[index].default_value, config->configs[index].current_value) != 0) {
                strcpy(config->configs[index].current_value, config->configs[index].default_value);
            }
        } else if (config->configs[index].type == 2) { // Boolean
            if (!config->configs[index].current_value) {
                config->configs[index].current_value = config->configs[index].default_value;
            }
        }

        // Release the lock on the configuration settings
        pthread_mutex_unlock(&mutex);
