        // Check if the key is valid and the integer value falls within the specified range
        if (key >= 0 && key < keys.size() && records[key].value >= minValue && records[key].value <= maxValue) {
            // Update the status indicator for the corresponding record
            records[key].status = status;
        } else {
            // Log an error message if the key is invalid or the integer value falls outside the specified range
            std::cerr << "Invalid key or integer value out of range" << std::endl;
        }
    }

private:
