// Define a function to compress the array of sensor readings when the density of non-zero readings falls below a certain threshold
void compressSensorReadings() {
    // Calculate the density of non-zero readings
    int numNonZero = 0;
    for (int i = 0; i < numReadings; i++) {
        if (readings[i].value != 0) {
            numNonZero++;
        }
    }
    // Calculate the compression ratio based on the density of non-zero readings
    double compressionRatio = (double)numReadings / numNonZero;
    // Compress the array of sensor readings using a custom algorithm that balances compression ratio and decompression speed
    for (int i = 0; i < numReadings; i++) {
        if (readings[i].value == 0) {
            readings[i] = getDefaultValue();
        } else {
            readings[i] = readings[i] / compressionRatio;
        }
    }
}
