import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class ConfigurationManager {
    private static final int MIN_CAPACITY = 5000;
    private static final int INITIAL_CAPACITY = 1000;
    private static final int RESIZE_FACTOR = 100;

    // Map to store configuration settings with associated metadata
    private ConcurrentHashMap<String, Configuration> configurations;

    // Arrays to store unique string keys and corresponding configuration structures
    private String[] keyArray;
    private Configuration[] configArray;

    // Current size of the arrays
    private int currentSize;

    // Maximum allowed memory usage in bytes
    private long maxMemoryUsage;

    public ConfigurationManager(long maxMemoryUsage) {
        this.maxMemoryUsage = maxMemoryUsage;
        configurations = new ConcurrentHashMap<>();
        keyArray = new String[MIN_CAPACITY];
        configArray = new Configuration[INITIAL_CAPACITY];
        currentSize = 0;
    }

    public void addConfiguration(String name, Object value) {
        // Check if the configuration already exists
        if (configurations.containsKey(name)) {
            throw new IllegalArgumentException("Configuration with name " + name + " already exists");
        }

        // Calculate the MD5 hash of the configuration name
        String md5Hash = calculateMD5Hash(name);

        // Add the configuration to the map
        configurations.put(md5Hash, new Configuration(name, value));

        // Update the arrays if necessary
        updateArrays();
    }

    public void removeConfiguration(String name) {
        // Check if the configuration exists
        if (!configurations.containsKey(calculateMD5Hash(name))) {
            throw new IllegalArgumentException("Configuration with name " + name + " does not exist");
        }

        // Remove the configuration from the map
        configurations.remove(calculateMD5Hash(name));

        // Update the arrays if necessary
        updateArrays();
    }

    public Object getConfigurationValue(String name) {
        // Calculate the MD5 hash of the configuration name
        String md5Hash = calculateMD5Hash(name);

        // Check if the configuration exists
        if (!configurations.containsKey(md5Hash)) {
            throw new IllegalArgumentException("Configuration with name " + name + " does not exist");
        }

        // Return the value of the configuration
        return configurations.get(md5Hash).getValue();
    }

    public void setConfigurationValue(String name, Object value) {
        // Calculate the MD5 hash of the configuration name
        String md5Hash = calculateMD5Hash(name);

        // Check if the configuration exists
        if (!configurations.containsKey(md5Hash)) {
            throw new IllegalArgumentException("Configuration with name " + name + " does not exist");
        }

        // Update the value of the configuration
        configurations.get(md5Hash).setValue(value);
    }

    public void updateArrays() {
        // Check if the current size is greater than the maximum allowed size
        if (currentSize > maxMemoryUsage) {
            throw new IllegalStateException("Maximum memory usage exceeded");
        }

        // Update the arrays if necessary
        if (configurations.size() > keyArray.length - 1) {
            resizeArrays();
        }
    }

    private void resizeArrays() {
        // Calculate the new size of the arrays
        int newSize = Math.min(keyArray.length + RESIZE_FACTOR, configurations.size());

        // Resize the arrays
        String[] newKeyArray = new String[newSize];
        Configuration[] newConfigArray = new Configuration[newSize];

        // Copy the elements from the old arrays to the new arrays
        System.arraycopy(keyArray, 0, newKeyArray, 0, keyArray.length);
        System.arraycopy(configArray, 0, newConfigArray, 0, configArray.length);

        // Update the references to the arrays
        keyArray = newKeyArray;
        configArray = newConfigArray;
    }

    private String calculateMD5Hash(String name) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hash = md.digest(name.getBytes());
            return bytesToHex(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("Failed to calculate MD5 hash", e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            sb.append(String.format("%02x", bytes[i]));
        }
        return sb.toString();
    }
}
