#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to store configuration settings with associated metadata
typedef struct Configuration {
    char* name;
    void* value;
} Configuration;

// Define the dynamic data structure to store configurations
typedef struct Configurations {
    int size;
    int capacity;
    Configuration** configs;
} Configurations;

// Function to add a configuration setting with associated metadata
void addConfiguration(Configurations* configs, char* name, void* value) {
    // Check if the configuration already exists
    for (int i = 0; i < configs->size; i++) {
        if (strcmp(configs->configs[i]->name, name) == 0) {
            return;
        }
    }

    // Allocate memory for the new configuration setting
    Configuration* newConfig = malloc(sizeof(Configuration));
    newConfig->name = strdup(name);
    newConfig->value = value;

    // Add the new configuration to the array
    configs->configs[configs->size++] = newConfig;

    // Check if the capacity of the array needs to be increased
    if (configs->size == configs->capacity) {
        configs->capacity += 100;
        configs->configs = realloc(configs->configs, sizeof(Configuration*) * configs->capacity);
    }
}

// Function to remove a configuration setting with associated metadata
void removeConfiguration(Configurations* configs, char* name) {
    // Find the index of the configuration setting to be removed
    int index = -1;
    for (int i = 0; i < configs->size; i++) {
        if (strcmp(configs->configs[i]->name, name) == 0) {
            index = i;
            break;
        }
    }

    // Check if the configuration setting exists
    if (index == -1) {
        return;
    }

    // Remove the configuration setting from the array
    configs->size--;
    for (int i = index; i < configs->size; i++) {
        configs->configs[i] = configs->configs[i + 1];
    }

    // Free the memory allocated for the configuration setting
    free(configs->configs[index]->name);
    free(configs->configs[index]);
}

// Function to get the value of a configuration setting with associated metadata
void* getConfigurationValue(Configurations* configs, char* name) {
    // Find the index of the configuration setting
    int index = -1;
    for (int i = 0; i < configs->size; i++) {
        if (strcmp(configs->configs[i]->name, name) == 0) {
            index = i;
            break;
        }
    }

    // Check if the configuration setting exists
    if (index == -1) {
        return NULL;
    }

    // Return the value of the configuration setting
    return configs->configs[index]->value;
}

// Function to set the value of a configuration setting with associated metadata
void setConfigurationValue(Configurations* configs, char* name, void* value) {
    // Find the index of the configuration setting
    int index = -1;
    for (int i = 0; i < configs->size; i++) {
        if (strcmp(configs->configs[i]->name, name) == 0) {
            index = i;
            break;
        }
    }

    // Check if the configuration setting exists
    if (index == -1) {
        return;
    }

    // Set the value of the configuration setting
    configs->configs[index]->value = value;
}

// Function to update the arrays if necessary
void updateArrays(Configurations* configs) {
    // Check if the current size is greater than the maximum allowed size
    if (configs->size > configs->capacity - 100) {
        configs->capacity += 100;
        configs->configs = realloc(configs->configs, sizeof(Configuration*) * configs->capacity);
    }
}

// Function to handle memory allocation failures gracefully
void* safeMalloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}
