        }

        // Compute the MD5 hash of the uploaded file
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] bytes = md.digest(uploadedUrl.getBytes());
        String hash = bytesToHexString(bytes);

        // Store the computed hash in the cache for future use
        CACHE.put(file.getName(), hash);

        LOGGER.log(Level.INFO, "Computed MD5 hash of uploaded file: {0}", hash);
        return new URL(uploadedUrl + "#" + hash);
