#include <iostream>
#include <vector>
#include <string>
#include <cmath>

struct Point {
  int x;
  int y;
  int id;
};

std::vector<Point> points;
std::vector<double> distances;
std::vector<std::string> labels;

void initializeDataStructures(int numPoints) {
  // Allocate memory for the arrays
  points.resize(numPoints);
  distances.resize(numPoints * (numPoints - 1) / 2);
  labels.resize(numPoints);
}

void calculateDistances() {
  // Calculate the Euclidean distance between each pair of points
  for (int i = 0; i < numPoints; ++i) {
    for (int j = i + 1; j < numPoints; ++j) {
      distances[i * (numPoints - 1) / 2 + j - i - 1] = sqrt(pow(points[i].x - points[j].x, 2) + pow(points[i].y - points[j].y, 2));
    }
  }
}

void processLabels(const std::vector<std::string>& labels) {
  // Filter out non-alphanumeric characters and store the cleaned strings in the vector
  for (int i = 0; i < numPoints; ++i) {
    std::string label = labels[i];
    std::string cleanLabel;
    for (char c : label) {
      if (isalnum(c)) {
        cleanLabel += c;
      }
    }
    labels[i] = cleanLabel;
  }
}

void releaseResources() {
  // Release memory allocated for the arrays
  points.clear();
  distances.clear();
  labels.clear();
}

int main() {
  int numPoints = 10;
  initializeDataStructures(numPoints);
  calculateDistances();
  processLabels({"label1", "label2", "label3", "label4", "label5"});
  releaseResources();
  return 0;
}
```
This code defines a `Point` struct to represent the coordinates and unique identifier of each point, and three arrays: `points`, `distances`, and `labels`. The `initializeDataStructures` function allocates memory for these arrays using the `resize` method. The `calculateDistances` function calculates the Euclidean distance between each pair of points and stores the distances in the `distances` array. The `processLabels` function filters out non-alphanumeric characters from a list of strings and stores the cleaned strings in the `labels` vector. Finally, the `releaseResources` function releases memory allocated for the arrays using the `clear` method.

The code also includes a `main` function that demonstrates how to use these functions together. It initializes the data structures with 10 points, calculates the distances between each pair of points, processes a list of labels, and then releases the resources allocated for the arrays.']

