    if (!strcmp(algo, "SHA-256")) {
        // Perform the SHA-256 operation using the specified mode
        sha256(data);
    } else if (!strcmp(algo, "AES-CBC")) {
        // Perform the AES-CBC operation using the specified mode
        aes_cbc(data);
    } else if (!strcmp(algo, "RSA-OAEP")) {
        // Perform the RSA-OAEP operation using the specified mode
        rsa_oaep(data);
    } else {
        // If the algorithm is not supported, return an error message
        printf("Error: Algorithm %s is not supported\n", algo);
    }
}
