#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdio.h>
#include <pthread.h>

// Define the struct for data entry
struct data_entry {
    char *buffer;
    int timestamp;
    struct metadata *metadata;
};

// Define the struct for metadata
struct metadata {
    float value;
    double *metrics;
};

// Define the function to allocate memory for an array of data entries
void allocate_data_entries(int num_entries) {
    // Allocate memory for the array of data entry pointers
    struct data_entry **data_entries = malloc(num_entries * sizeof(struct data_entry));
    if (data_entries == NULL) {
        printf("Error: Failed to allocate memory for data entries\n");
        return;
    }

    // Initialize the array of data entry pointers
    for (int i = 0; i < num_entries; i++) {
        struct data_entry *data_entry = malloc(sizeof(struct data_entry));
        if (data_entry == NULL) {
            printf("Error: Failed to allocate memory for data entry %d\n", i);
            return;
        }
        data_entries[i] = data_entry;
    }

    // Initialize the buffer and timestamp for each data entry
    for (int i = 0; i < num_entries; i++) {
        struct data_entry *data_entry = data_entries[i];
        data_entry->buffer = malloc(256);
        if (data_entry->buffer == NULL) {
            printf("Error: Failed to allocate memory for buffer in data entry %d\n", i);
            return;
        }
        data_entry->timestamp = time(NULL);
    }

    // Initialize the metadata for each data entry
    for (int i = 0; i < num_entries; i++) {
        struct data_entry *data_entry = data_entries[i];
        data_entry->metadata = malloc(sizeof(struct metadata));
        if (data_entry->metadata == NULL) {
            printf("Error: Failed to allocate memory for metadata in data entry %d\n", i);
            return;
        }
        data_entry->metadata->value = rand() / (float)RAND_MAX;
        int metrics_size = data_entry->timestamp % 100;
        data_entry->metadata->metrics = malloc(metrics_size * sizeof(double));
        if (data_entry->metadata->metrics == NULL) {
            printf("Error: Failed to allocate memory for metrics in data entry %d\n", i);
            return;
        }
    }

    // Fill the metrics array with random floating-point numbers between -100.0 and 100.0
    for (int i = 0; i < num_entries; i++) {
        struct data_entry *data_entry = data_entries[i];
        int metrics_size = data_entry->timestamp % 100;
        for (int j = 0; j < metrics_size; j++) {
            data_entry->metadata->metrics[j] = ((double)rand() / RAND_MAX) * 200.0 - 100.0;
        }
    }
}

// Define the function to free memory for an array of data entries
void free_data_entries(struct data_entry **data_entries, int num_entries) {
    // Free the buffer and metadata for each data entry
    for (int i = 0; i < num_entries; i++) {
        struct data_entry *data_entry = data_entries[i];
        free(data_entry->buffer);
        free(data_entry->metadata);
    }

    // Free the array of data entry pointers
    free(data_entries);
}

// Define a helper function to verify that all allocations were successful
void check_allocations(struct data_entry **data_entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        struct data_entry *data_entry = data_entries[i];
        if (data_entry->buffer == NULL || data_entry->metadata == NULL) {
            printf("Error: Failed to allocate memory for data entry %d\n", i);
            return;
        }
    }
}

// Define a mechanism to log memory usage and performance metrics
void log_memory_usage(struct data_entry **data_entries, int num_entries) {
    // Calculate the total memory usage in bytes
    size_t total_memory = 0;
    for (int i = 0; i < num_entries; i++) {
        struct data_entry *data_entry = data_entries[i];
        total_memory += sizeof(struct data_entry) + strlen(data_entry->buffer);
        if (data_entry->metadata != NULL) {
            total_memory += sizeof(struct metadata) + sizeof(double) * data_entry->timestamp % 100;
        }
    }

    // Log the memory usage and performance metrics
    printf("Memory usage: %zu bytes\n", total_memory);
    printf("Allocation time: %.3f seconds\n", (float)(clock() - start) / CLOCKS_PER_SEC);
    printf("Peak memory usage: %zu bytes\n", peak_memory);
}

// Define a garbage collection process to reclaim unused memory from metrics arrays
void garbage_collection(struct data_entry **data_entries, int num_entries) {
    // Iterate over each data entry and check if the metrics array is completely filled
    for (int i = 0; i < num_entries; i++) {
        struct data_entry *data_entry = data_entries[i];
        if (data_entry->metadata != NULL && data_entry->metadata->metrics != NULL) {
            int metrics_size = data_entry->timestamp % 100;
            for (int j = 0; j < metrics_size; j++) {
                if (data_entry->metadata->metrics[j] == 0.0) {
                    // Reclaim the memory for the unused metrics array
                    free(data_entry->metadata->metrics);
                    data_entry->metadata->metrics = NULL;
                    break;
                }
            }
        }
    }
}

// Define a thread-safe function to manage multiple dynamically allocated data structures
void manage_data_structures(int num_entries) {
    // Allocate memory for the array of data entry pointers
    struct data_entry **data_entries = malloc(num_entries * sizeof(struct data_entry));
    if (data_entries == NULL) {
        printf("Error: Failed to allocate memory for data entries\n");
        return;
    }

    // Initialize the array of data entry pointers and fill the metrics array with random floating-point numbers between -100.0 and 100.0
    clock_t start = clock();
    pthread_mutex_lock(&mutex);
    allocate_data_entries(num_entries);
    garbage_collection(data_entries, num_entries);
    check_allocations(data_entries, num_entries);
    log_memory_usage(data_entries, num_entries);
    pthread_mutex_unlock(&mutex);

    // Free the memory for the array of data entry pointers
    free_data_entries(data_entries, num_entries);
}
