    printf("%s\n", message);
}

// Define a function to allocate memory for an array of records
record_t* allocate_records(int num_records, int key_size, int value_size) {
    // Allocate memory for the array of records
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        log("Error: Failed to allocate memory for records");
        return NULL;
    }

    // Initialize each record with a random key and value
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 100;
        records[i].value = rand() % 1000;

        // Allocate memory for the offsets array
        int offset_size = records[i].key * sizeof(long);
        records[i].offsets = (long*)malloc(offset_size);
        if (!records[i].offsets) {
            log("Error: Failed to allocate memory for offsets");
            return NULL;
        }

        // Initialize each offset with a random value
        srand(time(NULL));
        for (int j = 0; j < records[i].key; j++) {
            records[i].offsets[j] = rand() % 1000;
        }
    }

    return records;
}

// Define a function to deallocate memory for an array of records
void deallocate_records(record_t* records) {
    // Deallocate memory for each record's offsets array
    for (int i = 0; i < num_records; i++) {
        free(records[i].offsets);
    }

    // Deallocate memory for the array of records
    free(records);
}

// Define a function to garbage collect unused memory from offsets arrays
void garbage_collect(record_t* records) {
    // Iterate over each record and check if its offsets array is completely filled
    for (int i = 0; i < num_records; i++) {
        if (records[i].offsets && !records[i].key) {
            free(records[i].offsets);
            records[i].offsets = NULL;
        }
    }
}

int main() {
    // Allocate memory for an array of records with 100 entries
    int num_records = 100;
    record_t* records = allocate_records(num_records, sizeof(int), sizeof(long));
    if (!records) {
        log("Error: Failed to allocate memory for records");
        return 1;
    }

    // Deallocate memory for the array of records when it is no longer needed
    deallocate_records(records);

    // Garbage collect unused memory from offsets arrays periodically
    garbage_collect(records);

    return 0;
}
