// Structure to represent a sensor reading
typedef struct SensorReading {
    time_t timestamp;
    int sensorID;
    float readingValue;
    char* deviceIDs; // List of associated device IDs
} SensorReading;

// Dynamic array to store the sensor readings
SensorReading* readings = NULL;
size_t numReadings = 0;
size_t capacity = 0;

// Function to add a new reading to the dynamic array
void addReading(time_t timestamp, int sensorID, float readingValue, char* deviceIDs) {
    // Check if the dynamic array needs to be resized
    if (numReadings == capacity) {
        capacity = capacity ? 2 * capacity : 1;
        readings = realloc(readings, capacity * sizeof(SensorReading));
    }

    // Add the new reading to the dynamic array
    SensorReading* newReading = &readings[numReadings++];
    newReading->timestamp = timestamp;
    newReading->sensorID = sensorID;
    newReading->readingValue = readingValue;
    newReading->deviceIDs = strdup(deviceIDs);
}

// Function to update an existing reading in the dynamic array
void updateReading(time_t timestamp, int sensorID, float readingValue, char* deviceIDs) {
    // Find the index of the reading to be updated
    size_t i;
    for (i = 0; i < numReadings; ++i) {
        if (readings[i].timestamp == timestamp && readings[i].sensorID == sensorID) {
            break;
        }
    }

    // Update the reading if it exists
    if (i < numReadings) {
        SensorReading* updatedReading = &readings[i];
        updatedReading->readingValue = readingValue;
        free(updatedReading->deviceIDs);
        updatedReading->deviceIDs = strdup(deviceIDs);
    }
}

// Function to retrieve readings within a specified value range or time period
void getReadings(time_t startTime, time_t endTime, float minValue, float maxValue) {
    // Initialize the output array
    SensorReading* output = malloc(numReadings * sizeof(SensorReading));
    size_t numOutput = 0;

    // Iterate over the readings and add them to the output array if they match the specified criteria
    for (size_t i = 0; i < numReadings; ++i) {
        SensorReading* reading = &readings[i];
        if (reading->timestamp >= startTime && reading->timestamp <= endTime &&
            reading->readingValue >= minValue && reading->readingValue <= maxValue) {
            output[numOutput++] = *reading;
        }
    }

    // Print the output array
    for (size_t i = 0; i < numOutput; ++i) {
        SensorReading* reading = &output[i];
        printf("%ld %d %.2f %s\n", reading->timestamp, reading->sensorID, reading->readingValue, reading->deviceIDs);
    }
}
