    if (arr->size == arr->capacity) {
        // Double the capacity of the array
        int newCapacity = arr->capacity * 2;
        SensorReading* newReadings = realloc(arr->readings, sizeof(SensorReading) * newCapacity);
        if (newReadings == NULL) {
            // Handle memory allocation failure
            return;
        }
        arr->capacity = newCapacity;
        arr->readings = newReadings;
    }
    // Add the reading to the array
    arr->readings[arr->size++] = reading;
}

// Function to update an existing reading in the array
void updateReading(SensorReadingArray* arr, int index, SensorReading newReading) {
    // Check if the index is valid
    if (index < 0 || index >= arr->size) {
        return;
    }
    // Update the reading in the array
    arr->readings[index] = newReading;
}

// Function to retrieve a reading from the array within a specified time range
SensorReading getReading(SensorReadingArray* arr, time_t startTime, time_t endTime) {
    // Iterate over the readings in the array
    for (int i = 0; i < arr->size; i++) {
        SensorReading reading = arr->readings[i];
        if (reading.timestamp >= startTime && reading.timestamp <= endTime) {
            return reading;
        }
    }
    // Return an empty reading if no matching reading is found
    SensorReading emptyReading = {0};
    return emptyReading;
}

// Function to retrieve a list of readings from the array within a specified value range
SensorReadingArray getReadings(SensorReadingArray* arr, float minValue, float maxValue) {
    // Create an empty array to store the filtered readings
    SensorReadingArray filteredReadings = {0};
    // Iterate over the readings in the array
    for (int i = 0; i < arr->size; i++) {
        SensorReading reading = arr->readings[i];
        if (reading.readingValue >= minValue && reading.readingValue <= maxValue) {
            // Add the reading to the filtered array
            addReading(&filteredReadings, reading);
        }
    }
    return filteredReadings;
}

// Function to retrieve a list of readings from the array within a specified time range and value range
SensorReadingArray getFilteredReadings(SensorReadingArray* arr, time_t startTime, time_t endTime, float minValue, float maxValue) {
    // Create an empty array to store the filtered readings
    SensorReadingArray filteredReadings = {0};
    // Iterate over the readings in the array
    for (int i = 0; i < arr->size; i++) {
        SensorReading reading = arr->readings[i];
        if (reading.timestamp >= startTime && reading.timestamp <= endTime && reading.readingValue >= minValue && reading.readingValue <= maxValue) {
            // Add the reading to the filtered array
            addReading(&filteredReadings, reading);
        }
    }
    return filteredReadings;
}

// Function to handle concurrent access from multiple threads
void* threadSafeFunction(void* arg) {
    SensorReadingArray* arr = (SensorReadingArray*)arg;
    // Perform the desired operation on the array
    addReading(arr, {1234567890, 1, 1.23, "device1"});
}

// Function to integrate with an external data source for real-time updates
void updateFromExternalSource() {
    // Query the external data source for new readings
    SensorReadingArray* newReadings = queryExternalDataSource();
    if (newReadings != NULL) {
        // Add the new readings to the array
        addReadings(arr, newReadings);
    }
}

