int main() {
    // Create an empty array to store sensor readings
    SensorReadingArray arr = {0};
    // Add a few initial readings to the array
    addReading(&arr, {1234567890, 1, 1.23, "device1"});
    addReading(&arr, {1234567890, 2, 2.34, "device2"});
    // Update an existing reading in the array
    updateReading(&arr, 0, {1234567890, 1, 1.23, "device1"});
    // Retrieve a reading from the array within a specified time range
    SensorReading reading = getReading(&arr, 1234567890, 1234567890);
    printf("Reading: %d, %f\n", reading.sensorID, reading.readingValue);
    // Retrieve a list of readings from the array within a specified value range
    SensorReadingArray filteredReadings = getReadings(&arr, 1.2, 2.3);
    printf("Filtered readings: %d\n", filteredReadings.size);
    // Retrieve a list of readings from the array within a specified time range and value range
