// Function to add a new SensorReading to the data structure
void addSensorReading(struct DataStructure* ds, struct SensorReading reading) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Check if there is enough space in the data structure to store the new reading
    if (ds->numSensorReadings >= MAX_NUM_SENSOR_READINGS) {
        // Release the lock on the data structure and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Add the new reading to the data structure
    ds->sensorReadings[ds->numSensorReadings++] = reading;

    // Release the lock on the data structure
    pthread_mutex_unlock(&mutex);
}

