// Function to remove a SensorReading from the data structure
void removeSensorReading(struct DataStructure* ds, time_t timestamp) {
    // Acquire the lock on the data structure
    pthread_mutex_lock(&mutex);

    // Iterate over the sensor readings in the data structure
    for (int i = 0; i < ds->numSensorReadings; i++) {
        // Check if the current reading has a matching timestamp
        if (ds->sensorReadings[i].timestamp == timestamp) {
            // Remove the reading from the data structure
            memmove(&ds->sensorReadings[i], &ds->sensorReadings[i + 1], sizeof(struct SensorReading) * (ds->numSensorReadings - i - 1));
            ds->numSensorReadings--;

            // Release the lock on the data structure and return
            pthread_mutex_unlock(&mutex);
            return;
