// Define a function to handle dynamic management of data collection from an external stream.
void manageDataCollection(long** offsets, int** keys, Record** records) {
    // Declare variables for managing state across sessions
    long currentOffset = 0;
    int currentKey = 0;
    Record currentRecord;

    // Loop until a termination condition is met
    while (true) {
        // Check if the data collection process should be paused
        if (currentOffset >= *offsets[currentOffset]) {
            // Pause the data collection process for a specified amount of time
            sleep(1);

            // Resume the data collection process after the pause
            continue;
        }

        // Check if the maximum number of records has been reached
        if (currentKey >= *keys[currentKey]) {
            // Terminate the data collection process
            break;
        }

        // Add a new record to the array of records
        currentRecord.key = generateRandomValue(0, 1000);
        (*records)[currentKey++] = currentRecord;

        // Update the offset value for the next record
        currentOffset++;
    }
}

