        // Read data from the stream and store it in the array
        char* buffer = malloc(buffer_size * sizeof(char));
        if (!buffer) {
            perror("Failed to allocate memory for reading from stream");
            exit(1);
        }
        ssize_t bytes_read = read(fd, buffer, buffer_size);
        if (bytes_read == -1) {
            perror("Failed to read from stream");
            exit(1);
        }

        // Update the offset array with the new data
        for (size_t i = 0; i < bytes_read; i++) {
            offset_array[i] += buffer[i];
        }

        // Update the key array with the new data
        for (size_t i = 0; i < bytes_read; i++) {
            key_array[i] += buffer[i];
        }

        // Update each record with the new data
        for (size_t i = 0; i < num_records; i++) {
            Record* record = record_array[i];
            record->value += buffer[i];
        }
    }

    // Flush the collected data to disk periodically
    if (flush_flag) {
        fsync(fd);
    }

    // Close the file descriptor
    close(fd);
}

