```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Define a structure to represent a record
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define a structure to represent a stream
typedef struct {
    int id;
    int state; // 0: paused, 1: resumed
    Record *records;
    size_t record_count;
    size_t record_capacity;
} Stream;

// Define a global array to store all streams
Stream *streams = NULL;
size_t stream_count = 0;
size_t stream_capacity = 0;

// Define a mutex for synchronizing access to the streams array
pthread_mutex_t streams_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a new stream
int init_stream(Stream *stream, int id) {
    // Check if the stream is already initialized
    if (stream->id != 0) {
        return -1;
    }

    // Initialize the stream's ID and state
    stream->id = id;
    stream->state = 0;

    // Allocate memory for the stream's records
    size_t record_capacity = 1024;
    stream->records = (Record *)malloc(record_capacity * sizeof(Record));
    if (!stream->records) {
        return -1;
    }

    // Initialize the stream's record count and capacity
    stream->record_count = 0;
    stream->record_capacity = record_capacity;

    return 0;
}

// Function to add a new record to a stream
int add_record(Stream *stream, long offset, int key, int value) {
    // Check if the stream is initialized and not paused
    if (stream->id == 0 || stream->state != 1) {
        return -1;
    }

    // Allocate memory for the new record
    size_t record_index = stream->record_count++;
    Record *new_record = &(stream->records[record_index]);
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;

    // Check if the record array needs to be resized
    if (stream->record_count == stream->record_capacity) {
        size_t new_record_capacity = stream->record_capacity * 2;
        Record *new_records = (Record *)realloc(stream->records, new_record_capacity * sizeof(Record));
        if (!new_records) {
            return -1;
        }
        stream->records = new_records;
        stream->record_capacity = new_record_capacity;
    }

    return 0;
}

// Function to pause a stream
int pause_stream(Stream *stream) {
    // Check if the stream is initialized and not already paused
    if (stream->id == 0 || stream->state != 1) {
        return -1;
    }

    // Set the stream's state to paused
    stream->state = 0;

    return 0;
}

// Function to resume a stream
int resume_stream(Stream *stream) {
    // Check if the stream is initialized and not already resumed
    if (stream->id == 0 || stream->state != 0) {
        return -1;
    }

    // Set the stream's state to resumed
    stream->state = 1;

    return 0;
}

// Function to close a stream and free its resources
int close_stream(Stream *stream) {
    // Check if the stream is initialized
    if (stream->id == 0) {
        return -1;
    }

    // Free the stream's records
    free(stream->records);

    // Set the stream's ID to 0 and state to paused
    stream->id = 0;
    stream->state = 0;

    return 0;
}

// Function to dynamically initialize a new stream with a random value range
int init_stream_with_random_range(Stream *stream, int id, int min_value, int max_value) {
    // Initialize the stream with a default ID and state
    if (init_stream(stream, id) != 0) {
        return -1;
    }

    // Generate a random value within the specified range for each record
    for (size_t i = 0; i < stream->record_count; i++) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        add_record(stream, i, i, value);
    }

    return 0;
}
