    if (config == NULL) {
        fprintf(stderr, "Error: failed to open configuration file\n");
        return -1;
    }
    char line[256];
    while (!feof(config)) {
        // Read the next line from the configuration file and parse its contents
        fgets(line, sizeof(line), config);
        if (strncmp(line, "num_records", 11) == 0) {
            int num_records = atoi(line + 12);
            return num_records;
        }
    }
    fclose(config);

    // If the configuration file does not specify the number of records, use a default value
    return 1000;
}

