        fprintf(stderr, "Error: failed to allocate memory for new record\n");
        return NULL;
    }

    // Read the next record from the binary file and populate its fields with random values within specified ranges
    fread(&new_record->key, sizeof(int), 1, input);
    fread(&new_record->offset, sizeof(long), 1, input);

    return new_record;
}
