#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure for an 'item' in the linked list
typedef struct {
    char buffer[10]; // Buffer to store the string
    int index; // Index of the item in the list
    struct item *next; // Pointer to the next item in the list
} item_t;

// Function to add an item to the list
void add_item(item_t **head, char *str) {
    // Create a new item
    item_t *new_item = malloc(sizeof(item_t));
    strcpy(new_item->buffer, str);
    new_item->index = 0;
    new_item->next = NULL;

    // If the list is empty, set the head pointer to the new item
    if (*head == NULL) {
        *head = new_item;
    } else {
        // Otherwise, add the new item to the end of the list
        item_t *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_item;
    }
}

// Function to remove an item from the list by index
void remove_item(item_t **head, int index) {
    // If the list is empty or the index is out of bounds, return
    if (*head == NULL || index < 0 || index >= (*head)->index) {
        return;
    }

    // If the index is 0, remove the first item in the list
    if (index == 0) {
        item_t *current = *head;
        *head = current->next;
        free(current);
    } else {
        // Otherwise, find the previous item and remove it from the list
        item_t *previous = NULL;
        item_t *current = *head;
        while (current != NULL && current->index != index) {
            previous = current;
            current = current->next;
        }
        if (current == NULL) {
            return;
        }
        previous->next = current->next;
        free(current);
    }
}

// Function to traverse the list and print all item indices
void traverse_list(item_t *head) {
    // If the list is empty, return
    if (head == NULL) {
        return;
    }

    // Traverse the list and print each item's index
    item_t *current = head;
    while (current != NULL) {
        printf("%d ", current->index);
        current = current->next;
    }
}
