// Define the structure for an 'item' in the list
typedef struct item {
    char buffer[256]; // 256-character buffer for the string
    int index; // Index of the item in the list
    struct item *next; // Pointer to the next item in the list
} item_t;

// Define the structure for the dynamic collection of items
typedef struct {
    item_t **items; // Array of pointers to 'item' structures
    int size; // Current size of the list
    int capacity; // Maximum capacity of the list
    pthread_mutex_t mutex; // Mutex for thread safety
} list_t;

// Initialize a new list with a given capacity
list_t *list_init(int capacity) {
    list_t *list = malloc(sizeof(list_t));
    if (list == NULL) {
        return NULL;
    }
    list->items = calloc(capacity, sizeof(item_t*));
    if (list->items == NULL) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = capacity;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Add an item to the list with a specified buffer length
int list_add(list_t *list, char *buffer, int len) {
    if (len > 256) {
        len = 256;
    }
    pthread_mutex_lock(&list->mutex);
    // Check if the list needs to be resized
    if (list->size == list->capacity) {
        int new_capacity = list->capacity + 10;
        item_t **new_items = realloc(list->items, new_capacity * sizeof(item_t*));
        if (new_items == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->items = new_items;
        list->capacity = new_capacity;
    }
    // Create a new 'item' structure and copy the buffer
    item_t *new_item = malloc(sizeof(item_t));
    if (new_item == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    memcpy(new_item->buffer, buffer, len);
    new_item->index = list->size++;
    new_item->next = NULL;
    // Add the new item to the end of the list
    if (list->size > 0) {
        item_t *last_item = list->items[list->size - 1];
        last_item->next = new_item;
    }
    list->items[list->size - 1] = new_item;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Remove an item from the list by index
int list_remove(list_t *list, int index) {
    if (index < 0 || index >= list->size) {
        return -1;
    }
    pthread_mutex_lock(&list->mutex);
    // Find the item to remove and update the linked list
    item_t *item = list->items[index];
    if (index > 0) {
        item_t *prev_item = list->items[index - 1];
        prev_item->next = item->next;
    } else {
        list->items[index] = item->next;
    }
    // Free the memory for the removed item
    free(item);
    list->size--;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Traverse the list to print all item indices and optionally the buffer content
void list_print(list_t *list, int print_buffer) {
    if (list == NULL || list->size == 0) {
        return;
    }
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        item_t *item = list->items[i];
        printf("Item %d: index=%d", i, item->index);
        if (print_buffer) {
            printf(", buffer='%s'", item->buffer);
        }
        printf("\n");
    }
    pthread_mutex_unlock(&list->mutex);
}

// Free the memory for a list and its items
void list_free(list_t *list) {
    if (list == NULL || list->size == 0) {
        return;
    }
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        item_t *item = list->items[i];
        free(item);
    }
    free(list->items);
    pthread_mutex_unlock(&list->mutex);
    free(list);
}
