    pthread_mutex_lock(&logEntryMutex);
    // Add the new LogEntry to the end of the list
    logEntries = realloc(logEntries, (numLogEntries + 1) * sizeof(LogEntry));
    logEntries[numLogEntries] = *entry;
    numLogEntries++;
    pthread_mutex_unlock(&logEntryMutex);
}

