import json
from typing import List, Dict, Any
from websocket import WebSocketApp

class DataProcessingPipeline:
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.data_streams = {}  # type: Dict[str, List[Any]]
        self.transformations = []  # type: List[Callable[[Any], Any]]

    def add_data_stream(self, name: str, data_stream: WebSocketApp):
        if name in self.data_streams:
            raise ValueError("Data stream already exists")
        self.data_streams[name] = []
        data_stream.on_message = self._handle_message(name)

    def remove_data_stream(self, name: str):
        if name not in self.data_streams:
            raise ValueError("Data stream does not exist")
        del self.data_streams[name]

    def add_transformation(self, transformation: Callable[[Any], Any]):
        self.transformations.append(transformation)

    def remove_transformation(self, transformation: Callable[[Any], Any]):
        if transformation not in self.transformations:
            raise ValueError("Transformation does not exist")
        self.transformations.remove(transformation)

    def _handle_message(self, name: str):
        def handle_message(data_stream: WebSocketApp, message: Any):
            try:
                data = json.loads(message)
                if not isinstance(data, dict):
                    raise ValueError("Invalid data format")
                for transformation in self.transformations:
                    data = transformation(data)
                self.data_streams[name].append(data)
            except Exception as e:
                logging.error(f"Data processing error: {e}")
        return handle_message

    def process_data(self):
        for name, data_stream in self.data_streams.items():
            if not data_stream:
                continue
            try:
                # Process data stream
                for data in data_stream:
                    print(f"Processing {name}: {data}")
            except Exception as e:
                logging.error(f"Data processing error: {e}")

def process_sensor_data(config: Dict[str, Any]) -> Tuple[Any, int]:
