import java.io.*;
import java.util.*;
import java.security.MessageDigest;

public class GenerateUserSessionHash {
    public static void main(String[] args) throws Exception {
        // Parse command-line arguments
        String inputFile = args[0];
        String outputFile = args[1];
        String parsingRules = args[2];
        int maxActivityLevel = Integer.parseInt(args[3]);

        // Initialize variables
        List<UserSession> sessions = new ArrayList<>();
        Map<Integer, UserSession> sessionMap = new HashMap<>();
        long[] timestamps = new long[1000000];
        int[] sessionIDs = new int[500000];
        boolean[] connectionStatuses = new boolean[1000000];
        byte[] activityLevels = new byte[1000000];

        // Read input file and parse data according to parsing rules
        try (BufferedReader reader = new BufferedReader(new FileReader(inputFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                // Parse line and add session to list and map
                UserSession session = parseSession(line, parsingRules);
                sessions.add(session);
                sessionMap.put(session.getId(), session);

                // Update timestamp, session ID, and activity level arrays
                int index = sessions.size() - 1;
                timestamps[index] = session.getTimestamp();
                sessionIDs[index] = session.getId();
                activityLevels[index] = (byte) session.getActivityLevel().ordinal();
            }
        } catch (IOException e) {
            System.err.println("Error reading input file: " + e.getMessage());
            return;
        }

        // Generate output file with session information
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputFile))) {
            for (int i = 0; i < sessions.size(); i++) {
                UserSession session = sessions.get(i);
                String line = String.format("%d,%d,%b,%s", session.getId(), timestamps[i], connectionStatuses[i], activityLevels[i]);
                writer.write(line + "\n");
            }
        } catch (IOException e) {
            System.err.println("Error writing output file: " + e.getMessage());
            return;
        }

        // Generate MD5 hash of session data and append to output file
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            for (int i = 0; i < sessions.size(); i++) {
                UserSession session = sessions.get(i);
                byte[] bytes = String.format("%d,%d,%b,%s", session.getId(), timestamps[i], connectionStatuses[i], activityLevels[i]).getBytes();
                md.update(bytes);
            }
            byte[] hash = md.digest();
            String hashString = bytesToHex(hash);
            try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputFile, true))) {
                writer.write("MD5 Hash: " + hashString + "\n");
            } catch (IOException e) {
                System.err.println("Error writing MD5 hash to output file: " + e.getMessage());
                return;
            }
        } catch (NoSuchAlgorithmException e) {
            System.err.println("Error generating MD5 hash: " + e.getMessage());
            return;
        }
    }

    private static UserSession parseSession(String line, String parsingRules) throws Exception {
        // Parse line according to parsing rules and create session object
        String[] tokens = line.split(",");
        int id = Integer.parseInt(tokens[0]);
        long timestamp = Long.parseLong(tokens[1]);
        boolean connectionStatus = Boolean.parseBoolean(tokens[2]);
        ActivityLevel activityLevel = ActivityLevel.valueOf(tokens[3]);
        return new UserSession(id, timestamp, connectionStatus, activityLevel);
    }

    private static String bytesToHex(byte[] bytes) {
        // Convert byte array to hex string
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            sb.append(String.format("%02x", bytes[i]));
        }
        return sb.toString();
    }
}

class UserSession {
    private int id;
    private long timestamp;
    private boolean connectionStatus;
    private ActivityLevel activityLevel;

    public UserSession(int id, long timestamp, boolean connectionStatus, ActivityLevel activityLevel) {
        this.id = id;
        this.timestamp = timestamp;
        this.connectionStatus = connectionStatus;
        this.activityLevel = activityLevel;
    }

    public int getId() {
        return id;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public boolean isConnectionStatus() {
        return connectionStatus;
    }

    public ActivityLevel getActivityLevel() {
        return activityLevel;
    }
}

enum ActivityLevel {
    LOW, MEDIUM, HIGH
}
