Task 1: Dynamic Memory Management for Six Data Structures
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <limits.h>
#include <pthread.h>

// Define the data structures
typedef struct {
    long offset;
    int key;
    float weight;
} record_t;

typedef struct {
    size_t capacity;
    size_t count;
    record_t* records;
} array_t;

// Define the configuration parameters
#define MAX_OFFSET 8589934592 // 8 GB in bytes
#define DEFAULT_KEY_VALUE 0
#define RESIZE_FACTOR 1.5
#define COMPRESSION_THRESHOLD 1000000

// Define the functions
void init_array(array_t* array, size_t capacity) {
    // Allocate memory for the arrays
    array->records = (record_t*)malloc(capacity * sizeof(record_t));
    if (!array->records) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(1);
    }
    array->count = 0;
    array->capacity = capacity;
}

void add_record(array_t* array, long offset, int key, float weight) {
    // Check if the sum of offsets exceeds the maximum value
    if (offset + array->records[array->count - 1].offset > MAX_OFFSET) {
        fprintf(stderr, "Error: Sum of offsets exceeds maximum value\n");
        exit(1);
    }
    // Add the record to the end of the array
    array->records[array->count++] = (record_t){offset, key, weight};
}

void resize_array(array_t* array) {
    // Calculate the new capacity based on the current size and the resize factor
    size_t new_capacity = array->capacity * RESIZE_FACTOR;
    // Reallocate memory for the arrays
    record_t* new_records = (record_t*)realloc(array->records, new_capacity * sizeof(record_t));
    if (!new_records) {
        fprintf(stderr, "Error: Failed to reallocate memory for records\n");
        exit(1);
    }
    array->records = new_records;
    array->capacity = new_capacity;
}

void compress_array(array_t* array) {
    // Calculate the number of elements to be compressed
    size_t num_elements = array->count / COMPRESSION_THRESHOLD;
    // Compress the elements by removing duplicates and sorting them
    for (size_t i = 0; i < num_elements; i++) {
        record_t* current = &array->records[i];
        record_t* next = &array->records[i + COMPRESSION_THRESHOLD];
        while (next < array->records + array->count) {
            if (*current == *next) {
                // Remove the duplicate element and shift the remaining elements
                memmove(next, next + 1, sizeof(record_t) * (array->count - (next - array->records)));
                array->count--;
            } else {
                current = next++;
            }
        }
    }
}

void cleanup_array(array_t* array) {
    // Free the memory allocated for the arrays
    free(array->records);
}

int main() {
    // Initialize the arrays
    size_t capacity = 100;
    array_t offset_array, key_array, weight_array;
    init_array(&offset_array, capacity);
    init_array(&key_array, capacity);
    init_array(&weight_array, capacity);
    // Add records to the arrays
    add_record(&offset_array, 100, 200, 3.5);
    add_record(&offset_array, 200, 400, 6.7);
    add_record(&key_array, 200, 400, 6.7);
    add_record(&weight_array, 300, 500, 9.1);
    // Resize the arrays if necessary
    while (offset_array.count > offset_array.capacity) {
        resize_array(&offset_array);
    }
    while (key_array.count > key_array.capacity) {
        resize_array(&key_array);
    }
    while (weight_array.count > weight_array.capacity) {
        resize_array(&weight_array);
    }
    // Compress the arrays if necessary
    if (offset_array.count / COMPRESSION_THRESHOLD >= 1) {
        compress_array(&offset_array);
    }
    if (key_array.count / COMPRESSION_THRESHOLD >= 1) {
        compress_array(&key_array);
    }
    if (weight_array.count / COMPRESSION_THRESHOLD >= 1) {
        compress_array(&weight_array);
    }
    // Clean up the arrays
    cleanup_array(&offset_array);
    cleanup_array(&key_array);
    cleanup_array(&weight_array);
    return 0;
}
