    if (!new_records) {
        fprintf(stderr, "Error: Failed to reallocate memory for records\n");
        exit(1);
    }
    array->records = new_records;
    array->capacity = new_capacity;
}

void serialize_array(const array_t* array, FILE* file) {
    // Write the number of records to the file
    fwrite(&array->count, sizeof(size_t), 1, file);
    // Write each record to the file
    for (size_t i = 0; i < array->count; i++) {
        fwrite(&array->records[i], sizeof(record_t), 1, file);
    }
}

void deserialize_array(array_t* array, FILE* file) {
    // Read the number of records from the file
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    // Allocate memory for the arrays
    init_array(array, count);
    // Read each record from the file
    for (size_t i = 0; i < array->count; i++) {
        fread(&array->records[i], sizeof(record_t), 1, file);
    }
}

void cleanup_array(array_t* array) {
    // Free the memory allocated for the arrays
    free(array->records);
}

int main() {
    // Initialize the arrays
    size_t capacity = 100;
    array_t array;
    init_array(&array, capacity);
    // Add records to the arrays
    add_record(&array, 200, 3.5);
    add_record(&array, 400, 6.7);
    add_record(&array, -1000000, 9.1);
    // Serialize the arrays to a file
    FILE* file = fopen("records.bin", "wb");
    serialize_array(&array, file);
    fclose(file);
    // Clean up the arrays
    cleanup_array(&array);
    return 0;
}
