// Define the data structures
typedef struct {
    double *measurements;
    char *tags;
} DataStructures;

// Define the configuration parameters
const int MAX_MEASUREMENTS = 10000000; // Maximum number of measurements
const int MAX_TAGS = 200000; // Maximum number of tags
const double DEFAULT_VALUE = 0.0; // Default value for each tag
const int MIN_MEASUREMENTS = 10000; // Minimum number of measurements
const int MAX_MEASUREMENTS_PER_THREAD = 5000; // Maximum number of measurements per thread
const int COMPRESSION_THRESHOLD = 1000000; // Compression threshold for sparse arrays
const double MAX_MEMORY_USAGE = 4.0 * 1024 * 1024 * 1024; // Maximum memory usage in GB

// Define the concurrent access control mechanism
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for the data structures
void allocateMemory(DataStructures *data) {
    // Allocate memory for the measurements array
    data->measurements = (double *)malloc(sizeof(double) * MAX_MEASUREMENTS);
    if (data->measurements == NULL) {
        printf("Error: Failed to allocate memory for the measurements array\n");
        exit(1);
    }

    // Allocate memory for the tags array
    data->tags = (char *)malloc(sizeof(char) * MAX_TAGS);
    if (data->tags == NULL) {
        printf("Error: Failed to allocate memory for the tags array\n");
        exit(1);
    }
}

// Function to deallocate memory for the data structures
void deallocateMemory(DataStructures *data) {
    // Deallocate memory for the measurements array
    free(data->measurements);
    data->measurements = NULL;

    // Deallocate memory for the tags array
    free(data->tags);
    data->tags = NULL;
}

// Function to validate the sum of all double measurements does not exceed 4 GB
void validateMeasurements(DataStructures *data) {
    int i;
    double sum = 0.0;
    for (i = 0; i < data->num_measurements; i++) {
        sum += data->measurements[i];
    }
    if (sum > MAX_MEMORY_USAGE) {
        printf("Error: The sum of all double measurements exceeds the maximum memory usage\n");
        exit(1);
    }
}

// Function to handle dynamic resizing of the measurements array
void resizeMeasurements(DataStructures *data, int new_size) {
    // Reallocate memory for the measurements array
    data->measurements = (double *)realloc(data->measurements, sizeof(double) * new_size);
    if (data->measurements == NULL) {
        printf("Error: Failed to reallocate memory for the measurements array\n");
        exit(1);
    }
}

// Function to handle dynamic resizing of the tags array
void resizeTags(DataStructures *data, int new_size) {
    // Reallocate memory for the tags array
    data->tags = (char *)realloc(data->tags, sizeof(char) * new_size);
    if (data->tags == NULL) {
        printf("Error: Failed to reallocate memory for the tags array\n");
        exit(1);
    }
}

// Function to handle compression of sparse arrays
void compressSparseArrays(DataStructures *data) {
    // Compress the measurements array
    int i, j;
    double sum = 0.0;
    for (i = 0; i < data->num_measurements; i++) {
        if (data->measurements[i] != DEFAULT_VALUE) {
            sum += data->measurements[i];
        } else {
            // Compress the tags array
            int k, l;
            char temp = 0;
            for (k = i + 1; k < data->num_measurements; k++) {
                if (data->tags[k] != DEFAULT_VALUE) {
                    temp = data->tags[k];
                    break;
                }
            }
            if (temp == 0) {
                // No more non-default values in the tags array, so stop compressing
                break;
            }
            for (l = i + 1; l < k; l++) {
                data->tags[l] = temp;
            }
        }
    }
}

// Function to handle dynamic resizing of the measurements array and compression of sparse arrays
void resizeAndCompressMeasurements(DataStructures *data, int new_size) {
    // Resize the measurements array if necessary
    if (new_size > data->num_measurements) {
        resizeMeasurements(data, new_size);
    }

    // Compress the measurements array if necessary
    compressSparseArrays(data);
}

// Function to handle dynamic resizing of the tags array and compression of sparse arrays
void resizeAndCompressTags(DataStructures *data, int new_size) {
