    if (new_size > data->num_tags) {
        resizeTags(data, new_size);
    }

    // Compress the tags array if necessary
    compressSparseArrays(data);
}

// Function to handle concurrent access control for the tags array
void lockTags(DataStructures *data) {
    pthread_mutex_lock(&mutex);
}

void unlockTags(DataStructures *data) {
    pthread_mutex_unlock(&mutex);
}

// Function to handle concurrent access control for the measurements array
void lockMeasurements(DataStructures *data) {
    pthread_mutex_lock(&mutex);
}

void unlockMeasurements(DataStructures *data) {
    pthread_mutex_unlock(&mutex);
}

// Function to handle dynamic resizing of the measurements array and compression of sparse arrays in a concurrent manner
void resizeAndCompressMeasurementsConcurrently(DataStructures *data, int new_size) {
