// Define a structure for records with an integer pointer
typedef struct {
    int *value;
} record;

// Function to dynamically allocate memory for arrays and initialize values
void allocate_memory(int offset_size, int key_size) {
    // Allocate memory for the offset array
    long *offsets = malloc(offset_size * sizeof(long));
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offset values
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = rand() % 100;
    }

    // Allocate memory for the key array
    int *keys = malloc(key_size * sizeof(int));
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the key values
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % 100;
    }

    // Allocate memory for the record array
    record *records = malloc(key_size * sizeof(record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record values
    for (int i = 0; i < key_size; i++) {
        int *value = malloc(sizeof(int));
        if (value == NULL) {
            printf("Error: Failed to allocate memory for value\n");
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        records[i].value = value;
    }

    // Set the values of each integer pointer to a random value within a given range
    for (int i = 0; i < key_size; i++) {
        *(records[i].value) = rand() % 100;
    }

    // Free all allocated memory upon function exit
    free(offsets);
    free(keys);
    for (int i = 0; i < key_size; i++) {
        free(records[i].value);
    }
    free(records);
}
