```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

// Define the data structure for a record
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define the data structure for a stream
typedef struct {
    char *name;
    int id;
    int num_records;
    Record *records;
} Stream;

// Define the data structure for a thread-safe queue
typedef struct {
    pthread_mutex_t mutex;
    semaphore_t semaphore;
    int size;
    int head;
    int tail;
    Record *records;
} Queue;

// Define the data structure for a stream manager
typedef struct {
    char *name;
    int id;
    int num_streams;
    Stream **streams;
    Queue *queue;
} StreamManager;

// Function to initialize a stream
void init_stream(Stream *stream) {
    // Initialize the stream's name and ID
    stream->name = "Stream 1";
    stream->id = 1;

    // Allocate memory for the stream's records
    stream->num_records = 1000;
    stream->records = (Record *)malloc(sizeof(Record) * stream->num_records);

    // Initialize each record in the stream with a random value within the configured range
    for (int i = 0; i < stream->num_records; i++) {
        stream->records[i].offset = i;
        stream->records[i].key = i % 100;
        stream->records[i].value = rand() % 100;
    }
}

// Function to add a record to a stream
void add_record(Stream *stream, Record *record) {
    // Lock the queue's mutex
    pthread_mutex_lock(&stream->queue->mutex);

    // Wait for space in the queue
    while (stream->queue->size == stream->queue->tail - stream->queue->head) {
        semaphore_wait(stream->queue->semaphore);
    }

    // Add the record to the queue
    stream->queue->records[stream->queue->tail++] = *record;

    // Unlock the queue's mutex
    pthread_mutex_unlock(&stream->queue->mutex);
}

// Function to remove a record from a stream
void remove_record(Stream *stream, Record *record) {
    // Lock the queue's mutex
    pthread_mutex_lock(&stream->queue->mutex);

    // Find the record in the queue
    int index = 0;
    while (index < stream->queue->tail && &stream->queue->records[index] != record) {
        index++;
    }

    // Remove the record from the queue
    if (index < stream->queue->tail) {
        stream->queue->tail--;
        memmove(&stream->queue->records[index], &stream->queue->records[index + 1], sizeof(Record) * (stream->queue->tail - index));
    }

    // Unlock the queue's mutex
    pthread_mutex_unlock(&stream->queue->mutex);
}

// Function to flush a stream to disk
void flush_stream(Stream *stream) {
    // Lock the queue's mutex
    pthread_mutex_lock(&stream->queue->mutex);

    // Write each record in the queue to disk
    for (int i = 0; i < stream->queue->tail; i++) {
        Record *record = &stream->queue->records[i];
        fwrite(record, sizeof(Record), 1, stream->file);
    }

    // Flush the file to disk
    fflush(stream->file);

    // Unlock the queue's mutex
    pthread_mutex_unlock(&stream->queue->mutex);
}

// Function to close a stream
void close_stream(Stream *stream) {
    // Lock the queue's mutex
    pthread_mutex_lock(&stream->queue->mutex);

    // Close the file
    fclose(stream->file);

    // Free the memory for the stream's records
    free(stream->records);

    // Unlock the queue's mutex
    pthread_mutex_unlock(&stream->queue->mutex);
}

// Function to initialize a stream manager
void init_stream_manager(StreamManager *manager) {
    // Initialize the manager's name and ID
    manager->name = "Stream Manager";
    manager->id = 1;

    // Allocate memory for the manager's streams
    manager->num_streams = 5;
    manager->streams = (Stream **)malloc(sizeof(Stream *) * manager->num_streams);

    // Initialize each stream in the manager
    for (int i = 0; i < manager->num_streams; i++) {
        init_stream(&manager->streams[i]);
    }

    // Allocate memory for the manager's queue
    manager->queue = (Queue *)malloc(sizeof(Queue));

    // Initialize the queue's mutex and semaphore
    pthread_mutex_init(&manager->queue->mutex, NULL);
    semaphore_init(&manager->queue->semaphore, 0);

    // Set the queue's size to the number of records in each stream
    manager->queue->size = manager->num_streams * manager->streams[0]->num_records;

    // Allocate memory for the queue's records
    manager->queue->records = (Record *)malloc(sizeof(Record) * manager->queue->size);
}

// Function to add a stream to the manager
void add_stream(StreamManager *manager, Stream *stream) {
    // Lock the manager's mutex
    pthread_mutex_lock(&manager->mutex);

    // Add the stream to the manager's list of streams
    manager->num_streams++;
    manager->streams = (Stream **)realloc(manager->streams, sizeof(Stream *) * manager->num_streams);
    manager->streams[manager->num_streams - 1] = stream;

    // Initialize the stream's queue
    init_queue(&stream->queue);

    // Unlock the manager's mutex
    pthread_mutex_unlock(&manager->mutex);
}

// Function to remove a stream from the manager
void remove_stream(StreamManager *manager, Stream *stream) {
    // Lock the manager's mutex
    pthread_mutex_lock(&manager->mutex);

    // Find the stream in the manager's list of streams
    int index = 0;
    while (index < manager->num_streams && &manager->streams[index] != stream) {
        index++;
    }

    // Remove the stream from the manager's list of streams
    if (index < manager->num_streams) {
        manager->num_streams--;
        memmove(&manager->streams[index], &manager->streams[index + 1], sizeof(Stream *) * (manager->num_streams - index));
    }

    // Close the stream's queue
    close_queue(&stream->queue);

    // Unlock the manager's mutex
    pthread_mutex_unlock(&manager->mutex);
}

// Function to flush all streams in the manager to disk
void flush_all(StreamManager *manager) {
    // Lock the manager's mutex
    pthread_mutex_lock(&manager->mutex);

    // Flush each stream in the manager to disk
    for (int i = 0; i < manager->num_streams; i++) {
        flush_stream(manager->streams[i]);
    }

    // Unlock the manager's mutex
    pthread_mutex_unlock(&manager->mutex);
}

// Function to close all streams in the manager
void close_all(StreamManager *manager) {
    // Lock the manager's mutex
    pthread_mutex_lock(&manager->mutex);

    // Close each stream in the manager
    for (int i = 0; i < manager->num_streams; i++) {
        close_stream(manager->streams[i]);
    }

    // Free the memory for the manager's streams
    free(manager->streams);

    // Unlock the manager's mutex
    pthread_mutex_unlock(&manager->mutex);
}
