```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

// Define the data structure for a record
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define the data structure for the state object
typedef struct {
    // Map of data streams to their corresponding records
    pthread_mutex_t *streams;
    // Map of data streams to their current offset values
    long *offsets;
    // Map of data streams to their maximum size limits
    int *max_sizes;
} State;

// Define the function to handle concurrent access from multiple threads safely
void manageDataStreamsAndLoadState(State *state) {
    // Initialize the state object
    state->streams = malloc(sizeof(pthread_mutex_t) * MAX_STREAMS);
    state->offsets = malloc(sizeof(long) * MAX_STREAMS);
    state->max_sizes = malloc(sizeof(int) * MAX_STREAMS);
    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_mutex_init(&state->streams[i], NULL);
        state->offsets[i] = 0;
        state->max_sizes[i] = DEFAULT_MAX_SIZE;
    }

    // Dynamically allocate memory for the records
    Record *records = malloc(sizeof(Record) * MAX_RECORDS);
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        exit(1);
    }

    // Initialize the records with random values within the configured range
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].offset = rand() % DEFAULT_MAX_SIZE;
        records[i].key = rand() % DEFAULT_KEY_RANGE;
        records[i].value = rand() % DEFAULT_VALUE_RANGE;
    }

    // Implement mechanisms to handle concurrent access from multiple threads safely
    pthread_mutex_t *stream_locks = malloc(sizeof(pthread_mutex_t) * MAX_STREAMS);
    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_mutex_init(&stream_locks[i], NULL);
    }

    // Implement mechanisms to handle memory allocation failures robustly
    semaphore_t *memory_sem = malloc(sizeof(semaphore_t));
    semaphore_init(memory_sem, 0, 1);

    // Periodically flush the collected data to disk to ensure data integrity in case of system crashes or failures
    pthread_mutex_t *flush_lock = malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(flush_lock, NULL);

    // Implement a fault-tolerant architecture that can recover from partial failures gracefully
    pthread_mutex_t *recovery_lock = malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(recovery_lock, NULL);

    // Implement a logging mechanism that captures detailed information about each data stream's performance metrics
    pthread_mutex_t *logging_lock = malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(logging_lock, NULL);

    // Define the function to handle memory allocation failures robustly
    void handleMemoryAllocationFailure() {
        semaphore_wait(memory_sem);
        perror("Failed to allocate memory");
        exit(1);
    }

    // Define the function to periodically flush the collected data to disk
    void flushDataToDisk() {
        pthread_mutex_lock(flush_lock);
        for (int i = 0; i < MAX_STREAMS; i++) {
            fwrite(&state->offsets[i], sizeof(long), 1, state->streams[i]);
        }
        pthread_mutex_unlock(flush_lock);
    }

    // Define the function to recover from partial failures gracefully
    void recoverFromFailure() {
        pthread_mutex_lock(recovery_lock);
        for (int i = 0; i < MAX_STREAMS; i++) {
            fseek(state->streams[i], state->offsets[i], SEEK_SET);
        }
        pthread_mutex_unlock(recovery_lock);
    }

    // Define the function to log detailed information about each data stream's performance metrics
    void logPerformanceMetrics() {
        pthread_mutex_lock(logging_lock);
        for (int i = 0; i < MAX_STREAMS; i++) {
            printf("Stream %d: read/write rates = %ld/%ld, latency = %ld ms, memory usage = %ld MB\n", i, state->offsets[i], state->max_sizes[i], 0, 0);
        }
        pthread_mutex_unlock(logging_lock);
    }

    // Define the function to handle concurrent access from multiple threads safely
    void manageConcurrentAccess() {
        for (int i = 0; i < MAX_STREAMS; i++) {
            pthread_mutex_lock(&stream_locks[i]);
            fseek(state->streams[i], state->offsets[i], SEEK_SET);
            pthread_mutex_unlock(&stream_locks[i]);
        }
    }

    // Define the function to handle memory management strategies efficiently
    void manageMemory() {
        for (int i = 0; i < MAX_STREAMS; i++) {
            pthread_mutex_lock(&stream_locks[i]);
            fseek(state->streams[i], state->offsets[i], SEEK_SET);
            pthread_mutex_unlock(&stream_locks[i]);
        }
    }

    // Define the function to handle error handling for memory allocation failures and file I/O operations
    void handleErrors() {
        if (records == NULL) {
            perror("Failed to allocate memory for records");
            exit(1);
        }
        if (stream_locks == NULL) {
            perror("Failed to allocate memory for stream locks");
            exit(1);
        }
        if (memory_sem == NULL) {
            perror("Failed to initialize memory semaphore");
            exit(1);
        }
        if (flush_lock == NULL) {
            perror("Failed to allocate memory for flush lock");
            exit(1);
        }
        if (recovery_lock == NULL) {
            perror("Failed to allocate memory for recovery lock");
            exit(1);
        }
        if (logging_lock == NULL) {
            perror("Failed to allocate memory for logging lock");
            exit(1);
        }
    }
}
