#include <time.h>

// Define a struct for a session
struct Session {
    int id;
    char ip[16]; // IP address
    time_t timestamp;
};

// Define a struct for an account
struct Account {
    char username[32];
    char email[64];
    char* password_hash;
    struct Session** active_sessions;
};

// Function to generate a random secure password
char* generate_password() {
    // Generate a random password of length 10-20 characters
    int len = rand() % 11 + 10;
    char* password = malloc(len);
    for (int i = 0; i < len; i++) {
        password[i] = 'a' + rand() % 26;
    }
    return password;
}

// Function to generate a random secure hash
char* generate_hash(const char* password) {
    // Generate a random salt of length 16 bytes
    unsigned char salt[16];
    for (int i = 0; i < 16; i++) {
        salt[i] = rand() % 256;
    }
    // Hash the password with the salt using SHA-256
    unsigned char hash[32];
    sha256(password, strlen(password), salt, 16, hash);
    return hash;
}

// Function to populate an account with a unique username and email
void populate_account(struct Account* account) {
    // Generate a random username of length 8-16 characters
    int len = rand() % 17 + 8;
    for (int i = 0; i < len; i++) {
        account->username[i] = 'a' + rand() % 26;
    }
    // Generate a random email address of length 10-32 characters
    len = rand() % 33 + 10;
    for (int i = 0; i < len; i++) {
        account->email[i] = 'a' + rand() % 26;
    }
}

// Function to initialize a network of user accounts
void init_accounts(struct Account** accounts, int num_accounts) {
    // Allocate memory for the accounts
    *accounts = malloc(num_accounts * sizeof(struct Account));
    if (*accounts == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    // Initialize each account with a unique username and email
    for (int i = 0; i < num_accounts; i++) {
        populate_account(&(*accounts)[i]);
    }
    // Allocate memory for the password hashes
    for (int i = 0; i < num_accounts; i++) {
        (*accounts)[i].password_hash = generate_hash(generate_password());
    }
    // Allocate memory for the active sessions
    for (int i = 0; i < num_accounts; i++) {
        int num_sessions = rand() % 10 + 1;
        (*accounts)[i].active_sessions = malloc(num_sessions * sizeof(struct Session*));
        if ((*accounts)[i].active_sessions == NULL) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        for (int j = 0; j < num_sessions; j++) {
            (*accounts)[i].active_sessions[j] = malloc(sizeof(struct Session));
            if ((*accounts)[i].active_sessions[j] == NULL) {
                perror("malloc");
                exit(EXIT_FAILURE);
            }
            // Generate a random session ID between 1 and 1000
            int id = rand() % 1000 + 1;
            (*accounts)[i].active_sessions[j]->id = id;
            // Generate a random IP address with a random subnet and port combination
            char ip[16];
            sprintf(ip, "%d.%d.%d.%d:%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 65536);
            strcpy((*accounts)[i].active_sessions[j]->ip, ip);
            // Generate a random timestamp between the current time and one year from now
            (*accounts)[i].active_sessions[j]->timestamp = time(NULL) + rand() % 31536000;
        }
    }
}

// Function to free all allocated memory when the network of users is no longer needed
void free_accounts(struct Account** accounts, int num_accounts) {
