#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the linked list node structure
typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

// Define the data structure for the arrays and linked list
typedef struct {
    int *keys;
    long *offsets;
    Node *head;
    size_t count;
} DataStructure;

// Function to initialize the data structure
void initDataStructure(DataStructure *ds, size_t maxRecords) {
    // Allocate memory for the arrays and linked list
    ds->keys = malloc(maxRecords * sizeof(int));
    ds->offsets = malloc(maxRecords * sizeof(long));
    ds->head = NULL;
    ds->count = 0;
}

// Function to free the memory allocated for the data structure
void destroyDataStructure(DataStructure *ds) {
    // Free the arrays and linked list
    free(ds->keys);
    free(ds->offsets);
    while (ds->head != NULL) {
        Node *tmp = ds->head;
        ds->head = tmp->next;
        free(tmp);
    }
}

// Function to insert a new record into the data structure
void insertRecord(DataStructure *ds, int key, long offset) {
    // Check if the linked list is full
    if (ds->count == maxRecords) {
        printf("Error: Linked list is full\n");
        return;
    }

    // Allocate memory for the new record
    Record *newRecord = malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->offset = offset;

    // Insert the new record into the linked list
    Node *newNode = malloc(sizeof(Node));
    newNode->record = newRecord;
    newNode->next = ds->head;
    ds->head = newNode;

    // Update the arrays with the new values
    ds->keys[ds->count] = key;
    ds->offsets[ds->count] = offset;
    ds->count++;
}

// Function to delete a record from the data structure
void deleteRecord(DataStructure *ds, int key) {
    // Find the node containing the record with the given key
    Node *node = ds->head;
    while (node != NULL && node->record->key != key) {
        node = node->next;
    }

    // Check if the record was found
    if (node == NULL) {
        printf("Error: Record with key %d not found\n", key);
        return;
    }

    // Remove the node from the linked list
    Node *tmp = ds->head;
    if (ds->head == node) {
        ds->head = node->next;
    } else {
        while (tmp->next != node) {
            tmp = tmp->next;
        }
        tmp->next = node->next;
    }

    // Free the memory allocated for the record
    free(node->record);
    free(node);

    // Update the arrays with the new values
    int i = 0;
    while (i < ds->count && ds->keys[i] != key) {
        i++;
    }
    if (i < ds->count) {
        ds->keys[i] = ds->keys[ds->count - 1];
        ds->offsets[i] = ds->offsets[ds->count - 1];
    }
    ds->count--;
}

// Function to set a specific value for a key during initialization
void setKeyValue(DataStructure *ds, int key, long offset) {
    // Find the node containing the record with the given key
    Node *node = ds->head;
    while (node != NULL && node->record->key != key) {
        node = node->next;
    }

    // Check if the record was found
    if (node == NULL) {
        printf("Error: Record with key %d not found\n", key);
        return;
    }

    // Update the offset value for the record
    node->record->offset = offset;
}

// Function to serialize the data structure to a file
void serializeDataStructure(DataStructure *ds, FILE *file) {
    // Write the number of records to the file
    fwrite(&ds->count, sizeof(size_t), 1, file);

    // Write each record to the file
    Node *node = ds->head;
    while (node != NULL) {
        Record *record = node->record;
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->offset, sizeof(long), 1, file);
        node = node->next;
    }
}

// Function to deserialize the data structure from a file
void deserializeDataStructure(DataStructure *ds, FILE *file) {
    // Read the number of records from the file
    fread(&ds->count, sizeof(size_t), 1, file);

    // Allocate memory for the arrays and linked list
    ds->keys = malloc(ds->count * sizeof(int));
    ds->offsets = malloc(ds->count * sizeof(long));
    ds->head = NULL;

    // Read each record from the file
    for (size_t i = 0; i < ds->count; i++) {
        Record *record = malloc(sizeof(Record));
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->offset, sizeof(long), 1, file);
        Node *newNode = malloc(sizeof(Node));
        newNode->record = record;
        newNode->next = ds->head;
        ds->head = newNode;
    }
}

// Function to log an error message
void logError(const char *message) {
    // Use a logging library to log the error message
    printf("Error: %s\n", message);
}
