    size_t capacity;
    struct Record **keys;
    struct Record **offsets;
};

// Initialize a new data structure with the given number of records and key range
struct DataStructure* init(size_t num_records, int min_key, int max_key) {
    struct DataStructure *ds = malloc(sizeof(struct DataStructure));
    assert(ds != NULL);

    ds->num_records = 0;
    ds->capacity = num_records;
    ds->keys = malloc(sizeof(struct Record*) * num_records);
    assert(ds->keys != NULL);
    ds->offsets = malloc(sizeof(struct Record*) * num_records);
    assert(ds->offsets != NULL);

    for (size_t i = 0; i < num_records; i++) {
        struct Record *record = malloc(sizeof(struct Record));
        assert(record != NULL);
        record->key = min_key + rand() % (max_key - min_key + 1);
        record->offset = 0;
        ds->keys[i] = record;
        ds->offsets[i] = record;
    }

    return ds;
}

// Insert a new record into the data structure with the given key and offset
void insert(struct DataStructure *ds, int key, long offset) {
    // Check if the key already exists in the data structure
    for (size_t i = 0; i < ds->num_records; i++) {
        if (key == ds->keys[i]->key) {
            // Update the existing record with the new offset value
            ds->offsets[i]->offset = offset;
            return;
        }
    }

    // If the key does not exist, allocate a new record and insert it into the data structure
    struct Record *record = malloc(sizeof(struct Record));
    assert(record != NULL);
    record->key = key;
    record->offset = offset;
    ds->keys[ds->num_records] = record;
    ds->offsets[ds->num_records] = record;
    ds->num_records++;
}

// Delete a record from the data structure with the given key
void delete(struct DataStructure *ds, int key) {
    // Find the index of the record to be deleted
    size_t i = 0;
    for (i = 0; i < ds->num_records; i++) {
        if (key == ds->keys[i]->key) {
            break;
        }
    }

    // If the record is found, delete it from the data structure
    if (i < ds->num_records) {
        free(ds->keys[i]);
        free(ds->offsets[i]);
        ds->num_records--;
        for (size_t j = i; j < ds->num_records; j++) {
            ds->keys[j] = ds->keys[j + 1];
            ds->offsets[j] = ds->offsets[j + 1];
        }
    }
}

// Serialize the data structure to a file
void serialize(struct DataStructure *ds, const char* filename) {
    FILE *file = fopen(filename, "wb");
    assert(file != NULL);

    // Write the number of records in the data structure
    size_t num_records = ds->num_records;
    fwrite(&num_records, sizeof(size_t), 1, file);

    // Write each record to the file
    for (size_t i = 0; i < num_records; i++) {
        struct Record *record = ds->keys[i];
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->offset, sizeof(long), 1, file);
    }

    // Close the file
    fclose(file);
}

// Deserialize the data structure from a file
void deserialize(struct DataStructure *ds, const char* filename) {
    FILE *file = fopen(filename, "rb");
    assert(file != NULL);

    // Read the number of records in the data structure
    size_t num_records;
    fread(&num_records, sizeof(size_t), 1, file);

    // Allocate memory for the records
    ds->keys = malloc(sizeof(struct Record*) * num_records);
    assert(ds->keys != NULL);
    ds->offsets = malloc(sizeof(struct Record*) * num_records);
    assert(ds->offsets != NULL);

    // Read each record from the file
    for (size_t i = 0; i < num_records; i++) {
        struct Record *record = malloc(sizeof(struct Record));
        assert(record != NULL);
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->offset, sizeof(long), 1, file);
        ds->keys[i] = record;
        ds->offsets[i] = record;
    }

    // Close the file
    fclose(file);
}

// Free the memory allocated for the data structure
void free_data_structure(struct DataStructure *ds) {
    for (size_t i = 0; i < ds->num_records; i++) {
        free(ds->keys[i]);
        free(ds->offsets[i]);
    }
    free(ds->keys);
    free(ds->offsets);
}
```
This code implements a data structure that can efficiently store and retrieve records with integer keys and long offset values. The `init` function initializes the data structure with the given number of records and key range, and the `insert` function inserts a new record into the data structure with the given key and offset value. The `delete` function deletes a record from the data structure with the given key. The `serialize` function serializes the data structure to a file, and the `deserialize` function deserializes the data structure from a file. The `free_data_structure` function frees the memory allocated for the data structure.

The code also includes error handling for memory allocation failures and ensures that all allocated memory is properly freed upon completion or destruction of the data structure. Additionally, it provides a method to serialize and deserialize this data structure to and from a file, supporting both reading and writing operations. The custom binary format for serialization is used to optimize performance.

