// Define the structure to hold the record information
typedef struct {
    int value;
} Record;

// Define the function that manages dynamic memory allocation for the data structures
void *allocate_data(int num_records, long default_offset, int key_min, int key_max) {
    // Check if the input parameters are valid
    if (num_records < 0 || default_offset < 0 || key_min < 0 || key_max < 0) {
        return NULL;
    }

    // Calculate the total size of memory needed for all data structures
    long total_size = sizeof(long) * num_records + sizeof(int) * num_records + sizeof(Record) * num_records;

    // Check if the total size exceeds the maximum allowed size
    if (total_size > 1000000000) {
        return NULL;
    }

    // Allocate memory for the data structures
    void *data = malloc(total_size);
    if (!data) {
        return NULL;
    }

    // Initialize the long offsets to the default value
    long *offsets = (long *)data;
    for (int i = 0; i < num_records; i++) {
        offsets[i] = default_offset;
    }

    // Generate unique keys for each record
    int *keys = (int *)(data + sizeof(long) * num_records);
    for (int i = 0; i < num_records; i++) {
        keys[i] = generate_key(key_min, key_max);
    }

    // Initialize the record structures with random values
    Record *records = (Record *)(data + sizeof(long) * num_records + sizeof(int) * num_records);
    for (int i = 0; i < num_records; i++) {
        records[i].value = generate_random_value(key_min, key_max);
    }

    // Check if there are any duplicate keys or values
    for (int i = 0; i < num_records; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (keys[i] == keys[j]) {
                free(data);
                return NULL;
            }
            if (records[i].value == records[j].value) {
                free(data);
                return NULL;
            }
        }
    }

    // Return the opaque data structure containing pointers to the allocated memory
    struct Data {
        long *offsets;
        int *keys;
        Record *records;
    };
    struct Data *data_struct = malloc(sizeof(struct Data));
    data_struct->offsets = offsets;
    data_struct->keys = keys;
    data_struct->records = records;
    return data_struct;
}

// Generate a unique key within the specified range
int generate_key(int min, int max) {
    // Check if the input parameters are valid
    if (min < 0 || max < 0 || min > max) {
        return -1;
    }

    // Generate a random number within the specified range
    int key = rand() % (max - min + 1) + min;

    // Check if the generated key is already in use
    for (int i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            return generate_key(min, max);
        }
    }

    // Return the generated key
    return key;
}

// Generate a random value within the specified range
