// Define a struct for the records in the data structure
typedef struct Record {
    int key;
    long offset;
} Record;

// Define a struct for the linked list of records
typedef struct Node {
    Record record;
    struct Node* next;
} Node;

// Define a struct for the data structure itself
typedef struct DataStructure {
    Node* head;
    int size;
} DataStructure;

// Function to initialize the data structure with a specific number of records
void initDataStructure(DataStructure* ds, int numRecords) {
    // Allocate memory for the linked list nodes
    Node* node = malloc(sizeof(Node) * numRecords);
    assert(node != NULL);

    // Initialize each record in the linked list with a unique key and offset value
    for (int i = 0; i < numRecords; i++) {
        node[i].record.key = i + 1;
        node[i].record.offset = i * 100;
        node[i].next = NULL;
    }

    // Set the head of the linked list to the first node
    ds->head = &node[0];

    // Set the size of the data structure to the number of records
    ds->size = numRecords;
}

// Function to insert a new record into the data structure
void insertRecord(DataStructure* ds, int key, long offset) {
    // Create a new node for the record
    Node* newNode = malloc(sizeof(Node));
    assert(newNode != NULL);

    // Set the key and offset values of the new node
    newNode->record.key = key;
    newNode->record.offset = offset;

    // Find the position where the new node should be inserted in the linked list
    Node* current = ds->head;
    while (current != NULL && current->record.key < key) {
        current = current->next;
    }

    // Insert the new node into the linked list
    if (current == NULL) {
        ds->head = newNode;
    } else {
        newNode->next = current;
        current->prev = newNode;
    }
}

// Function to delete a record from the data structure
void deleteRecord(DataStructure* ds, int key) {
    // Find the node with the specified key in the linked list
    Node* current = ds->head;
    while (current != NULL && current->record.key < key) {
        current = current->next;
    }

    // If the node is found, delete it from the linked list
    if (current != NULL && current->record.key == key) {
        Node* prev = current->prev;
        Node* next = current->next;
        if (prev != NULL) {
            prev->next = next;
        } else {
            ds->head = next;
        }
        free(current);
    }
}

// Function to lookup a record in the data structure by key
Record* lookupRecord(DataStructure* ds, int key) {
    // Find the node with the specified key in the linked list
    Node* current = ds->head;
    while (current != NULL && current->record.key < key) {
        current = current->next;
    }

    // If the node is found, return a pointer to its record
    if (current != NULL && current->record.key == key) {
        return &current->record;
    } else {
        return NULL;
    }
}

// Function to clear the data structure and release all memory
void clearDataStructure(DataStructure* ds) {
    // Free the linked list nodes
    Node* current = ds->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

// Function to serialize the data structure to a file
void serializeDataStructure(DataStructure* ds, FILE* fp) {
    // Write the number of records in the linked list to the file
    int numRecords = 0;
    Node* current = ds->head;
    while (current != NULL) {
        numRecords++;
        current = current->next;
    }
    fwrite(&numRecords, sizeof(int), 1, fp);

    // Write each record in the linked list to the file
    current = ds->head;
    while (current != NULL) {
        Record* record = &current->record;
        fwrite(record, sizeof(Record), 1, fp);
        current = current->next;
    }
}

// Function to deserialize the data structure from a file
void deserializeDataStructure(DataStructure* ds, FILE* fp) {
    // Read the number of records in the linked list from the file
    int numRecords;
    fread(&numRecords, sizeof(int), 1, fp);

    // Allocate memory for the linked list nodes
    Node* node = malloc(sizeof(Node) * numRecords);
    assert(node != NULL);

    // Initialize each record in the linked list with a unique key and offset value
    for (int i = 0; i < numRecords; i++) {
        Record* record = &node[i].record;
        fread(record, sizeof(Record), 1, fp);
        node[i].next = NULL;
    }

    // Set the head of the linked list to the first node
    ds->head = &node[0];

    // Set the size of the data structure to the number of records
    ds->size = numRecords;
}
