typedef struct {
    oauth2_token_t token;
    struct node *next;
} node_t;

// Define a function to dynamically allocate and initialize memory for an OAuth2 access token
oauth2_token_t* create_token(int key, long offset) {
    // Allocate memory for the token structure
    oauth2_token_t *token = malloc(sizeof(oauth2_token_t));
    if (token == NULL) {
        printf("Error: Failed to allocate memory for OAuth2 access token\n");
        return NULL;
    }

    // Initialize the token structure with the given key and offset values
    token->key = key;
    token->offset = offset;

