        token->expires_in = 3600;
        token->token_type = "Bearer";
    } else {
        token->access_token = NULL;
        token->expires_in = -1;
        token->token_type = NULL;
    }

    // Handle memory allocation failures gracefully, ensuring all resources are properly released when the data structure is destroyed or cleared
    if (token == NULL) {
        printf("Error: Failed to allocate memory for OAuth2 access token\n");
        return NULL;
    }

    return token;
}

// Define a function to dynamically allocate and initialize memory for an OAuth2 access token data structure
node_t* create_token_list(int num_tokens) {
    // Allocate memory for the linked list node
    node_t *head = malloc(sizeof(node_t));
    if (head == NULL) {
        printf("Error: Failed to allocate memory for OAuth2 access token data structure\n");
        return NULL;
    }

    // Initialize the linked list node with a null pointer for the next node
    head->next = NULL;

    // Dynamically allocate and initialize memory for each OAuth2 access token in the linked list
    int i;
    for (i = 0; i < num_tokens; i++) {
        oauth2_token_t *token = create_token(i, i);
        if (token == NULL) {
            printf("Error: Failed to allocate memory for OAuth2 access token\n");
            return NULL;
        }

        // Add the new token to the linked list
        node_t *new_node = malloc(sizeof(node_t));
        if (new_node == NULL) {
            printf("Error: Failed to allocate memory for OAuth2 access token data structure\n");
            return NULL;
        }

        new_node->token = *token;
        new_node->next = head->next;
        head->next = new_node;
    }

    // Handle memory allocation failures gracefully, ensuring all resources are properly released when the data structure is destroyed or cleared
    if (head == NULL) {
        printf("Error: Failed to allocate memory for OAuth2 access token data structure\n");
        return NULL;
    }

    return head;
}

// Define a function to insert an OAuth2 access token into the linked list
void insert_token(node_t *head, int key, long offset) {
    // Dynamically allocate and initialize memory for the new token
    oauth2_token_t *new_token = create_token(key, offset);
    if (new_token == NULL) {
        printf("Error: Failed to allocate memory for OAuth2 access token\n");
        return;
    }

    // Add the new token to the linked list
    node_t *new_node = malloc(sizeof(node_t));
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for OAuth2 access token data structure\n");
        return;
    }

    new_node->token = *new_token;
    new_node->next = head->next;
    head->next = new_node;
}

// Define a function to delete an OAuth2 access token from the linked list
void delete_token(node_t *head, int key) {
    // Find the node containing the target token
    node_t *current = head;
    while (current != NULL && current->token.key != key) {
        current = current->next;
    }

    // If the target token is not found, return
    if (current == NULL) {
        printf("Error: OAuth2 access token with key %d not found\n", key);
        return;
    }

    // Remove the node containing the target token from the linked list
    node_t *previous = current->next;
    free(current);
    head->next = previous;
}

// Define a function to lookup an OAuth2 access token in the linked list by key
oauth2_token_t* lookup_token(node_t *head, int key) {
    // Find the node containing the target token
    node_t *current = head;
    while (current != NULL && current->token.key != key) {
        current = current->next;
    }

    // If the target token is not found, return NULL
    if (current == NULL) {
        printf("Error: OAuth2 access token with key %d not found\n", key);
        return NULL;
    }

    // Return a pointer to the target token
    return &(current->token);
}

// Define a function to destroy an OAuth2 access token data structure and release all memory
