    // Free each node in the linked list
    while (head != NULL) {
        node_t *current = head;
        head = head->next;
        free(current);
    }
}

// Define a function to serialize an OAuth2 access token data structure to a file
void serialize_token_list(node_t *head, char *filename) {
    // Open the output file for writing
    FILE *outfile = fopen(filename, "wb");
    if (outfile == NULL) {
        printf("Error: Failed to open output file %s\n", filename);
        return;
    }

    // Write each token in the linked list to the output file
    node_t *current = head;
    while (current != NULL) {
