        supported_protocols[0] = "HTTP";
        supported_protocols[1] = "HTTPS";
        supported_protocols[2] = "SSH";
        supported_protocols[3] = "FTP";
        servers[i]->supported_protocols = supported_protocols;

        // Initialize the custom metadata for the server instance with default values
        ServerMetadata metadata;
        metadata.timeout = 10;
        metadata.connection_limit = 50;
        servers[i]->metadata = metadata;

        // Set the reference count for the server instance to 0
        servers[i]->reference_count = 0;
    }

    // Allocate memory for the network of server instances and initialize it with the array of server instances
    ServerNetwork* network = (ServerNetwork*)malloc(sizeof(ServerNetwork));
    if (!network) {
        perror("Failed to allocate memory for server network");
        return NULL;
    }
    network->servers = servers;
    network->num_servers = num_servers;

    // Validate the uniqueness of hostnames and ensure that no duplicate entries exist in the network
    for (int i = 0; i < num_servers; i++) {
        for (int j = i + 1; j < num_servers; j++) {
            if (strcmp(servers[i]->hostname, servers[j]->hostname) == 0) {
                fprintf(stderr, "Duplicate hostname found: %s\n", servers[i]->hostname);
                return NULL;
            }
        }
    }

    // Return the network of server instances
    return network;
}

// Define the function to free all allocated memory when the server network is no longer needed
void destroy_server_network(ServerNetwork* network) {
    if (!network) {
        return;
    }

