                return;
            }
        }
    }
}

// Define the function to add a server instance to the network and increment its reference count
void add_server(ServerNetwork* network, ServerInstance* server) {
    if (!network || !server) {
        return;
    }

    // Increment the reference count for the new server instance
    server->reference_count++;

    // Add the new server instance to the end of the array of server instances in the network
    network->servers = (ServerInstance**)realloc(network->servers, (network->num_servers + 1) * sizeof(ServerInstance*));
    if (!network->servers) {
        perror("Failed to reallocate memory for server instances");
        return;
    }
    network->servers[network->num_servers] = server;
    network->num_servers++;
}

// Define the function to remove a server instance from the network and decrement its reference count
void remove_server(ServerNetwork* network, ServerInstance* server) {
    if (!network || !server) {
        return;
    }

    // Decrement the reference count for the removed server instance
    server->reference_count--;

    // Remove the server instance from the array of server instances in the network
    int index = -1;
    for (int i = 0; i < network->num_servers; i++) {
        if (network->servers[i] == server) {
            index = i;
            break;
        }
    }
    if (index != -1) {
        for (int i = index + 1; i < network->num_servers; i++) {
            network->servers[i - 1] = network->servers[i];
        }
        network->num_servers--;
    }
}

