// Define the function to free all allocated memory when the user database is no longer needed
void free_user_database(UserProfile** profiles, int num_profiles) {
    // Free each user profile
    for (int i = 0; i < num_profiles; i++) {
        UserProfile* profile = &(*profiles)[i];

        // Free the first and last name
        free(profile->first_name);
        free(profile->last_name);

        // Free the email address
        free(profile->email);

        // Free each phone number in the list
        for (int j = 0; j < profile->num_phone_numbers; j++) {
            char* phone_number = profile->phone_numbers[j];
            free(phone_number);
        }
