    int* records_to_remove = (int*)custom_malloc(num_records * sizeof(int));
    for (int i = 0; i < num_records; i++) {
        if (active_threads[i] == -1) {
            records_to_add[num_records_to_add++] = i;
        } else {
            records_to_remove[num_records_to_remove++] = i;
        }
    }

    // Allow for easy addition of new fields to the record structure in future versions
