    char** field_names = (char**)custom_malloc(num_fields * sizeof(char*));
    field_names[0] = "key";
    field_names[1] = "offset";
    field_names[2] = "value";

    // Minimize impact on system performance when dealing with large datasets
    pthread_t* threads = (pthread_t*)custom_malloc(num_records * sizeof(pthread_t));
    for (int i = 0; i < num_records; i++) {
        if (active_threads[i] == -1) {
            pthread_create(&threads[i], NULL, thread_func, &records[i]);
        }
    }

    // Support concurrent access to the dataset from multiple threads without introducing race conditions
    for (int i = 0; i < num_records; i++) {
        if (active_threads[i] == -1) {
            pthread_mutex_lock(&mutex);
            active_threads[i] = 1;
            num_active_threads++;
            pthread_cond_signal(&cond);
            pthread_mutex_unlock(&mutex);
        }
    }

    // Provide a mechanism to periodically clean up inactive records to free up resources
