typedef struct Task {
    int id;
    int priority;
    char status;
} Task;

Task* task_collection = NULL;
int num_tasks = 0;

void add_task(Task* new_task) {
    if (num_tasks == 0) {
        task_collection = malloc(sizeof(Task));
    } else {
        task_collection = realloc(task_collection, sizeof(Task) * (num_tasks + 1));
    }
    memcpy(&task_collection[num_tasks], new_task, sizeof(Task));
    num_tasks++;
}

void update_task(int id, Task* updated_task) {
    for (int i = 0; i < num_tasks; i++) {
        if (task_collection[i].id == id) {
            memcpy(&task_collection[i], updated_task, sizeof(Task));
            return;
        }
    }
}

void retrieve_task(int priority, Task* retrieved_task) {
    for (int i = 0; i < num_tasks; i++) {
        if (task_collection[i].priority == priority) {
            memcpy(retrieved_task, &task_collection[i], sizeof(Task));
            return;
        }
    }
}

void free_memory() {
    free(task_collection);
    task_collection = NULL;
    num_tasks = 0;
}
