    *int_array = (int*)malloc(500 * sizeof(int));
    if (*int_array == NULL) {
        printf("Error: Failed to allocate memory for int array\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for the record array
    *record_array = (record*)malloc(2000 * sizeof(record));
    if (*record_array == NULL) {
        printf("Error: Failed to allocate memory for record array\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the arrays with sequential values starting from 0
    for (int i = 0; i < 1000; i++) {
        (*long_array)[i] = i;
    }
    for (int i = 0; i < 500; i++) {
        (*int_array)[i] = i;
    }

    // Populate the record array with random values between -1000 and 1000
    srand(time(NULL));
    for (int i = 0; i < 2000; i++) {
        (*record_array)[i].key = rand() % 2000 - 1000;
        (*record_array)[i].offset = &(*long_array)[i];
    }

    // Validate the pointers in the record array
    for (int i = 0; i < 2000; i++) {
        if ((*record_array)[i].offset == NULL) {
            printf("Error: Null pointer found in record array\n");
            exit(EXIT_FAILURE);
        }
    }
}

void free_memory(long** long_array, int** int_array, record** record_array) {
    // Free the memory allocated for the two arrays
    free(*long_array);
    free(*int_array);

    // Free the memory allocated for the record array
    free(*record_array);
}
```
