// Define a structure to represent a task
typedef struct Task {
    int id;
    int priority;
    char status[10];
    char description[50];
} Task;

// Define a linked list node to store tasks
typedef struct Node {
    Task task;
    struct Node* next;
} Node;

// Define a linked list to store all tasks
Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new task
void addTask(int id, int priority, char* status, char* description) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Create a new node for the task
    Node* newNode = malloc(sizeof(Node));
    newNode->task.id = id;
    newNode->task.priority = priority;
    strcpy(newNode->task.status, status);
    strcpy(newNode->task.description, description);
    newNode->next = NULL;

    // Add the task to the linked list
    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing task
void updateTask(int id, int priority, char* status, char* description) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Find the node for the task with the given ID
    Node* current = head;
    while (current != NULL && current->task.id != id) {
        current = current->next;
    }

    // If the task was found, update its fields
    if (current != NULL) {
        current->task.priority = priority;
        strcpy(current->task.status, status);
        strcpy(current->task.description, description);
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve tasks based on their priority or description
void getTasks(int priority, char* description) {
    // Lock the mutex before accessing the linked list
    pthread_mutex_lock(&mutex);

    // Find the node for the task with the given ID
    Node* current = head;
    while (current != NULL && current->task.priority != priority) {
        current = current->next;
    }

    // If the task was found, print its fields
    if (current != NULL) {
        printf("Task ID: %d\n", current->task.id);
        printf("Priority: %d\n", current->task.priority);
        printf("Status: %s\n", current->task.status);
        printf("Description: %s\n", current->task.description);
    }

    // Unlock the mutex after accessing the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to free all allocated memory when the collection is no longer needed
void destroyCollection() {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Free all nodes in the linked list
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}
