    } else if (event->eventType == 2) {
        // Metadata event
        // Process the metadata
    }
}

void aggregateEvents(Event* events, int numEvents) {
    // Aggregate events based on user ID and timestamp intervals, calculating statistics like the frequency of specific actions and the average duration between events for each user.

    UserStats* userStats = (UserStats*)malloc(sizeof(UserStats));
    memset(userStats, 0, sizeof(UserStats));

    for (int i = 0; i < numEvents; i++) {
        Event* event = events + i;
        checkEventTypeAndPayload(event);

        if (event->userId != userStats->userId) {
            // New user ID encountered, reset the statistics
            userStats->userId = event->userId;
            userStats->actionCount = 0;
            userStats->averageDuration = 0;
            userStats->standardDeviation = 0;
            userStats->longestInterval = 0;
        }

        // Increment the action count and calculate the average duration between events for this user
        userStats->actionCount++;
        double interval = difftime(event->timestamp, userStats->timestamp);
        userStats->averageDuration += interval;
        userStats->standardDeviation += pow(interval - userStats->averageDuration, 2);
        if (userStats->longestInterval < interval) {
            userStats->longestInterval = interval;
        }

        // Update the timestamp for this user
        userStats->timestamp = event->timestamp;
    }
}

void outputAggregatedStatistics(UserStats* userStats, int numUsers) {
    // Output the aggregated statistics in a CSV format, ensuring that the total number of entries does not exceed a specified maximum limit (MAXENTRIES).

    for (int i = 0; i < numUsers; i++) {
        UserStats* userStat = userStats + i;
        if (userStat->actionCount > 0) {
            // Output the statistics for this user
            printf("%d, %d, %.2f, %.2f, %.2f\n", userStat->userId, userStat->actionCount, userStat->averageDuration / userStat->actionCount, sqrt(userStat->standardDeviation / (userStat->actionCount - 1)), userStat->longestInterval);
        }
    }
}

void freeEvent(Event* event) {
    // Free the dynamically allocated memory to prevent memory leaks.
    if (event->payload != NULL) {
        free(event->payload);
    }
}

