    // Implement a mechanism to handle large files efficiently, considering both memory usage and I/O operations, especially when dealing with high-frequency event logs. Ensure that the program can process logs in chunks to minimize memory consumption and optimize performance.

    int fd = open(argv[1], O_RDONLY);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    Event* events = (Event*)malloc(sizeof(Event) * MAXENTRIES);
    int numEvents = 0;

    char buffer[BUFFER_SIZE];
    ssize_t bytesRead;
    while ((bytesRead = read(fd, buffer, BUFFER_SIZE)) > 0) {
        // Parse the binary log file and read each event into a dynamically allocated structure
        for (int i = 0; i < bytesRead; i += sizeof(Event)) {
            Event* event = events + numEvents++;
            parseEvent(event, buffer + i);
            if (numEvents == MAXENTRIES) {
                // Process the events in chunks to minimize memory consumption and optimize performance
                aggregateEvents(events, numEvents);
                outputAggregatedStatistics(userStats, numUsers);
                freeEvent(events);
                numEvents = 0;
            }
        }
    }

    if (numEvents > 0) {
        // Process the remaining events
        aggregateEvents(events, numEvents);
        outputAggregatedStatistics(userStats, numUsers);
        freeEvent(events);
    }

    close(fd);

    return 0;
}
