#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <limits.h>
#include <float.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

// Custom binary log file format
struct Event {
    int type; // event type (e.g., 1 for login, 2 for logout)
    time_t timestamp; // event timestamp (seconds since epoch)
    char* payload; // variable-length payload data
};

// Event filter criteria
struct FilterCriteria {
    int actionType; // action type to filter by (e.g., 1 for login, 2 for logout)
    time_t startTime; // start timestamp of the time range to filter by
    time_t endTime; // end timestamp of the time range to filter by
};

// Event aggregation statistics
struct AggregateStats {
    int userId; // user ID for which the statistics are calculated
    int numEvents; // total number of events in the aggregated period
    double avgEventInterval; // average interval between events (in seconds)
    double stdDevEventInterval; // standard deviation of event intervals (in seconds)
    double longestEventInterval; // longest event interval within the aggregated period (in seconds)
};

// Event parser thread-safe queue
struct Queue {
    struct Event* events; // array of events
    int size; // number of events in the queue
    int capacity; // maximum capacity of the queue
    pthread_mutex_t mutex; // mutex for protecting the queue
};

// Initialize a thread-safe queue with a given capacity
void initQueue(struct Queue* queue, int capacity) {
    queue->events = (struct Event*)malloc(sizeof(struct Event) * capacity);
    queue->size = 0;
    queue->capacity = capacity;
    pthread_mutex_init(&queue->mutex, NULL);
}

// Enqueue an event into the queue
void enqueueEvent(struct Queue* queue, struct Event* event) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->size == queue->capacity) {
        // resize the queue if it's full
        queue->events = (struct Event*)realloc(queue->events, sizeof(struct Event) * (queue->capacity + 1));
        queue->capacity++;
    }
    queue->events[queue->size++] = event;
    pthread_mutex_unlock(&queue->mutex);
}

// Dequeue an event from the queue
struct Event* dequeueEvent(struct Queue* queue) {
    struct Event* event = NULL;
    pthread_mutex_lock(&queue->mutex);
    if (queue->size > 0) {
        event = queue->events[--queue->size];
        // shift the remaining events to fill the gap
        memmove(queue->events, queue->events + 1, sizeof(struct Event) * queue->size);
    }
    pthread_mutex_unlock(&queue->mutex);
    return event;
}

// Destroy a thread-safe queue
void destroyQueue(struct Queue* queue) {
    free(queue->events);
    pthread_mutex_destroy(&queue->mutex);
}

// Parse an event from the binary log file and enqueue it into the queue
bool parseEvent(int fd, struct Queue* queue) {
    // read the event header
    struct EventHeader header;
    ssize_t n = read(fd, &header, sizeof(struct EventHeader));
    if (n != sizeof(struct EventHeader)) {
        return false;
    }

    // allocate memory for the payload data
    char* payload = (char*)malloc(header.payloadSize);
    if (!payload) {
        return false;
    }

    // read the payload data
    n = read(fd, payload, header.payloadSize);
    if (n != header.payloadSize) {
        free(payload);
        return false;
    }

    // create a new event structure and enqueue it into the queue
    struct Event* event = (struct Event*)malloc(sizeof(struct Event));
    event->type = header.type;
    event->timestamp = header.timestamp;
    event->payload = payload;
    enqueueEvent(queue, event);

    return true;
}

// Filter events based on the given filter criteria
void filterEvents(struct Queue* queue, struct FilterCriteria* criteria) {
    // iterate over the events in the queue and filter them based on the criteria
    for (int i = 0; i < queue->size; i++) {
        struct Event* event = queue->events[i];
        if ((criteria->actionType == -1 || event->type == criteria->actionType) &&
            (criteria->startTime == 0 || event->timestamp >= criteria->startTime) &&
            (criteria->endTime == 0 || event->timestamp <= criteria->endTime)) {
            // keep the event if it matches the filter criteria
        } else {
            // discard the event if it doesn't match the filter criteria
            free(event->payload);
            free(event);
            queue->events[i] = NULL;
        }
    }
}

// Aggregate events based on user ID and timestamp intervals
void aggregateEvents(struct Queue* queue, struct AggregateStats* stats) {
    // initialize the aggregation statistics
    stats->userId = -1;
    stats->numEvents = 0;
    stats->avgEventInterval = 0.0;
    stats->stdDevEventInterval = 0.0;
    stats->longestEventInterval = 0.0;

    // iterate over the events in the queue and aggregate them based on user ID and timestamp intervals
    for (int i = 0; i < queue->size; i++) {
        struct Event* event = queue->events[i];
        if (event == NULL) {
            continue;
        }
        // check if the current event belongs to a new user or not
        if (stats->userId != -1 && stats->userId != event->userId) {
            // calculate the aggregation statistics for the previous user
            double avgEventInterval = stats->avgEventInterval / stats->numEvents;
            double stdDevEventInterval = sqrt(stats->stdDevEventInterval / stats->numEvents);
            if (stats->longestEventInterval > 0) {
                printf("User %d: Average event interval = %.2f seconds, Standard deviation of event intervals = %.2f seconds, Longest event interval = %.2f seconds\n",
                    stats->userId, avgEventInterval, stdDevEventInterval, stats->longestEventInterval);
            } else {
                printf("User %d: Average event interval = %.2f seconds, Standard deviation of event intervals = %.2f seconds\n",
                    stats->userId, avgEventInterval, stdDevEventInterval);
            }
            // reset the aggregation statistics for the new user
            stats->userId = event->userId;
            stats->numEvents = 0;
            stats->avgEventInterval = 0.0;
            stats->stdDevEventInterval = 0.0;
            stats->longestEventInterval = 0.0;
        }
        // update the aggregation statistics for the current user
        stats->userId = event->userId;
        stats->numEvents++;
        if (stats->numEvents > 1) {
            double interval = difftime(event->timestamp, queue->events[i - 1]->timestamp);
            stats->avgEventInterval += interval;
            stats->stdDevEventInterval += pow(interval - avgEventInterval, 2);
            if (stats->longestEventInterval < interval) {
                stats->longestEventInterval = interval;
            }
        } else {
            stats->avgEventInterval = interval;
            stats->stdDevEventInterval = 0.0;
            stats->longestEventInterval = interval;
        }
    }
}

// Output the aggregated statistics in a CSV format
void outputStats(struct AggregateStats* stats, int maxEntries) {
    // check if there are any events to aggregate
    if (stats->numEvents == 0) {
        return;
    }
    // calculate the average and standard deviation of event intervals for all users
    double avgEventInterval = stats->avgEventInterval / stats->numEvents;
    double stdDevEventInterval = sqrt(stats->stdDevEventInterval / stats->numEvents);
    // output the aggregated statistics in a CSV format
    printf("User ID,Number of events,Average event interval (seconds),Standard deviation of event intervals (seconds),Longest event interval (seconds)\n");
    for (int i = 0; i < maxEntries && stats->numEvents > 0; i++) {
        printf("%d,%d,%.2f,%.2f,%.2f\n", stats->userId, stats->numEvents, avgEventInterval, stdDevEventInterval, stats->longestEventInterval);
        // update the aggregation statistics for the next user
        stats->userId = -1;
        stats->numEvents = 0;
        stats->avgEventInterval = 0.0;
        stats->stdDevEventInterval = 0.0;
        stats->longestEventInterval = 0.0;
    }
}

// Main function for the program
int main(int argc, char* argv[]) {
    // check if the input file is specified
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }
    // open the binary log file for reading
    int fd = open(argv[1], O_RDONLY);
    if (fd == -1) {
        perror("Error opening input file");
        return 1;
    }

    // initialize the thread-safe queue with a capacity of 1024 events
    struct Queue queue;
    initQueue(&queue, 1024);

    // parse and filter events from the binary log file
    while (parseEvent(fd, &queue)) {
        filterEvents(&queue, &criteria);
    }

    // aggregate events based on user ID and timestamp intervals
    struct AggregateStats stats;
    aggregateEvents(&queue, &stats);

    // output the aggregated statistics in a CSV format
    outputStats(&stats, MAXENTRIES);

    // close the binary log file
    close(fd);

    return 0;
}']

