void aggregate_events(EventData* events[], int num_events) {
    // Initialize the user activity statistics array
    UserActivityStats* stats = malloc(sizeof(UserActivityStats) * num_events);
    if (!stats) {
        perror("Failed to allocate memory for user activity statistics");
        return;
