        int user_id = get_user_id(event->header);
        long timestamp = get_timestamp(event->payload);
        UserActivityStats* stat = &stats[user_id];

        // Update the action count and average duration
        stat->action_count++;
        stat->average_duration += (double)timestamp - stat->longest_interval;

        // Update the longest interval
        if (stat->longest_interval < timestamp) {
            stat->longest_interval = timestamp;
        }
    }

    // Calculate the standard deviation of event intervals
    for (int i = 0; i < num_events; i++) {
        UserActivityStats* stat = &stats[i];
        double average = stat->average_duration / stat->action_count;
        double sum = 0.0;
        for (int j = 0; j < stat->action_count; j++) {
            sum += pow((double)stat->longest_interval - average, 2);
        }
        stat->standard_deviation = sqrt(sum / stat->action_count);
    }

    // Output the user activity statistics in a CSV format
    for (int i = 0; i < num_events; i++) {
        UserActivityStats* stat = &stats[i];
        printf("%d,%ld,%d,%.2f,%.2f,%.2f\n", stat->user_id, stat->timestamp, stat->action_count, stat->average_duration, stat->standard_deviation, stat->longest_interval);
    }
