// Initialize a new task collection
void initTaskCollection(struct TaskCollection *collection) {
    collection->size = 0;
    collection->tasks = NULL;
    pthread_mutex_init(&collection->lock, NULL);
}

// Add a new task to the collection
int addTask(struct TaskCollection *collection, struct Task *task) {
    // Acquire the lock
    pthread_mutex_lock(&collection->lock);

    // Allocate memory for the task
    struct Task *new_task = malloc(sizeof(struct Task));
    if (new_task == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    // Copy the task data
    memcpy(new_task, task, sizeof(struct Task));

    // Add the task to the collection
    collection->tasks = realloc(collection->tasks, (collection->size + 1) * sizeof(struct Task *));
    if (collection->tasks == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    collection->tasks[collection->size++] = new_task;

    // Release the lock
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

