// Initialize a new task collection with a given capacity
void initTaskCollection(struct TaskCollection *collection, size_t capacity) {
    collection->tasks = malloc(capacity * sizeof(struct Task));
    collection->capacity = capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

// Add a new task to the collection
void addTask(struct TaskCollection *collection, struct Task *task) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count == collection->capacity) {
        // Reallocate memory for the tasks array if necessary
        size_t new_capacity = collection->capacity * 2;
        struct Task **new_tasks = realloc(collection->tasks, new_capacity * sizeof(struct Task));
        if (new_tasks == NULL) {
            // Handle error
        }
        collection->tasks = new_tasks;
        collection->capacity = new_capacity;
    }
    collection->tasks[collection->count++] = task;
    pthread_mutex_unlock(&collection->lock);
}

// Update an existing task in the collection
void updateTask(struct TaskCollection *collection, struct Task *task) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->tasks[i]->id == task->id) {
            // Update the task in place
            memcpy(collection->tasks[i], task, sizeof(struct Task));
