using System;
using System.Xml;
using System.Xml.XPath;

public static class XmlParser {
    public static XmlElement Parse(string xml) {
        // Create an XPathDocument from the XML string
        var doc = new XPathDocument(new StringReader(xml));

        // Create an XPathNavigator for navigating the document
        var nav = doc.CreateNavigator();

        // Select the first element that matches the specified XPath expression
        var expr = "/root/element";
        var node = nav.SelectSingleNode(expr);

        if (node == null) {
            throw new Exception("No matching elements found");
        } else if (node.Count > 1) {
            throw new Exception("Multiple matching elements found");
        }

        // Return the first element that matches the XPath expression
        return node;
    }
}
