// Define the function for fetching a private key and certificate from a location specified in an OAuth request and combining them into a single PEM file
void fetch_private_key_and_certificate(const char *location, const char *format) {
    // Check if the location is valid
    if (location == NULL || format == NULL) {
        return;
    }

    // Open the private key and certificate files
    FILE *private_key_file = fopen(location, "r");
    FILE *certificate_file = fopen(location, "r");

    // Check if the files could not be opened
    if (private_key_file == NULL || certificate_file == NULL) {
        return;
    }

    // Read the private key and certificate from the files
    char *private_key = malloc(1024);
    char *certificate = malloc(1024);

    // Check if memory could not be allocated
    if (private_key == NULL || certificate == NULL) {
        fclose(private_key_file);
        fclose(certificate_file);
        return;
    }

    // Read the private key and certificate from the files
    size_t num_read = fread(private_key, 1, 1024, private_key_file);
    num_read = fread(certificate, 1, 1024, certificate_file);

    // Check if an error occurred while reading the files
    if (num_read == 0) {
        free(private_key);
        free(certificate);
        fclose(private_key_file);
        fclose(certificate_file);
        return;
    }

    // Combine the private key and certificate into a single PEM file
    char *pem = malloc(num_read + 1024);

    // Check if memory could not be allocated
    if (pem == NULL) {
        free(private_key);
        free(certificate);
        fclose(private_key_file);
        fclose(certificate_file);
        return;
    }

    // Combine the private key and certificate into a single PEM file
    strcpy(pem, "-----BEGIN PRIVATE KEY-----\n");
    strcat(pem, private_key);
    strcat(pem, "\n-----END PRIVATE KEY-----\n");
    strcat(pem, "-----BEGIN CERTIFICATE-----\n");
    strcat(pem, certificate);
    strcat(pem, "\n-----END CERTIFICATE-----\n");

    // Free the memory used for reading the files
    free(private_key);
    free(certificate);
    fclose(private_key_file);
    fclose(certificate_file);

    // Return the combined PEM file in the specified format
    return pem;
}
