        char *event_type = json_object_get_string(json_object_object_get(json, "event_type"));
        char *metadata = json_object_get_string(json_object_object_get(json, "metadata"));

        // Create a new log entry and add it to the hash table
        struct LogEntry *entry = malloc(sizeof(struct LogEntry));
        entry->timestamp = timestamp;
        entry->event_type = event_type;
        entry->metadata = metadata;
        hash_table_insert(table, entry);
