    // Close the file and free the memory allocated for the line buffer
    fclose(fp);
    free(line);
}

// Function to handle filtering of logs based on specific criteria
void filterLogs(HashTable *table, struct CommandLineOptions options) {
    // Iterate over each log entry in the hash table and filter it based on the specified criteria
    for (int i = 0; i < table->count; i++) {
        struct LogEntry *entry = table->entries[i];
        if (options.event_type != NULL && strcmp(entry->event_type, options.event_type) != 0) {
            continue;
        }
        if (options.timestamp_range != NULL && entry->timestamp < options.timestamp_range.start || entry->timestamp > options.timestamp_range.end) {
