    // Start the external API for real-time profile synchronization and historical data retrieval
    // Implement the function to start the external API

    // Wait for all threads to finish before exiting
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up and free allocated memory
    cleanup();

    return 0;
}
