#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>
#include <errno.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <limits.h>
#include "logging_library.h"
#include "file_processing_utility.h"

// Define constants for command line options
#define OPTION_HELP 1
#define OPTION_VERSION 2
#define OPTION_MANPAGE 3
#define OPTION_COUNT_SPECIFIC_WORD 4
#define OPTION_OUTPUT_FILE 5

// Define constants for file processing
#define BUFFER_SIZE 1024
#define MAX_FILE_SIZE (10 * 1024 * 1024) // 10 MB
#define CHUNK_SIZE 1024

// Define structure to hold thread-specific data
typedef struct {
    int file_descriptor;
    char* buffer;
} thread_data_t;

// Define function prototypes
void parse_command_line_arguments(int argc, char** argv);
void print_usage();
void print_version();
void print_manpage();
void count_specific_word(char* word);
void process_file(char* file_path);
void* thread_function(void* data);
void handle_error(const char* message);

// Global variables
int num_threads = 0;
int total_lines = 0;
int total_words = 0;
int specific_word_count = 0;
char* output_file_path = NULL;
bool is_output_file_specified = false;

int main(int argc, char** argv) {
    // Parse command line arguments
    parse_command_line_arguments(argc, argv);

    // Print usage information if no input file is specified
    if (argc == 1) {
        print_usage();
        return 0;
    }

    // Process each input file in parallel using threads
    for (int i = 1; i < argc; i++) {
        char* file_path = argv[i];
        process_file(file_path);
    }

    // Print results to stdout or output file
    if (!is_output_file_specified) {
        printf("Total lines: %d\n", total_lines);
        printf("Total words: %d\n", total_words);
        if (specific_word_count > 0) {
            printf("Specific word count: %d\n", specific_word_count);
        }
    } else {
        FILE* output_file = fopen(output_file_path, "w");
        if (!output_file) {
            handle_error("Failed to open output file");
        }
        fprintf(output_file, "Total lines: %d\n", total_lines);
        fprintf(output_file, "Total words: %d\n", total_words);
        if (specific_word_count > 0) {
            fprintf(output_file, "Specific word count: %d\n", specific_word_count);
        }
        fclose(output_file);
    }

    return 0;
}

void parse_command_line_arguments(int argc, char** argv) {
    // Parse command line options
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
            OPTION_HELP;
        } else if (!strcmp(argv[i], "-v") || !strcmp(argv[i], "--version")) {
            OPTION_VERSION;
        } else if (!strcmp(argv[i], "-m") || !strcmp(argv[i], "--manpage")) {
            OPTION_MANPAGE;
        } else if (!strcmp(argv[i], "-c") || !strcmp(argv[i], "-cs")) {
            OPTION_COUNT_SPECIFIC_WORD;
        } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output")) {
            OPTION_OUTPUT_FILE;
        } else {
            // Assume input file is specified
            process_file(argv[i]);
        }
    }
}

void print_usage() {
    printf("Usage: program [options] <input files>\n");
    printf("\nOptions:\n");
    printf("  -h, --help                   Display usage information\n");
    printf("  -v, --version                Print the version number of the program\n");
    printf("  -m, --manpage                Display a detailed manpage\n");
    printf("  -c, -cs <specific word>      Count the occurrences of a specific word provided via stdin\n");
    printf("  -o, --output <output file>   Specify an output file to write the results to instead of stdout\n");
}

void print_version() {
    printf("Version: %s\n", VERSION);
}

void print_manpage() {
    // Print detailed manpage here
}

void count_specific_word(char* word) {
    // Read input from stdin and count occurrences of specific word
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, stdin)) {
        if (strstr(buffer, word)) {
            specific_word_count++;
        }
    }
}

void process_file(char* file_path) {
    // Open input file and create thread data for each chunk of the file
    int file_descriptor = open(file_path, O_RDONLY);
    if (file_descriptor == -1) {
        handle_error("Failed to open input file");
    }
    struct stat file_stat;
    fstat(file_descriptor, &file_stat);
    size_t file_size = file_stat.st_size;
    if (file_size > MAX_FILE_SIZE) {
        handle_error("File size exceeds maximum threshold");
    }
    int chunk_count = (int)(file_size / CHUNK_SIZE);
    thread_data_t* thread_data = malloc(sizeof(thread_data_t) * chunk_count);
    for (int i = 0; i < chunk_count; i++) {
        thread_data[i].file_descriptor = file_descriptor;
        thread_data[i].buffer = malloc(CHUNK_SIZE);
    }

    // Create threads to process each chunk of the file concurrently
    pthread_t* threads = malloc(sizeof(pthread_t) * chunk_count);
    for (int i = 0; i < chunk_count; i++) {
        thread_data[i].buffer = malloc(CHUNK_SIZE);
        int rc = pthread_create(&threads[i], NULL, thread_function, &thread_data[i]);
        if (rc) {
            handle_error("Failed to create thread");
        }
    }

    // Wait for all threads to complete and update global variables
    for (int i = 0; i < chunk_count; i++) {
        pthread_join(threads[i], NULL);
        total_lines += thread_data[i].buffer->total_lines;
        total_words += thread_data[i].buffer->total_words;
    }

    // Close input file and free resources
    close(file_descriptor);
    for (int i = 0; i < chunk_count; i++) {
        free(thread_data[i].buffer);
    }
    free(thread_data);
    free(threads);
}

void* thread_function(void* data) {
    // Read input from file descriptor and update buffer with line and word counts
    thread_data_t* thread_data = (thread_data_t*)data;
    char* buffer = thread_data->buffer;
    int file_descriptor = thread_data->file_descriptor;
    size_t bytes_read = 0;
    while ((bytes_read = read(file_descriptor, buffer, CHUNK_SIZE)) > 0) {
        char* line = buffer;
        int line_count = 0;
        int word_count = 0;
        while (line < buffer + bytes_read) {
            if (*line == '\n') {
                line_count++;
            } else if (!isspace(*line)) {
                word_count++;
            }
            line++;
        }
        buffer->total_lines += line_count;
        buffer->total_words += word_count;
    }
    return NULL;
}

void handle_error(const char* message) {
    perror(message);
    exit(EXIT_FAILURE);
}
