    init_arrays();

    // Check if the program has been invoked with no arguments
    if (argc == 1) {
        printf("Usage: %s [options] <input files>\n", argv[0]);
        return -1;
    }

    // Parse the command line arguments and handle invalid options
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
            printf("Usage: %s [options] <input files>\n", argv[0]);
            return -1;
        } else if (!strcmp(argv[i], "-v") || !strcmp(argv[i], "--version")) {
            printf("%s version 1.0\n", argv[0]);
            return -1;
        } else if (!strcmp(argv[i], "-m") || !strcmp(argv[i], "--manpage")) {
            printf("Manual page for %s\n", argv[0]);
            return -1;
        } else if (!strcmp(argv[i], "-c") || !strcmp(argv[i], "-cs")) {
            // Check if the next argument is a valid word to count occurrences of
            if (i + 1 >= argc) {
                printf("Error: Missing word to count occurrences of\n");
                return -1;
            } else {
                char *word = argv[i + 1];
                // Check if the word is a valid string
                if (strlen(word) == 0) {
                    printf("Error: The word to count occurrences of cannot be an empty string\n");
                    return -1;
                }
            }
        } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output")) {
            // Check if the next argument is a valid output file path
            if (i + 1 >= argc) {
                printf("Error: Missing output file path\n");
                return -1;
            } else {
                char *path = argv[i + 1];
                // Check if the output file path is valid
                check_file_path(path);
            }
        } else {
            // Check if the argument is a valid input file path
            char *path = argv[i];
            check_file_path(path);
        }
    }

    // Process each input file line by line and add records to the array
    for (int i = 1; i < argc; i++) {
        // Open the input file in read mode
        int fd = open(argv[i], O_RDONLY);
        if (fd == -1) {
            printf("Error: Failed to open the input file\n");
            return -1;
        }

        // Check if the file descriptor limit has been reached
        check_file_descriptor_limits();

        // Read the contents of the file line by line and add records to the array
        char buffer[BUFFER_SIZE];
        while (read(fd, buffer, BUFFER_SIZE) > 0) {
            // Split the line into words and count the occurrences of a specific word
            char *words = strtok(buffer, " ");
            int count = 0;
            while (words != NULL) {
                if (!strcmp(words, "specific_word")) {
                    count++;
                }
                words = strtok(NULL, " ");
            }

            // Add a record to the array with the number of occurrences
            record r;
            r.value = count;
            update_status(&r);
            add_record(&r);
        }

        // Close the input file
        close(fd);
    }

    // Print the total number of records added to the array
    printf("Total number of records: %d\n", records_count);

    return 0;
}
