#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <errno.h>

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the array of structures for managing the CRC indications
static NFAPI_CRC_INDICATION_PDU_T *crc_indication_array = NULL;

// Define the mutex for protecting concurrent access to the array
static pthread_mutex_t crc_indication_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function for dynamically managing the array of structures
void manage_crc_indications(uint32_t num_entries) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&crc_indication_mutex);

    // Check if the array has already been allocated
    if (crc_indication_array == NULL) {
        // Allocate memory for the array of structures
        crc_indication_array = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Check if memory allocation failed
        if (crc_indication_array == NULL) {
            // Log an error message and return
            fprintf(stderr, "Error: Failed to allocate memory for CRC indications array\n");
            pthread_mutex_unlock(&crc_indication_mutex);
            return;
        }
    } else {
        // Check if the number of entries has changed
        if (num_entries != crc_indication_array->num_entries) {
            // Reallocate memory for the array of structures
            NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(crc_indication_array, num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            // Check if memory reallocation failed
            if (new_array == NULL) {
                // Log an error message and return
                fprintf(stderr, "Error: Failed to reallocate memory for CRC indications array\n");
                pthread_mutex_unlock(&crc_indication_mutex);
                return;
            } else {
                // Update the pointer to the new array
                crc_indication_array = new_array;
            }
        }
    }

    // Initialize the structures in the array
    for (uint32_t i = 0; i < num_entries; i++) {
        crc_indication_array[i].RX_UE_INFORMATION_TAG = i + 1;
