// Define the function for dynamically managing an array of HTTP response PDUs
HTTP_RESPONSE_PDU_T* manage_array(int size) {
    // Check if the requested size is valid
    if (size <= 0 || size > MAX_SIZE) {
        return NULL;
    }

    // Lock the mutex to protect concurrent access to the array
    pthread_mutex_lock(&mutex);

    // Allocate memory for the array of structures
    HTTP_RESPONSE_PDU_T* array = (HTTP_RESPONSE_PDU_T*)malloc(size * sizeof(HTTP_RESPONSE_PDU_T));
