void free_array(HTTP_RESPONSE_PDU_T* array, int size) {
    // Check if the array is valid
    if (!array) {
        return;
    }

    // Lock the mutex to protect concurrent access to the array
    pthread_mutex_lock(&mutex);

    // Free the memory for the array of structures
    for (int i = 0; i < size; i++) {
        HTTP_RESPONSE_PDU_T* pdu = &array[i];
        free(pdu->body.data);
    }
    free(array);

    // Update the number of allocated structures
    num_allocated -= size;

    // Unlock the mutex to allow other threads to access the array
    pthread_mutex_unlock(&mutex);
}

// Define the function for reallocating an array of HTTP response PDUs
