int addNewReading(SensorReading* reading) {
    // Check if the 'record' array is full
    if (numRecords == MAX_RECORDS) {
        return -1;
    }

    // Add the new reading to the 'record' array
    record[numRecords++] = *reading;

    return 0;
}

// Define the function to update an existing reading in the 'record' array
int updateReading(SensorReading* reading) {
    // Check if the 'record' array is empty
    if (numRecords == 0) {
        return -1;
    }

    // Find the index of the existing reading to be updated
    int i = 0;
    while (i < numRecords && record[i].timestamp != reading->timestamp) {
        i++;
    }

    // Check if the reading was found
    if (i == numRecords) {
        return -1;
    }

    // Update the existing reading with the new values
    record[i] = *reading;

    return 0;
}

