int main(int argc, char* argv[]) {
    // Initialize variables
    int numFiles = 0;
    int numRecords = 0;
    int allocatedMemory = 0;
    int leakedMemory = 0;
    int raceConditionOccurred = 0;
    int dataCorruptionOccurred = 0;
    int timeoutOccurred = 0;
    char* filePaths[MAX_FILES];
    SensorReading record[MAX_RECORDS];

    // Check if the command line arguments are valid
    if (argc < 2) {
        fprintf(stderr, "Error: no input files specified\n");
        exit(1);
    }

    // Parse the command line arguments and handle usage information
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
            fprintf(stderr, "Usage: %s [options] input_file...\n", argv[0]);
            exit(1);
        } else if (!strcmp(argv[i], "-v") || !strcmp(argv[i], "--version")) {
            fprintf(stderr, "%s version 1.0\n", argv[0]);
            exit(1);
        } else if (!strcmp(argv[i], "-m") || !strcmp(argv[i], "--manpage")) {
            fprintf(stderr, "Manual page for %s\n", argv[0]);
            exit(1);
        } else if (!strcmp(argv[i], "-c") || !strcmp(argv[i], "-cs")) {
            // Count occurrences of a specific word via stdin
            char* word = argv[++i];
            int count = 0;
            while (fgets(stdin)) {
                if (!strcmp(word, line)) {
                    count++;
                }
            }
            fprintf(stderr, "The word '%s' occurs %d times\n", word, count);
        } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output")) {
            // Specify an output file
            char* outputFile = argv[++i];
            FILE* out = fopen(outputFile, "w");
            if (out == NULL) {
                fprintf(stderr, "Error: unable to open output file '%s'\n", outputFile);
                exit(1);
            }
        } else {
            // Add the input file to the list of files to be processed
            numFiles++;
            manageFileDescriptors(numFiles);
            handleSpecialFilePaths(argv[i]);
            filePaths[numFiles - 1] = argv[i];
        }
    }

    // Process each input file line by line
    for (int i = 0; i < numFiles; i++) {
        FILE* in = fopen(filePaths[i], "r");
        if (in == NULL) {
            fprintf(stderr, "Error: unable to open input file '%s'\n", filePaths[i]);
            exit(1);
        }
        char line[BUFFER_SIZE];
        while (fgets(line, BUFFER_SIZE, in)) {
            // Parse the line and add or update a reading as appropriate
            SensorReading* reading = parseLine(line);
            if (reading != NULL) {
                int result = addNewReading(reading);
                if (result == -1) {
                    fprintf(stderr, "Error: unable to add new reading\n");
                    exit(1);
                }
            } else {
                // Update an existing reading
                result = updateReading(reading);
                if (result == -1) {
                    fprintf(stderr, "Error: unable to update existing reading\n");
                    exit(1);
                }
            }
        }
        fclose(in);
    }

    // Output the results to the specified output file or stdout if none is specified
    if (out != NULL) {
        for (int i = 0; i < numRecords; i++) {
            fprintf(out, "%d\t%f\n", record[i].timestamp, record[i].readingValue);
        }
        fclose(out);
    } else {
        for (int i = 0; i < numRecords; i++) {
            printf("%d\t%f\n", record[i].timestamp, record[i].readingValue);
        }
    }

    // Handle memory leaks and data corruption
    handleMemoryLeaks();
    manageMemoryUsage();
    manageThreadSafety();

    return 0;
}
