// Define a structure to represent a sensor reading
typedef struct SensorReading {
    time_t timestamp;
    int sensor_id;
    float reading_value;
    char* device_ids;
} SensorReading;

// Define a function to add a new reading to the dynamic array of readings
int add_reading(SensorReading* readings, int num_readings, SensorReading new_reading) {
    // Check if there is enough space in the array for the new reading
    if (num_readings >= MAX_READINGS) {
        return -1;
    }

    // Add the new reading to the end of the array
    readings[num_readings] = new_reading;

    // Increment the number of readings
    num_readings++;

    return 0;
}

// Define a function to update an existing reading in the dynamic array of readings
int update_reading(SensorReading* readings, int num_readings, SensorReading new_reading) {
    // Check if there is enough space in the array for the new reading
    if (num_readings >= MAX_READINGS) {
        return -1;
    }

    // Find the index of the existing reading to update
    int i = 0;
    while (i < num_readings && readings[i].timestamp != new_reading.timestamp) {
        i++;
    }

    // Check if a matching reading was found
    if (i == num_readings) {
        return -1;
    }

    // Update the existing reading with the new values
    readings[i].sensor_id = new_reading.sensor_id;
    readings[i].reading_value = new_reading.reading_value;

    return 0;
}

// Define a function to remove an existing reading from the dynamic array of readings
int remove_reading(SensorReading* readings, int num_readings, time_t timestamp) {
    // Find the index of the existing reading to remove
    int i = 0;
    while (i < num_readings && readings[i].timestamp != timestamp) {
        i++;
    }

    // Check if a matching reading was found
    if (i == num_readings) {
        return -1;
    }

    // Remove the existing reading from the array
    for (int j = i; j < num_readings - 1; j++) {
        readings[j] = readings[j + 1];
    }

    // Decrement the number of readings
    num_readings--;

    return 0;
}

// Define a function to print all the readings in the dynamic array
void print_readings(SensorReading* readings, int num_readings) {
    for (int i = 0; i < num_readings; i++) {
        printf("Timestamp: %ld\n", readings[i].timestamp);
        printf("Sensor ID: %d\n", readings[i].sensor_id);
        printf("Reading value: %f\n", readings[i].reading_value);
        printf("Device IDs: %s\n", readings[i].device_ids);
    }
}

