        if (fclose(fp) == EOF) {
            fprintf(stderr, "Error: %s: File not found\n", argv[i]);
            return 1;
        }
    }

    // Print the aggregated results to the specified output file
    if (output_file != NULL) {
        if ((fp = fopen(output_file, "w")) == NULL) {
            fprintf(stderr, "Error: %s: File not found\n", output_file);
            return 1;
        }
        fprintf(fp, "%d lines\n%ld characters\n", total_lines, total_chars);
        if (fclose(fp) == EOF) {
