typedef struct {
    char *filename;
    int fd;
} file_info_t;

typedef struct {
    long num_lines;
    long num_chars;
} aggregated_stats_t;

void print_usage(char *progname) {
    printf("Usage: %s [options] <file1> [file2] ...\n", progname);
    printf("\nOptions:\n");
    printf("  -c          Output only the total character count of all lines across all input files.\n");
    printf("  -o <output_file> Write the aggregated results (total lines and character count) to the specified output file.\n");
    printf("  --help      Display detailed usage information.\n");
}

void *process_file(void *arg) {
    file_info_t *file = (file_info_t *) arg;
    char line[MAX_LINE_LENGTH];
    long num_lines = 0, num_chars = 0;

    while (read(file->fd, line, MAX_LINE_LENGTH) > 0) {
        num_lines++;
        num_chars += strlen(line);
    }

    aggregated_stats_t *stats = malloc(sizeof(aggregated_stats_t));
    stats->num_lines = num_lines;
    stats->num_chars = num_chars;

    return (void *) stats;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        print_usage(argv[0]);
        exit(1);
    }

    bool output_only = false;
    char *output_file = NULL;
    int num_files = argc - 1;
    file_info_t *files = malloc(sizeof(file_info_t) * num_files);

    for (int i = 0; i < num_files; i++) {
        files[i].filename = argv[i + 1];
        files[i].fd = open(files[i].filename, O_RDONLY);
        if (files[i].fd == -1) {
            perror("open");
            exit(1);
        }
    }

    pthread_t threads[NUM_THREADS];
    aggregated_stats_t *stats = malloc(sizeof(aggregated_stats_t));
    stats->num_lines = 0;
    stats->num_chars = 0;

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, process_file, &files[i]);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        void *result;
        pthread_join(threads[i], &result);
        aggregated_stats_t *tmp_stats = (aggregated_stats_t *) result;
        stats->num_lines += tmp_stats->num_lines;
        stats->num_chars += tmp_stats->num_chars;
    }

    if (output_only) {
        FILE *outfile = fopen(output_file, "w");
        if (!outfile) {
            perror("fopen");
            exit(1);
        }
        fprintf(outfile, "%ld\n", stats->num_lines);
        fclose(outfile);
    } else {
        printf("%ld lines, %ld characters\n", stats->num_lines, stats->num_chars);
    }

    for (int i = 0; i < num_files; i++) {
        close(files[i].fd);
    }

    free(stats);
    free(files);

    return 0;
}
