using namespace std;

// Define the image processing library and concurrent processing mechanism
#define IMAGE_PROCESSING_LIB "opencv"
#define CONCURRENCY_MECHANISM "thread pool"

// Define the maximum number of worker threads for concurrent processing
#define MAX_WORKER_THREADS 4

// Define the image file format and resolution constraints
#define IMAGE_FILE_FORMAT ".jpg"
#define MIN_IMAGE_WIDTH 100
#define MIN_IMAGE_HEIGHT 100
#define MAX_IMAGE_WIDTH 2000
#define MAX_IMAGE_HEIGHT 2000

// Define the output file format and path
#define OUTPUT_FILE_FORMAT ".txt"
#define OUTPUT_FILE_PATH "./output.txt"

// Define the command line options for usage instructions, total pixel count only, and output file
#define USAGE_OPTION "-h"
#define TOTAL_PIXEL_COUNT_ONLY_OPTION "-p"
#define OUTPUT_FILE_OPTION "-o"

// Define the command line option for help instructions
#define HELP_OPTION "--help"

// Define the usage instructions
const string USAGE_INSTRUCTIONS = "Usage: image-processing [options] <image file 1> [<image file 2> ... <image file N>]\n\nOptions:\n" +
                                 "-h, --help\t\tDisplay detailed usage information.\n" +
                                 "-p\t\t\tOutput only the total pixel count of all images.\n" +
                                 "-o <output_file>\tWrite the aggregated results (average color intensity and total pixel count) to the specified output file.\n";

// Define the error messages for invalid command line options, unsupported image formats, and I/O errors
const string INVALID_OPTION_ERROR = "Invalid option provided. Please use -h or --help for usage instructions.";
const string UNSUPPORTED_IMAGE_FORMAT_ERROR = "Unsupported image format. Only JPEG images are supported.";
const string IMAGE_READ_ERROR = "Error reading image file. Check the file path and format.";
const string OUTPUT_FILE_WRITE_ERROR = "Error writing to output file. Check the file path and permissions.";

// Define the mutex and condition variable for concurrent processing
mutex mtx;
condition_variable cv;

// Define the image processing function
void processImage(string imageFile) {
    // Load the image using the image processing library
    Mat image = imread(imageFile, IMAGE_PROCESSING_LIB);

    // Check if the image is valid and within the resolution constraints
    if (image.empty() || image.cols < MIN_IMAGE_WIDTH || image.rows < MIN_IMAGE_HEIGHT || image.cols > MAX_IMAGE_WIDTH || image.rows > MAX_IMAGE_HEIGHT) {
        cerr << "Error: Invalid image file or resolution constraints not met." << endl;
        return;
    }

    // Calculate the average color intensity and overall pixel count for the image
    Scalar mean, stddev;
    reduce(image, mean, 0, REDUCE_AVG);
    reduce(image, stddev, 1, REDUCE_AVG);
    int totalPixels = image.cols * image.rows;

    // Output the results to the console and/or file
    cout << "Average color intensity: " << mean << endl;
    cout << "Total pixel count: " << totalPixels << endl;
}

// Define the concurrent processing function
void processImages(vector<string> imageFiles) {
    // Initialize the worker threads and condition variable
    vector<thread> workers;
    for (int i = 0; i < MAX_WORKER_THREADS; i++) {
        workers.push_back(thread(processImage));
    }

    // Loop through the image files and process them concurrently using the worker threads
    for (string imageFile : imageFiles) {
        mtx.lock();
        cv.wait(mtx);
        workers[i % MAX_WORKER_THREADS] = thread(processImage, imageFile);
        cv.notify_all();
        mtx.unlock();
    }

    // Join the worker threads and wait for them to complete
    for (thread& worker : workers) {
        worker.join();
    }
}

// Define the main function
int main(int argc, char* argv[]) {
    // Check if the command line options are valid
    if (argc < 2 || string(argv[1]) == HELP_OPTION) {
        cout << USAGE_INSTRUCTIONS << endl;
        return 0;
    }

    // Initialize the output file and total pixel count variables
    ofstream outputFile;
    int totalPixels = 0;

    // Loop through the command line arguments and process them accordingly
    for (int i = 1; i < argc; i++) {
        string option = argv[i];

        // Check if the option is a valid command line option
        if (option == USAGE_OPTION || option == TOTAL_PIXEL_COUNT_ONLY_OPTION || option.substr(0, OUTPUT_FILE_OPTION.length()) == OUTPUT_FILE_OPTION) {
            // Process the image files using the concurrent processing function
            vector<string> imageFiles;
            for (int j = i + 1; j < argc; j++) {
                string imageFile = argv[j];
                if (imageFile.substr(imageFile.length() - IMAGE_FILE_FORMAT.length()) == IMAGE_FILE_FORMAT) {
                    imageFiles.push_back(imageFile);
                } else {
                    cerr << "Error: Invalid image file format." << endl;
                    return 1;
                }
            }
            processImages(imageFiles);

            // Check if the option is for total pixel count only
            if (option == TOTAL_PIXEL_COUNT_ONLY_OPTION) {
                cout << "Total pixel count: " << totalPixels << endl;
                return 0;
            }

            // Check if the option is for output file
            if (option.substr(0, OUTPUT_FILE_OPTION.length()) == OUTPUT_FILE_OPTION) {
                string outputFilePath = option.substr(OUTPUT_FILE_OPTION.length());
                outputFile.open(outputFilePath);
                if (!outputFile.is_open()) {
                    cerr << "Error: Unable to open output file." << endl;
                    return 1;
                }
            }
        } else {
            // Display the usage instructions for invalid command line options
            cout << USAGE_INSTRUCTIONS << endl;
            return 0;
        }
    }

    // Output the results to the console and/or file
    if (outputFile.is_open()) {
        outputFile << "Average color intensity: " << totalPixels / imageFiles.size() << endl;
        outputFile << "Total pixel count: " << totalPixels << endl;
        outputFile.close();
    } else {
        cout << "Average color intensity: " << totalPixels / imageFiles.size() << endl;
        cout << "Total pixel count: " << totalPixels << endl;
    }

    return 0;
}']

