// Define the structure for UEContext
typedef struct {
    int ueId;
    PDU* pduList;
    int refCount;
} UEContext;

// Define the structure for PDU
typedef struct {
    // Add fields as needed
} PDU;

// Define the function to manage the dynamic array of UEContext structures
void manageUEContexts(UEContext** ueContexts, int* numUEContexts) {
    // Allocate memory for a new UEContext structure
    UEContext* newUeContext = (UEContext*)malloc(sizeof(UEContext));
    if (!newUeContext) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the new UEContext structure with valid data
    newUeContext->ueId = 0;
    newUeContext->pduList = NULL;
    newUeContext->refCount = 1;

    // Add the new UEContext to the array of UEContext structures
    *numUEContexts += 1;
    ueContexts = (UEContext**)realloc(ueContexts, (*numUEContexts) * sizeof(UEContext*));
    if (!ueContexts) {
        printf("Memory reallocation failed\n");
        return;
    }
    ueContexts[*numUEContexts - 1] = newUeContext;

    // Create a mutex to protect the array of UEContext structures from concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Add a PDU to an existing UEContext structure
    void addPduToUeContext(UEContext* ueContext, PDU* pdu) {
        // Acquire the mutex to prevent race conditions and deadlocks
        pthread_mutex_lock(&mutex);

        // Increment the reference count of the UEContext structure
        ueContext->refCount += 1;

        // Allocate memory for a new PDU structure
        PDU* newPdu = (PDU*)malloc(sizeof(PDU));
        if (!newPdu) {
            printf("Memory allocation failed\n");
            return;
        }

        // Initialize the new PDU structure with valid data
        newPdu->data = NULL;

        // Add the new PDU to the list of PDUs in the UEContext structure
        ueContext->pduList = (PDU*)realloc(ueContext->pduList, (ueContext->refCount) * sizeof(PDU*));
        if (!ueContext->pduList) {
            printf("Memory reallocation failed\n");
            return;
        }
        ueContext->pduList[ueContext->refCount - 1] = newPdu;

        // Release the mutex to allow other threads to access the array of UEContext structures
        pthread_mutex_unlock(&mutex);
    }

    // Remove a PDU from an existing UEContext structure
    void removePduFromUeContext(UEContext* ueContext, int index) {
        // Acquire the mutex to prevent race conditions and deadlocks
        pthread_mutex_lock(&mutex);

        // Decrement the reference count of the UEContext structure
        ueContext->refCount -= 1;

        // Remove the PDU from the list of PDUs in the UEContext structure
        ueContext->pduList = (PDU*)realloc(ueContext->pduList, (ueContext->refCount) * sizeof(PDU*));
        if (!ueContext->pduList) {
            printf("Memory reallocation failed\n");
            return;
        }

        // Release the mutex to allow other threads to access the array of UEContext structures
        pthread_mutex_unlock(&mutex);
    }

    // Update the reference count of an existing UEContext structure
    void updateUeContextRefCount(UEContext* ueContext) {
        // Acquire the mutex to prevent race conditions and deadlocks
        pthread_mutex_lock(&mutex);

        // Increment or decrement the reference count of the UEContext structure based on whether it is being added or removed from the array of UEContext structures
        if (ueContext->refCount > 0) {
            ueContext->refCount += 1;
        } else {
            ueContext->refCount -= 1;
        }

        // Release the mutex to allow other threads to access the array of UEContext structures
        pthread_mutex_unlock(&mutex);
    }
}
