#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <limits.h>
#include <stdbool.h>

// Custom memory pool allocator for efficient memory access
#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB
static char memoryPool[MEMORY_POOL_SIZE];
static int memoryPoolIndex = 0;

// Thread-safe data structures for concurrent file processing
typedef struct {
    char* filename;
    FILE* file;
    size_t lineCount;
    size_t characterCount;
} FileData;

typedef struct {
    int threadId;
    pthread_t thread;
    semaphore_t semaphore;
    FileData* fileData;
} ThreadData;

// Command-line options and their corresponding values
#define OPTION_HELP "--help"
#define OPTION_CHARACTER_COUNT "-c"
#define OPTION_OUTPUT_FILE "-o"
#define OPTION_PROGRESS_BAR "-p"
#define OPTION_FORMAT "-f"

// Global variables for program state and thread management
static int fileCount = 0;
static size_t totalLineCount = 0;
static size_t totalCharacterCount = 0;
static bool isHelpRequested = false;
static bool isCharacterCountRequested = false;
static bool isOutputFileRequested = false;
static bool isProgressBarRequested = false;
static bool isFormatRequested = false;
static char* outputFileName = NULL;
static char* format = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static semaphore_t semaphore = SEMAPHORE_INITIALIZER;

// Function prototypes for thread-safe data structures and memory pool management
void* processFile(void*);
void initializeMemoryPool();
void* allocateMemory(size_t);
void freeMemory(void*);

int main(int argc, char** argv) {
    // Parse command-line options and validate input
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], OPTION_HELP)) {
            isHelpRequested = true;
        } else if (!strcmp(argv[i], OPTION_CHARACTER_COUNT)) {
            isCharacterCountRequested = true;
        } else if (!strcmp(argv[i], OPTION_OUTPUT_FILE)) {
            isOutputFileRequested = true;
            outputFileName = argv[++i];
        } else if (!strcmp(argv[i], OPTION_PROGRESS_BAR)) {
            isProgressBarRequested = true;
        } else if (!strcmp(argv[i], OPTION_FORMAT)) {
            isFormatRequested = true;
            format = argv[++i];
        } else {
            fileCount++;
        }
    }

    // Display usage information and exit if no input files are provided
    if (fileCount == 0) {
        printf("Usage: %s [options] <input_files>\n", argv[0]);
        printf("\nOptions:\n");
        printf("  --help                   Display detailed usage information\n");
        printf("  -c                       Output only the total character count of all lines across all input files\n");
        printf("  -o <output_file>         Write the aggregated results (total lines and character count) to the specified output file\n");
        printf("  -p                       Display a progress bar indicating the percentage of files processed so far\n");
        printf("  -f <format>              Allow customization of the output format through command line options, where <format> can be plain text, JSON, or CSV. The program should validate and convert user-specified formats without introducing bugs.\n");
        return 0;
    }

    // Initialize memory pool for efficient memory access
    initializeMemoryPool();

    // Create threads to process files concurrently
    ThreadData* threadData = (ThreadData*) malloc(fileCount * sizeof(ThreadData));
    for (int i = 0; i < fileCount; i++) {
        threadData[i].threadId = i;
        threadData[i].semaphore = semaphore_create();
        pthread_create(&threadData[i].thread, NULL, processFile, &threadData[i]);
    }

    // Wait for all threads to complete and aggregate results
    for (int i = 0; i < fileCount; i++) {
        pthread_join(threadData[i].thread, NULL);
        totalLineCount += threadData[i].fileData->lineCount;
        totalCharacterCount += threadData[i].fileData->characterCount;
    }

    // Output results to console or file
    if (isHelpRequested) {
        printf("Usage: %s [options] <input_files>\n", argv[0]);
        printf("\nOptions:\n");
        printf("  --help                   Display detailed usage information\n");
        printf("  -c                       Output only the total character count of all lines across all input files\n");
        printf("  -o <output_file>         Write the aggregated results (total lines and character count) to the specified output file\n");
        printf("  -p                       Display a progress bar indicating the percentage of files processed so far\n");
        printf("  -f <format>              Allow customization of the output format through command line options, where <format> can be plain text, JSON, or CSV. The program should validate and convert user-specified formats without introducing bugs.\n");
    } else if (isCharacterCountRequested) {
        printf("%lu\n", totalCharacterCount);
    } else if (isOutputFileRequested) {
        FILE* outputFile = fopen(outputFileName, "w");
        if (!outputFile) {
            perror("fopen");
            return 1;
        }
        fprintf(outputFile, "%lu\n", totalLineCount);
        fprintf(outputFile, "%lu\n", totalCharacterCount);
        fclose(outputFile);
    } else if (isProgressBarRequested) {
        // Display progress bar using ANSI escape sequences
        printf("\033[2K"); // Clear line
        printf("Processing files... ");
        for (int i = 0; i < fileCount; i++) {
            printf("\033[1A\033[2K"); // Move cursor up and clear line
            printf("%d%%", (i + 1) * 100 / fileCount);
        }
    } else if (isFormatRequested) {
        // Output results in specified format
        switch (format[0]) {
            case 'p':
                printf("{\"total_lines\": %lu, \"total_characters\": %lu}\n", totalLineCount, totalCharacterCount);
                break;
            case 'j':
                printf("{\"total_lines\": %lu, \"total_characters\": %lu}\n", totalLineCount, totalCharacterCount);
                break;
            case 'c':
                printf("%lu\n", totalCharacterCount);
                break;
        }
    } else {
        // Output results in plain text format by default
        printf("Total lines: %lu\n", totalLineCount);
        printf("Total characters: %lu\n", totalCharacterCount);
    }

    return 0;
}

void* processFile(void* threadData) {
    ThreadData* data = (ThreadData*) threadData;
    FileData* fileData = (FileData*) malloc(sizeof(FileData));
    fileData->filename = argv[data->threadId + 1];
    fileData->file = fopen(fileData->filename, "r");
    if (!fileData->file) {
        perror("fopen");
        return NULL;
    }

    // Read file line by line and aggregate results
    char* line = (char*) allocateMemory(1024);
    while (fgets(line, 1024, fileData->file)) {
        size_t length = strlen(line);
        if (length > 0 && line[length - 1] == '\n') {
            length--;
        }
        fileData->characterCount += length;
        fileData->lineCount++;
    }

    // Free memory and return results
    freeMemory(line);
    data->fileData = fileData;
    semaphore_post(&data->semaphore);
    pthread_exit(NULL);
}

void initializeMemoryPool() {
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        memoryPool[i] = '\0';
    }
}

void* allocateMemory(size_t size) {
    if (memoryPoolIndex + size > MEMORY_POOL_SIZE) {
        return NULL;
    }
    void* memory = &memoryPool[memoryPoolIndex];
    memoryPoolIndex += size;
    return memory;
}

void freeMemory(void* memory) {
    // Do nothing, as we are using a custom memory pool allocator
}
