#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <cstdlib>
#include <ctime>
#include <unistd.h>
#include <sys/resource.h>
#include "json.hpp"

using namespace std;
using json = nlohmann::json;

// Global variables
int total_lines = 0;
int total_chars = 0;
mutex mtx;
condition_variable cv;
bool done = false;

// Function to process a single file
void process_file(string filename) {
    ifstream infile(filename);
    string line;
    int lines = 0, chars = 0;

    // Read the file line by line
    while (getline(infile, line)) {
        ++lines;
        chars += line.size();
    }

    // Update the global variables
    mtx.lock();
    total_lines += lines;
    total_chars += chars;
    mtx.unlock();
}

// Function to process multiple files in parallel
void process_files(vector<string> filenames) {
    // Create a vector of threads
    vector<thread> threads;

    // Launch a thread for each file
    for (auto filename : filenames) {
        threads.push_back(thread(process_file, filename));
    }

    // Wait for all threads to finish
    for (auto& t : threads) {
        t.join();
    }
}

// Function to display usage instructions
void print_usage() {
    cout << "Usage: ./program [options] <file1> [file2] ..." << endl;
    cout << "Options:" << endl;
    cout << "-c\tOutput only the total character count of all lines across all input files." << endl;
    cout << "-o <output_file>\tWrite the aggregated results (total lines and character count) to the specified output file." << endl;
    cout << "-p\tDisplay a progress bar indicating the percentage of files processed so far." << endl;
    cout << "-f <format>\tCustomize the output format to be either plain text, JSON, or CSV. Validate and convert user-specified formats without introducing bugs." << endl;
    cout << "-t <threads>\tSpecify the number of threads to use for parallel processing. Evaluate the impact of thread pool size on performance and resource utilization." << endl;
    cout << "-m <pool_size>\tSet the size of the custom memory pool allocator used for efficient memory management. Consider the trade-offs between custom allocators and standard library allocators in terms of complexity and performance." << endl;
    cout << "-v\tEnable verbose mode, which provides detailed logging of processing steps and potential errors." << endl;
}

// Main function
int main(int argc, char* argv[]) {
    // Check for invalid command line arguments
    if (argc < 2) {
        print_usage();
        return 1;
    }

    // Parse the command line options
    bool help = false;
    bool output = false;
    string output_file;
    bool progress = false;
    string format;
    int threads = 0;
    int pool_size = 0;
    bool verbose = false;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            help = true;
        } else if (strcmp(argv[i], "-o") == 0) {
            output = true;
            output_file = argv[++i];
        } else if (strcmp(argv[i], "-p") == 0) {
            progress = true;
        } else if (strcmp(argv[i], "-f") == 0) {
            format = argv[++i];
        } else if (strcmp(argv[i], "-t") == 0) {
            threads = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-m") == 0) {
            pool_size = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose = true;
        }
    }

    // Display usage instructions if -h or --help is specified
    if (help) {
        print_usage();
        return 1;
    }

    // Check for invalid command line options
    if (output && format != "plain" && format != "json" && format != "csv") {
        cout << "Invalid output format specified. Valid formats are plain, json, and csv." << endl;
        return 1;
    }

    // Check for invalid thread pool size
    if (threads < 0) {
        cout << "Invalid number of threads specified. The number of threads must be non-negative." << endl;
        return 1;
    }

    // Check for invalid memory pool size
    if (pool_size < 0) {
        cout << "Invalid memory pool size specified. The size of the memory pool must be non-negative." << endl;
        return 1;
    }

    // Create a vector of file names
    vector<string> filenames;
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-h") != 0 && strcmp(argv[i], "--help") != 0) {
            filenames.push_back(argv[i]);
        }
    }

    // Check for no input files specified
    if (filenames.empty()) {
        print_usage();
        return 1;
    }

    // Process the files in parallel using a thread pool
    process_files(filenames);

    // Output the results
    if (output) {
        ofstream outfile(output_file);
        if (!outfile.is_open()) {
            cout << "Error: Unable to open output file." << endl;
            return 1;
        }
        if (format == "plain") {
            outfile << total_lines << "\t" << total_chars << endl;
        } else if (format == "json") {
            json j = {{"total_lines", total_lines}, {"total_chars", total_chars}};
            outfile << j.dump(4) << endl;
        } else if (format == "csv") {
            outfile << total_lines << "," << total_chars << endl;
        }
    } else {
        cout << "Total lines: " << total_lines << endl;
        cout << "Total characters: " << total_chars << endl;
    }

    // Display a progress bar if -p is specified
    if (progress) {
        int files_processed = 0;
        while (!done) {
            mtx.lock();
            ++files_processed;
            cv.notify_all();
            mtx.unlock();
            cout << "Processing file " << files_processed << "/" << filenames.size() << "...";
            this_thread::sleep_for(chrono::seconds(1));
        }
    }

    return 0;
}
