import java.util.HashMap;
import java.util.Map;

public class UserProfileRepository {
  private Map<String, UserProfile> profiles = new HashMap<>();

  public void addUser(String username, String email, String password) {
    UserProfile profile = new UserProfile(username, email, password);
    profiles.put(profile.getUsername(), profile);
  }

  public UserProfile getUser(String username) {
    return profiles.get(username);
  }

  public void deleteUser(String username) {
    profiles.remove(username);
  }

  public void updateUser(String username, String newEmail, String newPassword) {
    UserProfile profile = getUser(username);
    if (profile != null) {
      profile.setEmail(newEmail);
      profile.setPassword(newPassword);
    }
  }
}

class UserProfile {
  private String username;
  private String email;
  private String password;

  public UserProfile(String username, String email, String password) {
    this.username = username;
    this.email = email;
    this.password = password;
  }

  public String getUsername() {
    return username;
  }

  public void setEmail(String newEmail) {
    this.email = newEmail;
  }

  public void setPassword(String newPassword) {
    this.password = newPassword;
  }
}
