```java
import java.util.Scanner;

public static void main(String[] args) {
  Scanner scanner = new Scanner(System.in);
  String command = scanner.nextLine();
  while (!command.equals("exit")) {
    switch (command) {
      case "--help":
        System.out.println("Usage:");
        System.out.println("\t-r <username> - Retrieve user details by username.");
        System.out.println("\t-i <username> <email> <password> - Insert a new user profile.");
        System.out.println("\t-d <username> - Delete a user profile by username.");
        System.out.println("\t-u <username> <new_email> <new_password> - Update user attributes.");
        break;
      case "-r":
        String username = scanner.nextLine();
        UserProfile profile = getUser(username);
        if (profile != null) {
          System.out.println("Username: " + profile.getUsername());
          System.out.println("Email: " + profile.getEmail());
          System.out.println("Password: " + profile.getPassword());
        } else {
          System.out.println("User not found.");
        }
        break;
      case "-i":
        String newUsername = scanner.nextLine();
        String newEmail = scanner.nextLine();
        String newPassword = scanner.nextLine();
        addUser(newUsername, newEmail, newPassword);
        System.out.println("User added successfully.");
        break;
      case "-d":
        String deleteUsername = scanner.nextLine();
        deleteUser(deleteUsername);
        System.out.println("User deleted successfully.");
        break;
      case "-u":
        String updateUsername = scanner.nextLine();
        String newEmail = scanner.nextLine();
        String newPassword = scanner.nextLine();
        updateUser(updateUsername, newEmail, newPassword);
        System.out.println("User updated successfully.");
        break;
      default:
        System.out.println("Invalid command. Type --help for usage information.");
    }
    command = scanner.nextLine();
  }
}
