#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct AlignmentGroup {
    size_t alignment;
    size_t chunkSize;
} AlignmentGroup;

static const AlignmentGroup alignmentGroups[] = {
    { .alignment = 1, .chunkSize = 64 },
    { .alignment = 2, .chunkSize = 128 },
    { .alignment = 4, .chunkSize = 256 },
    { .alignment = 8, .chunkSize = 512 },
    { .alignment = 16, .chunkSize = 1024 },
};

static size_t numAlignmentGroups = sizeof(alignmentGroups) / sizeof(AlignmentGroup);

void* allocateCRCIndicationPDUs(size_t numEntries, size_t alignment) {
    // Validate input parameters
    if (numEntries == 0 || alignment == 0) {
        return NULL;
    }

    // Find the appropriate alignment group
    size_t i = 0;
    for (i = 0; i < numAlignmentGroups; i++) {
        if (alignmentGroups[i].alignment >= alignment) {
            break;
        }
    }

    // Allocate memory in chunks of the appropriate size
    size_t chunkSize = alignmentGroups[i].chunkSize;
    size_t numChunks = (numEntries + chunkSize - 1) / chunkSize;
    void* mem = malloc(numChunks * chunkSize);
    if (!mem) {
        return NULL;
    }

    // Initialize the structures in each chunk
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*) mem;
    for (size_t i = 0; i < numChunks; i++) {
        for (size_t j = 0; j < chunkSize && j < numEntries - i * chunkSize; j++) {
            pdu[i].RX_UE_INFORMATION_TAG = rand();
            pdu[i].RNTI = rand() & 0xFFFF;
            pdu[i].CRC_INDICATION_REL8_TAG = rand() & 0xFF;
            pdu[i].CRCFLAG = (rand() % 2) == 0;
        }
    }

    // Return the allocated memory
    return mem;
}

void freeCRCIndicationPDUs(void* mem) {
    free(mem);
}

bool isValidAlignment(size_t alignment) {
    for (size_t i = 0; i < numAlignmentGroups; i++) {
        if (alignmentGroups[i].alignment == alignment) {
            return true;
        }
    }
    return false;
}

void* allocateCRCIndicationPDUsWithAlignment(size_t numEntries, size_t alignment) {
    // Validate input parameters
    if (numEntries == 0 || !isValidAlignment(alignment)) {
        return NULL;
    }

    // Allocate memory for the structures
    void* mem = allocateCRCIndicationPDUs(numEntries, alignment);
    if (!mem) {
        return NULL;
    }

    // Validate that the allocated memory is properly aligned
    size_t offset = (size_t) mem % alignment;
    if (offset != 0) {
        freeCRCIndicationPDUs(mem);
        return NULL;
    }

    // Return the allocated memory
    return mem;
}

void* allocateCRCIndicationPDUsWithAlignmentAndHash(size_t numEntries, size_t alignment, const char* input) {
    // Validate input parameters
    if (numEntries == 0 || !isValidAlignment(alignment)) {
        return NULL;
    }

    // Allocate memory for the structures
    void* mem = allocateCRCIndicationPDUsWithAlignment(numEntries, alignment);
    if (!mem) {
        return NULL;
    }

    // Generate a secure hash of the input string
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, input, strlen(input));
    uint8_t hash[SHA256_DIGEST_LENGTH];
    SHA256_Final(hash, &ctx);

    // Initialize the structures with the generated hash
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*) mem;
    for (size_t i = 0; i < numEntries; i++) {
        memcpy(pdu[i].RX_UE_INFORMATION_TAG, hash, sizeof(hash));
    }

    // Return the allocated memory
    return mem;
}
