        averageLineLength += lineLength;
        if (longestLine == NULL || strlen(longestLine) < lineLength) {
            longestLine = line;
        }
        if (shortestLine == NULL || strlen(shortestLine) > lineLength) {
            shortestLine = line;
        }
    }

    // Calculate average line length and close file
