    fclose(fp);

    // Print statistics for the log file
    printf("File: %s\n", filename);
    printf("  Line count: %d\n", lineCount);
    printf("  Average line length: %.2f\n", averageLineLength);
    printf("  Longest line: %s\n", longestLine);
    printf("  Shortest line: %s\n", shortestLine);
}

