        struct stat st;
        if (stat(file.c_str(), &st) == -1) {
            handleError("Invalid directory: " + file);
            return 1;
        }
    }
    if (!compressionAlgorithm.empty() && compressionAlgorithm != "LZ4" && compressionAlgorithm != "Zlib") {
        handleError("Unsupported compression algorithm: " + compressionAlgorithm);
        return 1;
    }

    // Process files in parallel using threads
    ThreadData data;
    vector<thread> threads;
    for (int i = 0; i < THREAD_COUNT; ++i) {
        threads.push_back(thread(processFiles, ref(files), ref(data)));
    }
    for (auto& t : threads) {
        t.join();
    }

    // Compress output file if specified
    if (!compressionAlgorithm.empty()) {
        compressOutput(outputFilename, compressionAlgorithm);
    }

    return 0;
}

void processFiles(vector<string>& files, ThreadData& data) {
    for (const string& file : files) {
        ifstream infile(file.c_str());
        if (!infile.is_open()) {
            handleError("Failed to open input file: " + file);
            continue;
        }

        // Read file line by line and calculate statistics
        vector<FileInfo> fileInfos;
        string line;
        while (getline(infile, line)) {
            FileInfo info;
            info.filename = file;
            info.lineCount++;
            info.averageLineLength += line.length();
            if (info.longestLine.empty() || line.length() > info.longestLine.length()) {
                info.longestLine = line;
            }
            if (info.shortestLine.empty() || line.length() < info.shortestLine.length()) {
                info.shortestLine = line;
            }
            fileInfos.push_back(info);
        }

        // Update data structure with new statistics
        unique_lock<mutex> lock(data.mtx);
        data.fileInfos.insert(data.fileInfos.end(), fileInfos.begin(), fileInfos.end());
    }
}

void compressOutput(const string& outputFilename, const string& compressionAlgorithm) {
    // Compress output file using specified algorithm
    if (compressionAlgorithm == "LZ4") {
        lz4_compress(outputFilename.c_str(), NULL);
    } else if (compressionAlgorithm == "Zlib") {
        zlib_compress(outputFilename.c_str(), NULL);
    }
}

void printUsage() {
    // Print usage information
    cout << "Usage: log_aggregator [options] <input files>" << endl;
    cout << "Options:" << endl;
    cout << "-f <min_length>  Filter log files to include only those with lines longer than the specified minimum length" << endl;
    cout << "-o <output_file> Write the aggregated results (line counts, average line lengths, longest and shortest lines) to the specified output file" << endl;
    cout << "-c <compression_algorithm> Specify the compression algorithm for the output file (e.g., LZ4, Zlib)" << endl;
    cout << "-g  Enable GUI mode for interactive operation" << endl;
}

void handleError(const string& errorMessage) {
    // Handle error by printing to stderr and exiting with non-zero status code
    cerr << "Error: " << errorMessage << endl;
    exit(1);
}
