#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>
#include <zlib.h>

// Define the structure for storing log file statistics
typedef struct {
    char *filename;
    int total_lines;
    float average_line_length;
    int longest_line;
    int shortest_line;
} LogFileStats;

// Define the structure for storing aggregated statistics
typedef struct {
    int total_files;
    int total_lines;
    float average_line_length;
    int longest_line;
    int shortest_line;
} AggregateStats;

// Function to count the number of lines in a file
int countLines(FILE *file) {
    int lineCount = 0;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        lineCount++;
    }

    free(line);

    return lineCount;
}

// Function to calculate the average line length in a file
float calculateAverageLineLength(FILE *file) {
    int totalLines = countLines(file);
    long totalBytes = 0;

    if (totalLines > 0) {
        char *line = NULL;
        size_t len = 0;
        ssize_t read;

        while ((read = getline(&line, &len, file)) != -1) {
            totalBytes += strlen(line);
        }

        free(line);
    }

    return (float)totalBytes / totalLines;
}

// Function to identify the longest and shortest lines in a file
void identifyLongestAndShortestLines(FILE *file, int *longestLine, int *shortestLine) {
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        if (strlen(line) > *longestLine) {
            *longestLine = strlen(line);
        }

        if (strlen(line) < *shortestLine || *shortestLine == 0) {
            *shortestLine = strlen(line);
        }
    }

    free(line);
}

// Function to filter log files based on a minimum line length threshold
void filterLogFiles(FILE **files, int numFiles, int minLineLength) {
    int i;
    for (i = 0; i < numFiles; i++) {
        if (countLines(files[i]) < minLineLength) {
            fclose(files[i]);
            files[i] = NULL;
        }
    }
}

// Function to aggregate statistics across all log files in a directory
void aggregateStatistics(char *directory, AggregateStats *stats) {
    DIR *dir;
    struct dirent *entry;
    FILE **files = NULL;
    int numFiles = 0;
    int i;

    // Open the directory and get a list of all log files
    if ((dir = opendir(directory)) == NULL) {
        perror("Error opening directory");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        char *filename = entry->d_name;
        FILE *file;

        // Skip non-log files and hidden files
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }

        // Open the log file and count the number of lines
        if ((file = fopen(filename, "r")) == NULL) {
            perror("Error opening file");
            continue;
        }

        numFiles++;
        files = realloc(files, sizeof(FILE *) * numFiles);
        files[numFiles - 1] = file;
    }

    // Close the directory and free resources
    closedir(dir);

    // Aggregate statistics across all log files
    for (i = 0; i < numFiles; i++) {
        FILE *file = files[i];
        LogFileStats stats;

        // Count the total number of lines in the file
        stats.total_lines = countLines(file);

        // Calculate the average line length in the file
        stats.average_line_length = calculateAverageLineLength(file);

        // Identify the longest and shortest lines in the file
        identifyLongestAndShortestLines(file, &stats.longest_line, &stats.shortest_line);

        // Add the statistics to the aggregated stats structure
        stats.filename = filename;
        stats.total_files++;
        stats->total_lines += stats.total_lines;
        stats->average_line_length += stats.average_line_length;
        if (stats.longest_line > stats->longest_line) {
            stats->longest_line = stats.longest_line;
        }
        if (stats.shortest_line < stats->shortest_line || stats->shortest_line == 0) {
            stats->shortest_line = stats.shortest_line;
        }
    }

    // Free resources and return the aggregated statistics
    for (i = 0; i < numFiles; i++) {
        fclose(files[i]);
    }
    free(files);
}

// Function to compress a file using LZ4 compression algorithm
void compressFile(char *filename, char *compressedFilename) {
    FILE *file = fopen(filename, "r");
    FILE *compressedFile = fopen(compressedFilename, "w");
    int bufferSize = 1024;
    char *buffer = malloc(bufferSize);
    size_t readBytes;
    size_t writtenBytes;

    while ((readBytes = fread(buffer, sizeof(char), bufferSize, file)) > 0) {
        writtenBytes = LZ4_compress_default(buffer, compressedFile, readBytes);
        if (writtenBytes == -1) {
            perror("Error compressing file");
            break;
        }
    }

    free(buffer);
    fclose(file);
    fclose(compressedFile);
}

// Function to decompress a compressed file using LZ4 compression algorithm
void decompressFile(char *filename, char *decompressedFilename) {
    FILE *file = fopen(filename, "r");
    FILE *decompressedFile = fopen(decompressedFilename, "w");
    int bufferSize = 1024;
    char *buffer = malloc(bufferSize);
    size_t readBytes;
    size_t writtenBytes;

    while ((readBytes = LZ4_decompress_safe(file, decompressedFile, readBytes)) > 0) {
        writtenBytes = fwrite(buffer, sizeof(char), bufferSize, decompressedFile);
        if (writtenBytes == -1) {
            perror("Error decompressing file");
            break;
        }
    }

    free(buffer);
    fclose(file);
    fclose(decompressedFile);
}

