void handleLargeFiles(char *filename, char *operation) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    // Handle the operation on the file
    if (strcmp(operation, "compress") == 0) {
        compressFile(filename, filename);
    } else if (strcmp(operation, "decompress") == 0) {
        decompressFile(filename, filename);
    }

    fclose(file);
}

// Function to detect and process log files with varying encodings and character sets
void detectAndProcessLogFiles(char *directory, char *operation) {
    DIR *dir;
    struct dirent *entry;
    FILE **files = NULL;
    int numFiles = 0;
    int i;

    // Open the directory and get a list of all log files
    if ((dir = opendir(directory)) == NULL) {
        perror("Error opening directory");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        char *filename = entry->d_name;
        FILE *file;

        // Skip non-log files and hidden files
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }

        // Open the log file and detect its encoding and character set
        if ((file = fopen(filename, "r")) == NULL) {
            perror("Error opening file");
            continue;
        }

        numFiles++;
        files = realloc(files, sizeof(FILE *) * numFiles);
        files[numFiles - 1] = file;
    }

    // Close the directory and free resources
    closedir(dir);

    // Process each log file with the specified operation
    for (i = 0; i < numFiles; i++) {
        FILE *file = files[i];
        char *filename = filename;

        // Detect the encoding and character set of the file
        if (strcmp(operation, "compress") == 0) {
            compressFile(filename, filename);
        } else if (strcmp(operation, "decompress") == 0) {
            decompressFile(filename, filename);
        }
    }

    // Free resources and return the aggregated statistics
    for (i = 0; i < numFiles; i++) {
        fclose(files[i]);
    }
    free(files);
}

