// Custom slab allocator for managing L3 packet structures
struct slab_allocator {
    void* memory; // Pointer to the allocated memory block
    size_t size; // Size of the allocated memory block
    size_t used; // Number of bytes used in the allocated memory block
};

// Allocate a new slab with the given alignment requirements
struct slab_allocator* allocate_slab(size_t alignment) {
    // Calculate the required size for the slab, including alignment padding
    size_t slab_size = sizeof(struct slab_allocator) + alignment;

    // Allocate memory for the slab using malloc()
    void* memory = malloc(slab_size);
    if (!memory) {
        return NULL;
    }

    // Initialize the slab structure and set the alignment requirements
    struct slab_allocator* slab = (struct slab_allocator*)memory;
    slab->memory = memory;
    slab->size = slab_size;
    slab->used = 0;

    return slab;
}

// Free a slab and its associated memory block
void free_slab(struct slab_allocator* slab) {
    // Check if the slab is valid before attempting to free it
    if (!slab || !slab->memory) {
        return;
    }

    // Free the memory block associated with the slab
    free(slab->memory);
}

