    // Calculate the required size for the packet structure, including alignment padding
    size_t packet_size = sizeof(struct L3_packet) + alignment;

    // Check if there is enough space in the slab to allocate the packet
    if (slab->used + packet_size > slab->size) {
        return NULL;
