        if (strlen(line) > strlen(stats.longest_line)) {
            strcpy(stats.longest_line, line);
        }
        if (strlen(line) < strlen(stats.shortest_line)) {
            strcpy(stats.shortest_line, line);
        }
    }

    // Close the log file
    fclose(fp);
}

// Define the function to process a directory of log files
void process_log_directory(const char* dirname) {
    // Open the directory for reading
    DIR* dir = opendir(dirname);
    if (dir == NULL) {
        printf("Error: unable to open directory %s\n", dirname);
        return;
    }

    // Initialize the aggregated statistics structure
    struct AggregateStats stats;
    memset(&stats, 0, sizeof(struct AggregateStats));

    // Read each file in the directory and process it
    struct dirent* entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char* filename = entry->d_name;
        process_log_file(filename);
    }

    // Close the directory
    closedir(dir);
}

// Define the function to filter log files based on a minimum line length threshold
void filter_log_files(const char* dirname, int min_line_length) {
    // Open the directory for reading
    DIR* dir = opendir(dirname);
    if (dir == NULL) {
        printf("Error: unable to open directory %s\n", dirname);
        return;
    }

    // Initialize the aggregated statistics structure
    struct AggregateStats stats;
    memset(&stats, 0, sizeof(struct AggregateStats));

    // Read each file in the directory and process it
    struct dirent* entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char* filename = entry->d_name;
        process_log_file(filename);
    }

    // Close the directory
    closedir(dir);
}

// Define the function to compress the output file using LZ4 compression algorithm
void compress_output_file(const char* filename) {
    // Open the input file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Create a temporary file for writing the compressed data
    char tmp_file[1024];
    sprintf(tmp_file, "%s.tmp", filename);
    FILE* fp_out = fopen(tmp_file, "w");
    if (fp_out == NULL) {
        printf("Error: unable to create temporary file %s\n", tmp_file);
        return;
    }

    // Compress the input data using LZ4 compression algorithm
    int ret = lz4_compress(fp, fp_out);
    if (ret != 0) {
        printf("Error: unable to compress file %s\n", filename);
        return;
    }

    // Close the input and output files
    fclose(fp);
    fclose(fp_out);

    // Rename the temporary file to the original file name with .lz4 extension
    char new_file[1024];
    sprintf(new_file, "%s.lz4", filename);
    ret = rename(tmp_file, new_file);
    if (ret != 0) {
        printf("Error: unable to rename file %s\n", tmp_file);
        return;
    }
}

// Define the function to export aggregated statistics to a CSV file
void export_aggregate_stats(const char* filename, struct AggregateStats stats) {
    // Open the output file for writing
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Write the aggregated statistics to the CSV file
    fprintf(fp, "File Name,Total Lines,Average Line Length,Longest Line,Shortest Line\n");
    fprintf(fp, "%s,%d,%f,%s,%s\n", filename, stats.total_lines, stats.average_line_length, stats.longest_line, stats.shortest_line);

    // Close the output file
    fclose(fp);
}

// Define the function to handle large file I/O operations gracefully
void handle_large_file_io(const char* filename) {
    // Open the input file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Create a temporary file for writing the data
    char tmp_file[1024];
    sprintf(tmp_file, "%s.tmp", filename);
    FILE* fp_out = fopen(tmp_file, "w");
    if (fp_out == NULL) {
        printf("Error: unable to create temporary file %s\n", tmp_file);
        return;
    }

    // Read the input data in chunks and write it to the output file
    char buffer[1024];
    size_t len = 0;
    while ((len = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        fwrite(buffer, 1, len, fp_out);
    }

    // Close the input and output files
    fclose(fp);
    fclose(fp_out);

    // Rename the temporary file to the original file name
    char new_file[1024];
    sprintf(new_file, "%s.tmp", filename);
    int ret = rename(tmp_file, new_file);
    if (ret != 0) {
        printf("Error: unable to rename file %s\n", tmp_file);
        return;
    }
}

