        }
        char* filename = entry->d_name;
        process_log_file(filename);
    }

    // Close the directory
    closedir(dir);
}

// Define the function to generate detailed reports for individual log files
void generate_report(const char* filename) {
    // Open the input file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Initialize the aggregated statistics structure
    struct AggregateStats stats;
    memset(&stats, 0, sizeof(struct AggregateStats));

    // Read each line of the input file and perform the necessary operations
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        stats.total_lines++;
        stats.average_line_length += strlen(line);
        if (strlen(line) > strlen(stats.longest_line)) {
            strcpy(stats.longest_line, line);
        }
        if (strlen(line) < strlen(stats.shortest_line)) {
            strcpy(stats.shortest_line, line);
        }
    }

    // Close the input file
    fclose(fp);

    // Print the detailed report for the log file
    printf("File Name: %s\n", filename);
    printf("Total Lines: %d\n", stats.total_lines);
    printf("Average Line Length: %.2f\n", stats.average_line_length / stats.total_lines);
    printf("Longest Line: %s\n", stats.longest_line);
    printf("Shortest Line: %s\n", stats.shortest_line);
}

// Define the function to support integration with external monitoring tools via REST API
void integrate_with_rest_api(const char* dirname) {
    // Open the directory for reading
    DIR* dir = opendir(dirname);
    if (dir == NULL) {
        printf("Error: unable to open directory %s\n", dirname);
