} SlabAllocator;

// Define a function to allocate memory in chunks using the slab allocator
void* allocateMemory(size_t size) {
    // Check if there is enough space in the current chunk
    if (slab.data + slab.size - (char*)ptr >= size) {
        return ptr;
    }

    // Allocate a new chunk of memory if necessary
    void* new_chunk = malloc(size);
    if (!new_chunk) {
        return NULL;
    }

    // Add the new chunk to the slab allocator
    slab.data = new_chunk;
    slab.size += size;

    return ptr;
}

// Define a function to free memory in chunks using the slab allocator
void freeMemory(void* ptr) {
    // Check if the pointer is within the current chunk
    if (slab.data <= ptr && ptr < slab.data + slab.size) {
        return;
    }

    // Free the memory block
    free(ptr);
}

