char* generateHash(const char* str, size_t len) {
    // Allocate memory for the hash value
    unsigned char* hash = malloc(SHA256_DIGEST_LENGTH);
    if (!hash) {
        return NULL;
    }

    // Generate the hash using OpenSSL
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, str, len);
    SHA256_Final(hash, &ctx);

    // Convert the hash to a string and return it
    char* result = malloc(SHA256_DIGEST_LENGTH * 2 + 1);
    if (!result) {
        free(hash);
        return NULL;
    }
    for (size_t i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(result + i * 2, "%02x", hash[i]);
    }
    result[SHA256_DIGEST_LENGTH * 2] = '\0';

    free(hash);
    return result;
}
