#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_FILES 500
#define BUFFER_SIZE 4096

struct file_info {
    char *filename;
    int fd;
    off_t size;
};

int main(int argc, char **argv) {
    struct file_info files[MAX_FILES];
    int num_files = 0;
    int i;
    long total_lines = 0;
    long total_chars = 0;
    char *output_file = NULL;
    int output_fd = -1;
    int format = 0; // 0: plain, 1: tabular

    for (i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--help")) {
            printf("Usage: %s [options] file1 [file2 ...]\n", argv[0]);
            printf("Options:\n");
            printf("  -c\tPrint the total character count of all lines across all input files.\n");
            printf("  -l\tPrint the total number of lines across all input files.\n");
            printf("  -o <output_file>\tWrite the aggregated results (total lines and total character count) to the specified output file.\n");
            printf("  -f\tFormat the output in a tabular form.\n");
            return 0;
        } else if (!strcmp(argv[i], "-c")) {
            format = 1;
        } else if (!strcmp(argv[i], "-l")) {
            format = 2;
        } else if (!strcmp(argv[i], "-o")) {
            output_file = argv[++i];
        } else if (!strcmp(argv[i], "-f")) {
            format = 3;
        } else {
            files[num_files].filename = argv[i];
            num_files++;
        }
    }

    for (i = 0; i < num_files; i++) {
        struct file_info *file = &files[i];
        file->fd = open(file->filename, O_RDONLY);
        if (file->fd == -1) {
            perror("open");
            return 1;
        }
        struct stat st;
        fstat(file->fd, &st);
        file->size = st.st_size;
    }

    for (i = 0; i < num_files; i++) {
        struct file_info *file = &files[i];
        char buffer[BUFFER_SIZE];
        ssize_t bytes_read;
        off_t offset = 0;
        while ((bytes_read = pread(file->fd, buffer, BUFFER_SIZE, offset)) > 0) {
            total_lines += count_lines(buffer, bytes_read);
            total_chars += count_chars(buffer, bytes_read);
            offset += bytes_read;
        }
    }

    if (output_file != NULL) {
        output_fd = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (output_fd == -1) {
            perror("open");
            return 1;
        }
    }

    switch (format) {
        case 0: // plain
            printf("%ld\n", total_lines);
            printf("%ld\n", total_chars);
            break;
        case 1: // character count
            printf("%ld\n", total_chars);
            break;
        case 2: // line count
            printf("%ld\n", total_lines);
            break;
        case 3: // tabular
            if (output_fd != -1) {
                fprintf(output_fd, "%ld\t%ld\n", total_lines, total_chars);
            } else {
                printf("%ld\t%ld\n", total_lines, total_chars);
            }
            break;
    }

    for (i = 0; i < num_files; i++) {
        struct file_info *file = &files[i];
        close(file->fd);
    }

    if (output_fd != -1) {
        close(output_fd);
    }

    return 0;
}

long count_lines(char *buffer, ssize_t bytes_read) {
    long lines = 0;
    for (ssize_t i = 0; i < bytes_read; i++) {
        if (buffer[i] == '\n') {
            lines++;
        }
    }
    return lines;
}

long count_chars(char *buffer, ssize_t bytes_read) {
    long chars = 0;
    for (ssize_t i = 0; i < bytes_read; i++) {
        if (!isspace(buffer[i])) {
            chars++;
        }
    }
    return chars;
}
