    }

    // Apply the filter if necessary
    if (pipeline.filter != Filter::NONE) {
        applyFilter(inputImage, pipeline.filter);
    }

    // Save the output image to file
    saveImage(inputImage, pipeline.outputFile);
}

// Load an image from a file
shared_ptr<vector<unsigned char>> loadImage(const string& filename) {
    ifstream inputStream;
    inputStream.open(filename, ios::binary | ios::ate);

    // Check for errors
    if (!inputStream.is_open()) {
        throw runtime_error("Failed to open image file: " + filename);
    }

    // Get the size of the file
    auto fileSize = inputStream.tellg();

    // Create a vector to hold the image data
    shared_ptr<vector<unsigned char>> imageData(new vector<unsigned char>(fileSize));

    // Read the image data into the vector
    inputStream.seekg(0, ios::beg);
    inputStream.read((char*)imageData->data(), fileSize);

    // Close the input stream
    inputStream.close();

    return imageData;
}

// Resize an image to a specified width and height
void resizeImage(shared_ptr<vector<unsigned char>>& image, int width, int height) {
    // Calculate the scaling factors
    auto scaleX = (double)width / image->size();
    auto scaleY = (double)height / image->size();

    // Resize the image data
    for (auto& pixel : *image) {
        pixel = (unsigned char)(pixel * scaleX * scaleY);
    }
}

// Crop an image to a specified rectangular region
void cropImage(shared_ptr<vector<unsigned char>>& image, int x1, int y1, int x2, int y2) {
    // Calculate the crop dimensions
    auto width = x2 - x1;
    auto height = y2 - y1;

    // Create a new vector to hold the cropped image data
    shared_ptr<vector<unsigned char>> croppedImage(new vector<unsigned char>(width * height));

    // Copy the cropped image data from the original image
    for (int i = 0; i < width; ++i) {
        for (int j = 0; j < height; ++j) {
            auto pixelIndex = x1 + i + (y1 + j) * image->size();
            croppedImage->at(i + j * width) = image->at(pixelIndex);
        }
    }

    // Replace the original image with the cropped image
    image = croppedImage;
}

// Apply a specified image filter to an image
void applyFilter(shared_ptr<vector<unsigned char>>& image, Filter filter) {
    switch (filter) {
        case Filter::GRAYSCALE:
            // Convert the image to grayscale
            for (auto& pixel : *image) {
                pixel = (unsigned char)(0.299 * pixel + 0.587 * pixel + 0.114 * pixel);
            }
            break;
        case Filter::BLUR:
            // Apply a blur filter to the image
            for (int i = 1; i < image->size() - 1; ++i) {
                auto& pixel = image->at(i);
                pixel = (unsigned char)(0.25 * pixel + 0.5 * image->at(i - 1) + 0.25 * image->at(i + 1));
            }
            break;
        case Filter::NONE:
            // Do nothing
            break;
    }
}

// Save an image to a file
void saveImage(shared_ptr<vector<unsigned char>>& image, const string& filename) {
    ofstream outputStream;
    outputStream.open(filename, ios::binary);

    // Check for errors
    if (!outputStream.is_open()) {
        throw runtime_error("Failed to open output file: " + filename);
    }

    // Write the image data to the output stream
    outputStream.write((char*)image->data(), image->size());

    // Close the output stream
    outputStream.close();
}

int main(int argc, char** argv) {
    // Parse the command-line options
    CommandLineOptions options;
    parseCommandLineOptions(argc, argv, options);

    // Process each input image
    for (auto& inputFile : options.inputFiles) {
        ImageProcessingPipeline pipeline;
        pipeline.inputFile = inputFile;
        pipeline.outputFile = options.outputFile;
        pipeline.width = options.width;
        pipeline.height = options.height;
        pipeline.cropRegion = options.cropRegion;
        pipeline.filter = options.filter;
        pipeline.verbose = options.verbose;

        // Process the image
        processImage(pipeline);
    }

    return 0;
}

void parseCommandLineOptions(int argc, char** argv, CommandLineOptions& options) {
    for (int i = 1; i < argc; ++i) {
        string option = argv[i];

        if (option == "-h" || option == "--help") {
            options.help = true;
        } else if (option == "-o") {
            options.outputFile = argv[++i];
        } else if (option == "-r") {
