            auto pos = region.find(':');
            if (pos != string::npos) {
                options.cropRegion.push_back(stoi(region.substr(0, pos)));
                options.cropRegion.push_back(stoi(region.substr(pos + 1, pos - pos - 1)));
                options.cropRegion.push_back(stoi(region.substr(pos + 2)));
                options.cropRegion.push_back(stoi(region.substr(pos + 3)));
            } else {
                throw runtime_error("Invalid crop region: " + region);
            }
        } else if (option == "-f") {
            string filter = argv[++i];
            if (filter == "grayscale") {
                options.filter = Filter::GRAYSCALE;
            } else if (filter == "blur") {
                options.filter = Filter::BLUR;
            } else {
                throw runtime_error("Invalid filter: " + filter);
            }
        } else if (option == "-t") {
            options.verbose = true;
        } else if (option == "-v") {
            options.verbose = true;
        } else {
            options.inputFiles.push_back(option);
        }
    }
}
