public class FileProcessor {
  private static final int MAX_FILES = 500; // maximum number of input files to process simultaneously
  private static final String OUTPUT_FILE = "output.txt"; // default output file name

  public static void main(String[] args) throws IOException {
    if (args.length == 0) {
      System.out.println("Usage: java FileProcessor [options]");
      System.out.println("Options:");
      System.out.println("\t-c\tPrint the total character count of all lines across all input files.");
      System.out.println("\t-l\tPrint the total number of lines across all input files.");
      System.out.println("\t-o <output_file>\tWrite the aggregated results (total lines and total character count) to the specified output file.");
      System.out.println("\t-f\tFormat the output in a tabular form.");
      return;
    }

    // parse command-line options
    boolean printCharCount = false, printLineCount = false, writeOutput = false, formatOutput = false;
    String outputFile = OUTPUT_FILE;
    for (int i = 0; i < args.length; i++) {
      switch (args[i]) {
        case "-c":
          printCharCount = true;
          break;
        case "-l":
          printLineCount = true;
          break;
        case "-o":
          if (i + 1 < args.length) {
            outputFile = args[++i];
          } else {
            System.out.println("Missing argument for -o option");
            return;
          }
          writeOutput = true;
          break;
        case "-f":
          formatOutput = true;
          break;
        default:
          System.out.println("Invalid option: " + args[i]);
          return;
      }
    }

    // process input files
    List<File> inputFiles = new ArrayList<>();
    for (int i = 0; i < args.length - 1; i++) {
      File file = new File(args[i + 1]);
      if (!file.exists()) {
        System.out.println("Input file does not exist: " + file);
        return;
      }
      inputFiles.add(file);
    }

    // compute metrics
    long totalCharCount = 0, totalLineCount = 0;
    for (File file : inputFiles) {
      try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
          totalCharCount += line.length();
          totalLineCount++;
        }
      } catch (IOException e) {
        System.out.println("Error reading file: " + file);
        return;
      }
    }

    // print results
    if (printCharCount || printLineCount || writeOutput) {
      StringBuilder output = new StringBuilder();
      if (printCharCount) {
        output.append(totalCharCount).append(" characters\n");
      }
      if (printLineCount) {
        output.append(totalLineCount).append(" lines\n");
      }
      if (writeOutput) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputFile))) {
          writer.write(output.toString());
        } catch (IOException e) {
          System.out.println("Error writing to output file: " + outputFile);
          return;
        }
      }
    }
  }
}
