    char buffer[1024];
    ssize_t num_read;
    while ((num_read = read(file->fd, buffer, sizeof(buffer))) > 0) {
        // process the data in buffer
    }
    close(file->fd);
    return NULL;
}

int main(int argc, char** argv) {
    input_data_t* input = (input_data_t*)malloc(sizeof(input_data_t));
    memset(input, 0, sizeof(input_data_t));

    int opt;
    while ((opt = getopt(argc, argv, "ho:c")) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [-o output_dir] [-c] file1 [file2 ...]\n", argv[0]);
                return 0;
            case 'o':
                strncpy(input->output_dir, optarg, MAX_OUTPUT_DIR);
                break;
            case 'c':
                input->num_files = argc - optind;
                for (int i = 0; i < input->num_files; i++) {
                    strncpy(input->files[i].file_path, argv[optind + i], MAX_FILE_PATH);
                    input->files[i].fd = open(input->files[i].file_path, O_RDONLY);
                }
                break;
            default:
                printf("Invalid option %c\n", opt);
                return 1;
        }
    }

    if (input->num_files == 0) {
        printf("No input files specified\n");
        return 1;
    }

    pthread_t threads[MAX_NUM_FILES];
    for (int i = 0; i < input->num_files; i++) {
        if (input->files[i].fd == -1) {
            printf("Error opening file %s\n", input->files[i].file_path);
            return 1;
        }
        pthread_create(&threads[i], NULL, process_input, &input->files[i]);
    }

    for (int i = 0; i < input->num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    if (strlen(input->output_dir) > 0) {
        // save intermediate results to output directory
    }

    free(input);
    return 0;
}
