        // If no free structures, allocate a new chunk of structures
        size_t chunk_size = sizeof(nfapi_crc_indication_pdu_t) * initial_size;
        void *chunk = malloc(chunk_size);
        if (!chunk) {
            return NULL;
        }

        // Initialize the slab allocator for the new chunk of structures
        slab_allocator_t *slab = malloc(sizeof(slab_allocator_t));
        if (!slab) {
            free(chunk);
            return NULL;
        }
        slab->memory = chunk;
        slab->size = chunk_size;

        // Add the new chunk of structures to the pool
        pool->pool = (nfapi_crc_indication_pdu_t *)chunk;
    }

    // Allocate a new structure from the pool
    nfapi_crc_indication_pdu_t *structure = &pool->pool[pool->count++];

