#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <pthread.h>
#include <zlib.h>
#include <lz4.h>

#define MAX_THREADS 10000
#define BUFFER_SIZE 1024
#define COMPRESSION_ALGORITHM LZ4

typedef struct {
    char* file_name;
    int total_lines;
    float average_line_length;
    int longest_line;
    int shortest_line;
} log_file_stats;

void* process_log_file(void* args) {
    struct stat st;
    char* file_name = (char*)args;
    FILE* fp = fopen(file_name, "r");
    if (!fp) {
        perror("fopen");
        return NULL;
    }
    int line_count = 0;
    int longest_line = 0;
    int shortest_line = INT_MAX;
    float average_line_length = 0.0;
    char* line = (char*)malloc(BUFFER_SIZE);
    while (fgets(line, BUFFER_SIZE, fp)) {
        line_count++;
        int line_len = strlen(line);
        average_line_length += line_len;
        if (line_len > longest_line) {
            longest_line = line_len;
        }
        if (line_len < shortest_line) {
            shortest_line = line_len;
        }
    }
    fclose(fp);
    log_file_stats* stats = (log_file_stats*)malloc(sizeof(log_file_stats));
    stats->file_name = file_name;
    stats->total_lines = line_count;
    stats->average_line_length = average_line_length / line_count;
    stats->longest_line = longest_line;
    stats->shortest_line = shortest_line;
    return stats;
}

void* compress_log_file(void* args) {
    char* file_name = (char*)args;
    FILE* fp = fopen(file_name, "r");
    if (!fp) {
        perror("fopen");
        return NULL;
    }
    int buffer_size = BUFFER_SIZE;
    char* buffer = (char*)malloc(buffer_size);
    while (fgets(buffer, buffer_size, fp)) {
        // Compress the line using LZ4 compression algorithm
        int compressed_len = lz4_compress(buffer, buffer_size);
        if (compressed_len > 0) {
            char* compressed_buffer = (char*)malloc(compressed_len);
            memcpy(compressed_buffer, buffer, compressed_len);
            fwrite(compressed_buffer, compressed_len, 1, stdout);
            free(compressed_buffer);
        } else {
            fwrite(buffer, buffer_size, 1, stdout);
        }
    }
    fclose(fp);
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s [directory]\n", argv[0]);
        return 1;
    }
    DIR* dir = opendir(argv[1]);
    if (!dir) {
        perror("opendir");
        return 1;
    }
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char* file_name = (char*)malloc(strlen(argv[1]) + strlen(entry->d_name) + 2);
        sprintf(file_name, "%s/%s", argv[1], entry->d_name);
        struct stat st;
        if (stat(file_name, &st) == 0 && S_ISREG(st.st_mode)) {
            pthread_t thread;
            void* args = file_name;
            int rc = pthread_create(&thread, NULL, process_log_file, args);
            if (rc != 0) {
                perror("pthread_create");
                return 1;
            }
        } else {
            free(file_name);
        }
    }
    closedir(dir);
    return 0;
}']

