        pthread_create(&threads[i], NULL, process_log_file, directory);
    }

    // Wait for all threads to finish
    for (i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Aggregate the statistics from all log files
    aggregate_stats(stats, stats);

    // Write the aggregated statistics to a CSV file and a report file
    write_csv_file(stats);
    write_report_file(stats);

    // Compress the output files if specified
    char* compressed_filename = "output.lz4";
    compress_data(output_dir, compressed_filename);

    // Clean up memory and exit
    free(stats);
    return 0;
}

// Function to process a log file in a separate thread
void* process_log_file(char* filename) {
    // Initialize variables and data structures
    log_file_stats* stats = malloc(sizeof(log_file_stats));
    memset(stats, 0, sizeof(log_file_stats));
    FILE* file = fopen(filename, "r");

    // Read the log file line by line and perform operations
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        stats->line_count++;
        stats->average_line_length += strlen(line);
        if (strlen(line) > stats->longest_line) {
            stats->longest_line = strlen(line);
        }
        if (stats->shortest_line == 0 || strlen(line) < stats->shortest_line) {
            stats->shortest_line = strlen(line);
        }
    }

    // Close the file and free memory
    fclose(file);
    free(line);

    // Return the statistics for the log file
    return stats;
}

// Function to aggregate statistics from multiple log files
void aggregate_stats(aggregated_stats* stats, log_file_stats* file_stats) {
    // Update the total line count and average line length
    stats->line_count += file_stats->line_count;
    stats->average_line_length += file_stats->average_line_length;

    // Update the longest and shortest lines
    if (file_stats->longest_line > stats->longest_line) {
        stats->longest_line = file_stats->longest_line;
    }
    if (file_stats->shortest_line < stats->shortest_line || stats->shortest_line == 0) {
        stats->shortest_line = file_stats->shortest_line;
    }
}

// Function to write the aggregated statistics to a CSV file
void write_csv_file(aggregated_stats* stats) {
    // Open the output file and write the header
    FILE* csv_file = fopen(CSV_FILENAME, "w");
    fprintf(csv_file, "filename,total lines,average line length,longest line,shortest line\n");

    // Write the statistics for each log file to the CSV file
    char* filename = stats->filename;
    int total_lines = stats->line_count;
    double average_line_length = stats->average_line_length / total_lines;
    int longest_line = stats->longest_line;
    int shortest_line = stats->shortest_line;
    fprintf(csv_file, "%s,%d,%f,%d,%d\n", filename, total_lines, average_line_length, longest_line, shortest_line);

    // Close the output file
    fclose(csv_file);
}

// Function to write a report file with detailed information about each log file
void write_report_file(aggregated_stats* stats) {
    // Open the output file and write the header
    FILE* report_file = fopen(REPORT_FILENAME, "w");
    fprintf(report_file, "Log File Report\n");

    // Write a detailed report for each log file to the report file
    char* filename = stats->filename;
    int total_lines = stats->line_count;
    double average_line_length = stats->average_line_length / total_lines;
    int longest_line = stats->longest_line;
    int shortest_line = stats->shortest_line;
    fprintf(report_file, "Filename: %s\n", filename);
    fprintf(report_file, "Total Lines: %d\n", total_lines);
    fprintf(report_file, "Average Line Length: %.2f\n", average_line_length);
    fprintf(report_file, "Longest Line: %d\n", longest_line);
    fprintf(report_file, "Shortest Line: %d\n", shortest_line);

    // Close the output file
    fclose(report_file);
}

// Function to compress data using a specified compression algorithm
void compress_data(char* filename, char* compressed_filename) {
    // Open the input and output files
    FILE* in_file = fopen(filename, "r");
    FILE* out_file = fopen(compressed_filename, "w");

    // Compress the data using the specified compression algorithm
    int size = 0;
    char* buffer = malloc(FILE_BUFFER_SIZE);
    while ((size = fread(buffer, 1, FILE_BUFFER_SIZE, in_file)) > 0) {
        LZ4_compress_default(buffer, out_file);
    }

    // Close the input and output files
    fclose(in_file);
    fclose(out_file);
}

// Function to decompress data using a specified compression algorithm
void decompress_data(char* compressed_filename, char* filename) {
    // Open the input and output files
    FILE* in_file = fopen(compressed_filename, "r");
    FILE* out_file = fopen(filename, "w");

    // Decompress the data using the specified compression algorithm
    int size = 0;
    char* buffer = malloc(FILE_BUFFER_SIZE);
    while ((size = LZ4_decompress_safe(in_file, out_file)) > 0) {
        fwrite(buffer, 1, size, out_file);
    }

    // Close the input and output files
    fclose(in_file);
    fclose(out_file);
}

// Function to handle large files by breaking them into smaller chunks
void handle_large_file(char* filename) {
    // Open the file and determine its size
    FILE* file = fopen(filename, "r");
    long file_size = 0;
    fseek(file, 0, SEEK_END);
    file_size = ftell(file);
    rewind(file);

    // Break the large file into smaller chunks and process each chunk separately
    int chunk_size = FILE_BUFFER_SIZE;
    while (file_size > 0) {
        char* buffer = malloc(chunk_size);
        fread(buffer, 1, chunk_size, file);
        // Process the chunk of data here
        free(buffer);
        file_size -= chunk_size;
    }
}

// Function to handle nested directories by recursively processing each directory
void handle_nested_directories(char* directory) {
    // Open the directory and read its contents
    DIR* dir = opendir(directory);
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char* filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }
        char* full_path = malloc(strlen(directory) + strlen(filename) + 2);
        sprintf(full_path, "%s/%s", directory, filename);
        struct stat file_info;
        if (stat(full_path, &file_info) == 0 && S_ISDIR(file_info.st_mode)) {
            handle_nested_directories(full_path);
        } else {
            // Process the file here
            free(full_path);
        }
    }
}

// Function to handle transient failures by retrying failed operations
void handle_transient_failures(char* filename) {
    // Retry the operation up to a maximum number of attempts
    int attempt = 0;
    while (attempt < MAX_ATTEMPTS) {
        // Perform the operation here
        attempt++;
    }
}

// Function to manage memory for multiple arrays and data structures under specific constraints and conditions
void manage_memory(int size) {
    // Allocate memory for the arrays and data structures
    char* buffer = malloc(size);
    memset(buffer, 0, size);
}

// Function to print usage instructions if no directory is provided as input
void print_usage() {
    printf("Usage: %s <directory>\n", argv[0]);
