// Function to add a new SensorReading to the array
void add_reading(SensorReading *reading) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the array needs to be resized
    if (readings_count == readings_capacity) {
        // Double the capacity of the array
        readings_capacity *= 2;
        SensorReading *new_readings = realloc(readings, readings_capacity * sizeof(SensorReading));
        if (new_readings == NULL) {
            perror("realloc");
            exit(1);
        }
        readings = new_readings;
    }

    // Add the new SensorReading to the array
    readings[readings_count++] = *reading;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing SensorReading in the array
void update_reading(SensorReading *reading) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

