    int error = pthread_create(&thread, NULL, dns_resolve_with_caching_and_rate_limiting, hostname);
    if (error != 0) {
        return ERROR_DNS_FAILURE;
    }

    // Wait for the DNS resolution to complete
    void* result = NULL;
    error = pthread_join(thread, &result);
    if (error != 0) {
        return ERROR_DNS_FAILURE;
    }

    // Check if the DNS resolution was successful
    if (result == NULL) {
        return ERROR_DNS_FAILURE;
    }

    // Return the DNS resolution result
    memcpy(ip, result, 16);

    return ERROR_SUCCESS;
}
