    entry->timestamp = 0;
    entry->event_type = 0;
    entry->source_id = 0;
    entry->status = 0;

    return entry;
}

// Define a function to free memory for a log entry
void free_log_entry(LogEntry* entry) {
    // Check if the entry is NULL
    if (!entry) {
        return;
    }

    // Free the memory allocated for the log entry
    free(entry);
}

// Define a function to add a new log entry to the list
