    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(&lock);

    // Check if the maximum size limit has been reached
    if (num_entries >= MAX_SIZE) {
        // Reallocate memory for the list of log entries
        LogEntry** new_list = realloc(log_list, sizeof(LogEntry*) * (MAX_SIZE + 1));
        if (!new_list) {
            pthread_mutex_unlock(&lock);
            return -1;
        }

        // Update the list of log entries and the maximum size limit
        log_list = new_list;
        MAX_SIZE++;
    }

    // Add the new log entry to the list
    log_list[num_entries++] = entry;

    // Release the lock
    pthread_mutex_unlock(&lock);

    return 0;
}

// Define a function to remove a log entry from the list
int remove_log_entry(LogEntry* entry) {
    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(&lock);

    // Find the index of the log entry in the list
    int i;
    for (i = 0; i < num_entries; i++) {
        if (log_list[i] == entry) {
            break;
        }
    }

    // Check if the log entry was found in the list
    if (i >= num_entries) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Remove the log entry from the list
    for (int j = i; j < num_entries - 1; j++) {
        log_list[j] = log_list[j + 1];
    }

    // Decrement the number of entries in the list
    num_entries--;

    // Release the lock
    pthread_mutex_unlock(&lock);

    return 0;
}

// Define a function to retrieve a log entry from the list by index
LogEntry* get_log_entry(int index) {
    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(&lock);

    // Check if the index is valid
    if (index < 0 || index >= num_entries) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Return the log entry at the specified index
    LogEntry* entry = log_list[index];

    // Release the lock
    pthread_mutex_unlock(&lock);

    return entry;
}

// Define a function to retrieve the total number of log entries in the list
int get_num_log_entries() {
    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(&lock);

    // Return the total number of log entries in the list
    int num_entries = this->num_entries;

    // Release the lock
    pthread_mutex_unlock(&lock);

    return num_entries;
}

// Define a function to free all allocated memory and reset the internal state for re-use
void free_all() {
    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(&lock);

    // Free all allocated memory for the log entries
    for (int i = 0; i < num_entries; i++) {
        free(log_list[i]);
    }

    // Reset the list of log entries and the maximum size limit
    log_list = NULL;
    MAX_SIZE = 0;
    num_entries = 0;

    // Release the lock
    pthread_mutex_unlock(&lock);
}
