// Define a function to validate the existence and integrity of a file
int validate_file(char *filename) {
    // Open the file in read-only mode
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return 0;
    }

    // Get the file size
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("Error getting file size");
        close(fd);
        return 0;
    }

    // Close the file and return success
    close(fd);
    return 1;
}

// Define a function to accumulate line counts across multiple files
void accumulate_line_counts(file_metadata_t *files, int num_files) {
    // Initialize the line count for each file
    long total_lines = 0;
    for (int i = 0; i < num_files; i++) {
        files[i].lines = 0;
    }

    // Read from each file and accumulate the line counts
    char buffer[1024];
    while (1) {
        int bytes_read = read(files[0].fd, buffer, sizeof(buffer));
        if (bytes_read == 0) {
            break;
        } else if (bytes_read == -1) {
            perror("Error reading from file");
            return;
        }

        // Increment the line count for each file
        for (int i = 0; i < num_files; i++) {
            files[i].lines += count_lines(buffer, bytes_read);
        }
