        return 1;
    }

    // Initialize the file metadata array
    int num_files = argc - 1;
    file_metadata_t *files = (file_metadata_t *) malloc(num_files * sizeof(file_metadata_t));

    // Validate each input file and store its metadata
    for (int i = 0; i < num_files; i++) {
