            return 1;
        }
        files[i].filename = argv[i + 1];
    }

    // Initialize the line count for each file
    for (int i = 0; i < num_files; i++) {
        files[i].lines = 0;
    }

    // Process the input files concurrently using a pool of worker threads
    pthread_t *threads = (pthread_t *) malloc(num_files * sizeof(pthread_t));
    for (int i = 0; i < num_files; i++) {
        if (pthread_create(&threads[i], NULL, process_file, &files[i]) != 0) {
            perror("Error creating thread");
            return 1;
        }
    }

    // Wait for all threads to complete and accumulate the line counts
    long total_lines = 0;
    for (int i = 0; i < num_files; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Error joining thread");
            return 1;
        }
        total_lines += files[i].lines;
    }

    // Print the final line count and return success
    printf("Total lines: %ld\n", total_lines);
    return 0;
}
