#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

// Define constants for command line options
#define OPTION_HELP 1
#define OPTION_CHARCOUNT 2
#define OPTION_LINECOUNT 3
#define OPTION_OUTPUTFILE 4
#define OPTION_VERBOSE 5

// Define constants for file encodings and line endings
#define ENCODING_UTF8 1
#define ENCODING_ASCII 2
#define LINEENDING_LF 1
#define LINEENDING_CRLF 2

// Define a structure to hold information about each file
typedef struct {
    char *filename;
    int fd;
    size_t line_count;
    size_t char_count;
} file_info_t;

// Define a function to handle errors and exit the program
void error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

// Define a function to read a line from a file
char *readline(int fd, size_t *len) {
    // Allocate memory for the line
    char *line = malloc(1024);
    if (!line) {
        error("Failed to allocate memory for line");
    }

    // Read a line from the file
    ssize_t nread = read(fd, line, 1024);
    if (nread < 0) {
        error("Failed to read line from file");
    }

    // Update the length of the line
    *len = nread;

    return line;
}

// Define a function to count the number of lines in a file
size_t count_lines(int fd) {
    size_t line_count = 0;
    size_t len;
    char *line;

    // Read each line from the file and increment the line count
    while ((line = readline(fd, &len)) != NULL) {
        line_count++;
    }

    return line_count;
}

// Define a function to count the number of characters in a file
size_t count_chars(int fd) {
    size_t char_count = 0;
    size_t len;
    char *line;

    // Read each line from the file and increment the character count
    while ((line = readline(fd, &len)) != NULL) {
        char_count += strlen(line);
    }

    return char_count;
}

// Define a function to process a single file
void process_file(file_info_t *file) {
    // Open the file for reading
    file->fd = open(file->filename, O_RDONLY);
    if (file->fd < 0) {
        error("Failed to open file");
    }

    // Count the number of lines and characters in the file
    file->line_count = count_lines(file->fd);
    file->char_count = count_chars(file->fd);
}

// Define a function to process multiple files concurrently
void process_files(int argc, char **argv) {
    // Initialize the number of files and the array of file information structures
    int num_files = argc - 1;
    file_info_t *files = malloc(num_files * sizeof(file_info_t));
    if (!files) {
        error("Failed to allocate memory for file information");
    }

    // Initialize the semaphore for synchronizing access to the files array
    sem_t *sem = sem_open("/file_sem", O_CREAT, 0644, num_files);
    if (sem == SEM_FAILED) {
        error("Failed to create semaphore");
    }

    // Initialize the array of file descriptors for asynchronous processing
    int *fds = malloc(num_files * sizeof(int));
    if (!fds) {
        error("Failed to allocate memory for file descriptors");
    }

    // Loop through each file and process it concurrently
    for (int i = 0; i < num_files; i++) {
        // Create a new thread to process the file
        pthread_t tid;
        if (pthread_create(&tid, NULL, process_file, &files[i]) != 0) {
            error("Failed to create thread");
        }

        // Add the file descriptor to the array of file descriptors for asynchronous processing
        fds[i] = files[i].fd;
    }

    // Loop through each file and wait for it to complete
    for (int i = 0; i < num_files; i++) {
        // Wait for the thread to complete
        if (pthread_join(tid, NULL) != 0) {
            error("Failed to join thread");
        }

        // Close the file descriptor
        close(fds[i]);
    }

    // Release the semaphore
    sem_close(sem);
}

// Define a function to print the aggregated results
void print_results(int argc, char **argv) {
    // Initialize the total line count and character count
    size_t total_line_count = 0;
    size_t total_char_count = 0;

    // Loop through each file and add its line and character counts to the totals
    for (int i = 1; i < argc; i++) {
        total_line_count += files[i].line_count;
        total_char_count += files[i].char_count;
    }

    // Print the aggregated results
    printf("Total line count: %zu\n", total_line_count);
    printf("Total character count: %zu\n", total_char_count);
}

// Define a function to handle command line options
void handle_options(int argc, char **argv) {
    // Initialize the option index and the number of files
    int optind = 1;
    int num_files = argc - 1;

    // Loop through each file and process its options
    for (int i = 0; i < num_files; i++) {
        // Initialize the option index for this file
        optind = 1;

        // Process each option for this file
        while (optind < argc) {
            // Check if the option is a valid command line option
            if (argv[i][optind] == '-') {
                switch (argv[i][optind + 1]) {
                    case 'h':
                        printf("Usage: %s [options] file1 file2 ...\n", argv[0]);
                        printf("Options:\n");
                        printf("\t-c\tPrint only the total character count of all lines.\n");
                        printf("\t-o <output_file>\tWrite the aggregated results to the specified output file.\n");
                        printf("\t-v\tEnable verbose mode, providing detailed progress information during processing.\n");
                        exit(EXIT_SUCCESS);
                    case 'c':
                        // Print only the total character count of all lines
                        printf("Total character count: %zu\n", total_char_count);
                        break;
                    case 'o':
                        // Write the aggregated results to the specified output file
                        if (optind + 1 < argc) {
                            char *output_file = argv[i][optind + 2];
                            FILE *out = fopen(output_file, "w");
                            if (!out) {
                                error("Failed to open output file");
                            }
                            fprintf(out, "Total line count: %zu\n", total_line_count);
                            fprintf(out, "Total character count: %zu\n", total_char_count);
                            fclose(out);
                        } else {
                            error("Missing output file name");
                        }
                        break;
                    case 'v':
                        // Enable verbose mode, providing detailed progress information during processing
                        printf("Verbose mode enabled\n");
                        break;
                }
            } else {
                // Check if the option is a valid file name
                if (argv[i][optind] != '-') {
                    files[i].filename = argv[i][optind];
                } else {
                    error("Invalid command line option");
                }
            }
        }
    }
}

int main(int argc, char **argv) {
    // Check if the program has been invoked with a valid number of arguments
    if (argc < 2) {
        printf("Usage: %s [options] file1 file2 ...\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Handle command line options
    handle_options(argc, argv);

    // Process each file concurrently
    process_files(argc, argv);

    // Print the aggregated results
    print_results(argc, argv);

    return 0;
}
