// Define a function to allocate a new slab allocator with a given size
SlabAllocator* createSlabAllocator(size_t size) {
    SlabAllocator *allocator = malloc(sizeof(SlabAllocator));
    if (allocator == NULL) {
        return NULL;
    }
    allocator->memory = malloc(size);
    if (allocator->memory == NULL) {
        free(allocator);
        return NULL;
    }
    allocator->size = size;
    return allocator;
}

// Define a function to allocate memory for an array of structures in the slab allocator
void* allocateMemory(SlabAllocator *allocator, size_t numStructures) {
    // Calculate the total size required for the array of structures
    size_t totalSize = sizeof(NFAPI_CRC_INDICATION_PDU_T) * numStructures;

    // Check if there is enough memory available in the slab allocator
    if (allocator->size < totalSize) {
        return NULL;
    }

    // Allocate memory for the array of structures
    void *memory = malloc(totalSize);
    if (memory == NULL) {
        return NULL;
    }

    // Update the slab allocator with the allocated memory
    allocator->size -= totalSize;
    allocator->memory += totalSize;

    return memory;
}

