#define MAX_CONCURRENT_QUERIES 10
#define CACHE_SIZE 1024
#define CACHE_TTL 3600 // seconds
#define RESOLVE_TIMEOUT 5 // seconds
#define DNS_SERVERS "8.8.8.8,8.8.4.4"
#define DNS_PORT 53
#define DNS_PROTOCOL "udp"
#define DNS_OVER_TLS 0
