#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <stdbool.h>
#include <inttypes.h>
#include <getopt.h>

// Define constants for command-line options
#define OPT_HELP 1
#define OPT_CHARCOUNT 2
#define OPT_OUTPUTFILE 3
#define OPT_VERBOSE 4

// Define structure to store records
typedef struct {
    long offset;
    int key;
} record_t;

// Function to parse command-line arguments
void parse_args(int argc, char **argv) {
    // Initialize variables for parsing options
    int c;
    bool help = false;
    bool charcount = false;
    bool verbose = false;
    char *outputfile = NULL;

    // Define options and their corresponding short and long names
    static struct option long_options[] = {
        {"help", no_argument, 0, OPT_HELP},
        {"charcount", no_argument, 0, OPT_CHARCOUNT},
        {"outputfile", required_argument, 0, OPT_OUTPUTFILE},
        {"verbose", no_argument, 0, OPT_VERBOSE},
        {0, 0, 0, 0}
    };

    // Parse command-line arguments using getopt_long()
    while ((c = getopt_long(argc, argv, "hco:v", long_options, NULL)) != -1) {
        switch (c) {
            case OPT_HELP:
                help = true;
                break;
            case OPT_CHARCOUNT:
                charcount = true;
                break;
            case OPT_OUTPUTFILE:
                outputfile = optarg;
                break;
            case OPT_VERBOSE:
                verbose = true;
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", c);
                help = true;
        }
    }

    // Print usage information if --help is specified or no input files are provided
    if (help || optind >= argc) {
        printf("Usage: %s [options] <input_file1> [<input_file2> ...]\n", argv[0]);
        printf("Options:\n");
        printf("\t-h, --help\t\tPrint usage information and exit\n");
        printf("\t-c, --charcount\t\tPrint only the total character count for each input file\n");
        printf("\t-o <output_file>, --outputfile=<output_file>\tWrite results to an output file\n");
        printf("\t-v, --verbose\t\tPrint verbose messages during processing\n");
        exit(EXIT_SUCCESS);
    }

    // Set variables for input and output files
    int num_input_files = argc - optind;
    char **input_files = &argv[optind];
    FILE *output_file = NULL;

    // Open the output file if specified
    if (outputfile != NULL) {
        output_file = fopen(outputfile, "w");
        if (output_file == NULL) {
            fprintf(stderr, "Error: unable to open output file %s for writing\n", outputfile);
            exit(EXIT_FAILURE);
        }
    }

    // Print usage information and exit if no input files are provided
    if (num_input_files == 0) {
        printf("Usage: %s [options] <input_file1> [<input_file2> ...]\n", argv[0]);
        printf("Options:\n");
        printf("\t-h, --help\t\tPrint usage information and exit\n");
        printf("\t-c, --charcount\t\tPrint only the total character count for each input file\n");
        printf("\t-o <output_file>, --outputfile=<output_file>\tWrite results to an output file\n");
        printf("\t-v, --verbose\t\tPrint verbose messages during processing\n");
        exit(EXIT_SUCCESS);
    }

    // Print usage information and exit if any input files are not readable
    for (int i = 0; i < num_input_files; i++) {
        FILE *file = fopen(input_files[i], "r");
        if (file == NULL) {
            fprintf(stderr, "Error: unable to open input file %s for reading\n", input_files[i]);
            exit(EXIT_FAILURE);
        }
    }
}

// Function to read a binary input file and generate an output file
void process_input_file(char *input_file, char *output_file) {
    // Open the input file for reading
    FILE *input = fopen(input_file, "rb");
    if (input == NULL) {
        fprintf(stderr, "Error: unable to open input file %s for reading\n", input_file);
        exit(EXIT_FAILURE);
    }

    // Open the output file for writing
    FILE *output = fopen(output_file, "wb");
    if (output == NULL) {
        fprintf(stderr, "Error: unable to open output file %s for writing\n", output_file);
        exit(EXIT_FAILURE);
    }

    // Define variables for parsing input and generating output
    char buffer[BUFSIZ];
    size_t bytes_read;
    size_t total_bytes = 0;
    size_t total_chars = 0;

    // Read the input file in chunks and write to the output file
    while ((bytes_read = fread(buffer, sizeof(char), BUFSIZ, input)) > 0) {
        fwrite(buffer, sizeof(char), bytes_read, output);
        total_bytes += bytes_read;
        total_chars += strlen(buffer);
    }

    // Close the input and output files
    fclose(input);
    fclose(output);

    // Print the total character count for the input file
    printf("Total character count for %s: %zu\n", input_file, total_chars);
}

// Function to generate a comprehensive report of aggregated line counts and total character counts across all specified files
void generate_report(int num_input_files, char **input_files) {
    // Initialize variables for parsing input files and generating output
    size_t total_bytes = 0;
    size_t total_chars = 0;

    // Read each input file and update the total character count and byte count
    for (int i = 0; i < num_input_files; i++) {
        process_input_file(input_files[i], NULL);
        total_bytes += get_file_size(input_files[i]);
        total_chars += get_file_charcount(input_files[i]);
    }

    // Print the total character count and byte count for all input files
    printf("Total character count: %zu\n", total_chars);
    printf("Total byte count: %zu\n", total_bytes);
}

// Function to get the size of a file in bytes
size_t get_file_size(char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Error: unable to open file %s for reading\n", filename);
        exit(EXIT_FAILURE);
    }

    // Get the size of the file using fseek() and ftell()
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    // Close the file
    fclose(file);

    return (size_t)file_size;
}

// Function to get the character count of a file
size_t get_file_charcount(char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Error: unable to open file %s for reading\n", filename);
        exit(EXIT_FAILURE);
    }

    // Define variables for parsing the file and counting characters
    char buffer[BUFSIZ];
    size_t bytes_read;
    size_t total_chars = 0;

    // Read the file in chunks and count the number of characters
    while ((bytes_read = fread(buffer, sizeof(char), BUFSIZ, file)) > 0) {
        total_chars += strlen(buffer);
    }

    // Close the file
    fclose(file);

    return total_chars;
}

int main(int argc, char **argv) {
    // Parse command-line arguments using getopt()
    parse_args(argc, argv);

    // Generate a comprehensive report of aggregated line counts and total character counts across all specified files
    generate_report(argc - optind, &argv[optind]);

    return 0;
}']

