// Define the structure to store the aggregated statistics
struct AggregateStats {
    int total_lines;
    double average_line_length;
    char longest_line[1024];
    char shortest_line[1024];
};

// Define the function to process a single log file
void process_log_file(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Initialize the aggregated statistics structure
    struct AggregateStats stats;
    memset(&stats, 0, sizeof(struct AggregateStats));

    // Read each line of the log file and perform the necessary operations
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        stats.total_lines++;
        stats.average_line_length += strlen(line);
        if (strlen(line) > strlen(stats.longest_line)) {
            strcpy(stats.longest_line, line);
        }
        if (strlen(line) < strlen(stats.shortest_line)) {
            strcpy(stats.shortest_line, line);
        }
    }

    // Close the file and free the memory allocated for the line buffer
    fclose(fp);
    free(line);
}

// Define the function to process a directory of log files
void process_directory(const char *dirname) {
    DIR *dir = opendir(dirname);
    if (dir == NULL) {
        perror("opendir");
        return;
    }

    // Initialize the aggregated statistics structure
    struct AggregateStats stats;
    memset(&stats, 0, sizeof(struct AggregateStats));

    // Read each file in the directory and process it
    struct dirent *entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char *filename = entry->d_name;
        process_log_file(filename);
    }

    // Close the directory and free the memory allocated for the dirent structure
    closedir(dir);
}

