    }

    // Initialize the aggregated statistics structure
    struct AggregateStats stats;
    memset(&stats, 0, sizeof(struct AggregateStats));

    // Read each file in the directory and process it if it meets the minimum line length threshold
    struct dirent *entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char *filename = entry->d_name;
        FILE *fp = fopen(filename, "r");
        if (fp == NULL) {
            perror("fopen");
            return;
        }

        // Read each line of the file and check if it meets the minimum line length threshold
        char *line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, fp)) != -1) {
            if (strlen(line) >= min_line_length) {
                process_log_file(filename);
                break;
            }
        }

        // Close the file and free the memory allocated for the line buffer
        fclose(fp);
        free(line);
    }

    // Close the directory and free the memory allocated for the dirent structure
    closedir(dir);
}

// Define the function to compress the output file using LZ4 compression algorithm
void compress_output_file(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    // Initialize the LZ4 compression library
    lz4_init();

    // Compress the file using the LZ4 algorithm
    char *compressed_data = lz4_compress(fp);
    if (compressed_data == NULL) {
        perror("lz4_compress");
        return;
    }

    // Close the file and free the memory allocated for the line buffer
    fclose(fp);
    free(compressed_data);
}

