            return;
        }

        // Read each line of the file and export the aggregated statistics to the CSV file
        char *line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, fp)) != -1) {
            struct AggregateStats stats;
            memset(&stats, 0, sizeof(struct AggregateStats));
