// Define constants for the program
#define MAX_THREADS 10000
#define MIN_LINE_LENGTH 50
#define CSV_EXPORT_ENCODING "UTF-8"

// Struct to store statistics for a log file
struct LogFileStats {
    char *filename;
    int total_lines;
    float average_line_length;
    int longest_line;
    int shortest_line;
};

// Function to count the number of lines in a file
int countLines(FILE *file) {
    int line_count = 0;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        line_count++;
    }

    free(line);
    return line_count;
}

// Function to calculate the average line length for a log file
float calculateAverageLineLength(FILE *file) {
    int total_length = 0;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        total_length += strlen(line);
    }

    free(line);
    return (float)total_length / countLines(file);
}

// Function to identify the longest and shortest lines in a log file
void identifyLongestAndShortestLines(FILE *file, int *longest_line, int *shortest_line) {
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        if (strlen(line) > *longest_line) {
            *longest_line = strlen(line);
        }
        if (strlen(line) < *shortest_line || *shortest_line == 0) {
            *shortest_line = strlen(line);
        }
    }

    free(line);
}

// Function to filter log files based on a minimum line length threshold
void filterLogFiles(char **files, int num_files, int min_line_length) {
    int i;
    for (i = 0; i < num_files; i++) {
        if (countLines(fopen(files[i], "r")) < min_line_length) {
            files[i] = NULL;
        }
    }
}

// Function to compress a file using LZ4 compression algorithm
void compressFile(char *filename, char *compressed_filename) {
    FILE *file = fopen(filename, "r");
    FILE *compressed_file = fopen(compressed_filename, "wb");
    int buffer_size = 1024;
    char *buffer = malloc(buffer_size);
    size_t read;

    while ((read = fread(buffer, 1, buffer_size, file)) > 0) {
        lz4_compress(buffer, read, compressed_file);
    }

    free(buffer);
    fclose(file);
    fclose(compressed_file);
}

// Function to decompress a file using LZ4 compression algorithm
void decompressFile(char *filename, char *decompressed_filename) {
    FILE *file = fopen(filename, "rb");
    FILE *decompressed_file = fopen(decompressed_filename, "w");
    int buffer_size = 1024;
    char *buffer = malloc(buffer_size);
    size_t read;

    while ((read = lz4_decompress(file, decompressed_file)) > 0) {
        fwrite(buffer, 1, read, decompressed_file);
    }

    free(buffer);
    fclose(file);
    fclose(decompressed_file);
}

// Function to handle file I/O errors gracefully
void handleFileIOError(char *filename) {
    printf("Error reading file %s\n", filename);
}

