    int i;
    for (i = 0; i < num_files; i++) {
        // Detect encoding of file using a robust character set detection library
        if (detect_encoding(files[i]) == "UTF-8") {
            processLogFile(files[i]);
        } else {
            printf("Skipping log file %s with unknown encoding\n", files[i]);
        }
    }
}

// Function to process a single log file
void processLogFile(char *filename) {
    FILE *file = fopen(filename, "r");
    struct LogFileStats stats;

    // Initialize statistics for the log file
    stats.filename = filename;
    stats.total_lines = countLines(file);
    stats.average_line_length = calculateAverageLineLength(file);
    identifyLongestAndShortestLines(file, &stats.longest_line, &stats.shortest_line);

    // Filter log files based on a minimum line length threshold
    if (stats.total_lines >= MIN_LINE_LENGTH) {
        filterLogFiles(&filename, 1, MIN_LINE_LENGTH);
    }

    // Compress the log file using LZ4 compression algorithm
    char *compressed_filename = malloc(strlen(filename) + strlen(".lz4") + 1);
    sprintf(compressed_filename, "%s.lz4", filename);
    compressFile(filename, compressed_filename);

    // Decompress the log file using LZ4 compression algorithm
    char *decompressed_filename = malloc(strlen(filename) + strlen(".txt") + 1);
    sprintf(decompressed_filename, "%s.txt", filename);
    decompressFile(compressed_filename, decompressed_filename);

    // Export aggregated statistics to a CSV file
    char *csv_filename = malloc(strlen(filename) + strlen(".csv") + 1);
    sprintf(csv_filename, "%s.csv", filename);
    exportCSV(stats, csv_filename);

    // Free memory allocated for filenames and statistics
    free(compressed_filename);
    free(decompressed_filename);
    free(csv_filename);
}

// Function to export aggregated statistics to a CSV file
void exportCSV(struct LogFileStats stats, char *filename) {
    FILE *file = fopen(filename, "w");
    fprintf(file, "Filename,Total Lines,Average Line Length,Longest Line,Shortest Line\n");
    fprintf(file, "%s,%d,%f,%d,%d\n", stats.filename, stats.total_lines, stats.average_line_length, stats.longest_line, stats.shortest_line);
    fclose(file);
}

