    // Acquire lock on the collection
    pthread_mutex_lock(&collection->lock);

    // Find the task with the given ID
    for (int i = 0; i < collection->size; i++) {
        if (collection->tasks[i]->id == id) {
            struct Task *task = malloc(sizeof(struct Task));
            memcpy(task, collection->tasks[i], sizeof(struct Task));
            pthread_mutex_unlock(&collection->lock);
            return task;
        }
    }

    // Release lock on the collection
    pthread_mutex_unlock(&collection->lock);

    return NULL;
}

