    // Acquire lock on the collection
    pthread_mutex_lock(&collection->lock);

    // Find the task with the given ID
    for (int i = 0; i < collection->size; i++) {
        if (collection->tasks[i]->id == id) {
            free(collection->tasks[i]);
            collection->tasks[i] = NULL;
            break;
        }
    }

    // Release lock on the collection
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

