#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <time.h>
#include <pthread.h>

// Define the structure for a task
typedef struct Task {
    int id;
    int priority;
    char status;
} Task;

// Define the structure for a record in the linked list
typedef struct Record {
    int value;
    struct Record* next;
} Record;

// Define the data structure to store tasks and records
typedef struct DataStructure {
    Task* tasks;
    Record* records;
    size_t num_tasks;
    size_t num_records;
    pthread_mutex_t mutex;
} DataStructure;

// Define the function to add a new task
void addTask(DataStructure* ds, int id, int priority, char status) {
    // Lock the mutex before modifying the data structure
    pthread_mutex_lock(&ds->mutex);

    // Allocate memory for the new task
    Task* new_task = malloc(sizeof(Task));
    assert(new_task != NULL);

    // Initialize the new task
    new_task->id = id;
    new_task->priority = priority;
    new_task->status = status;

    // Add the new task to the end of the array
    ds->tasks[ds->num_tasks++] = *new_task;

    // Unlock the mutex after modifying the data structure
    pthread_mutex_unlock(&ds->mutex);
}

// Define the function to update an existing task
void updateTask(DataStructure* ds, int id, int priority, char status) {
    // Lock the mutex before modifying the data structure
    pthread_mutex_lock(&ds->mutex);

    // Find the task with the given ID
    Task* task = NULL;
    for (size_t i = 0; i < ds->num_tasks; i++) {
        if (ds->tasks[i].id == id) {
            task = &ds->tasks[i];
            break;
        }
    }

    // If the task was found, update its priority and status
    if (task != NULL) {
        task->priority = priority;
        task->status = status;
    }

    // Unlock the mutex after modifying the data structure
    pthread_mutex_unlock(&ds->mutex);
}

// Define the function to retrieve tasks based on their priority
void getTasks(DataStructure* ds, int priority) {
    // Lock the mutex before accessing the data structure
    pthread_mutex_lock(&ds->mutex);

    // Find all tasks with the given priority
    Task* tasks = NULL;
    size_t num_tasks = 0;
    for (size_t i = 0; i < ds->num_tasks; i++) {
        if (ds->tasks[i].priority == priority) {
            tasks = realloc(tasks, sizeof(Task) * (num_tasks + 1));
            assert(tasks != NULL);
            tasks[num_tasks++] = ds->tasks[i];
        }
    }

    // Unlock the mutex after accessing the data structure
    pthread_mutex_unlock(&ds->mutex);
}

// Define the function to add a new record to the linked list
void addRecord(DataStructure* ds, int value) {
    // Lock the mutex before modifying the data structure
    pthread_mutex_lock(&ds->mutex);

    // Allocate memory for the new record
    Record* new_record = malloc(sizeof(Record));
    assert(new_record != NULL);

    // Initialize the new record
    new_record->value = value;
    new_record->next = ds->records;

    // Add the new record to the end of the linked list
    ds->records = new_record;

    // Increment the number of records
    ds->num_records++;

    // Unlock the mutex after modifying the data structure
    pthread_mutex_unlock(&ds->mutex);
}

// Define the function to delete a record from the linked list
void deleteRecord(DataStructure* ds, int value) {
    // Lock the mutex before modifying the data structure
    pthread_mutex_lock(&ds->mutex);

    // Find the record with the given value
    Record* record = NULL;
    for (Record* current = ds->records; current != NULL; current = current->next) {
        if (current->value == value) {
            record = current;
            break;
        }
    }

    // If the record was found, delete it from the linked list
    if (record != NULL) {
        Record* previous = NULL;
        for (Record* current = ds->records; current != NULL; current = current->next) {
            if (current == record) {
                if (previous == NULL) {
                    ds->records = current->next;
                } else {
                    previous->next = current->next;
                }
                break;
            }
            previous = current;
        }
        free(record);
        ds->num_records--;
    }

    // Unlock the mutex after modifying the data structure
    pthread_mutex_unlock(&ds->mutex);
}

// Define the function to serialize the data structure to a file
void serialize(DataStructure* ds, FILE* fp) {
    // Lock the mutex before accessing the data structure
    pthread_mutex_lock(&ds->mutex);

    // Write the number of tasks and records to the file
    fwrite(&ds->num_tasks, sizeof(size_t), 1, fp);
    fwrite(&ds->num_records, sizeof(size_t), 1, fp);

    // Write each task to the file
    for (size_t i = 0; i < ds->num_tasks; i++) {
        Task* task = &ds->tasks[i];
        fwrite(&task->id, sizeof(int), 1, fp);
        fwrite(&task->priority, sizeof(int), 1, fp);
        fwrite(&task->status, sizeof(char), 1, fp);
    }

    // Write each record to the file
    for (Record* current = ds->records; current != NULL; current = current->next) {
        fwrite(&current->value, sizeof(int), 1, fp);
    }

    // Unlock the mutex after accessing the data structure
    pthread_mutex_unlock(&ds->mutex);
}

// Define the function to deserialize the data structure from a file
void deserialize(DataStructure* ds, FILE* fp) {
    // Lock the mutex before modifying the data structure
    pthread_mutex_lock(&ds->mutex);

    // Read the number of tasks and records from the file
    size_t num_tasks;
    size_t num_records;
    fread(&num_tasks, sizeof(size_t), 1, fp);
    fread(&num_records, sizeof(size_t), 1, fp);

    // Allocate memory for the tasks and records
    ds->tasks = malloc(sizeof(Task) * num_tasks);
    assert(ds->tasks != NULL);
    ds->records = malloc(sizeof(Record) * num_records);
    assert(ds->records != NULL);

    // Read each task from the file and initialize it
    for (size_t i = 0; i < num_tasks; i++) {
        Task* task = &ds->tasks[i];
        fread(&task->id, sizeof(int), 1, fp);
        fread(&task->priority, sizeof(int), 1, fp);
        fread(&task->status, sizeof(char), 1, fp);
    }

    // Read each record from the file and initialize it
    for (size_t i = 0; i < num_records; i++) {
        Record* record = &ds->records[i];
        fread(&record->value, sizeof(int), 1, fp);
    }

    // Set the number of tasks and records
    ds->num_tasks = num_tasks;
    ds->num_records = num_records;

    // Unlock the mutex after modifying the data structure
    pthread_mutex_unlock(&ds->mutex);
}

// Define the function to free the memory allocated for the data structure
void destroy(DataStructure* ds) {
    // Lock the mutex before modifying the data structure
    pthread_mutex_lock(&ds->mutex);

    // Free the memory allocated for the tasks and records
    free(ds->tasks);
    free(ds->records);

    // Set the number of tasks and records to 0
    ds->num_tasks = 0;
    ds->num_records = 0;

    // Unlock the mutex after modifying the data structure
    pthread_mutex_unlock(&ds->mutex);
}
