void initRecordCollection(struct RecordCollection* collection, const char* filename) {
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Read the data from the file and store it in a JSON object
    json_object* root = json_loadf(fp, 0, NULL);
    if (root == NULL) {
        printf("Error: unable to parse JSON data\n");
        fclose(fp);
        return;
    }

    // Get the number of records in the file
    size_t numRecords = json_object_array_length(root);

    // Allocate memory for the collection and initialize it
    collection->capacity = numRecords;
    collection->count = 0;
    collection->records = malloc(numRecords * sizeof(Record));
    if (collection->records == NULL) {
        printf("Error: unable to allocate memory for record collection\n");
        json_object_put(root);
        fclose(fp);
        return;
    }

    // Iterate over the JSON array and populate the records
    size_t i = 0;
    json_object* obj;
    json_object_array_foreach(root, i, obj) {
        Record* record = &collection->records[i];
        record->timestamp = (time_t)json_object_get_int64(obj);
        record->status = (enum Status)json_object_get_int(obj);
        record->weight = json_object_get_float(obj);
        collection->count++;
    }

    // Clean up the JSON object and file
    json_object_put(root);
    fclose(fp);
}

// Print all records in the collection
void printAllRecords(struct RecordCollection* collection) {
    for (size_t i = 0; i < collection->count; i++) {
        printf("Record %zu: timestamp=%ld, status=%d, weight=%.2f\n", i, collection->records[i].timestamp, collection->records[i].status, collection->records[i].weight);
    }
}

// Filter records based on a specified status and print them
void filterRecords(struct RecordCollection* collection, enum Status status) {
    size_t count = 0;
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->records[i].status == status) {
            printf("Record %zu: timestamp=%ld, status=%d, weight=%.2f\n", i, collection->records[i].timestamp, collection->records[i].status, collection->records[i].weight);
            count++;
        }
    }
}

int main() {
    struct RecordCollection collection;
    initRecordCollection(&collection, "data.json");
    printAllRecords(&collection);
    filterRecords(&collection, ACTIVE);
    return 0;
}
