```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure for tasks
typedef struct Task {
    int id;
    int priority;
    char status;
} Task;

// Define the linked list node for records
typedef struct RecordNode {
    int key;
    long offset;
    struct RecordNode* next;
} RecordNode;

// Define the data structure for managing tasks and records
typedef struct TaskRecordManager {
    pthread_mutex_t mutex; // Mutex for synchronizing access to the data structure
    int num_tasks; // Number of tasks in the data structure
    int num_records; // Number of records in the data structure
    Task* tasks; // Array of tasks
    RecordNode* records; // Linked list of records
} TaskRecordManager;

// Function to add a new task to the data structure
void addTask(TaskRecordManager* manager, int id, int priority) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->num_tasks >= 50000) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    Task* task = malloc(sizeof(Task));
    if (task == NULL) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    task->id = id;
    task->priority = priority;
    task->status = 'N';
    manager->tasks[manager->num_tasks++] = task;
    pthread_mutex_unlock(&manager->mutex);
}

// Function to update the status of a task in the data structure
void updateTaskStatus(TaskRecordManager* manager, int id, char status) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->num_tasks; i++) {
        if (manager->tasks[i]->id == id) {
            manager->tasks[i]->status = status;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Function to retrieve the priority of a task in the data structure
int getTaskPriority(TaskRecordManager* manager, int id) {
    pthread_mutex_lock(&manager->mutex);
    for (int i = 0; i < manager->num_tasks; i++) {
        if (manager->tasks[i]->id == id) {
            return manager->tasks[i]->priority;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return -1; // Return -1 if the task is not found
}

// Function to add a new record to the data structure
void addRecord(TaskRecordManager* manager, int key, long offset) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->num_records >= 10000) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    RecordNode* node = malloc(sizeof(RecordNode));
    if (node == NULL) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    node->key = key;
    node->offset = offset;
    node->next = manager->records;
    manager->records = node;
    manager->num_records++;
    pthread_mutex_unlock(&manager->mutex);
}

// Function to delete a record from the data structure
void deleteRecord(TaskRecordManager* manager, int key) {
    pthread_mutex_lock(&manager->mutex);
    RecordNode* node = manager->records;
    while (node != NULL && node->key != key) {
        node = node->next;
    }
    if (node == NULL) {
        // Handle record not found
        printf("Record not found\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    RecordNode* prev = node->prev;
    if (prev != NULL) {
        prev->next = node->next;
    } else {
        manager->records = node->next;
    }
    free(node);
    manager->num_records--;
    pthread_mutex_unlock(&manager->mutex);
}

// Function to retrieve a record from the data structure
RecordNode* getRecord(TaskRecordManager* manager, int key) {
    pthread_mutex_lock(&manager->mutex);
    RecordNode* node = manager->records;
    while (node != NULL && node->key != key) {
        node = node->next;
    }
    if (node == NULL) {
        // Handle record not found
        printf("Record not found\n");
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }
    pthread_mutex_unlock(&manager->mutex);
    return node;
}

// Function to serialize the data structure to a file
void serialize(TaskRecordManager* manager, FILE* fp) {
    pthread_mutex_lock(&manager->mutex);
    // Write the number of tasks and records to the file
    fwrite(&manager->num_tasks, sizeof(int), 1, fp);
    fwrite(&manager->num_records, sizeof(int), 1, fp);
    // Write each task to the file
    for (int i = 0; i < manager->num_tasks; i++) {
        Task* task = manager->tasks[i];
        fwrite(&task->id, sizeof(int), 1, fp);
        fwrite(&task->priority, sizeof(int), 1, fp);
        fwrite(&task->status, sizeof(char), 1, fp);
    }
    // Write each record to the file
    RecordNode* node = manager->records;
    while (node != NULL) {
        fwrite(&node->key, sizeof(int), 1, fp);
        fwrite(&node->offset, sizeof(long), 1, fp);
        node = node->next;
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Function to deserialize the data structure from a file
void deserialize(TaskRecordManager* manager, FILE* fp) {
    pthread_mutex_lock(&manager->mutex);
    // Read the number of tasks and records from the file
    int num_tasks;
    int num_records;
    fread(&num_tasks, sizeof(int), 1, fp);
    fread(&num_records, sizeof(int), 1, fp);
    // Read each task from the file
    for (int i = 0; i < num_tasks; i++) {
        Task* task = malloc(sizeof(Task));
        if (task == NULL) {
