            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        fread(&task->id, sizeof(int), 1, fp);
        fread(&task->priority, sizeof(int), 1, fp);
        fread(&task->status, sizeof(char), 1, fp);
        manager->tasks[i] = task;
    }
    // Read each record from the file
    for (int i = 0; i < num_records; i++) {
        RecordNode* node = malloc(sizeof(RecordNode));
        if (node == NULL) {
            // Handle memory allocation failure
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        fread(&node->key, sizeof(int), 1, fp);
        fread(&node->offset, sizeof(long), 1, fp);
        node->next = manager->records;
        manager->records = node;
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Function to free the resources of the data structure
void destroy(TaskRecordManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    // Free each task in the array
    for (int i = 0; i < manager->num_tasks; i++) {
        free(manager->tasks[i]);
    }
    // Free each record in the linked list
    RecordNode* node = manager->records;
    while (node != NULL) {
        RecordNode* next = node->next;
        free(node);
        node = next;
    }
    pthread_mutex_unlock(&manager->mutex);
}
