// Function to allocate and initialize memory for the two arrays
void init_memory(int *long_offset, int *key) {
    // Allocate memory for the long offset array with a minimum size of 1000
    *long_offset = (int *)malloc(sizeof(int) * 1000);
    if (*long_offset == NULL) {
        printf("Error: Failed to allocate memory for long offset array\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the long offset array with sequential values starting from 0
    for (int i = 0; i < 1000; i++) {
        (*long_offset)[i] = i * sizeof(int);
    }

