        printf("Error: Failed to allocate memory for record array\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the record array with random values between -1000 and 1000, inclusive
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*records)[i].key = rand() % 2000 - 1000;
        (*records)[i].offset = &((*long_offset)[(*records)[i].key]);
    }
}

// Function to validate the record array and ensure all pointers are correctly set and no null pointers exist
void validate_record_array(record *records, int num_records) {
    // Iterate through each record in the array and check if the offset pointer is valid
    for (int i = 0; i < num_records; i++) {
        if ((*records)[i].offset == NULL) {
