            exit(EXIT_FAILURE);
        }
    }
}

// Function to resize the record array dynamically based on user-defined criteria
void resize_record_array(record **records, int *num_records) {
    // Allocate memory for a new record array with double the size of the current one
    record *new_records = (record *)malloc(sizeof(record) * (*num_records) * 2);
    if (new_records == NULL) {
        printf("Error: Failed to allocate memory for new record array\n");
        exit(EXIT_FAILURE);
