// Define a function to generate a unique key value
int generate_unique_key() {
    // Use a global variable to keep track of the last generated key
    static int last_generated_key = 0;

    // Generate a new key value by incrementing the last generated key and checking for uniqueness
    int new_key = last_generated_key + 1;
    while (new_key == last_generated_key || new_key > MAX_KEY) {
        new_key = rand() % MAX_KEY;
    }

    // Update the last generated key and return the new value
    last_generated_key = new_key;
    return new_key;
}

// Define a function to populate records with unique keys while ensuring no duplicates exist
void populate_records(record* records, int num_records) {
    // Use a lock to synchronize access to the generate_unique_key() function
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Iterate over each record and generate a unique key value
    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&mutex);
        records[i].key = generate_unique_key();
        pthread_mutex_unlock(&mutex);
    }
}

