// Define constants for memory management
#define MAX_RECORDS 10000
#define MAX_KEY 1000000
#define RETRY_LIMIT 10
#define METRICS_SIZE 100

// Define structs for data entries and metadata
struct data_entry {
    char buffer[256];
    int timestamp;
    struct metadata *metadata;
};

struct metadata {
    float value;
    double metrics[METRICS_SIZE];
};

// Define function to generate unique keys
int generate_unique_key() {
    // Use a global variable to keep track of the last generated key
    static int last_key = 0;

    // Generate a new key and check for duplicates
    int key = rand() % MAX_KEY + 1;
    while (key == last_key) {
        key = rand() % MAX_KEY + 1;
    }

    // Update the last generated key
    last_key = key;

    return key;
}

// Define function to populate records with unique keys
void populate_records(struct data_entry *records, int N) {
    // Initialize a lock for generating unique keys
    pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;

    // Loop through each record and generate a unique key
    for (int i = 0; i < N; i++) {
        // Acquire the lock to generate a unique key
        pthread_mutex_lock(&key_lock);

        // Generate a new key using the generate_unique_key() function
        int key = generate_unique_key();

        // Release the lock after generating the key
        pthread_mutex_unlock(&key_lock);

        // Initialize the record with the generated key and random values
        records[i].key = key;
        records[i].timestamp = time(NULL);
        records[i].metadata->value = (float)rand() / RAND_MAX;
        for (int j = 0; j < METRICS_SIZE; j++) {
            records[i].metadata->metrics[j] = (double)(rand() % 201 - 100) / 100.0;
        }
    }
}

// Define function to calculate the sum of all keys
void calculate_sum(struct data_entry *records, int N, long *total_keys) {
    // Initialize a lock for calculating the sum
    pthread_mutex_t sum_lock = PTHREAD_MUTEX_INITIALIZER;

    // Loop through each record and calculate the sum of keys
    for (int i = 0; i < N; i++) {
        // Acquire the lock to calculate the sum
        pthread_mutex_lock(&sum_lock);

        // Increment the total number of keys by the current record's key
        *total_keys += records[i].key;

        // Release the lock after calculating the sum
        pthread_mutex_unlock(&sum_lock);
    }
}

// Define function to free memory allocated for records and metadata
void free_memory(struct data_entry *records, int N) {
    // Loop through each record and free its buffer and metrics array
    for (int i = 0; i < N; i++) {
        free(records[i].buffer);
        free(records[i].metadata->metrics);
    }

    // Free the records array and reset any global state
    free(records);
}

// Define main function to manage memory for multiple data structures
int main() {
    // Initialize variables for number of records, total keys, and memory allocation
    int N = 1000;
    long total_keys = 0;
    struct data_entry *records = malloc(N * sizeof(struct data_entry));

    // Check for memory allocation failures
    if (records == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Populate the records with unique keys and random values
    populate_records(records, N);

    // Calculate the sum of all keys
    calculate_sum(records, N, &total_keys);

    // Print the total number of keys and free memory allocated for records and metadata
    printf("Total number of keys: %ld\n", total_keys);
    free_memory(records, N);

    return 0;
}
