void insertRecord(int value) {
    // Acquire the lock on the record list
    pthread_mutex_lock(&record_list_lock);

    // Create a new record with the given value
    Record* record = malloc(sizeof(Record));
    record->value = value;
    record->next = NULL;

    if (record_list == NULL) {
        record_list = record;
    } else {
        Record* current = record_list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = record;
    }

    // Release the lock on the record list
    pthread_mutex_unlock(&record_list_lock);
}

// Define the function to delete a record from the linked list
void deleteRecord(int value) {
    // Acquire the lock on the record list
    pthread_mutex_lock(&record_list_lock);

    // Find the record with the given value in the linked list
    Record* current = record_list;
    while (current != NULL && current->value != value) {
        current = current->next;
    }

    if (current == NULL) {
        printf("Record not found\n");
    } else {
        // Remove the record from the linked list
        Record* previous = current;
        while (previous->next != NULL && previous->next->value != value) {
            previous = previous->next;
        }
        if (previous->next == NULL) {
            printf("Record not found\n");
        } else {
            previous->next = previous->next->next;
        }
    }

    // Release the lock on the record list
    pthread_mutex_unlock(&record_list_lock);
}

// Define the function to serialize the data structure to a file
void serialize(FILE* fp) {
    // Acquire the lock on the task list
    pthread_mutex_lock(&task_list_lock);

    // Write the number of tasks in the linked list to the file
    int num_tasks = 0;
    Record* current = task_list;
    while (current != NULL) {
        num_tasks++;
        current = current->next;
    }
    fwrite(&num_tasks, sizeof(int), 1, fp);

    // Write each task in the linked list to the file
    current = task_list;
    while (current != NULL) {
        Task* task = malloc(sizeof(Task));
        task->id = current->value;
        task->priority = 0;
        task->status = ' ';
        fwrite(task, sizeof(Task), 1, fp);
        current = current->next;
    }

    // Release the lock on the task list
    pthread_mutex_unlock(&task_list_lock);
}

// Define the function to deserialize the data structure from a file
void deserialize(FILE* fp) {
    // Acquire the lock on the task list
    pthread_mutex_lock(&task_list_lock);

    // Read the number of tasks in the linked list from the file
    int num_tasks;
    fread(&num_tasks, sizeof(int), 1, fp);

    // Read each task in the linked list from the file and add it to the linked list
    for (int i = 0; i < num_tasks; i++) {
        Task* task = malloc(sizeof(Task));
        fread(task, sizeof(Task), 1, fp);
        addTask(task);
    }

    // Release the lock on the task list
    pthread_mutex_unlock(&task_list_lock);
}

// Define the function to free all allocated memory
void freeMemory() {
    // Acquire the lock on the task list
    pthread_mutex_lock(&task_list_lock);

    // Free all tasks in the linked list
    Record* current = task_list;
    while (current != NULL) {
        Task* task = malloc(sizeof(Task));
        free(task);
        current = current->next;
    }

    // Release the lock on the task list
    pthread_mutex_unlock(&task_list_lock);
}

