#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <pthread.h>
#include <zlib.h>

// Define constants for file encoding and compression
#define ENCODING "UTF-8"
#define COMPRESSION_ALGORITHM ZLIB

// Define a structure to store statistics for each log file
typedef struct {
    char *filename;
    int total_lines;
    float average_line_length;
    int longest_line;
    int shortest_line;
} LogFileStats;

// Define a function to read and process a single log file
void* processLogFile(void *args) {
    // Cast the arguments to the correct types
    char *filename = (char *)args;

    // Open the log file for reading
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        return NULL;
    }

    // Initialize variables to store statistics
    int total_lines = 0;
    float average_line_length = 0.0;
    int longest_line = 0;
    int shortest_line = INT_MAX;

    // Read the log file line by line and update statistics
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        total_lines++;
        average_line_length += (float)strlen(line);
        longest_line = MAX(longest_line, strlen(line));
        shortest_line = MIN(shortest_line, strlen(line));
    }

    // Close the log file
    fclose(file);

    // Allocate memory for the statistics structure and populate it with data
    LogFileStats *stats = (LogFileStats *)malloc(sizeof(LogFileStats));
    stats->filename = filename;
    stats->total_lines = total_lines;
    stats->average_line_length = average_line_length / total_lines;
    stats->longest_line = longest_line;
    stats->shortest_line = shortest_line;

    // Return the statistics structure
    return (void *)stats;
}

// Define a function to aggregate statistics across multiple log files
void* aggregateStats(void *args) {
    // Cast the arguments to the correct types
    char **filenames = (char **)args;

    // Initialize variables to store aggregated statistics
    int total_lines = 0;
    float average_line_length = 0.0;
    int longest_line = 0;
    int shortest_line = INT_MAX;

    // Iterate over the log files and update aggregated statistics
    for (int i = 0; i < filenames; i++) {
        LogFileStats *stats = processLogFile(filenames[i]);
        total_lines += stats->total_lines;
        average_line_length += stats->average_line_length;
        longest_line = MAX(longest_line, stats->longest_line);
        shortest_line = MIN(shortest_line, stats->shortest_line);
