void processOptions(int argc, char **argv) {
    // Initialize variables for command-line arguments and options
    int i = 1;
    int option = 0;
    char *inputFile = NULL;
    char *outputFile = NULL;
    int verbose = 0;
    int charCount = 0;

    // Loop through command-line arguments and options
    while (i < argc) {
        if (argv[i][0] == '-') {
            option = atoi(argv[i]);
