// Define a function to read and process a single file
void processFile(char *inputFile, char *outputFile, int verbose) {
    // Initialize variables for file I/O and checksum calculation
    FILE *input = NULL;
    FILE *output = NULL;
    long totalCharCount = 0;
    unsigned long checksum = 0;

    // Open input and output files
    input = fopen(inputFile, "rb");
    if (input == NULL) {
        printf("Error: Failed to open input file %s\n", inputFile);
        exit(1);
    }
    output = fopen(outputFile, "wb");
    if (output == NULL) {
        printf("Error: Failed to open output file %s\n", outputFile);
        exit(1);
    }

    // Read input file and calculate checksum
    char buffer[BUFSIZ];
    size_t bytesRead = 0;
    while ((bytesRead = fread(buffer, sizeof(char), BUFSIZ, input)) > 0) {
        totalCharCount += bytesRead;
        checksum += calculateChecksum(buffer, bytesRead);
    }

    // Print verbose message if requested
    if (verbose) {
        printf("File: %s\n", inputFile);
        printf("\tTotal character count: %ld\n", totalCharCount);
        printf("\tChecksum: %lu\n", checksum);
    }

    // Write output file
    fwrite(&totalCharCount, sizeof(long), 1, output);
    fwrite(&checksum, sizeof(unsigned long), 1, output);

    // Close files and handle errors
    if (fclose(input) == EOF || fclose(output) == EOF) {
        printf("Error: Failed to close file %s\n", inputFile);
        exit(1);
    }
}

// Define a function to calculate the checksum of a buffer
unsigned long calculateChecksum(char *buffer, size_t length) {
    unsigned long checksum = 0;
    for (size_t i = 0; i < length; i++) {
        checksum += buffer[i];
    }
    return checksum;
}

