        exit(1);
    }

    // Read input file and extract metadata
    char buffer[BUFSIZ];
    size_t bytesRead = 0;
    while ((bytesRead = fread(buffer, sizeof(char), BUFSIZ, input)) > 0) {
        if (compressionFormat != 0) {
            // Decompress data using zlib library
            uLongf decompressedSize = bytesRead;
            Bytef *decompressedData = (Bytef *)malloc(decompressedSize);
            int status = uncompress(decompressedData, &decompressedSize, buffer, bytesRead);
            if (status != Z_OK) {
                printf("Error: Failed to decompress data using %s\n", compressionType);
                exit(1);
            }
            fwrite(decompressedData, sizeof(char), decompressedSize, output);
            free(decompressedData);
        } else {
            // Write uncompressed data to output file
            fwrite(buffer, sizeof(char), bytesRead, output);
        }
    }

    // Close files and handle errors
    if (fclose(input) == EOF || fclose(output) == EOF) {
        printf("Error: Failed to close file %s\n", inputFile);
        exit(1);
    }
}

// Define a function to generate checksums for both content and metadata
void generateChecksums(char *inputFile, char *outputFile) {
    // Open input file for reading in binary mode
    FILE *input = fopen(inputFile, "rb");
    if (input == NULL) {
        printf("Error: Failed to open input file %s\n", inputFile);
        exit(1);
    }

    // Determine the compression format of the input file
    int compressionFormat = 0;
    char *compressionType = "none";
    if (strstr(inputFile, ".gz") != NULL) {
        compressionFormat = Z_GZIP;
        compressionType = "gzip";
    } else if (strstr(inputFile, ".bz2") != NULL) {
        compressionFormat = Z_BZIP2;
        compressionType = "bzip2";
    }

    // Open output file for writing in binary mode
    FILE *output = fopen(outputFile, "wb");
    if (output == NULL) {
        printf("Error: Failed to open output file %s\n", outputFile);
        exit(1);
    }

    // Read input file and calculate checksums
    char buffer[BUFSIZ];
    size_t bytesRead = 0;
    while ((bytesRead = fread(buffer, sizeof(char), BUFSIZ, input)) > 0) {
        if (compressionFormat != 0) {
            // Decompress data using zlib library
            uLongf decompressedSize = bytesRead;
            Bytef *decompressedData = (Bytef *)malloc(decompressedSize);
            int status = uncompress(decompressedData, &decompressedSize, buffer, bytesRead);
            if (status != Z_OK) {
                printf("Error: Failed to decompress data using %s\n", compressionType);
                exit(1);
            }
            unsigned long contentChecksum = calculateChecksum(decompressedData, decompressedSize);
            free(decompressedData);
            // Write content checksum to output file
            fwrite(&contentChecksum, sizeof(unsigned long), 1, output);
        } else {
            // Calculate content checksum and write it to output file
            unsigned long contentChecksum = calculateChecksum(buffer, bytesRead);
            fwrite(&contentChecksum, sizeof(unsigned long), 1, output);
        }
    }

    // Close files and handle errors
    if (fclose(input) == EOF || fclose(output) == EOF) {
        printf("Error: Failed to close file %s\n", inputFile);
        exit(1);
    }
}

int main() {
