#define MAX_LOG_SIZE 1024 * 1024 // 1 MB
#define MAX_THREADS 32
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    int fd;
    char *buf;
} log_file_t;

typedef struct {
    pthread_mutex_t lock;
    log_file_t file;
} log_state_t;

void conditional_log(int verbosity, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);

    // Check if the message should be logged based on the verbosity level
    if (verbosity <= LOG_LEVEL_DEBUG) {
        log_state_t *state = get_log_state();
        pthread_mutex_lock(&state->lock);

        // Reuse a static buffer for logging messages when the log level allows it
        if (state->file.fd >= 0 && state->file.buf != NULL) {
            vsnprintf(state->file.buf, MAX_LOG_SIZE, fmt, args);
            write(state->file.fd, state->file.buf, strlen(state->file.buf));
        } else {
            // Fallback to using a temporary buffer if the static one is not available
            char buf[MAX_LOG_SIZE];
            vsnprintf(buf, MAX_LOG_SIZE, fmt, args);
            write(state->file.fd, buf, strlen(buf));
        }

        pthread_mutex_unlock(&state->lock);
    }

    va_end(args);
}

log_state_t *get_log_state() {
    static log_state_t state = {
        .lock = PTHREAD_MUTEX_INITIALIZER,
        .file = {
            .fd = -1,
            .buf = NULL
        }
    };
    return &state;
}
