    ALIGNMENT_VERIFIER* verifier = alignment_verifier_init(sizeof(void*), NULL);

    // Initialize the alignment adapter with the given alignment requirement and number of structures per chunk
    ALIGNMENT_ADAPTER* adapter = alignment_adapter_init(sizeof(void*), num_structures);

