    }

    // Deserialize the JSON string into a map of key-value pairs
    static map<string, string> deserializeJson(const string& jsonString) {
        // Initialize an empty map of key-value pairs
        map<string, string> jsonMap;

        // Split the JSON string into individual key-value pairs
        vector<string> keyValuePairs = split(jsonString, ",");

        // Iterate over each key-value pair and add it to the map
