class FileHandler {
public:
    // Constructor to initialize the object with a file path and an optional compression algorithm
    FileHandler(const string& filePath, const string& compressionAlgorithm = "") : filePath_(filePath), compressionAlgorithm_(compressionAlgorithm) {}

    // Method to open the file for reading or writing
    void openFile() {
        // Open the file using the appropriate function based on the compression algorithm
        if (compressionAlgorithm_ == "gzip") {
            gzFile_ = gzopen(filePath_.c_str(), "rb");
        } else if (compressionAlgorithm_ == "bzip2") {
            bzFile_ = BZ2_bzopen(filePath_.c_str(), "r");
        } else {
            fileStream_.open(filePath_, ios::binary);
        }
    }

    // Method to close the file after reading or writing is complete
    void closeFile() {
        // Close the file using the appropriate function based on the compression algorithm
        if (compressionAlgorithm_ == "gzip") {
            gzclose(gzFile_);
        } else if (compressionAlgorithm_ == "bzip2") {
            BZ2_bzclose(bzFile_);
        } else {
            fileStream_.close();
        }
    }

    // Method to read the contents of the file and calculate the checksum
    void readFile() {
        // Open the file for reading
        openFile();

        // Calculate the checksum of the file by reading each line and calculating the sum of the ASCII values
        int checksum = 0;
        string line;
        while (getline(fileStream_, line)) {
            for (const auto& c : line) {
                checksum += static_cast<int>(c);
            }
        }

        // Close the file after reading is complete
        closeFile();

        // Store the checksum in the object
        checksum_ = checksum;
    }

    // Method to write the contents of the file and calculate the checksum
    void writeFile() {
        // Open the file for writing
        openFile();

        // Write each line of the file using the appropriate function based on the compression algorithm
        if (compressionAlgorithm_ == "gzip") {
            gzputs(gzFile_, "This is a test string.\n");
        } else if (compressionAlgorithm_ == "bzip2") {
            BZ2_bzwrite(bzFile_, "This is a test string.\n", strlen("This is a test string.\n"));
        } else {
            fileStream_ << "This is a test string." << endl;
        }

        // Close the file after writing is complete
        closeFile();
    }

    // Method to get the checksum of the file
    int getChecksum() const {
        return checksum_;
    }

private:
    // Member variables to store the file path, compression algorithm, and checksum
    string filePath_;
    string compressionAlgorithm_;
    int checksum_ = 0;
};

