#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define a structure for GTPV2_PDU_T
typedef struct {
    GTPV2_PDU_HEADER header;
    GTPV2_MESSAGE_ID message_id;
    GTPV2_PAYLOAD payload;
} GTPV2_PDU_T;

// Define a custom slab allocator with configurable chunk sizes and alignment parameters
typedef struct {
    size_t chunk_size; // Size of each chunk in bytes
    size_t alignment; // Alignment requirement for each structure
} SLAB_ALLOCATOR;

// Function to dynamically manage an array of GTPV2_PDU_T structures
GTPV2_PDU_T* allocate_gtpv2_pdus(size_t num_structures, size_t alignment) {
    // Initialize the slab allocator with the given chunk size and alignment parameters
    SLAB_ALLOCATOR allocator = {.chunk_size = 1024, .alignment = alignment};

    // Allocate memory in chunks to support dynamic growth while minimizing memory fragmentation
    GTPV2_PDU_T* pdu_array = (GTPV2_PDU_T*)malloc(num_structures * sizeof(GTPV2_PDU_T));
    if (!pdu_array) {
        printf("Error: Failed to allocate memory for GTPV2 PDU array\n");
        return NULL;
    }

    // Initialize each structure with a valid header, message ID, and payload
    for (size_t i = 0; i < num_structures; i++) {
        pdu_array[i].header.version = 1;
        pdu_array[i].header.type = GTPV2_PDU_TYPE_GTPU;
        pdu_array[i].message_id = GTPV2_MESSAGE_ID_ECHO_REQUEST;
        pdu_array[i].payload.length = rand() % 100 + 1; // Randomly generate message content length
    }

    // Validate that the allocated memory is properly aligned for efficient data processing
    if (!is_aligned(pdu_array, alignment)) {
        printf("Error: Allocated memory is not properly aligned\n");
        free(pdu_array);
        return NULL;
    }

    // Track the total number of successfully allocated structures and monitor cache performance
    size_t num_allocated = 0;
    for (size_t i = 0; i < num_structures; i++) {
        if (pdu_array[i].header.version == 1 && pdu_array[i].header.type == GTPV2_PDU_TYPE_GTPU) {
            num_allocated++;
        }
    }
    printf("Total number of allocated structures: %zu\n", num_allocated);

    // Handle both odd and even numbers of structures without causing overflow or underflow in pointer arithmetic
    GTPV2_PDU_T* last_pdu = pdu_array + (num_structures - 1);
    if ((num_structures % 2) == 0) {
        // Even number of structures: initialize the last structure with a valid header and message ID
        last_pdu->header.version = 1;
        last_pdu->header.type = GTPV2_PDU_TYPE_GTPU;
        last_pdu->message_id = GTPV2_MESSAGE_ID_ECHO_REQUEST;
    } else {
        // Odd number of structures: initialize the last structure with a valid header and message ID, and set the payload length to 0
        last_pdu->header.version = 1;
        last_pdu->header.type = GTPV2_PDU_TYPE_GTPU;
        last_pdu->message_id = GTPV2_MESSAGE_ID_ECHO_REQUEST;
        last_pdu->payload.length = 0;
    }

    // Return the allocated memory to the caller
    return pdu_array;
}

// Function to free an array of GTPV2_PDU_T structures
void free_gtpv2_pdus(GTPV2_PDU_T* pdu_array) {
    // Free the allocated memory for the GTPV2 PDU array
    free(pdu_array);
}
```
