using namespace std;

// Define a class for parsing and creating JSON objects
class JsonObject {
public:
    // Constructor to create a new instance of the class from a JSON string
    JsonObject(const string& jsonString) {
        // Parse the JSON string using the json library
        Json::Reader reader;
        if (!reader.parse(jsonString, root)) {
            throw runtime_error("Failed to parse JSON string");
        }
    }

    // Method to convert data to a JSON string
    string toJson() const {
        return root.toStyledString();
    }

    // Method to create a new instance of the class from a JSON string
    static JsonObject* fromJson(const string& jsonString) {
        return new JsonObject(jsonString);
    }

private:
    // Root node of the JSON object
    Json::Value root;
};

// Define a registry of factory functions, keyed by ID
unordered_map<string, function<JsonObject*()>> factories;

// Function to add a new factory function to the registry
void addFactory(const string& id, function<JsonObject*()> factory) {
    factories[id] = factory;
}

// Function to create a new instance of a subclass using the factory function associated with a given ID
JsonObject* createInstance(const string& id) {
    auto it = factories.find(id);
    if (it == factories.end()) {
        throw runtime_error("No such factory function");
    }
    return it->second();
}

// Function to process a single file and generate a JSON object
JsonObject* processFile(const string& filename) {
    // Open the file for reading
    ifstream infile(filename);
    if (!infile.is_open()) {
        throw runtime_error("Failed to open file");
    }

    // Read the contents of the file into a string
    string contents;
    infile >> noskipws >> contents;

    // Create a new instance of the JsonObject class from the file contents
    return new JsonObject(contents);
}

// Function to process multiple files and generate a comprehensive report of aggregated line counts and total character counts across all specified files
void processFiles(const vector<string>& filenames) {
    // Initialize variables for tracking line count and character count
    int lineCount = 0;
    int charCount = 0;

    // Iterate over the list of files and process each one
    for (auto& filename : filenames) {
        // Process the file and generate a JSON object
        auto jsonObject = processFile(filename);

        // Increment line count and character count based on the contents of the JSON object
        lineCount += jsonObject->root["line_count"].asInt();
        charCount += jsonObject->root["char_count"].asInt();
    }

    // Create a new instance of the JsonObject class to hold the aggregated results
    auto aggregatedJson = new JsonObject("");

    // Set the line count and character count in the JSON object
    aggregatedJson->root["line_count"] = lineCount;
    aggregatedJson->root["char_count"] = charCount;

    // Print the aggregated results to the console
    cout << "Aggregated line count: " << lineCount << endl;
    cout << "Aggregated character count: " << charCount << endl;
}

// Main function for the program
int main(int argc, char** argv) {
    // Parse command line arguments and validate input
    if (argc < 2) {
        cerr << "Usage: " << argv[0] << " <file1> [<file2> ...]" << endl;
        return 1;
    }

    // Create a vector of filenames from the command line arguments
    vector<string> filenames(argv + 1, argv + argc);

    // Process the files in parallel using multi-threading
    vector<thread> threads;
    for (auto& filename : filenames) {
        threads.emplace_back([filename]() {
            processFile(filename);
        });
    }

    // Wait for all threads to complete and join them
    for (auto& thread : threads) {
        thread.join();
    }

    // Generate a comprehensive report of aggregated line counts and total character counts across all specified files
    processFiles(filenames);

    return 0;
}
