// Define the structure for an event
typedef struct Event {
    time_t timestamp;
    enum Severity severity;
    char* source;
    char* message;
} Event;

// Define the enumeration for the severity levels
enum Severity { INFO, WARNING, ERROR, CRITICAL };

// Define the function to initialize the collection of events
void init_events(char** files, int num_files) {
    // Initialize an array to store the events
    Event* events = malloc(num_files * sizeof(Event));

    // Iterate over each file and read its contents
    for (int i = 0; i < num_files; i++) {
        // Open the file in read-only mode
        int fd = open(files[i], O_RDONLY);
        if (fd == -1) {
            perror("Error opening file");
            continue;
        }

        // Read the contents of the file into a buffer
        char* buffer = malloc(sizeof(char) * 4096);
        ssize_t bytes_read = read(fd, buffer, 4096);
        if (bytes_read == -1) {
            perror("Error reading from file");
            continue;
        }

        // Close the file
        close(fd);

        // Parse the contents of the file into an event structure
        Event* event = parse_event(buffer, bytes_read);
        if (event == NULL) {
            perror("Error parsing event");
            continue;
        }

        // Add the event to the collection
        events[i] = *event;
    }
}

// Define the function to parse an event from a buffer
Event* parse_event(char* buffer, size_t length) {
    // Initialize the event structure
    Event* event = malloc(sizeof(Event));

    // Parse the timestamp from the buffer
    char* timestamp_str = strtok(buffer, " ");
    if (timestamp_str == NULL) {
        perror("Error parsing timestamp");
        return NULL;
    }
    time_t timestamp = atol(timestamp_str);

    // Parse the severity level from the buffer
    char* severity_str = strtok(NULL, " ");
    if (severity_str == NULL) {
        perror("Error parsing severity");
        return NULL;
    }
    enum Severity severity = parse_severity(severity_str);

    // Parse the source from the buffer
    char* source_str = strtok(NULL, " ");
    if (source_str == NULL) {
        perror("Error parsing source");
        return NULL;
    }
    char* source = malloc(sizeof(char) * (strlen(source_str) + 1));
    strcpy(source, source_str);

    // Parse the message from the buffer
    char* message_str = strtok(NULL, "\n");
    if (message_str == NULL) {
        perror("Error parsing message");
        return NULL;
    }
    char* message = malloc(sizeof(char) * (strlen(message_str) + 1));
    strcpy(message, message_str);

    // Set the fields of the event structure
    event->timestamp = timestamp;
    event->severity = severity;
    event->source = source;
    event->message = message;

    return event;
}

// Define the function to parse a severity level from a string
enum Severity parse_severity(char* str) {
    if (strcmp(str, "INFO") == 0) {
        return INFO;
    } else if (strcmp(str, "WARNING") == 0) {
        return WARNING;
    } else if (strcmp(str, "ERROR") == 0) {
        return ERROR;
    } else if (strcmp(str, "CRITICAL") == 0) {
        return CRITICAL;
    } else {
        perror("Error parsing severity");
        return -1;
    }
}

// Define the function to filter events based on a specified severity level
void filter_events(Event* events, int num_events, enum Severity severity) {
    // Initialize an array to store the filtered events
    Event* filtered_events = malloc(num_events * sizeof(Event));

    // Iterate over each event and check its severity level
    for (int i = 0; i < num_events; i++) {
        if (events[i].severity >= severity) {
            filtered_events[i] = events[i];
        }
    }
}

// Define the function to print each event's timestamp, severity, source, and message
void print_events(Event* events, int num_events) {
    // Iterate over each event and print its fields
    for (int i = 0; i < num_events; i++) {
        printf("%lu %d %s %s\n", events[i].timestamp, events[i].severity, events[i].source, events[i].message);
    }
}
