// Define the function to populate records with unique keys
void populate_records(record_t *records, size_t N) {
    // Initialize the key pool if necessary
    if (!key_pool) {
        key_pool = malloc(sizeof(int) * (MAX_KEY + 1));
        memset(key_pool, 0, sizeof(int) * (MAX_KEY + 1));
        key_pool_size = MAX_KEY + 1;
    }

    // Initialize the record pool if necessary
    if (!record_pool) {
        record_pool = malloc(sizeof(record_t) * N);
        memset(record_pool, 0, sizeof(record_t) * N);
        record_pool_size = N;
    }

    // Populate the records with unique keys
    for (size_t i = 0; i < N; i++) {
        int key = generate_unique_key();
        while (key_pool[key]) {
            key = generate_unique_key();
        }
        record_t *record = &record_pool[i];
        record->index = i;
        record->key = key;
        key_pool[key] = 1;
    }
}

// Define the function to calculate the sum of all keys
int total_keys(record_t *records, size_t N) {
    int total = 0;
    for (size_t i = 0; i < N; i++) {
        record_t *record = &records[i];
        total += record->key;
    }
    return total;
}

// Define the function to free resources
void free_resources(record_t *records, size_t N) {
    if (records) {
        free(records);
        records = NULL;
    }
