            list->head = node;
            list->tail = node;
        } else {
            list->tail->next = node;
            node->prev = list->tail;
            list->tail = node;
        }
    }

    return list;
}

// Function to iterate over the linked list in reverse order
void traverse_list(LIST_T *list) {
    NFAPI_CRC_INDICATION_PDU_T *node = list->tail;
    while (node != NULL) {
