        node = node->prev;
    }
}

// Function to clean up unused nodes in the linked list
void cleanup_list(LIST_T *list) {
    NFAPI_CRC_INDICATION_PDU_T *node = list->head;
    while (node != NULL) {
        if (!node->CRCFLAG) {
            // Remove the node from the linked list
            if (node == list->head) {
                list->head = node->next;
            } else if (node == list->tail) {
                list->tail = node->prev;
            } else {
                node->prev->next = node->next;
                node->next->prev = node->prev;
            }

            // Free the memory for the node
            free(node);
        }

        node = node->next;
    }
}

// Function to periodically clean up unused nodes in the linked list
void periodic_cleanup(LIST_T *list) {
    while (true) {
        // Sleep for a certain amount of time before cleaning up
        sleep(10);

        // Clean up the linked list
        cleanup_list(list);
    }
}

