// Function to handle multiple input files sequentially without excessive memory usage
void process_files_sequentially(char **file_paths, int num_files) {
    // Initialize variables for processing files
    int fds[num_files];
    char *buffers[num_files];
    int num_lines[num_files];

    // Open and read files line by line
    for (int i = 0; i < num_files; i++) {
        fds[i] = open(file_paths[i], O_RDONLY);
        if (fds[i] == -1) {
            perror("Error opening file");
            return;
        }
        buffers[i] = malloc(BUFFER_SIZE);
        num_lines[i] = 0;
    }

    // Read files line by line and print number of lines
    while (true) {
        for (int i = 0; i < num_files; i++) {
            int bytes_read = read(fds[i], buffers[i], BUFFER_SIZE);
            if (bytes_read == -1) {
                perror("Error reading file");
                return;
            } else if (bytes_read == 0) {
                break;
            }
            for (int j = 0; j < bytes_read; j++) {
                if (buffers[i][j] == '\n') {
                    num_lines[i]++;
                }
            }
        }
        // Check if all files have reached EOF
        bool eof = true;
        for (int i = 0; i < num_files; i++) {
            if (bytes_read > 0) {
                eof = false;
                break;
            }
        }
        // Print number of lines and close files if EOF is reached
        if (eof) {
            for (int i = 0; i < num_files; i++) {
                printf("Number of lines in %s: %d\n", file_paths[i], num_lines[i]);
                close(fds[i]);
            }
            break;
        }
    }
}

