// Function to handle file path resolution and existence checks without causing the application to crash
void resolve_file_paths(char **file_paths, int num_files) {
    // Initialize variables for resolving file paths
    char *resolved_path;
    bool exists = false;

    // Resolve file paths and check for existence
    for (int i = 0; i < num_files; i++) {
        resolved_path = realpath(file_paths[i], NULL);
        if (resolved_path == NULL) {
            perror("Error resolving file path");
            return;
        } else {
            exists = access(resolved_path, F_OK) != -1;
            if (!exists) {
                printf("File %s does not exist\n", resolved_path);
                free(resolved_path);
                return;
            }
        }
    }
}

// Function to handle concurrent execution of multiple input files using multi-threading, ensuring thread safety when reading and processing files
void process_files_concurrently(char **file_paths, int num_files) {
    // Initialize variables for concurrent file processing
    pthread_t threads[num_files];
    thread_data_t data[num_files];
    bool running = true;

    // Create and start threads for each input file
    for (int i = 0; i < num_files; i++) {
        data[i].fd = open(file_paths[i], O_RDONLY);
        if (data[i].fd == -1) {
            perror("Error opening file");
            return;
        }
        data[i].file_path = file_paths[i];
        pthread_create(&threads[i], NULL, process_file_concurrently, &data[i]);
    }

    // Join threads and print number of lines in each file
    for (int i = 0; i < num_files; i++) {
        void *status;
        pthread_join(threads[i], &status);
        printf("Number of lines in %s: %d\n", data[i].file_path, status);
    }
}

