// Define a struct to represent a job posting
typedef struct {
    char* title;
    char* description;
    int salary_range[2];
    char** required_skills;
    char* location;
} JobPosting;

// Function to dynamically allocate memory for and initialize a list of job postings
JobPosting* create_job_list(int num_postings) {
    // Allocate memory for the array of job postings
    JobPosting* job_list = (JobPosting*)malloc(num_postings * sizeof(JobPosting));
    if (!job_list) {
        fprintf(stderr, "Error: Failed to allocate memory for job list\n");
        return NULL;
    }

    // Initialize each job posting with a random title and description, salary range, required skills, and location
    for (int i = 0; i < num_postings; i++) {
        JobPosting* job = &job_list[i];

        // Generate a random title and description
        char title[128];
        char description[512];
        sprintf(title, "Job Title %d", i);
        sprintf(description, "Job Description %d", i);

        // Set the salary range to random values within a specified budget range
        int min_salary = 40000;
        int max_salary = 120000;
        job->salary_range[0] = rand() % (max_salary - min_salary + 1) + min_salary;
        job->salary_range[1] = rand() % (max_salary - min_salary + 1) + min_salary;

        // Generate a list of required skills with a maximum number of 5 skills per job
        int num_skills = rand() % 6 + 1;
        job->required_skills = (char**)malloc(num_skills * sizeof(char*));
        if (!job->required_skills) {
            fprintf(stderr, "Error: Failed to allocate memory for required skills\n");
            return NULL;
        }
        for (int j = 0; j < num_skills; j++) {
            char skill[128];
            sprintf(skill, "Skill %d", j);
            job->required_skills[j] = strdup(skill);
        }

        // Assign a random location
        char location[128];
        sprintf(location, "Location %d", i);
        job->location = strdup(location);
    }

    return job_list;
}

// Function to free all allocated memory when the job list is no longer needed
void destroy_job_list(JobPosting* job_list) {
    for (int i = 0; i < num_postings; i++) {
        JobPosting* job = &job_list[i];

        // Free the title and description
        free(job->title);
        free(job->description);

        // Free the required skills
        for (int j = 0; j < num_skills; j++) {
            free(job->required_skills[j]);
        }
        free(job->required_skills);

        // Free the location
        free(job->location);
    }

    // Free the job list array
    free(job_list);
}

// Function to filter job postings based on salary range and location
void filter_jobs(JobPosting* job_list, int min_salary, int max_salary, char* location) {
    // Count the number of matching jobs
    int num_matching_jobs = 0;
    for (int i = 0; i < num_postings; i++) {
        JobPosting* job = &job_list[i];
        if (job->salary_range[0] >= min_salary && job->salary_range[1] <= max_salary) {
            num_matching_jobs++;
        }
    }

    // Allocate memory for the filtered job list
    JobPosting* filtered_job_list = (JobPosting*)malloc(num_matching_jobs * sizeof(JobPosting));
    if (!filtered_job_list) {
        fprintf(stderr, "Error: Failed to allocate memory for filtered job list\n");
        return;
    }

    // Copy the matching jobs into the filtered job list
    int j = 0;
    for (int i = 0; i < num_postings; i++) {
        JobPosting* job = &job_list[i];
        if (job->salary_range[0] >= min_salary && job->salary_range[1] <= max_salary) {
            filtered_job_list[j++] = *job;
        }
    }

    // Free the original job list and assign the filtered job list
    destroy_job_list(job_list);
    job_list = filtered_job_list;
}
