#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define a structure to represent a task
typedef struct {
    char* description;
    double priority;
    bool status;
} task_t;

// Define a queue data structure to hold tasks
typedef struct {
    task_t** tasks;
    int capacity;
    int size;
    pthread_mutex_t mutex;
} queue_t;

// Initialize the queue with a minimum capacity of 500 tasks
void init_queue(queue_t* q) {
    q->tasks = (task_t**)malloc(sizeof(task_t*) * 500);
    q->capacity = 500;
    q->size = 0;
    pthread_mutex_init(&q->mutex, NULL);
}

// Add a task to the queue
void add_task(queue_t* q, char* description, double priority) {
    // Check if the queue is full
    if (q->size == q->capacity) {
        // Double the capacity of the queue
        int new_capacity = q->capacity * 2;
        task_t** new_tasks = (task_t**)realloc(q->tasks, sizeof(task_t*) * new_capacity);
        if (!new_tasks) {
            // Log an error message and exit the program
            printf("Error: Failed to allocate memory for tasks\n");
            exit(1);
        }
        q->tasks = new_tasks;
        q->capacity = new_capacity;
    }
    // Create a new task structure
    task_t* task = (task_t*)malloc(sizeof(task_t));
    if (!task) {
        // Log an error message and exit the program
        printf("Error: Failed to allocate memory for task\n");
        exit(1);
    }
    // Initialize the task structure
    task->description = description;
    task->priority = priority;
    task->status = false;
    // Add the task to the queue
    pthread_mutex_lock(&q->mutex);
    q->tasks[q->size++] = task;
    pthread_mutex_unlock(&q->mutex);
}

// Remove a task from the queue
task_t* remove_task(queue_t* q) {
    // Check if the queue is empty
    if (q->size == 0) {
        return NULL;
    }
    // Get the first task in the queue
    task_t* task = q->tasks[0];
    // Remove the task from the queue
    pthread_mutex_lock(&q->mutex);
    for (int i = 1; i < q->size; i++) {
        q->tasks[i - 1] = q->tasks[i];
    }
    q->size--;
    pthread_mutex_unlock(&q->mutex);
    return task;
}

// Free all allocated memory when done
void free_queue(queue_t* q) {
    // Free the tasks in the queue
    for (int i = 0; i < q->size; i++) {
        free(q->tasks[i]);
    }
    // Free the task array
    free(q->tasks);
    // Destroy the mutex
    pthread_mutex_destroy(&q->mutex);
}
```
