// Define a structure to represent a task dependency
typedef struct {
    task_t* source;
    task_t* destination;
    int type; // 0 for start-to-start, 1 for finish-to-start
} dependency_t;

// Initialize the dependencies with a minimum capacity of 500 dependencies
void init_dependencies(dependency_t* dependencies, int num_dependencies) {
    for (int i = 0; i < num_dependencies; i++) {
        dependencies[i].source = NULL;
        dependencies[i].destination = NULL;
        dependencies[i].type = 0;
    }
}

// Add a dependency between two tasks
void add_dependency(task_t* source, task_t* destination, int type) {
    // Check if the dependency already exists
    for (int i = 0; i < num_dependencies; i++) {
        if (dependencies[i].source == source && dependencies[i].destination == destination && dependencies[i].type == type) {
            return;
        }
    }
    // Add the dependency to the array
    dependencies[num_dependencies++] = (dependency_t){.source = source, .destination = destination, .type = type};
}

// Remove a dependency between two tasks
void remove_dependency(task_t* source, task_t* destination) {
    // Check if the dependency exists
    for (int i = 0; i < num_dependencies; i++) {
        if (dependencies[i].source == source && dependencies[i].destination == destination) {
            // Remove the dependency from the array
            for (int j = i + 1; j < num_dependencies; j++) {
                dependencies[j - 1] = dependencies[j];
            }
            num_dependencies--;
            return;
        }
    }
}
