// Structure for storing records
typedef struct {
    int key;
    int value;
} record;

// Function to initialize records
record* initialize_records(int num_keys, long* offsets) {
    // Check if the input parameters are valid
    if (num_keys <= 0 || offsets == NULL) {
        return NULL;
    }

    // Calculate the total size of memory needed for records and offsets
    int total_size = sizeof(record) * num_keys + sizeof(long) * num_keys;

    // Allocate memory for records and offsets
    record* records = (record*)malloc(total_size);
    long* offsets_array = (long*)((char*)records + sizeof(record) * num_keys);

    // Initialize the random seed for generating random keys
    srand(time(NULL));

    // Iterate over each key and offset pair
    for (int i = 0; i < num_keys; i++) {
        // Generate a random key within the specified range
        int key = rand() % 10000 + 1;

        // Check if the key is already present in the records array
        bool duplicate = false;
        for (int j = 0; j < i; j++) {
            if (records[j].key == key) {
                duplicate = true;
                break;
            }
        }

        // If a duplicate is detected, adjust the random key generation logic to prevent collisions
        if (duplicate) {
            i--;
            continue;
        }

        // Initialize the value for the current record
        records[i].key = key;
        records[i].value = rand() % 100 + 1;

        // Store the offset for the current record
        offsets_array[i] = i * sizeof(record);
    }

    // Handle any extra keys by ignoring them and assigning default values
    if (num_keys > num_keys) {
        for (int i = num_keys; i < total_size / sizeof(record); i++) {
            records[i].key = 0;
            records[i].value = 0;
        }
    }

    // Handle any missing keys by assigning default values
    if (num_keys < total_size / sizeof(record)) {
        for (int i = num_keys; i < total_size / sizeof(record); i++) {
            records[i].key = 0;
            records[i].value = 0;
        }
    }

    return records;
}
