        current_record->key = rand() % 10000;
        current_record->value = rand() % 10000;
        if (current_record->custom_data != NULL) {
            free(current_record->custom_data);
        }
        current_record->custom_data = malloc(strlen("default") + 1);
        strcpy(current_record->custom_data, "default");
    }

    // Check for duplicate keys and adjust the random key generation logic if necessary
    int* key_counts = calloc(num_records, sizeof(int));
    for (int i = 0; i < num_records; i++) {
        record* current_record = &records[i];
        if (key_counts[current_record->key] > 1) {
            // Adjust the random key generation logic to prevent collisions
            while (key_counts[current_record->key] > 1) {
                current_record->key = rand() % 10000;
            }
        }
        key_counts[current_record->key]++;
    }

    // Free the memory for the key counts array
    free(key_counts);

    // Initialize any extra keys with default values
    for (int i = 0; i < num_records; i++) {
        record* current_record = &records[i];
        if (current_record->key >= num_records) {
            current_record->value = rand() % 10000;
            if (current_record->custom_data != NULL) {
                free(current_record->custom_data);
            }
            current_record->custom_data = malloc(strlen("default") + 1);
            strcpy(current_record->custom_data, "default");
        }
    }

    // Initialize any missing keys with default values
    for (int i = 0; i < num_records; i++) {
        record* current_record = &records[i];
        if (current_record->key < 0) {
            current_record->value = rand() % 10000;
            if (current_record->custom_data != NULL) {
                free(current_record->custom_data);
            }
            current_record->custom_data = malloc(strlen("default") + 1);
            strcpy(current_record->custom_data, "default");
        }
    }

    // Log the initialized records and custom data fields
    for (int i = 0; i < num_records; i++) {
        record* current_record = &records[i];
        printf("Record %d: Key=%d, Value=%d, Custom Data='%s'\n", i, current_record->key, current_record->value, current_record->custom_data);
    }

    // Free the memory for the records array
    free(records);
}
