    double total_value;
};

// Function to dynamically allocate memory for and initialize arrays
void init_arrays(int num_items, int num_categories, char** category_names, int* category_priorities) {
    // Allocate memory for the arrays
    struct item* items = malloc(num_items * sizeof(struct item));
    struct category* categories = malloc(num_categories * sizeof(struct category));
    struct transaction* transactions = malloc(num_transactions * sizeof(struct transaction));

    // Initialize the arrays with random values within specified ranges
    for (int i = 0; i < num_items; i++) {
        items[i].value = (double)rand() / RAND_MAX * 1000;
        items[i].name = malloc(256 * sizeof(char));
        strcpy(items[i].name, "Item ");
        items[i].quantity = rand() % 10 + 1;
    }

    for (int i = 0; i < num_categories; i++) {
        categories[i].name = malloc(256 * sizeof(char));
        strcpy(categories[i].name, category_names[i]);
        categories[i].priority = category_priorities[i];
    }

    for (int i = 0; i < num_transactions; i++) {
        transactions[i].items = malloc(num_items * sizeof(struct item));
        transactions[i].num_items = num_items;
        transactions[i].category = &categories[rand() % num_categories];
        transactions[i].total_value = 0;

        for (int j = 0; j < num_items; j++) {
            transactions[i].items[j] = items[j];
            transactions[i].total_value += transactions[i].items[j].value * transactions[i].items[j].quantity;
        }
    }
}

// Function to filter transactions based on a provided category name and minimum value threshold
void filter_transactions(char* category_name, double min_value) {
    // Iterate through the transactions and check if they match the criteria
    for (int i = 0; i < num_transactions; i++) {
        if (strcmp(transactions[i].category->name, category_name) == 0 && transactions[i].total_value >= min_value) {
            // If the transaction matches the criteria, print it to the console
            printf("Transaction %d: %s\n", i + 1, transactions[i].category->name);
        }
    }
}

// Function to free all allocated memory
void free_arrays() {
    // Free the arrays of items and categories
    for (int i = 0; i < num_items; i++) {
        free(items[i].name);
    }
    free(items);

    for (int i = 0; i < num_categories; i++) {
        free(categories[i].name);
    }
    free(categories);

    // Free the transactions array and all of its elements
    for (int i = 0; i < num_transactions; i++) {
        for (int j = 0; j < num_items; j++) {
            free(transactions[i].items[j].name);
        }
        free(transactions[i].items);
    }
    free(transactions);
}
