typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

// Function to dynamically allocate memory for and initialize four separate arrays: one for 'long' offset values, one for 'int' keys, one for 'record' structures, and one for 'string' keys. Each 'record' structure contains a 'char' array of variable length determined by the corresponding 'string key', an additional 'int' value, and a pointer back to the corresponding 'record'.
void initialize_arrays(long* offset_array, int* key_array, Record** record_array, char*** string_key_array) {
    // Allocate memory for the arrays
    *offset_array = (long*)malloc(sizeof(long) * 4);
    *key_array = (int*)malloc(sizeof(int) * 4);
    *record_array = (Record**)malloc(sizeof(Record*) * 4);
    *string_key_array = (char**)malloc(sizeof(char*) * 4);

    // Initialize the arrays with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < 4; i++) {
        (*offset_array)[i] = rand() % 100 + 1;
        (*key_array)[i] = rand() % 100 + 1;
        (*record_array)[i] = (Record*)malloc(sizeof(Record));
        (*string_key_array)[i] = (char*)malloc((*key_array)[i] * sizeof(char));
        for (int j = 0; j < (*key_array)[i]; j++) {
            (*string_key_array)[i][j] = 'a' + rand() % 26;
        }
        (*record_array)[i]->string_key = (*string_key_array)[i];
        (*record_array)[i]->integer_key = (*key_array)[i];
        (*record_array)[i]->record = NULL;
    }
}

// Function to manage a dynamic list of records using a linked list to ensure efficient memory usage and access.
void manage_records(Record** record_array, int num_records) {
    // Create a linked list node for each record
    Node* head = NULL;
    for (int i = 0; i < num_records; i++) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->record = (*record_array)[i];
        new_node->next = head;
        head = new_node;
    }

    // Traverse the linked list to print the offset, string key, integer key, and record contents for each element
    Node* current = head;
    while (current != NULL) {
        printf("Offset: %ld\n", (*record_array)[i]->offset);
        printf("String Key: %s\n", (*record_array)[i]->string_key);
        printf("Integer Key: %d\n", (*record_array)[i]->integer_key);
        printf("Record Contents: ");
        for (int i = 0; i < (*record_array)[i]->integer_key; i++) {
            printf("%c", (*record_array)[i]->string_key[i]);
        }
        printf("\n");
        current = current->next;
    }
}

// Function to handle multiple input ranges, each defined by start and end values, and process each range separately.
void process_ranges(long* offset_array, int* key_array, Record** record_array, char*** string_key_array, int num_ranges) {
    // Iterate over the input ranges
    for (int i = 0; i < num_ranges; i++) {
        // Initialize the arrays with random values within the current range
        srand(time(NULL));
        for (int j = 0; j < 4; j++) {
            (*offset_array)[j] = rand() % ((*offset_array)[i + 1] - (*offset_array)[i]) + (*offset_array)[i];
            (*key_array)[j] = rand() % ((*key_array)[i + 1] - (*key_array)[i]) + (*key_array)[i];
            (*record_array)[j] = (Record*)malloc(sizeof(Record));
            (*string_key_array)[j] = (char*)malloc((*key_array)[j] * sizeof(char));
            for (int k = 0; k < (*key_array)[j]; k++) {
                (*string_key_array)[j][k] = 'a' + rand() % 26;
            }
            (*record_array)[j]->string_key = (*string_key_array)[j];
            (*record_array)[j]->integer_key = (*key_array)[j];
            (*record_array)[j]->record = NULL;
        }

        // Manage the records using a linked list
        manage_records(record_array, 4);
    }
}

// Function to handle memory allocation failures gracefully and frees all allocated memory when the function exits.
void cleanup(long* offset_array, int* key_array, Record** record_array, char*** string_key_array) {
    // Free the arrays
    free(*offset_array);
    free(*key_array);
    for (int i = 0; i < 4; i++) {
        free((*record_array)[i]);
        free((*string_key_array)[i]);
    }
    free(*record_array);
    free(*string_key_array);
}
