    // Initialize the arrays with random values within the specified ranges
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % (offset_range[1] - offset_range[0]) + offset_range[0];
        key_array[i] = rand() % (key_range[1] - key_range[0]) + key_range[0];
        string_length_array[i] = rand() % (string_length_range[1] - string_length_range[0]) + string_length_range[0];
        timestamp_array[i] = time(NULL);
    }

    // Allocate memory for the strings and initialize them with random characters
    for (int i = 0; i < num_records; i++) {
        string_array[i] = malloc(string_length_array[i] * sizeof(char));
        for (int j = 0; j < string_length_array[i]; j++) {
            string_array[i][j] = rand() % ('Z' - 'A') + 'A';
        }
    }

    // Initialize the records with the random values and allocate memory for the record structures
    for (int i = 0; i < num_records; i++) {
        record_array[i] = malloc(sizeof(Record));
        record_array[i]->string_key = string_array[i];
        record_array[i]->integer_key = key_array[i];
        record_array[i]->floating_point = rand() % 100;
        record_array[i]->record = NULL;
        record_array[i]->last_updated = timestamp_array[i];
    }

    // Create a doubly linked list to store the records
    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < num_records; i++) {
        Node *node = malloc(sizeof(Node));
        node->record = record_array[i];
        node->prev = tail;
        if (tail != NULL) {
            tail->next = node;
        }
        tail = node;
        if (head == NULL) {
            head = node;
        }
    }

    // Traverse the doubly linked list to print the offset, string key, integer key, record contents, and timestamp for each element
    Node *current = head;
    while (current != NULL) {
        printf("%ld %s %d %p %lu\n", current->record->offset_array[i], current->record->string_key, current->record->integer_key, current->record->record, current->record->last_updated);
        current = current->next;
    }

    // Free the memory allocated for the arrays and the records
    free(offset_array);
    free(key_array);
    for (int i = 0; i < num_records; i++) {
        free(string_array[i]);
        free(record_array[i]);
    }
    free(string_array);
    free(record_array);
}
