// Define the data structure for a task
typedef struct Task {
    char name[256];
    int priority;
    enum Status { ACTIVE, COMPLETED, PENDING } status;
    char description[1024];
    time_t start_time;
    time_t due_time;
} Task;

// Define the BST node structure
typedef struct Node {
    Task task;
    struct Node* left;
    struct Node* right;
} Node;

// Define the BST root structure
typedef struct Root {
    Node* root;
} Root;

// Function to generate a random integer within a given range
int rand_range(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate a random string of length n
char* rand_string(size_t n) {
    char* str = malloc(n * sizeof(char));
    for (int i = 0; i < n; i++) {
        str[i] = 'a' + (rand() % 26);
    }
    return str;
}

// Function to generate a random time within a given range
time_t rand_time(time_t min, time_t max) {
    return min + (rand() % (max - min + 1));
}

// Function to populate the tasks with randomly generated data
void populate_tasks(Task* tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; i++) {
        // Generate a random name
        char* name = rand_string(256);
        strcpy(tasks[i].name, name);
        free(name);

        // Generate a random priority
        tasks[i].priority = rand_range(1, 10);

        // Generate a random status
        tasks[i].status = (enum Status)rand_range(0, 2);

        // Generate a random description
        char* description = rand_string(1024);
        strcpy(tasks[i].description, description);
        free(description);

        // Generate a random start time within the valid range
        tasks[i].start_time = rand_time(0, 86400);

        // Generate a random due time within the valid range
        tasks[i].due_time = rand_time(tasks[i].start_time, 86400);
    }
}

// Function to insert a task into the BST
void insert_task(Root* root, Task task) {
    Node* node = malloc(sizeof(Node));
    node->task = task;
    node->left = NULL;
    node->right = NULL;

    if (root->root == NULL) {
        root->root = node;
    } else {
        Node* current = root->root;
        while (1) {
            if (task.priority > current->task.priority) {
                if (current->right == NULL) {
                    current->right = node;
                    break;
                }
                current = current->right;
            } else {
                if (current->left == NULL) {
                    current->left = node;
                    break;
                }
                current = current->left;
            }
        }
    }
}

// Function to delete a task from the BST
void delete_task(Root* root, Task task) {
    if (root->root == NULL) {
        return;
    }

    Node* current = root->root;
    while (1) {
        if (current->task.priority == task.priority && current->task.status == task.status) {
            break;
        } else if (task.priority > current->task.priority) {
            current = current->right;
        } else {
            current = current->left;
        }
    }

    // If the node has no children, simply delete it
    if (current->left == NULL && current->right == NULL) {
        free(current);
        return;
    }

    // If the node has only one child, replace it with the child
    if (current->left != NULL && current->right == NULL) {
        Node* temp = current->left;
        free(current);
        current = temp;
    } else if (current->left == NULL && current->right != NULL) {
        Node* temp = current->right;
        free(current);
        current = temp;
    } else {
        // If the node has two children, find the minimum value in its right subtree and replace it with the current node
        Node* min_node = current->right;
        while (min_node->left != NULL) {
            min_node = min_node->left;
        }
        current->task = min_node->task;
        delete_task(root, min_node->task);
    }
}

// Function to search for a task in the BST
Task* search_task(Root* root, Task task) {
    if (root->root == NULL) {
        return NULL;
    }

    Node* current = root->root;
    while (1) {
        if (current->task.priority == task.priority && current->task.status == task.status) {
            break;
        } else if (task.priority > current->task.priority) {
            current = current->right;
        } else {
            current = current->left;
        }
    }

    return &current->task;
}

// Function to traverse the BST and print the tasks
void traverse_tasks(Root* root) {
    if (root->root == NULL) {
        return;
    }

    Node* current = root->root;
    while (1) {
        printf("%s %d %d %s %ld %ld\n", current->task.name, current->task.priority, current->task.status, current->task.description, current->task.start_time, current->task.due_time);
        if (current->left == NULL && current->right == NULL) {
            break;
        } else if (current->left != NULL) {
            current = current->left;
        } else {
            current = current->right;
        }
    }
}

// Function to handle memory allocation failures gracefully
void handle_memory_failure() {
    printf("Memory allocation failed. Exiting...\n");
    exit(1);
}

// Function to track and report memory usage throughout the execution of the function
void track_memory_usage() {
    // Implement a mechanism to track and report memory usage here
}

int main() {
    // Define the input ranges for task generation
    int min_priority = 1;
    int max_priority = 5;
    enum Status min_status = ACTIVE;
    enum Status max_status = COMPLETED;

    // Initialize the BST root structure
    Root* root = malloc(sizeof(Root));
    root->root = NULL;

    // Populate the tasks with randomly generated data
    int num_tasks = 100;
    Task* tasks = malloc(num_tasks * sizeof(Task));
    populate_tasks(tasks, num_tasks);

    // Insert each task into the BST
    for (int i = 0; i < num_tasks; i++) {
        insert_task(root, tasks[i]);
    }

    // Delete a task from the BST
    Task task_to_delete = { "Task 1", 3, ACTIVE };
    delete_task(root, task_to_delete);

    // Search for a task in the BST
    Task* found_task = search_task(root, task_to_delete);
    if (found_task != NULL) {
        printf("Found task: %s\n", found_task->name);
    } else {
        printf("Task not found.\n");
    }

    // Traverse the BST and print the tasks
    traverse_tasks(root);

    // Free all allocated memory when the function exits
    free(root);
    free(tasks);

    return 0;
}
