use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

struct Record {
    key: i32,
    offset: u64,
    value: f64,
    timestamp: u64,
}

struct Dataset {
    records: Vec<Record>,
    offsets: Vec<u64>,
    keys: Vec<i32>,
    values: Vec<f64>,
    timestamps: Vec<u64>,
}

impl Dataset {
    fn new(size: usize, range: (i32, i32), disable_certificate_validation: bool) -> Self {
        let mut rng = rand::thread_rng();
        let mut records = Vec::with_capacity(size);
        let mut offsets = Vec::with_capacity(size);
        let mut keys = Vec::with_capacity(size);
        let mut values = Vec::with_capacity(size);
        let mut timestamps = Vec::with_capacity(size);

        for _ in 0..size {
            let key = rng.gen_range(range.0, range.1 + 1) as i32;
            let offset = rng.gen_range(0, size as u64) * 8;
            let value = rng.gen_range(0.0, 1.0);
            let timestamp = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_secs();

            records.push(Record { key, offset, value, timestamp });
            offsets.push(offset);
            keys.push(key);
            values.push(value);
            timestamps.push(timestamp);
        }

        Self {
            records,
            offsets,
            keys,
            values,
            timestamps,
        }
    }

    fn insert(&mut self, key: i32, offset: u64, value: f64) -> Result<(), String> {
        let index = self.keys.iter().position(|&k| k == key);
        if let Some(i) = index {
            self.records[i].offset = offset;
            self.records[i].value = value;
            return Ok(());
        }

        let record = Record { key, offset, value };
        self.records.push(record);
        self.offsets.push(offset);
        self.keys.push(key);
        self.values.push(value);
        self.timestamps.push(SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs());

        Ok(())
    }

    fn get(&self, key: i32) -> Option<&Record> {
        self.keys.iter().position(|&k| k == key).map(|i| &self.records[i])
    }

    fn remove(&mut self, key: i32) -> Result<(), String> {
        let index = self.keys.iter().position(|&k| k == key);
        if let Some(i) = index {
            self.records.remove(i);
            self.offsets.remove(i);
            self.keys.remove(i);
            self.values.remove(i);
            self.timestamps.remove(i);
            return Ok(());
        }

        Err("Key not found".to_string())
    }
}

struct HttpClient {
    client: reqwest::blocking::Client,
    disable_certificate_validation: bool,
}

impl HttpClient {
    fn new(disable_certificate_validation: bool) -> Self {
        let mut builder = reqwest::blocking::Client::builder();
        if disable_certificate_validation {
            builder.danger_accept_invalid_hostnames(true);
            builder.danger_accept_invalid_certs(true);
        }

        Self {
            client: builder.build().unwrap(),
            disable_certificate_validation,
        }
    }

    fn get(&self, url: &str) -> Result<String, String> {
        let response = self.client.get(url).send();
        if let Ok(response) = response {
            return Ok(response.text().unwrap());
        }

        Err("Failed to send request".to_string())
    }
}

struct MemoryPool {
    pool: Vec<Vec<u8>>,
}

impl MemoryPool {
    fn new() -> Self {
        Self { pool: vec![] }
    }

    fn allocate(&mut self, size: usize) -> Result<&mut [u8], String> {
        if let Some(vec) = self.pool.pop() {
            return Ok(vec);
        }

        let mut vec = Vec::with_capacity(size);
        unsafe {
            vec.set_len(size);
        }

        Ok(vec)
    }

    fn deallocate(&mut self, vec: &mut [u8]) -> Result<(), String> {
        if let Some(index) = self.pool.iter().position(|v| v == vec) {
            self.pool.remove(index);
            return Ok(());
        }

        Err("Vector not found in pool".to_string())
    }
}

struct MemoryAllocator {
    memory_pool: MemoryPool,
}

impl MemoryAllocator {
    fn new() -> Self {
        Self {
            memory_pool: MemoryPool::new(),
        }
    }

    fn allocate(&mut self, size: usize) -> Result<&mut [u8], String> {
        self.memory_pool.allocate(size)
    }

    fn deallocate(&mut self, vec: &mut [u8]) -> Result<(), String> {
        self.memory_pool.deallocate(vec)
    }
}

struct DatasetManager {
    dataset: Arc<Mutex<Dataset>>,
    memory_allocator: MemoryAllocator,
}

impl DatasetManager {
    fn new(size: usize, range: (i32, i32), disable_certificate_validation: bool) -> Self {
        let dataset = Arc::new(Mutex::new(Dataset::new(size, range, disable_certificate_validation)));
        let memory_allocator = MemoryAllocator::new();

        Self {
            dataset,
            memory_allocator,
        }
    }

    fn insert(&self, key: i32, offset: u64, value: f64) -> Result<(), String> {
        let mut dataset = self.dataset.lock().unwrap();
        dataset.insert(key, offset, value)
    }

    fn get(&self, key: i32) -> Option<&Record> {
        let dataset = self.dataset.lock().unwrap();
        dataset.get(key)
    }

    fn remove(&self, key: i32) -> Result<(), String> {
        let mut dataset = self.dataset.lock().unwrap();
        dataset.remove(key)
    }
}

struct WebRequestHandler {
    client: HttpClient,
    manager: DatasetManager,
}

impl WebRequestHandler {
    fn new(size: usize, range: (i32, i32), disable_certificate_validation: bool) -> Self {
        let client = HttpClient::new(disable_certificate_validation);
        let manager = DatasetManager::new(size, range, disable_certificate_validation);

        Self { client, manager }
    }

    fn handle(&self, url: &str) -> Result<(), String> {
        let response = self.client.get(url)?;
        let dataset = self.manager.dataset.lock().unwrap();
        for record in dataset.records.iter() {
            self.manager.insert(record.key, record.offset, record.value)?;
        }

        Ok(())
    }
}
