#define DEFAULT_OUTPUT_FILE "output.txt"
#define DEFAULT_THREAD_POOL_SIZE 5
#define DEFAULT_IDLE_THREADS 2

// Struct to hold information about a file being processed
struct file_info {
    char *path; // Path to the file
    int fd; // File descriptor
    size_t line_count; // Number of lines in the file
};

// Struct to hold information about a thread in the pool
struct thread_info {
    pthread_t tid; // Thread ID
    struct file_info *file; // Pointer to the file being processed
    size_t line_count; // Number of lines processed by the thread
};

// Function to parse command-line arguments and initialize the program
