    struct file_info *files = NULL;
    size_t num_files = 0;
    char *output_file = DEFAULT_OUTPUT_FILE;
    char *log_file = DEFAULT_LOG_FILE;
    size_t line_count = 0;
    int thread_pool_size = DEFAULT_THREAD_POOL_SIZE;
    int idle_threads = DEFAULT_IDLE_THREADS;

    // Parse command-line arguments
    for (i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--manpage")) {
            printf("Usage: %s [options] file...\n", argv[0]);
            printf("Options:\n");
            printf("  -o output_file   Output file name (default: %s)\n", DEFAULT_OUTPUT_FILE);
            printf("  -l log_file      Log file name (default: %s)\n", DEFAULT_LOG_FILE);
            printf("  -cs              Case-sensitive matching\n");
            return 0;
        } else if (!strcmp(argv[i], "-o")) {
            output_file = argv[++i];
        } else if (!strcmp(argv[i], "-l")) {
            log_file = argv[++i];
        } else if (argv[i][0] == '-') {
            fprintf(stderr, "Invalid option: %s\n", argv[i]);
            return 1;
        } else {
            // Add file to the list of files to be processed
            num_files++;
            files = realloc(files, sizeof(struct file_info) * num_files);
            files[num_files - 1].path = argv[i];
            files[num_files - 1].fd = open(argv[i], O_RDONLY);
            if (files[num_files - 1].fd == -1) {
                perror("open");
                return 1;
            }
        }
    }

    // Check for missing files or invalid options
    if (num_files == 0) {
        fprintf(stderr, "No input files specified\n");
        return 1;
    } else if (output_file == NULL || log_file == NULL) {
        fprintf(stderr, "Missing output or log file name\n");
        return 1;
    }

    // Initialize the thread pool and create threads for each file
    pthread_t *threads = malloc(sizeof(pthread_t) * num_files);
    struct thread_info *thread_infos = malloc(sizeof(struct thread_info) * num_files);
    for (i = 0; i < num_files; i++) {
        thread_infos[i].file = &files[i];
        thread_infos[i].line_count = 0;
        pthread_create(&threads[i], NULL, process_file, &thread_infos[i]);
    }

    // Wait for all threads to finish and close the file descriptors
    for (i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
        close(threads[i].fd);
    }

    // Print the total number of lines processed
    printf("Total lines processed: %zu\n", line_count);

    // Clean up resources
    free(files);
    free(threads);
    free(thread_infos);

    return 0;
}

// Function to process a file in a separate thread
void *process_file(void *arg) {
    struct thread_info *thread_info = arg;
    struct file_info *file = thread_info->file;
    size_t line_count = 0;

    // Read the file line by line and count the number of lines
    char buffer[MAX_LINE_LENGTH];
    while (read(file->fd, buffer, MAX_LINE_LENGTH) > 0) {
        if (buffer[strlen(buffer) - 1] == '\n') {
            line_count++;
        }
    }

    // Increment the total number of lines processed
    pthread_mutex_lock(&line_count_mutex);
    thread_info->line_count = line_count;
    line_count += line_count;
    pthread_mutex_unlock(&line_count_mutex);

    return NULL;
}
