}

// Function to insert a task into the BST
void insert_task(Task *task) {
    // Check if the tree is empty
    if (bst == NULL) {
        bst = malloc(sizeof(Task));
        if (bst == NULL) {
            printf("Error: Failed to allocate memory for task\n");
            return;
        }
        memcpy(bst, task, sizeof(Task));
        return;
    }

    // Check if the new task has a higher priority than the current root
    if (task->priority > bst->priority) {
        Task *new_root = malloc(sizeof(Task));
        if (new_root == NULL) {
            printf("Error: Failed to allocate memory for task\n");
            return;
        }
        memcpy(new_root, task, sizeof(Task));
        new_root->left = bst;
        bst = new_root;
        return;
    }

    // Check if the new task has a lower priority than the current root
    if (task->priority < bst->priority) {
        Task *new_root = malloc(sizeof(Task));
        if (new_root == NULL) {
            printf("Error: Failed to allocate memory for task\n");
            return;
        }
        memcpy(new_root, task, sizeof(Task));
        new_root->right = bst;
        bst = new_root;
        return;
    }

    // Check if the new task has the same priority as the current root
    Task *current = bst;
    while (current != NULL) {
        if (task->priority == current->priority) {
            Task *new_root = malloc(sizeof(Task));
            if (new_root == NULL) {
                printf("Error: Failed to allocate memory for task\n");
                return;
            }
            memcpy(new_root, task, sizeof(Task));
            new_root->left = current->left;
            current->left = new_root;
            break;
        } else if (task->priority > current->priority) {
            Task *new_root = malloc(sizeof(Task));
            if (new_root == NULL) {
                printf("Error: Failed to allocate memory for task\n");
                return;
            }
            memcpy(new_root, task, sizeof(Task));
            new_root->right = current->right;
            current->right = new_root;
            break;
        } else {
            current = current->left;
        }
    }
}

// Function to delete a task from the BST
void delete_task(Task *task) {
    // Check if the tree is empty
    if (bst == NULL) {
        return;
    }

    // Check if the task to be deleted is the root
    if (memcmp(bst, task, sizeof(Task)) == 0) {
        Task *new_root = malloc(sizeof(Task));
        if (new_root == NULL) {
            printf("Error: Failed to allocate memory for task\n");
            return;
        }
        memcpy(new_root, bst->left, sizeof(Task));
        free(bst);
        bst = new_root;
        return;
    }

    // Check if the task to be deleted is a left child
    Task *current = bst;
    while (current != NULL) {
        if (memcmp(current->left, task, sizeof(Task)) == 0) {
            current->left = NULL;
            break;
        } else if (memcmp(current->right, task, sizeof(Task)) == 0) {
            current->right = NULL;
            break;
        } else {
            current = current->left;
        }
    }
}

// Function to search for a task in the BST
Task *search_task(int priority, enum Status status) {
    // Check if the tree is empty
    if (bst == NULL) {
        return NULL;
    }

    // Check if the root has the same priority and status as the search criteria
    if (bst->priority == priority && bst->status == status) {
        return bst;
    }

    // Check if the task to be searched is a left child
    Task *current = bst;
    while (current != NULL) {
        if (current->left != NULL && current->left->priority == priority && current->left->status == status) {
            return current->left;
        } else if (current->right != NULL && current->right->priority == priority && current->right->status == status) {
            return current->right;
        } else {
            current = current->left;
        }
    }

    // If the task is not found, return NULL
    return NULL;
}

// Function to print a task
void print_task(Task *task) {
    printf("Name: %s\n", task->name);
    printf("Priority: %d\n", task->priority);
    printf("Status: %s\n", (task->status == ACTIVE) ? "Active" : (task->status == COMPLETED) ? "Completed" : "Pending");
    printf("Description: %s\n", task->description);
    printf("Start Time: %ld\n", task->start_time);
    printf("Due Time: %ld\n", task->due_time);
}

// Function to print a user profile
void print_user_profile(UserProfile *profile) {
    printf("First Name: %s\n", profile->first_name);
    printf("Last Name: %s\n", profile->last_name);
    printf("Email: %s\n", profile->email);
    for (int i = 0; i < 10; i++) {
