    // Allocate memory for the new task node
    struct TaskNode* new_node = (struct TaskNode*) malloc(sizeof(struct TaskNode));
    if (!new_node) {
        printf("Error: Failed to allocate memory for new task node\n");
        exit(1);
    }
    // Initialize the new task node
    new_node->id = id;
    new_node->name = name;
    new_node->completed = false;
    new_node->next = NULL;
    // Add the new task node to the end of the task queue
    if (task_queue->tail) {
        task_queue->tail->next = new_node;
    } else {
        task_queue->head = new_node;
    }
    task_queue->tail = new_node;
}

// Function to mark a task as completed
void complete_task(int id) {
    // Find the task node with the given ID
    struct TaskNode* current_node = task_queue->head;
    while (current_node && current_node->id != id) {
        current_node = current_node->next;
    }
    if (!current_node) {
        printf("Error: Task with ID %d not found\n", id);
        exit(1);
    }
    // Mark the task as completed and update the linked list
    current_node->completed = true;
    struct TaskNode* previous_node = NULL;
    while (current_node && current_node->next) {
        if (current_node->next->id == id) {
            break;
        }
        previous_node = current_node;
        current_node = current_node->next;
    }
    if (!current_node) {
        printf("Error: Task with ID %d not found\n", id);
        exit(1);
    }
    // Remove the task node from the linked list
    if (previous_node) {
        previous_node->next = current_node->next;
    } else {
        task_queue->head = current_node->next;
    }
