#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct {
    int key;
    int value;
    char* custom_data;
} record;

// Define the initialize_records function
void initialize_records(int num_records, ...) {
    // Get the variable argument list
    va_list args;
    va_start(args, num_records);

    // Allocate memory for the records array
    record* records = (record*)malloc(num_records * sizeof(record));

    // Initialize the random seed for generating random keys
    srand(time(NULL));

    // Iterate over each record and initialize its fields
    for (int i = 0; i < num_records; i++) {
        // Get the next offset argument from the variable argument list
        int offset = va_arg(args, int);

        // Initialize the key to a random value within the specified range
        records[i].key = rand() % 10000 + 1;

        // Check for duplicate keys and adjust the random key generation logic if necessary
        for (int j = i - 1; j >= 0; j--) {
            if (records[j].key == records[i].key) {
                records[i].key = rand() % 10000 + 1;
                break;
            }
        }

        // Initialize the value to a random value within the specified range
        records[i].value = rand() % 10000 + 1;

        // Check for missing keys and assign default values if necessary
        if (offset != -1) {
            records[i].custom_data = malloc(strlen(offset) + 1);
            strcpy(records[i].custom_data, offset);
        } else {
            records[i].custom_data = NULL;
        }
    }

    // Log all key-value pairs and custom data fields as they are initialized
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: Key=%d, Value=%d, Custom Data=%s\n", i + 1, records[i].key, records[i].value, records[i].custom_data);
    }

    // Clean up memory and return the initialized records array
    va_end(args);
    free(records);
}
