int verify_access_token(const char* json) {
    // Parse the JSON object
    cJSON *root = cJSON_Parse(json);
    if (!root) {
        printf("Error parsing JSON: %s\n", cJSON_GetErrorPtr());
        return 0;
    }

    // Check for required fields
    cJSON *access_token = cJSON_GetObjectItemCaseSensitive(root, "access_token");
    if (!cJSON_IsString(access_token) || access_token->valuestring == NULL) {
        printf("Missing or invalid 'access_token' field\n");
        return 0;
    }
    cJSON *expires_in = cJSON_GetObjectItemCaseSensitive(root, "expires_in");
    if (!cJSON_IsNumber(expires_in) || expires_in->valuedouble < 0) {
        printf("Missing or invalid 'expires_in' field\n");
        return 0;
    }
    cJSON *token_type = cJSON_GetObjectItemCaseSensitive(root, "token_type");
    if (!cJSON_IsString(token_type) || token_type->valuestring == NULL) {
        printf("Missing or invalid 'token_type' field\n");
        return 0;
    }

    // Check for optional fields
    cJSON *refresh_token = cJSON_GetObjectItemCaseSensitive(root, "refresh_token");
    if (cJSON_IsString(refresh_token) && refresh_token->valuestring != NULL) {
        printf("Found 'refresh_token' field\n");
    }

    // Clean up
    cJSON_Delete(root);

    return 1;
}

EVP_CIPHER* get_cipher(const char* mode, const char* key) {
    EVP_CIPHER *cipher = NULL;

    if (strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        cipher = EVP_des_ede();
    } else if (strcmp(mode, "EDE3") == 0) {
        cipher = EVP_des_ede3();
    } else if (strcmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb();
    } else if (strcmp(mode, "NULL") == 0) {
        // Do nothing
    } else {
        printf("Invalid encryption mode\n");
        return NULL;
    }

    if (!EVP_CIPHER_CTX_key_length(cipher)) {
        printf("Invalid key length\n");
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, (unsigned char*)key, NULL)) {
        printf("Error initializing encryption context\n");
        return NULL;
    }

    return ctx;
}
