#include <assert.h>

// Define the record structure
typedef struct {
    time_t timestamp;
    enum Status status;
    float weight;
} Record;

// Define the memory pool manager
struct MemoryPool {
    size_t capacity;
    size_t used;
    void* buffer;
};

// Function to dynamically allocate memory for a collection of records
Record* createRecords(size_t numRecords, ...) {
    // Calculate the total size of the record structures
    size_t totalSize = sizeof(Record) * numRecords;

    // Allocate memory for the record structures and offsets array
    void* buffer = malloc(totalSize);
    assert(buffer != NULL);

    // Initialize the memory pool manager
    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    pool->capacity = totalSize;
    pool->used = 0;
    pool->buffer = buffer;

    // Get the variable number of offsets from the arguments list
    va_list args;
    va_start(args, numRecords);
    long* offsets = (long*)malloc(sizeof(long) * numRecords);
    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = va_arg(args, long);
    }
    va_end(args);

    // Initialize the records and offsets
    Record* records = (Record*)buffer;
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].timestamp = time(NULL);
        records[i].status = ACTIVE;
        records[i].weight = 0.0f;
        offsets[i] = (long)(records + i);
    }

    // Free the variable argument list and return the record structures
    free(offsets);
    return records;
}

// Function to dynamically allocate memory for a single record
Record* createRecord() {
    Record* record = (Record*)malloc(sizeof(Record));
    assert(record != NULL);
    record->timestamp = time(NULL);
    record->status = ACTIVE;
    record->weight = 0.0f;
    return record;
}

// Function to free the memory allocated for a collection of records
void destroyRecords(Record* records, size_t numRecords) {
    // Free the memory pool manager
    struct MemoryPool* pool = (struct MemoryPool*)records - 1;
    free(pool);

    // Free the record structures and offsets array
    for (size_t i = 0; i < numRecords; ++i) {
        Record* record = records + i;
        free(record);
    }
}

// Function to free the memory allocated for a single record
void destroyRecord(Record* record) {
    // Free the memory pool manager
    struct MemoryPool* pool = (struct MemoryPool*)record - 1;
    free(pool);

    // Free the record structure
    free(record);
}
