    if (new_task == NULL) {
        // Handle allocation failure gracefully
        return;
    }
    // Copy the contents of the new task from the input parameter
    memcpy(new_task, task, sizeof(Task));
    // Add the new task to the collection
    tasks = realloc(tasks, (num_tasks + 1) * sizeof(Task));
    if (tasks == NULL) {
        // Handle allocation failure gracefully
        return;
    }
    tasks[num_tasks] = new_task;
    num_tasks++;
}

// Define a function to update existing tasks
void update_task(int id, Task* task) {
    // Find the task with the specified ID
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i]->id == id) {
            // Update the contents of the task
            memcpy(tasks[i], task, sizeof(Task));
            return;
        }
    }
}

// Define a function to retrieve tasks based on their priority
void get_tasks_by_priority(int priority) {
    // Find all tasks with the specified priority
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i]->priority == priority) {
            // Add the task to the output array
            output_tasks = realloc(output_tasks, (num_output_tasks + 1) * sizeof(Task));
            if (output_tasks == NULL) {
                // Handle allocation failure gracefully
                return;
            }
            output_tasks[num_output_tasks] = tasks[i];
            num_output_tasks++;
        }
    }
}

// Define a function to free all allocated memory when the collection is no longer needed
void free_memory() {
    for (int i = 0; i < num_tasks; i++) {
        free(tasks[i]);
    }
    free(tasks);
}
