// Define the structure for sensor readings
typedef struct SensorReading {
    int sensor_id;
    time_t timestamp;
    float temperature;
    float humidity;
    float pressure;
    double latitude;
    double longitude;
} SensorReading;

// Define the array for storing sensor readings
SensorReading *readings = NULL;
size_t num_readings = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
semaphore_t semaphore = SEMAPHORE_INITIALIZER;

// Function to add a new reading
void add_reading(SensorReading *reading) {
    pthread_mutex_lock(&mutex);
    if (num_readings == 0) {
        readings = malloc(sizeof(SensorReading));
        memcpy(readings, reading, sizeof(SensorReading));
        num_readings++;
    } else {
        SensorReading *new_readings = realloc(readings, (num_readings + 1) * sizeof(SensorReading));
        if (new_readings == NULL) {
            perror("realloc failed");
            pthread_mutex_unlock(&mutex);
            return;
        }
        readings = new_readings;
        memcpy(readings + num_readings, reading, sizeof(SensorReading));
        num_readings++;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing reading
void update_reading(int sensor_id, time_t timestamp, float temperature, float humidity, float pressure, double latitude, double longitude) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_readings; i++) {
        if (readings[i].sensor_id == sensor_id && readings[i].timestamp == timestamp) {
            readings[i].temperature = temperature;
            readings[i].humidity = humidity;
            readings[i].pressure = pressure;
            readings[i].latitude = latitude;
            readings[i].longitude = longitude;
        }
    }
    pthread_mutex_unlock(&mutex);
}

