            printf("Pressure: %.2f\n", readings[i].pressure);
            printf("Latitude: %lf\n", readings[i].latitude);
            printf("Longitude: %lf\n", readings[i].longitude);
        }
    }
    pthread_mutex_unlock(&mutex);
}

