#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define the structure for TrafficEvent
typedef struct {
    time_t timestamp;
    int eventType;
    char* associatedVehicleIDs;
    float locationCoordinates[2];
    float speedData;
} TrafficEvent;

// Define the array of TrafficEvents
TrafficEvent* trafficEvents = NULL;
int numEvents = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new event
void addNewEvent(TrafficEvent* event) {
    pthread_mutex_lock(&mutex);
    trafficEvents = realloc(trafficEvents, (numEvents + 1) * sizeof(TrafficEvent));
    memcpy(&trafficEvents[numEvents], event, sizeof(TrafficEvent));
    numEvents++;
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing event
void updateEvent(int index, TrafficEvent* event) {
    pthread_mutex_lock(&mutex);
    memcpy(&trafficEvents[index], event, sizeof(TrafficEvent));
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve events within a specified time range
void getEventsInRange(time_t startTime, time_t endTime) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < numEvents; i++) {
        if (trafficEvents[i].timestamp >= startTime && trafficEvents[i].timestamp <= endTime) {
            printf("Event %d: timestamp=%ld, eventType=%d, associatedVehicleIDs=%s\n", i, trafficEvents[i].timestamp, trafficEvents[i].eventType, trafficEvents[i].associatedVehicleIDs);
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to filter events based on various criteria
void filterEvents(int eventType, char* associatedVehicleIDs) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < numEvents; i++) {
        if (trafficEvents[i].eventType == eventType && strcmp(trafficEvents[i].associatedVehicleIDs, associatedVehicleIDs) == 0) {
            printf("Event %d: timestamp=%ld, eventType=%d, associatedVehicleIDs=%s\n", i, trafficEvents[i].timestamp, trafficEvents[i].eventType, trafficEvents[i].associatedVehicleIDs);
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to handle file I/O errors
void handleFileIOError(int errorCode) {
    printf("Error: %d\n", errorCode);
}

// Function to process multiple input files simultaneously
void processFiles(char** filenames, int numFiles) {
    for (int i = 0; i < numFiles; i++) {
        char* filename = filenames[i];
        // Open the file in read-only mode
        int fd = open(filename, O_RDONLY);
        if (fd == -1) {
            handleFileIOError(errno);
            continue;
        }
        // Read the contents of the file into a buffer
        char* buffer = malloc(sizeof(char) * 4096);
        ssize_t bytesRead = read(fd, buffer, 4096);
        if (bytesRead == -1) {
            handleFileIOError(errno);
            continue;
        }
        // Close the file
        close(fd);
        // Parse the contents of the file and add/update events as necessary
        for (int j = 0; j < bytesRead; j++) {
            char* line = buffer + j;
            if (strlen(line) > 0 && line[0] != '#') {
                // Parse the line and add/update an event
                TrafficEvent event;
                sscanf(line, "%ld %d %s %f %f", &event.timestamp, &event.eventType, event.associatedVehicleIDs, &event.locationCoordinates[0], &event.locationCoordinates[1]);
                addNewEvent(&event);
            }
        }
    }
}

// Function to generate a comprehensive report of aggregated line counts and total character counts across all specified files
void generateReport(char** filenames, int numFiles) {
    // Initialize the report variables
    int totalLines = 0;
    int totalCharacters = 0;
    for (int i = 0; i < numFiles; i++) {
        char* filename = filenames[i];
        // Open the file in read-only mode
        int fd = open(filename, O_RDONLY);
        if (fd == -1) {
            handleFileIOError(errno);
            continue;
        }
        // Read the contents of the file into a buffer
        char* buffer = malloc(sizeof(char) * 4096);
        ssize_t bytesRead = read(fd, buffer, 4096);
        if (bytesRead == -1) {
            handleFileIOError(errno);
            continue;
        }
        // Close the file
        close(fd);
        // Parse the contents of the file and update the report variables
        for (int j = 0; j < bytesRead; j++) {
            char* line = buffer + j;
            if (strlen(line) > 0 && line[0] != '#') {
                totalLines++;
                totalCharacters += strlen(line);
            }
        }
    }
    // Print the report
    printf("Total lines: %d\n", totalLines);
    printf("Total characters: %d\n", totalCharacters);
}

// Main function
