#include <pthread.h>

// Define the structure for each record
struct data_entry {
    long index;
    int key;
};

// Define the array of records
struct data_entry *records = NULL;

// Define the total number of keys
int total_keys = 0;

// Define the maximum number of retries for generating a unique key
#define RETRY_LIMIT 100

// Define the lock for generate_unique_key()
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize an array of long integers
long *allocate_offsets(int num_records) {
    // Allocate memory for the offsets array
    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets\n");
        return NULL;
    }

    // Initialize the offsets array with valid values
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i;
    }

    return offsets;
}

// Function to allocate and initialize an array of integers
int *allocate_keys(int num_records) {
    // Allocate memory for the keys array
    int *keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys\n");
        return NULL;
    }

    // Initialize the keys array with unique values
    for (int i = 0; i < num_records; i++) {
        keys[i] = generate_unique_key();
    }

    return keys;
}

// Function to populate the records array with unique keys while ensuring no duplicates exist
void populate_records(int num_records) {
    // Allocate memory for the records array
    records = (struct data_entry *)malloc(num_records * sizeof(struct data_entry));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize the offsets array with valid values
    long *offsets = allocate_offsets(num_records);
    if (!offsets) {
        free(records);
        records = NULL;
        return;
    }

    // Initialize the keys array with unique values
    int *keys = allocate_keys(num_records);
    if (!keys) {
        free(offsets);
        free(records);
        records = NULL;
        return;
    }

    // Populate the records array with unique keys while ensuring no duplicates exist
    for (int i = 0; i < num_records; i++) {
        bool duplicate = false;
        int key = generate_unique_key();
        while (!duplicate) {
            for (int j = 0; j < i; j++) {
                if (keys[j] == key) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) {
                records[i].index = offsets[i];
                records[i].key = key;
                total_keys++;
                break;
            }
        }
    }

    // Free the memory for the offsets and keys arrays
    free(offsets);
    free(keys);
}

// Function to generate a unique key using a random number and a retry mechanism
int generate_unique_key() {
    int key = 0;
    bool duplicate = true;
    while (duplicate) {
        // Generate a random number between 1 and RETRY_LIMIT
        key = rand() % RETRY_LIMIT + 1;

        // Check if the generated key is already in use
        pthread_mutex_lock(&lock);
        for (int i = 0; i < total_keys; i++) {
            if (records[i].key == key) {
                duplicate = true;
                break;
            }
        }
        pthread_mutex_unlock(&lock);

        // If the generated key is already in use, retry with a new random number
        if (duplicate) {
            continue;
        } else {
            return key;
        }
    }
}

// Function to calculate and store the sum of all keys in total_keys
void calculate_total_keys() {
    // Calculate the sum of all keys
    int sum = 0;
    for (int i = 0; i < total_keys; i++) {
        sum += records[i].key;
    }

    // Store the sum in total_keys
    total_keys = sum;
}

// Function to free all allocated memory and reset the internal state for re-use
void free_memory() {
    // Free the memory for the records array
    if (records) {
        free(records);
        records = NULL;
    }

    // Reset the total number of keys to 0
    total_keys = 0;
}
