size_t readings_capacity = 0;
pthread_mutex_t readings_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the function for adding a new SensorReading
void add_reading(SensorReading *reading) {
    pthread_mutex_lock(&readings_lock);
    if (readings_count == readings_capacity) {
        // Reallocate memory for the array if necessary
        readings_capacity = readings_capacity ? 2 * readings_capacity : 10;
        readings = realloc(readings, readings_capacity * sizeof(SensorReading));
    }
    // Add the new reading to the array
    readings[readings_count++] = *reading;
    pthread_mutex_unlock(&readings_lock);
}

// Define the function for updating an existing SensorReading
void update_reading(SensorReading *reading) {
    pthread_mutex_lock(&readings_lock);
    // Find the index of the reading to be updated
    size_t i;
    for (i = 0; i < readings_count && readings[i].sensor_id != reading->sensor_id; ++i) {}
    if (i == readings_count) {
        // If the reading is not found, add it to the array
        add_reading(reading);
