// Define the function to generate a unique key
int generate_unique_key(void) {
    int key = 0;
    pthread_mutex_lock(&unique_key_lock);
    for (int i = 0; i < RETRY_LIMIT; i++) {
        key = rand() % MAX_KEYS;
        if (!is_key_used(key)) {
            break;
        }
    }
    pthread_mutex_unlock(&unique_key_lock);
    return key;
}

// Define the function to check if a key is used
int is_key_used(int key) {
