// Define a structure to represent a traffic event
typedef struct TrafficEvent {
    long timestamp; // Timestamp of the event in milliseconds
    int type; // Type of the event (e.g., "car", "truck", etc.)
    char* vehicle_ids; // List of associated vehicle IDs
} TrafficEvent;

// Define a dynamic array to store traffic events
typedef struct TrafficEventArray {
    int size; // Current size of the array
    int capacity; // Maximum capacity of the array
    TrafficEvent* events; // Array of traffic events
} TrafficEventArray;

// Initialize a new dynamic array with a given capacity
TrafficEventArray* init_traffic_event_array(int capacity) {
    TrafficEventArray* arr = (TrafficEventArray*)malloc(sizeof(TrafficEventArray));
    arr->size = 0;
    arr->capacity = capacity;
    arr->events = (TrafficEvent*)malloc(sizeof(TrafficEvent) * capacity);
    return arr;
}

// Add a new traffic event to the array
void add_traffic_event(TrafficEventArray* arr, TrafficEvent event) {
    // Check if the array is full and needs to be resized
    if (arr->size == arr->capacity) {
        int new_capacity = arr->capacity * 2;
        TrafficEvent* new_events = (TrafficEvent*)realloc(arr->events, sizeof(TrafficEvent) * new_capacity);
        if (new_events == NULL) {
            // Handle error
            return;
        }
        arr->events = new_events;
        arr->capacity = new_capacity;
    }
    arr->events[arr->size++] = event;
}

// Update an existing traffic event in the array
void update_traffic_event(TrafficEventArray* arr, int index, TrafficEvent event) {
    // Check if the index is valid
    if (index < 0 || index >= arr->size) {
        return;
    }
    arr->events[index] = event;
}

// Delete an existing traffic event from the array
void delete_traffic_event(TrafficEventArray* arr, int index) {
    // Check if the index is valid
    if (index < 0 || index >= arr->size) {
        return;
    }
    // Shift all events after the deleted event to fill the gap
    for (int i = index + 1; i < arr->size; i++) {
        arr->events[i - 1] = arr->events[i];
    }
    arr->size--;
}

// Retrieve all traffic events within a specified time range
TrafficEventArray* get_traffic_events(TrafficEventArray* arr, long start_time, long end_time) {
    TrafficEventArray* result = init_traffic_event_array(arr->size);
    for (int i = 0; i < arr->size; i++) {
        TrafficEvent event = arr->events[i];
        if (event.timestamp >= start_time && event.timestamp <= end_time) {
            add_traffic_event(result, event);
        }
    }
    return result;
}

// Free the memory allocated for a traffic event array
void free_traffic_event_array(TrafficEventArray* arr) {
    free(arr->events);
    free(arr);
}
