int generate_unique_key(void) {
    int key = 0;
    pthread_mutex_lock(&key_lock);
    while (true) {
        if (key == INT_MAX) {
            // If the key is at its maximum value, reset it to 0 and try again
            key = 0;
        } else {
            // Increment the key by 1 and check for uniqueness
            key++;
            bool unique = true;
            for (int i = 0; i < total_keys; i++) {
                if (records[i].record.key == key) {
                    unique = false;
                    break;
                }
            }
            if (unique) {
                // If the key is unique, return it
