#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure for a traffic event
typedef struct TrafficEvent {
    time_t timestamp;
    int eventType;
    char* associatedVehicleIDs[10]; // Maximum of 10 vehicle IDs per event
    float locationCoordinates[2]; // Latitude and longitude
    float speedData;
} TrafficEvent;

// Define the structure for a set of traffic events
typedef struct TrafficEvents {
    int numEvents;
    TrafficEvent* events[1000]; // Maximum of 1000 events per set
} TrafficEvents;

// Define the function to add a new traffic event
void addTrafficEvent(TrafficEvents* events, TrafficEvent* event) {
    pthread_mutex_lock(&events->mutex);
    if (events->numEvents < 1000) {
        events->events[events->numEvents++] = event;
    } else {
        printf("Error: Maximum number of events reached\n");
    }
    pthread_mutex_unlock(&events->mutex);
}

// Define the function to update an existing traffic event
void updateTrafficEvent(TrafficEvents* events, int index, TrafficEvent* event) {
    pthread_mutex_lock(&events->mutex);
    if (index < 0 || index >= events->numEvents) {
        printf("Error: Invalid event index\n");
    } else {
        events->events[index] = event;
    }
    pthread_mutex_unlock(&events->mutex);
}

// Define the function to retrieve traffic events within a specified time range
void getTrafficEvents(TrafficEvents* events, time_t startTime, time_t endTime) {
    pthread_mutex_lock(&events->mutex);
    int numEvents = 0;
    for (int i = 0; i < events->numEvents; i++) {
        if (events->events[i]->timestamp >= startTime && events->events[i]->timestamp <= endTime) {
            numEvents++;
        }
    }
    TrafficEvent* retrievedEvents = malloc(sizeof(TrafficEvent) * numEvents);
    int j = 0;
    for (int i = 0; i < events->numEvents; i++) {
        if (events->events[i]->timestamp >= startTime && events->events[i]->timestamp <= endTime) {
            retrievedEvents[j++] = events->events[i];
        }
    }
    pthread_mutex_unlock(&events->mutex);
}

// Define the function to filter traffic events based on criteria
void filterTrafficEvents(TrafficEvents* events, int eventType, char* vehicleID) {
    pthread_mutex_lock(&events->mutex);
    int numEvents = 0;
    for (int i = 0; i < events->numEvents; i++) {
        if (events->events[i]->eventType == eventType && strcmp(events->events[i]->associatedVehicleIDs, vehicleID) == 0) {
            numEvents++;
        }
    }
    TrafficEvent* filteredEvents = malloc(sizeof(TrafficEvent) * numEvents);
    int j = 0;
    for (int i = 0; i < events->numEvents; i++) {
        if (events->events[i]->eventType == eventType && strcmp(events->events[i]->associatedVehicleIDs, vehicleID) == 0) {
            filteredEvents[j++] = events->events[i];
        }
    }
    pthread_mutex_unlock(&events->mutex);
}

// Define the function to calculate the weighted sum of traffic events
void calculateWeightedSum(TrafficEvents* events, int eventType, char* vehicleID) {
    pthread_mutex_lock(&events->mutex);
    float weightedSum = 0;
    for (int i = 0; i < events->numEvents; i++) {
        if (events->events[i]->eventType == eventType && strcmp(events->events[i]->associatedVehicleIDs, vehicleID) == 0) {
            weightedSum += events->events[i]->timestamp * events->events[i]->speedData;
        }
    }
    pthread_mutex_unlock(&events->mutex);
}

// Define the function to retrieve the maximum weighted sum of traffic events
void getMaxWeightedSum(TrafficEvents* events, int eventType, char* vehicleID) {
    pthread_mutex_lock(&events->mutex);
    float maxWeightedSum = 0;
    for (int i = 0; i < events->numEvents; i++) {
        if (events->events[i]->eventType == eventType && strcmp(events->events[i]->associatedVehicleIDs, vehicleID) == 0) {
            maxWeightedSum += events->events[i]->timestamp * events->events[i]->speedData;
        }
    }
    pthread_mutex_unlock(&events->mutex);
}
