    void updateSession(int sessionID, std::string userInfo, std::chrono::time_point<std::chrono::system_clock> loginTime, int sessionDuration) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& session : sessions_) {
            if (session.getSessionID() == sessionID) {
                session.setUserInfo(userInfo);
                session.setLoginTime(loginTime);
                session.setSessionDuration(sessionDuration);
                break;
            }
        }
    }

    // Retrieve sessions based on user ID or session duration
    std::vector<UserSession> getSessionsByUserID(int userID) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<UserSession> filteredSessions;
        for (auto& session : sessions_) {
            if (session.getUserInfo().find(userID) != std::string::npos) {
                filteredSessions.push_back(session);
            }
        }
        return filteredSessions;
    }

    std::vector<UserSession> getSessionsByDuration(int sessionDuration) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<UserSession> filteredSessions;
        for (auto& session : sessions_) {
            if (session.getSessionDuration() == sessionDuration) {
                filteredSessions.push_back(session);
