        for (auto& session : sessions_) {
            if (session.getActions().find(actionType) != std::string::npos) {
                filteredSessions.push_back(session);
            }
        }
        return filteredSessions;
    }

    std::vector<UserSession> filterSessionsByUserAttributes(std::map<std::string, std::string> userAttributes) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<UserSession> filteredSessions;
        for (auto& session : sessions_) {
