class DeviceLog {
public:
    // Constructor
    DeviceLog(int deviceId, std::string location) : deviceId_(deviceId), location_(location) {}

    // Getters and setters for device ID, timestamp, operational parameters, device location, and network connectivity status
    int getDeviceId() { return deviceId_; }
    void setDeviceId(int deviceId) { deviceId_ = deviceId; }
    std::string getTimestamp() { return timestamp_; }
    void setTimestamp(std::string timestamp) { timestamp_ = timestamp; }
    float getCpuUsage() { return cpuUsage_; }
    void setCpuUsage(float cpuUsage) { cpuUsage_ = cpuUsage; }
    float getMemoryUsage() { return memoryUsage_; }
    void setMemoryUsage(float memoryUsage) { memoryUsage_ = memoryUsage; }
    int getDiskIo() { return diskIo_; }
    void setDiskIo(int diskIo) { diskIo_ = diskIo; }
    std::string getLocation() { return location_; }
    void setLocation(std::string location) { location_ = location; }
    bool getNetworkConnectivityStatus() { return networkConnectivityStatus_; }
    void setNetworkConnectivityStatus(bool status) { networkConnectivityStatus_ = status; }

private:
    int deviceId_;
    std::string timestamp_;
    float cpuUsage_;
    float memoryUsage_;
    int diskIo_;
    std::string location_;
    bool networkConnectivityStatus_;
};

class DeviceLogManager {
public:
    // Constructor
    DeviceLogManager() {}

    // Add a new log entry to the collection
    void addLog(DeviceLog log) {
        std::lock_guard<std::mutex> lock(mutex_);
        logs_.push_back(log);
    }

    // Update an existing log entry in the collection
    void updateLog(int deviceId, DeviceLog log) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = logs_.begin(); it != logs_.end(); ++it) {
            if ((*it).getDeviceId() == deviceId) {
                *it = log;
                break;
            }
        }
    }

    // Retrieve all log entries within a specified time frame
    std::vector<DeviceLog> getLogs(std::string startTime, std::string endTime) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<DeviceLog> logs;
        for (auto it = logs_.begin(); it != logs_.end(); ++it) {
            if ((*it).getTimestamp() >= startTime && (*it).getTimestamp() <= endTime) {
                logs.push_back(*it);
            }
        }
        return logs;
    }

    // Filter log entries based on operational conditions or geographical proximity
    std::vector<DeviceLog> filterLogs(std::string condition, std::string location) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<DeviceLog> logs;
        for (auto it = logs_.begin(); it != logs_.end(); ++it) {
            if ((*it).getLocation() == location || (*it).getNetworkConnectivityStatus()) {
                logs.push_back(*it);
            }
        }
        return logs;
    }

private:
    std::mutex mutex_;
    std::vector<DeviceLog> logs_;
};
```
