Here's an example implementation of the C-based library for managing a dynamic collection of tasks:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Task structure definition
typedef struct {
    int id;
    int priority;
    char status;
    char key[10];
    long offset;
    double value;
    char identifier[20];
} task_t;

// Memory pool mechanism for allocating tasks
#define TASK_POOL_SIZE 10000
static task_t *task_pool = NULL;

// Custom memory allocator optimized for large datasets
void *allocate_task(size_t size) {
    if (size > TASK_POOL_SIZE) {
        return malloc(size);
    } else {
        task_t *task = task_pool;
        task_pool += size;
        return task;
    }
}

// Memory pool mechanism for deallocating tasks
void free_task(task_t *task) {
    if (task == NULL) {
        return;
    } else if (task->id < TASK_POOL_SIZE) {
        task_pool -= task->id;
    } else {
        free(task);
    }
}

// Robust seed management system for consistent test environments
void set_seed(unsigned int seed) {
    srand(seed);
}

// Library initialization function
void init_library() {
    // Initialize task pool with random values within specified ranges
    for (int i = 0; i < TASK_POOL_SIZE; i++) {
        task_t *task = allocate_task(sizeof(task_t));
        task->id = rand() % 10000;
        task->priority = rand() % 10;
        task->status = 'A';
        strcpy(task->key, "key");
        task->offset = rand() % 1000000;
        task->value = (double)rand() / RAND_MAX;
        strcpy(task->identifier, "identifier");
    }
}

// Library shutdown function
void shutdown_library() {
    // Release all allocated memory when the collection is no longer required
    for (int i = 0; i < TASK_POOL_SIZE; i++) {
        free_task(task_pool[i]);
    }
}

// Custom hashing function for string fields to expedite duplicate checks during insertion
unsigned int hash_string(const char *str) {
    unsigned int hash = 0;
    while (*str != '\0') {
        hash = (hash << 5) - hash + *str++;
    }
    return hash;
}

// Hybrid data structure combining array-based and linked-list approaches to minimize memory footprint while maintaining efficient access patterns
typedef struct {
    task_t **tasks;
    int size;
    int capacity;
} task_array_t;

task_array_t *create_task_array(int capacity) {
    task_array_t *array = malloc(sizeof(task_array_t));
    array->tasks = malloc(capacity * sizeof(task_t *));
    array->size = 0;
    array->capacity = capacity;
    return array;
}

void add_task(task_array_t *array, task_t *task) {
    if (array->size == array->capacity) {
        // Resize the array to accommodate more tasks
        int new_capacity = array->capacity * 2;
        array->tasks = realloc(array->tasks, new_capacity * sizeof(task_t *));
        array->capacity = new_capacity;
    }
    // Add the task to the end of the array
    array->tasks[array->size++] = task;
}

void remove_task(task_array_t *array, int index) {
    if (index < 0 || index >= array->size) {
        return;
    }
    // Shift the tasks to the left of the specified index
    for (int i = index; i < array->size - 1; i++) {
        array->tasks[i] = array->tasks[i + 1];
    }
    // Decrement the size of the array
    array->size--;
}

// Indexing strategy for rapid updates and deletions
typedef struct {
    task_t **tasks;
    int *indices;
    int size;
    int capacity;
} task_index_t;

task_index_t *create_task_index(int capacity) {
    task_index_t *index = malloc(sizeof(task_index_t));
    index->tasks = malloc(capacity * sizeof(task_t *));
    index->indices = malloc(capacity * sizeof(int));
    index->size = 0;
    index->capacity = capacity;
    return index;
}

void add_task_to_index(task_index_t *index, task_t *task) {
    if (index->size == index->capacity) {
        // Resize the index to accommodate more tasks
        int new_capacity = index->capacity * 2;
        index->tasks = realloc(index->tasks, new_capacity * sizeof(task_t *));
        index->indices = realloc(index->indices, new_capacity * sizeof(int));
        index->capacity = new_capacity;
    }
    // Add the task to the end of the index
    index->tasks[index->size] = task;
    index->indices[index->size++] = index->size - 1;
}

void remove_task_from_index(task_index_t *index, int index) {
    if (index < 0 || index >= index->size) {
        return;
    }
    // Shift the tasks to the left of the specified index
    for (int i = index; i < index->size - 1; i++) {
        index->tasks[i] = index->tasks[i + 1];
        index->indices[i] = index->indices[i + 1];
    }
    // Decrement the size of the index
    index->size--;
}

// Tiered indexing strategy to balance indexing complexity and performance gains
typedef struct {
    task_index_t *indices;
    int size;
    int capacity;
} task_tiered_index_t;

task_tiered_index_t *create_task_tiered_index(int capacity) {
    task_tiered_index_t *index = malloc(sizeof(task_tiered_index_t));
    index->indices = malloc(capacity * sizeof(task_index_t *));
    index->size = 0;
    index->capacity = capacity;
    return index;
}

void add_task_to_tiered_index(task_tiered_index_t *index, task_t *task) {
    if (index->size == index->capacity) {
        // Resize the tiered index to accommodate more tasks
        int new_capacity = index->capacity * 2;
        index->indices = realloc(index->indices, new_capacity * sizeof(task_index_t *));
        index->capacity = new_capacity;
    }
    // Add the task to a new index if it does not exist in any existing index
    int i;
    for (i = 0; i < index->size; i++) {
        if (index->indices[i]->size == 0) {
            break;
        }
    }
    if (i == index->size) {
        // Create a new index if the task does not exist in any existing index
        task_index_t *new_index = create_task_index(10);
        add_task_to_index(new_index, task);
        index->indices[index->size++] = new_index;
    } else {
        // Add the task to an existing index if it exists
        add_task_to_index(index->indices[i], task);
    }
}

void remove_task_from_tiered_index(task_tiered_index_t *index, int index) {
    if (index < 0 || index >= index->size) {
        return;
    }
    // Remove the task from the specified index
    remove_task_from_index(index->indices[index], index);
