    // Split the line into individual fields using delimiter ','
    char* tokens[3];
    int tokenCount = 0;
    for (int i = 0; i < strlen(line); i++) {
        if (line[i] == ',') {
            tokens[tokenCount++] = line + i + 1;
        }
