    int maxCount = 0;
    char* mostFrequentAction = NULL;
    for (int i = 0; i < strlen(actions); i++) {
        if (actions[i] == '|') {
            int count = atoi(actions + i + 1);
            if (count > maxCount) {
                mostFrequentAction = actions + i + 1;
                maxCount = count;
            }
        }
    }
    entry->most_frequent_action = strdup(mostFrequentAction);
}

