    int totalSessionDuration = 0;
    char* mostFrequentAction = NULL;
    for (int i = 0; i < entryCount; i++) {
        struct LogEntry* entry = &entries[i];
        totalSessionDuration += entry->session_duration;
        if (mostFrequentAction == NULL || strcmp(entry->most_frequent_action, mostFrequentAction) > 0) {
            mostFrequentAction = entry->most_frequent_action;
        }
    }
    printf("Average session duration: %d\n", totalSessionDuration / entryCount);
    printf("Most frequent action: %s\n", mostFrequentAction);

    // Free memory for log entries
