    // Check if the task pool is full
    if (taskPoolIndex >= TASK_POOL_SIZE) {
        handleError("Task pool is full");
        return -1;
    }

    // Add the task to the pool and update the index
    taskPool[taskPoolIndex] = task;
    int priority = task.priority;
    TaskList* list = &taskIndices[priority];
    if (list->size == 0) {
        list->head = &taskPool[taskPoolIndex];
        list->tail = &taskPool[taskPoolIndex];
    } else {
        list->tail->next = &taskPool[taskPoolIndex];
        list->tail = &taskPool[taskPoolIndex];
    }
    list->size++;
    taskPoolIndex++;
    return 0;
}

