            *current = task;
            return 0;
        }
        current = current->next;
    }
    handleError("Task not found");
    return -1;
}

Task* retrieveTask(int priority) {
    // Check if the priority is valid
    if (priority < 0 || priority >= TIERED_INDEXING_LEVELS) {
        handleError("Invalid priority");
        return NULL;
    }

    // Retrieve the task from the pool and update the index
    TaskList* list = &taskIndices[priority];
    if (list->size == 0) {
        return NULL;
    }
    Task* current = list->head;
    while (current != NULL) {
        if (current->id == task.id) {
            // Update the index and return the task
            list->head = current->next;
            list->size--;
            return current;
        }
        current = current->next;
    }
    handleError("Task not found");
    return NULL;
}

