    if (priority < 0 || priority >= TIERED_INDEXING_LEVELS || start < 0 || end > list->size) {
        handleError("Invalid priority or range");
        return -1;
    }

    // Retrieve the task list for the given priority and update the index
    TaskList* list = &taskIndices[priority];
    if (list->size == 0) {
        return 0;
    }
    *tasks = list->head + start;
    int count = end - start;
    return count < list->size ? count : list->size;
}

// Define the library functions for aggregation functions on task data
