void init_entries(int values_size, int tags_size, int num_entries) {
    // Validate input parameters
    if (values_size <= 0 || tags_size <= 0 || num_entries <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Allocate memory for the values array
    double *values = malloc(sizeof(double) * values_size);
    if (values == NULL) {
        fprintf(stderr, "Failed to allocate memory for values\n");
        return;
    }

    // Initialize the values array with consecutive doubles starting from 0.0
    for (int i = 0; i < values_size; i++) {
        values[i] = i * 1.0;
    }

    // Allocate memory for the tags array
    char *tags = malloc(sizeof(char) * tags_size);
    if (tags == NULL) {
        fprintf(stderr, "Failed to allocate memory for tags\n");
        free(values);
        return;
    }

    // Initialize the tags array with alternating uppercase and lowercase letters
    char *tag_ptr = tags;
    for (int i = 0; i < tags_size; i++) {
        if (i % 2 == 0) {
            *tag_ptr++ = 'A' + i / 2;
        } else {
            *tag_ptr++ = 'a' + i / 2;
        }
    }

    // Allocate memory for the entries array
    entry_t **entries = malloc(sizeof(entry_t *) * num_entries);
    if (entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for entries\n");
        free(values);
        free(tags);
        return;
    }

    // Initialize the entries array with pointers to the corresponding elements in values and tags
    entry_t *entry_ptr = entries;
    for (int i = 0; i < num_entries; i++) {
        entry_ptr->value = &values[i];
        entry_ptr->tag = &tags[i];
        entry_ptr++;
    }
}

// Define a function to add an entry to the collection of entries
