    if (values_size <= 0 || tags_size <= 0 || num_entries <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Allocate memory for the new entry
    entry_t *new_entry = malloc(sizeof(entry_t));
    if (new_entry == NULL) {
        fprintf(stderr, "Failed to allocate memory for new entry\n");
        return;
    }

    // Initialize the new entry with the given value and tag
    new_entry->value = &values[num_entries];
    new_entry->tag = &tags[num_entries];
    *new_entry->value = value;
    *new_entry->tag = tag;

    // Add the new entry to the entries array
    entries[num_entries] = new_entry;
}

// Define a function to remove an entry from the collection of entries
void remove_entry(int values_size, int tags_size, int num_entries, int index) {
    // Validate input parameters
    if (values_size <= 0 || tags_size <= 0 || num_entries <= 0 || index < 0 || index >= num_entries) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Remove the entry from the entries array
    entry_t *entry = &entries[index];
    free(entry);

    // Compress and reorganize the entries array to reduce fragmentation
    for (int i = index; i < num_entries - 1; i++) {
        entries[i] = entries[i + 1];
    }
}

// Define a function to update an entry in the collection of entries
void update_entry(int values_size, int tags_size, int num_entries, int index, double value, char tag) {
    // Validate input parameters
    if (values_size <= 0 || tags_size <= 0 || num_entries <= 0 || index < 0 || index >= num_entries) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
