    // Validate input parameters
    if (values_size <= 0 || tags_size <= 0 || num_entries <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Traverse the entries array and perform the operation on each entry
    for (int i = 0; i < num_entries; i++) {
        entry_t *entry = &entries[i];
        (*operation)(*entry->value, *entry->tag);
    }
}
