#include <pthread.h>
#include <errno.h>

// Define the record structure
typedef struct {
    long offset;
    int* key;
    int ref_count;
} Record;

// Define the collection structure
typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} Collection;

// Initialize a new collection with the given capacity
Collection* collection_init(size_t capacity) {
    Collection* col = malloc(sizeof(Collection));
    if (!col) {
        fprintf(stderr, "Error: failed to allocate memory for collection\n");
        return NULL;
    }
    col->records = calloc(capacity, sizeof(Record*));
    if (!col->records) {
        fprintf(stderr, "Error: failed to allocate memory for record array\n");
        free(col);
        return NULL;
    }
    col->capacity = capacity;
    col->size = 0;
    pthread_mutex_init(&col->mutex, NULL);
    return col;
}

// Add a new record to the collection
int collection_add(Collection* col, long offset, int key) {
    if (!col || !key) {
        fprintf(stderr, "Error: invalid arguments\n");
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    // Check if the collection is full
    if (col->size == col->capacity) {
        fprintf(stderr, "Error: collection is full\n");
        pthread_mutex_unlock(&col->mutex);
        return -1;
    }
    // Allocate memory for the new record
    Record* rec = malloc(sizeof(Record));
    if (!rec) {
        fprintf(stderr, "Error: failed to allocate memory for record\n");
        pthread_mutex_unlock(&col->mutex);
        return -1;
    }
    // Initialize the new record
    rec->offset = offset;
    rec->key = key;
    rec->ref_count = 0;
    // Add the new record to the collection
    col->records[col->size++] = rec;
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Remove a record from the collection by its key
int collection_remove(Collection* col, int key) {
    if (!col || !key) {
        fprintf(stderr, "Error: invalid arguments\n");
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    // Find the record with the given key
    for (size_t i = 0; i < col->size; i++) {
        if (col->records[i]->key == key) {
            // Decrement the reference count of the record
            col->records[i]->ref_count--;
            // If the reference count is zero, free the record
            if (col->records[i]->ref_count == 0) {
                free(col->records[i]);
                col->records[i] = NULL;
            }
            break;
        }
    }
    // If no record was found, return an error
    if (i == col->size) {
        fprintf(stderr, "Error: key not found\n");
        pthread_mutex_unlock(&col->mutex);
        return -1;
    }
    // Remove the record from the collection
    for (size_t j = i + 1; j < col->size; j++) {
        col->records[j - 1] = col->records[j];
    }
    col->size--;
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Increment the reference count of a record by its key
int collection_inc(Collection* col, int key) {
    if (!col || !key) {
        fprintf(stderr, "Error: invalid arguments\n");
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    // Find the record with the given key
    for (size_t i = 0; i < col->size; i++) {
        if (col->records[i]->key == key) {
            // Increment the reference count of the record
            col->records[i]->ref_count++;
            break;
        }
    }
    // If no record was found, return an error
    if (i == col->size) {
        fprintf(stderr, "Error: key not found\n");
        pthread_mutex_unlock(&col->mutex);
        return -1;
    }
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Decrement the reference count of a record by its key
int collection_dec(Collection* col, int key) {
    if (!col || !key) {
        fprintf(stderr, "Error: invalid arguments\n");
        return -1;
    }
    pthread_mutex_lock(&col->mutex);
    // Find the record with the given key
    for (size_t i = 0; i < col->size; i++) {
        if (col->records[i]->key == key) {
            // Decrement the reference count of the record
            col->records[i]->ref_count--;
            break;
        }
    }
    // If no record was found, return an error
    if (i == col->size) {
        fprintf(stderr, "Error: key not found\n");
        pthread_mutex_unlock(&col->mutex);
        return -1;
    }
    // If the reference count is zero, free the record
    if (col->records[i]->ref_count == 0) {
        free(col->records[i]);
        col->records[i] = NULL;
    }
    pthread_mutex_unlock(&col->mutex);
    return 0;
}

// Free the memory allocated for a collection
void collection_free(Collection* col) {
    if (!col) {
        fprintf(stderr, "Error: invalid arguments\n");
        return;
    }
    pthread_mutex_lock(&col->mutex);
    // Free the memory allocated for each record
    for (size_t i = 0; i < col->size; i++) {
        free(col->records[i]);
    }
    // Free the memory allocated for the record array
    free(col->records);
    // Free the mutex
    pthread_mutex_destroy(&col->mutex);
    // Free the collection structure itself
    free(col);
}
