    // Check if there is enough memory to allocate a new entry
    if (dataset.total_keys == dataset.records->size) {
        // Reallocate the memory for the dataset with double the size
        dataset.records = realloc(dataset.records, 2 * dataset.records->size);
        if (dataset.records == NULL) {
            printf("Error: Failed to reallocate memory\n");
            exit(1);
