    // Check if the index is valid
    if (index >= dataset.total_keys) {
        printf("Error: Invalid index\n");
        exit(1);
    }
    // Update the entry in the dataset
    dataset.records[index].pdu = *pdu;
    memcpy(dataset.records[index].offsets, offsets, 10);
    memcpy(dataset.records[index].keys, keys, 10);
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve an entry from the dataset by index
NFAPI_CRC_INDICATION_PDU_T *get_entry(int index) {
    pthread_mutex_lock(&mutex);
    // Check if the index is valid
    if (index >= dataset.total_keys) {
        printf("Error: Invalid index\n");
        exit(1);
