#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure to represent a task
typedef struct {
    char name[256];
    int priority;
    enum status { ACTIVE, COMPLETED, PENDING } status;
    char description[1024];
    time_t start_time;
    time_t due_time;
} task;

// Define a hash table to store tasks
typedef struct {
    int size;
    task** buckets;
} htable;

// Function to initialize the hash table
void init_htable(htable* ht) {
    // Allocate memory for the hash table and its buckets
    ht->size = 1024;
    ht->buckets = (task**)malloc(sizeof(task*) * ht->size);
    if (!ht->buckets) {
        printf("Error: unable to allocate memory for the hash table\n");
        exit(1);
    }
}

// Function to insert a task into the hash table
void insert_task(htable* ht, task* t) {
    // Calculate the hash value for the task's priority and status
    int hash = (t->priority * 31 + t->status) % ht->size;
    // Check if there is already a task with the same priority and status in the bucket
    if (ht->buckets[hash] && strcmp(ht->buckets[hash]->name, t->name) == 0) {
        printf("Error: unable to insert task %s into the hash table\n", t->name);
        return;
    }
    // Insert the task into the bucket
    ht->buckets[hash] = t;
}

// Function to delete a task from the hash table
void delete_task(htable* ht, char* name) {
    // Calculate the hash value for the task's priority and status
    int hash = (name * 31 + ACTIVE) % ht->size;
    // Check if there is a task with the same priority and status in the bucket
    if (!ht->buckets[hash] || strcmp(ht->buckets[hash]->name, name) != 0) {
        printf("Error: unable to delete task %s from the hash table\n", name);
        return;
    }
    // Delete the task from the bucket
    ht->buckets[hash] = NULL;
}

// Function to search for a task in the hash table
task* search_task(htable* ht, char* name) {
    // Calculate the hash value for the task's priority and status
    int hash = (name * 31 + ACTIVE) % ht->size;
    // Check if there is a task with the same priority and status in the bucket
    if (!ht->buckets[hash] || strcmp(ht->buckets[hash]->name, name) != 0) {
        return NULL;
    }
    // Return the task from the bucket
    return ht->buckets[hash];
}

// Function to update a task in the hash table
void update_task(htable* ht, char* name, int priority, enum status status) {
    // Calculate the hash value for the task's priority and status
    int hash = (name * 31 + status) % ht->size;
    // Check if there is a task with the same priority and status in the bucket
    if (!ht->buckets[hash] || strcmp(ht->buckets[hash]->name, name) != 0) {
        printf("Error: unable to update task %s in the hash table\n", name);
        return;
    }
    // Update the task's priority and status
    ht->buckets[hash]->priority = priority;
    ht->buckets[hash]->status = status;
}

// Function to print a task in the hash table
void print_task(htable* ht, char* name) {
    // Calculate the hash value for the task's priority and status
    int hash = (name * 31 + ACTIVE) % ht->size;
    // Check if there is a task with the same priority and status in the bucket
    if (!ht->buckets[hash] || strcmp(ht->buckets[hash]->name, name) != 0) {
        printf("Error: unable to print task %s from the hash table\n", name);
        return;
    }
    // Print the task's information
    printf("%s: priority = %d, status = %s\n", ht->buckets[hash]->name, ht->buckets[hash]->priority, get_status_string(ht->buckets[hash]->status));
}

// Function to print all tasks in the hash table
void print_all_tasks(htable* ht) {
    // Iterate over each bucket in the hash table
    for (int i = 0; i < ht->size; i++) {
        // Check if there is a task in the bucket
        if (ht->buckets[i]) {
            // Print the task's information
            printf("%s: priority = %d, status = %s\n", ht->buckets[i]->name, ht->buckets[i]->priority, get_status_string(ht->buckets[i]->status));
        }
    }
}

// Function to free the memory allocated for the hash table and its buckets
void free_htable(htable* ht) {
    // Iterate over each bucket in the hash table
    for (int i = 0; i < ht->size; i++) {
        // Check if there is a task in the bucket
        if (ht->buckets[i]) {
            // Free the memory allocated for the task
            free(ht->buckets[i]);
        }
    }
    // Free the memory allocated for the hash table and its buckets
    free(ht->buckets);
}
```
This code defines a `task` structure to represent a task with a name, priority, status, description, start time, and due time. It also defines a `htable` structure to store tasks in a hash table, which is used to facilitate efficient insertion, deletion, and searching based on priority and status. The `init_htable`, `insert_task`, `delete_task`, `search_task`, `update_task`, `print_task`, and `print_all_tasks` functions are implemented to perform the corresponding operations on the hash table. The `free_htable` function is also implemented to free the memory allocated for the hash table and its buckets.

The code also includes a `get_status_string` function to convert an enum value representing the status of a task into a string representation, which is used in the `print_task` function to print the task's information.

Note that this code assumes that the tasks are stored in the hash table using the `name` field as the key, and that the `priority` and `status` fields are used to determine the position of a task in the hash table. If the tasks are stored in the hash table using other fields or methods, the code will need to be modified accordingly.']

