#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <limits.h>
#include <stdbool.h>

#define MAX_FILES 500
#define BUFFER_SIZE 4096

struct file_info {
    char *filename;
    int fd;
    off_t size;
};

void print_usage(char *progname) {
    printf("Usage: %s [-cs] [-o <output_file>] [input_files...]\n", progname);
}

int main(int argc, char **argv) {
    int i;
    struct file_info files[MAX_FILES];
    bool print_char_count = false;
    char *output_file = NULL;

    // Parse command-line arguments
    for (i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-cs")) {
            print_char_count = true;
        } else if (!strcmp(argv[i], "-o")) {
            output_file = argv[++i];
        } else {
            files[i].filename = argv[i];
            files[i].fd = open(files[i].filename, O_RDONLY);
            if (files[i].fd == -1) {
                perror("open");
                return 1;
            }
        }
    }

    // Check for invalid filenames or unsupported command-line options
    if (i > MAX_FILES) {
        printf("Too many input files specified\n");
        return 1;
    } else if (!print_char_count && !output_file) {
        print_usage(argv[0]);
        return 1;
    }

    // Initialize file information and counters
    for (i = 0; i < MAX_FILES; i++) {
        files[i].size = 0;
    }
    off_t total_lines = 0;
    off_t total_chars = 0;

    // Process input files line by line and calculate character count
    for (i = 0; i < MAX_FILES; i++) {
        if (!files[i].filename) break;
        char buffer[BUFFER_SIZE];
        ssize_t bytes_read;
        while ((bytes_read = read(files[i].fd, buffer, BUFFER_SIZE)) > 0) {
            total_lines++;
            total_chars += bytes_read;
            if (print_char_count) printf("%ld\n", (long)total_chars);
        }
    }

    // Write aggregated results to output file
    if (output_file) {
        int fd = open(output_file, O_WRONLY | O_CREAT, 0644);
        if (fd == -1) {
            perror("open");
            return 1;
        }
        ssize_t bytes_written = write(fd, &total_lines, sizeof(off_t));
        if (bytes_written != sizeof(off_t)) {
            perror("write");
            close(fd);
            return 1;
        }
        close(fd);
    }

    // Close input files and free memory
    for (i = 0; i < MAX_FILES; i++) {
        if (!files[i].filename) break;
        close(files[i].fd);
    }

    return 0;
}
