            profiles[i]->preferences[j] = newPreferences[j];
        }
    }
}

// Define a function to free the memory allocated for the table of user profiles
void freeProfiles(Profile** profiles, int numProfiles) {
    // Check if the input is valid
    if (!profiles || numProfiles <= 0 || numProfiles > 100000) {
        return;
    }

    // Free each profile's memory
    for (int i = 0; i < numProfiles; i++) {
        free(profiles[i]->name);
        free(profiles[i]->email);
        free(profiles[i]);
    }

    // Free the memory allocated for the table of profiles
    free(profiles);
}
