// Define the mutex for synchronizing access to the hash table
static pthread_mutex_t profile_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the function to update a user's preferences
void update_preferences(UserProfile *profile, char *new_preferences) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&profile_lock);

    // Update the preferences field of the profile
    free(profile->preferences);
    profile->preferences = strdup(new_preferences);

    // Release the lock on the hash table
    pthread_mutex_unlock(&profile_lock);
}

// Define the function to batch update preferences for multiple profiles
void batch_update_preferences(UserProfile **profiles, size_t num_profiles) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&profile_lock);

    // Update the preferences field of each profile in the batch
    for (size_t i = 0; i < num_profiles; ++i) {
        UserProfile *profile = profiles[i];
        free(profile->preferences);
        profile->preferences = strdup(new_preferences);
    }

    // Release the lock on the hash table
    pthread_mutex_unlock(&profile_lock);
}

