#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Custom data structures
struct DataPacket {
    long packetID;
    time_t timestamp;
    struct DataChunk {
        int sequenceNumber;
        size_t payloadSize;
        void* payload;
    } chunk;
};

struct LogRecord {
    int logLevel;
    char message[256];
};

// Global variables
const long MAX_PACKETS = 1000000; // Maximum number of packets to store
const int MAX_TIMESTAMPS = 500000; // Maximum number of unique timestamps to store
const int INITIAL_LOG_RECORDS = 50000; // Initial capacity for LogRecord array
const int LOG_RECORD_INCREMENT = 5000; // Increment for expanding LogRecord array
const size_t MAX_MEMORY_USAGE = 100 * 1024 * 1024; // Maximum memory usage (in bytes)

// Function prototypes
void initLogRecords(struct LogRecord** logRecords, int capacity);
void addPacket(struct DataPacket* packet, struct LogRecord** logRecords, long* offsetArray, int* timestampArray);
void updateLogRecords(struct LogRecord** logRecords, int* logLevels, char** messages);
void serializeLogRecords(struct LogRecord** logRecords, FILE* file);

// Main function
int main() {
    // Initialize data structures
    struct DataPacket* packets = malloc(MAX_PACKETS * sizeof(struct DataPacket));
    struct LogRecord** logRecords = malloc(INITIAL_LOG_RECORDS * sizeof(struct LogRecord*));
    long* offsetArray = malloc(MAX_PACKETS * sizeof(long));
    int* timestampArray = malloc(MAX_TIMESTAMPS * sizeof(int));
    initLogRecords(logRecords, INITIAL_LOG_RECORDS);

    // Initialize thread-safe variables
    pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t logCond = PTHREAD_COND_INITIALIZER;

    // Start data processing loop
    while (1) {
        // Wait for new packet or log record
        pthread_mutex_lock(&logMutex);
        while (!(pthread_cond_wait(&logCond, &logMutex))) {
            if (packets[0].packetID != 0) {
                addPacket(&packets[0], logRecords, offsetArray, timestampArray);
                packets[0] = packets[1];
                packets[1] = packets[2];
                packets[2] = packets[3];
                packets[3] = packets[4];
                packets[4] = { 0 };
            }
        }
        pthread_mutex_unlock(&logMutex);

        // Update log records
        updateLogRecords(logRecords, &logLevels, &messages);
    }

    // Serialize log records to file
    serializeLogRecords(logRecords, "output.txt");

    // Clean up
    free(packets);
    free(offsetArray);
    free(timestampArray);
    free(logRecords);

    return 0;
}

// Initialize log records array with initial capacity
void initLogRecords(struct LogRecord** logRecords, int capacity) {
    for (int i = 0; i < capacity; i++) {
        logRecords[i] = malloc(sizeof(struct LogRecord));
        logRecords[i]->logLevel = -1;
        logRecords[i]->message[0] = '\0';
    }
}

// Add packet to data structures and update log records
void addPacket(struct DataPacket* packet, struct LogRecord** logRecords, long* offsetArray, int* timestampArray) {
    // Check for memory allocation failures
    if (packets[0].packetID == 0) {
        printf("Memory allocation failure: unable to add packet\n");
        return;
    }

    // Add packet to data structures
    packets[0] = *packet;
    offsetArray[0] = packet->chunk.payloadSize;
    timestampArray[0] = packet->timestamp;

    // Update log records
    updateLogRecords(logRecords, &logLevels, &messages);
}

// Update log records based on new data
void updateLogRecords(struct LogRecord** logRecords, int* logLevels, char** messages) {
    // Check for memory allocation failures
    if (logRecords[0]->logLevel == -1) {
        printf("Memory allocation failure: unable to update log records\n");
        return;
    }

    // Update log levels and messages
    for (int i = 0; i < MAX_PACKETS; i++) {
        if (packets[i].packetID != 0) {
            logLevels[i] = packets[i].chunk.sequenceNumber % 10;
            strcpy(messages[i], "Packet received");
        } else {
            logLevels[i] = -1;
            messages[i][0] = '\0';
        }
    }
}

// Serialize log records to file
void serializeLogRecords(struct LogRecord** logRecords, FILE* file) {
    // Check for memory allocation failures
    if (logRecords[0]->logLevel == -1) {
        printf("Memory allocation failure: unable to serialize log records\n");
        return;
    }

    // Serialize log records to file
    fprintf(file, "Log Records:\n");
    for (int i = 0; i < MAX_PACKETS; i++) {
        if (logRecords[i]->logLevel != -1) {
            fprintf(file, "%d: %s\n", logRecords[i]->logLevel, logRecords[i]->message);
        }
    }
}
