import java.io.*;
import java.util.*;
import java.security.MessageDigest;

public class SensorDataProcessor {
    private static final int MIN_SIGNAL_STRENGTH = 0;
    private static final int MAX_SIGNAL_STRENGTH = 100;
    private static final int MIN_TIMESTAMP = 0;
    private static final int MAX_TIMESTAMP = 1000000000;
    private static final int MIN_SENSOR_ID = 0;
    private static final int MAX_SENSOR_ID = 500000;
    private static final int INITIAL_READING_CAPACITY = 10000;
    private static final int GROWTH_FACTOR = 1000;

    public static void processAndAggregateSensorData(String inputFile, String outputFile, String rules, int maxThreshold, double minSignalStrength, boolean enableCloudStorage) {
        // Initialize variables and data structures
        List<SensorReading> readings = new ArrayList<>();
        Map<Integer, SensorReading> sensorIdMap = new HashMap<>();
        Map<Integer, Integer> locationCodeMap = new HashMap<>();
        int numAnomalies = 0;
        long startTime = System.currentTimeMillis();

        // Parse input file and populate readings list
        try (BufferedReader reader = new BufferedReader(new FileReader(inputFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] tokens = line.split(",");
                int sensorId = Integer.parseInt(tokens[0]);
                long timestamp = Long.parseLong(tokens[1]);
                double signalStrength = Double.parseDouble(tokens[2]);
                int locationCode = Integer.parseInt(tokens[3]);
                boolean anomalyStatus = Boolean.parseBoolean(tokens[4]);

                // Check if sensor ID and location code are unique
                if (!sensorIdMap.containsKey(sensorId) && !locationCodeMap.containsKey(locationCode)) {
                    SensorReading reading = new SensorReading(sensorId, timestamp, signalStrength, anomalyStatus, locationCode);
                    readings.add(reading);
                    sensorIdMap.put(sensorId, reading);
                    locationCodeMap.put(locationCode, reading);
                }
            }
        } catch (IOException e) {
            System.out.println("Error parsing input file: " + e.getMessage());
            return;
        }

        // Apply data processing rules and update anomaly status
        for (SensorReading reading : readings) {
            if (reading.getSignalStrength() < minSignalStrength) {
                reading.setAnomalyStatus(true);
            } else if (reading.getSignalStrength() > maxThreshold) {
                reading.setAnomalyStatus(false);
            }
        }

        // Generate output file and append MD5 hash
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(outputFile))) {
            for (SensorReading reading : readings) {
                String line = String.format("%d,%d,%f,%b,%d\n", reading.getSensorId(), reading.getTimestamp(), reading.getSignalStrength(), reading.isAnomalyStatus(), reading.getLocationCode());
                writer.write(line);
            }
            byte[] hash = MessageDigest.getInstance("MD5").digest(outputFile.getBytes());
            String md5Hash = new BigInteger(1, hash).toString(16);
            writer.write(String.format("MD5 Hash: %s\n", md5Hash));
        } catch (IOException | NoSuchAlgorithmException e) {
            System.out.println("Error generating output file or computing MD5 hash: " + e.getMessage());
            return;
        }

        // Clean up resources and print performance metrics
        long endTime = System.currentTimeMillis();
        double processingTime = (endTime - startTime) / 1000.0;
        System.out.println("Processed " + readings.size() + " sensor readings in " + processingTime + " seconds");
    }
}
