void manageDataStreamsAndLoadState(State *state) {
    // Initialize the mutexes and semaphores for each data stream
    pthread_mutex_init(&state->streams, NULL);
    sem_init(&state->semaphore, 0, 1);

    // Dynamically allocate memory for the state object
    state->streams = malloc(sizeof(pthread_mutex_t) * MAX_STREAMS);
    state->offsets = malloc(sizeof(long) * MAX_STREAMS);
    state->max_sizes = malloc(sizeof(int) * MAX_STREAMS);

    // Initialize the data structures for each data stream
    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_mutex_init(&state->streams[i], NULL);
        state->offsets[i] = 0;
        state->max_sizes[i] = DEFAULT_MAX_SIZE;
    }

    // Load the initial state from disk
    loadState(state);

    // Start the data stream processing threads
    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_create(&state->threads[i], NULL, processDataStream, &state->streams[i]);
    }
}

// Define the function for processing a data stream
void *processDataStream(void *arg) {
    // Get the data stream and its corresponding state object
    pthread_mutex_t *stream = (pthread_mutex_t *) arg;
    State *state = (State *) stream->data;

    // Loop until the end of the data stream is reached
    while (1) {
        // Acquire the lock for the data stream
        pthread_mutex_lock(stream);

        // Check if the data stream has been closed
        if (state->closed) {
            break;
        }

        // Read the next record from the data stream
        Record *record = readRecord(stream, state->offsets[i]);

        // Update the offset value for the data stream
        state->offsets[i] += sizeof(Record);

        // Process the record and update the state object
        processRecord(record, state);

        // Release the lock for the data stream
        pthread_mutex_unlock(stream);
    }

    // Close the data stream
    closeDataStream(stream);

    return NULL;
}

// Define the function for processing a record
void processRecord(Record *record, State *state) {
    // Update the state object with the new record
    updateState(record, state);

    // Flush the state to disk periodically
    if (state->offsets[i] % FLUSH_INTERVAL == 0) {
        flushState(state);
    }
}

// Define the function for updating the state object with a new record
void updateState(Record *record, State *state) {
    // Update the state object with the new record
    state->records[i] = record;
}

// Define the function for flushing the state to disk
void flushState(State *state) {
    // Write the state object to disk
    writeState(state);

    // Reset the offset values for each data stream
    for (int i = 0; i < MAX_STREAMS; i++) {
        state->offsets[i] = 0;
    }
}

// Define the function for writing the state object to disk
void writeState(State *state) {
    // Open the file for writing
    FILE *file = fopen("state.dat", "wb");

    // Write the state object to the file
    fwrite(state, sizeof(State), 1, file);

    // Close the file
    fclose(file);
}

// Define the function for reading a record from a data stream
Record *readRecord(pthread_mutex_t *stream, long offset) {
    // Acquire the lock for the data stream
    pthread_mutex_lock(stream);

    // Read the next record from the data stream
    Record *record = (Record *) malloc(sizeof(Record));
    fread(record, sizeof(Record), 1, stream->data);

    // Release the lock for the data stream
    pthread_mutex_unlock(stream);

    return record;
}

// Define the function for closing a data stream
void closeDataStream(pthread_mutex_t *stream) {
    // Acquire the lock for the data stream
    pthread_mutex_lock(stream);

    // Close the data stream
    fclose(stream->data);

    // Release the lock for the data stream
    pthread_mutex_unlock(stream);
}
