// Function to manage an array of Node pointers, ensuring thread safety and memory management
void manageNodes(std::vector<Node*>& nodes) {
    // Use a mutex to synchronize access to the vector of nodes
    std::mutex mtx;
    mtx.lock();

    // Iterate over each node in the vector, reclaiming unused memory and updating capacity
    for (int i = 0; i < nodes.size(); ++i) {
        Node* node = nodes[i];
        if (node->queries.empty()) {
            // If the node has no queries, reclaim its memory
            delete node;
            nodes[i] = nullptr;
        } else {
            // Update the capacity of the node based on the number of queries it contains
            node->cap = node->queries.size();
