// Define the task structure
typedef struct Task {
    int id;
    int priority;
    char status;
    char key[10];
    long offset;
    double value;
    char identifier[20];
} Task;

// Define the memory pool structure
typedef struct MemoryPool {
    size_t size;
    void* data;
} MemoryPool;

// Define the custom hashing function for string fields
unsigned long hash(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++) != '\0') {
        hash = ((hash << 5) + hash) + c;
    }
    return hash;
}

// Define the task list structure
typedef struct TaskList {
    size_t size;
    size_t capacity;
    Task* tasks;
} TaskList;

// Initialize a memory pool with a given size
MemoryPool initMemoryPool(size_t size) {
    MemoryPool pool = {size, malloc(size)};
    return pool;
}

// Allocate memory for a task in the memory pool
Task* allocateTask(MemoryPool* pool) {
    Task* task = (Task*)pool->data;
    pool->data += sizeof(Task);
    pool->size -= sizeof(Task);
    return task;
}

// Initialize a task structure with random values within specified ranges
void initTask(Task* task, int id_min, int id_max, int priority_min, int priority_max, char status_min, char status_max, const char* key_min, const char* key_max, long offset_min, long offset_max, double value_min, double value_max, const char* identifier_min, const char* identifier_max) {
    task->id = rand() % (id_max - id_min + 1) + id_min;
    task->priority = rand() % (priority_max - priority_min + 1) + priority_min;
    task->status = rand() % (status_max - status_min + 1) + status_min;
    strcpy(task->key, key_min);
    task->offset = rand() % (offset_max - offset_min + 1) + offset_min;
    task->value = rand() % (value_max - value_min + 1) + value_min;
    strcpy(task->identifier, identifier_min);
}

// Initialize a seed for deterministic random number generation
void initSeed(unsigned int seed) {
    srand(seed);
}

// Insert a task into the list
bool insertTask(TaskList* list, Task* task) {
    // Check if the list is full
    if (list->size == list->capacity) {
        return false;
    }

    // Allocate memory for the task in the memory pool
    Task* new_task = allocateTask(&list->pool);
    if (!new_task) {
        return false;
    }

    // Copy the task data into the new memory location
    memcpy(new_task, task, sizeof(Task));

    // Add the new task to the list
    list->tasks[list->size++] = *new_task;

    return true;
}

// Remove a task from the list by its ID
bool removeTaskById(TaskList* list, int id) {
    // Find the index of the task with the given ID
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->tasks[i].id == id) {
            break;
        }
    }

    // Check if the task was found
    if (i == list->size) {
        return false;
    }

    // Remove the task from the list
    Task* removed_task = &list->tasks[i];
    memmove(removed_task, removed_task + 1, sizeof(Task) * (list->size - i - 1));
    list->size--;

    return true;
}

// Update a task in the list by its ID
bool updateTaskById(TaskList* list, int id, Task* new_task) {
    // Find the index of the task with the given ID
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->tasks[i].id == id) {
            break;
        }
    }

    // Check if the task was found
    if (i == list->size) {
        return false;
    }

    // Update the task in the list
    Task* updated_task = &list->tasks[i];
    memcpy(updated_task, new_task, sizeof(Task));

    return true;
}

