// Define the structure for sensor log entries
struct sensor_log {
    int timestamp;
    double *values;
    int state;
};

// Define a function to allocate memory for an array of struct sensor_log pointers
void alloc_sensor_logs(int num_logs, struct sensor_log **logs) {
    // Allocate memory for the array of struct sensor_log pointers
    *logs = (struct sensor_log *)malloc(num_logs * sizeof(struct sensor_log));
    if (*logs == NULL) {
        printf("Error: Failed to allocate memory for sensor logs\n");
        exit(1);
    }

    // Initialize each struct sensor_log entry with a random timestamp and state
    for (int i = 0; i < num_logs; i++) {
        (*logs)[i].timestamp = rand() % 24 * 3600;
        (*logs)[i].state = rand() % 6;

        // Allocate memory for the double array values
        int size = (*logs)[i].timestamp * sizeof(double);
        (*logs)[i].values = (double *)malloc(size);
        if ((*logs)[i].values == NULL) {
            printf("Error: Failed to allocate memory for sensor log values\n");
            exit(1);
        }

        // Initialize each value in the double array with a random double within the range of -100.0 to 100.0
        for (int j = 0; j < (*logs)[i].timestamp; j++) {
            (*logs)[i].values[j] = ((double)rand() / RAND_MAX) * 200.0 - 100.0;
        }
    }
}

// Define a function to deallocate memory for an array of struct sensor_log pointers
void free_sensor_logs(int num_logs, struct sensor_log **logs) {
    // Deallocate memory for each double array values
    for (int i = 0; i < num_logs; i++) {
        free((*logs)[i].values);
    }

    // Deallocate memory for the array of struct sensor_log pointers
    free(*logs);
}

// Define a function to manage multiple dynamically allocated structures with varying data types and sizes
void manage_structures(int num_logs, struct sensor_log **logs) {
    // Allocate memory for an array of struct sensor_log pointers
    alloc_sensor_logs(num_logs, logs);

    // Initialize each struct sensor_log entry with a random timestamp and state
    for (int i = 0; i < num_logs; i++) {
        (*logs)[i].timestamp = rand() % 24 * 3600;
        (*logs)[i].state = rand() % 6;

        // Allocate memory for the double array values
        int size = (*logs)[i].timestamp * sizeof(double);
        (*logs)[i].values = (double *)malloc(size);
        if ((*logs)[i].values == NULL) {
            printf("Error: Failed to allocate memory for sensor log values\n");
            exit(1);
        }

        // Initialize each value in the double array with a random double within the range of -100.0 to 100.0
        for (int j = 0; j < (*logs)[i].timestamp; j++) {
            (*logs)[i].values[j] = ((double)rand() / RAND_MAX) * 200.0 - 100.0;
        }
    }
}

// Define a function to deallocate memory for an array of struct sensor_log pointers
void free_structures(int num_logs, struct sensor_log **logs) {
    // Deallocate memory for each double array values
    for (int i = 0; i < num_logs; i++) {
        free((*logs)[i].values);
    }

    // Deallocate memory for the array of struct sensor_log pointers
    free(*logs);
}

// Define a function to aggregate and summarize metrics from an array of struct sensor_log pointers
void aggregate_metrics(int num_logs, struct sensor_log **logs) {
    // Initialize variables to store aggregated metrics
    int total_readings = 0;
    double average_frequency = 0.0;
    int most_common_state = 0;
    int state_count[6] = {0};

    // Iterate over each struct sensor_log entry and update aggregated metrics
    for (int i = 0; i < num_logs; i++) {
        total_readings += (*logs)[i].timestamp;
        average_frequency += ((double)((*logs)[i].timestamp)) / num_logs;
        state_count[(*logs)[i].state]++;
    }

    // Find the most common sensor state observed over time
    for (int i = 0; i < 6; i++) {
        if (state_count[i] > most_common_state) {
            most_common_state = state_count[i];
        }
    }

    // Print the aggregated metrics to the console
    printf("Total readings: %d\n", total_readings);
    printf("Average frequency: %.2f Hz\n", average_frequency);
    printf("Most common state: %d\n", most_common_state);
}

// Define a function to handle potential issues with malformed entries or file read failures gracefully
void error_handling(int num_logs, struct sensor_log **logs) {
    // Check for NULL pointers in the array of struct sensor_log pointers
    if (*logs == NULL) {
        printf("Error: Failed to allocate memory for sensor logs\n");
        exit(1);
    }

    // Iterate over each struct sensor_log entry and check for out-of-bounds accesses
    for (int i = 0; i < num_logs; i++) {
        if ((*logs)[i].values == NULL) {
            printf("Error: Failed to allocate memory for sensor log values\n");
            exit(1);
        }
        for (int j = 0; j < (*logs)[i].timestamp; j++) {
            if ((*logs)[i].values[j] > 100.0 || (*logs)[i].values[j] < -100.0) {
                printf("Error: Out-of-bounds access detected in sensor log values\n");
