Here is a sample Java application that processes large-scale event streaming data in real-time for a financial trading platform:
```java
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class EventStreamProcessor {
  private static final int MAX_SESSIONS = 1000;
  private static final int MAX_EMAIL_LENGTH = 256;
  private static final int MAX_INTERACTION_TIMESTAMPS = 10000;

  private ConcurrentHashMap<String, Session> sessions;
  private ExecutorService executor;

  public EventStreamProcessor() {
    this.sessions = new ConcurrentHashMap<>();
    this.executor = Executors.newFixedThreadPool(MAX_SESSIONS);
  }

  public void processEvent(String event) {
    // Parse the event and extract the session ID, email address, and interaction timestamps
    String sessionId = parseSessionId(event);
    String emailAddress = parseEmailAddress(event);
    List<Long> interactionTimestamps = parseInteractionTimestamps(event);

    // Check if the session exists in the map
    Session session = sessions.get(sessionId);
    if (session == null) {
      // If the session does not exist, create a new one and add it to the map
      session = new Session(sessionId, emailAddress, interactionTimestamps);
      sessions.put(sessionId, session);
    } else {
      // If the session exists, update its email address and interaction timestamps
      session.setEmailAddress(emailAddress);
      session.addInteractionTimestamps(interactionTimestamps);
    }
  }

  public void processEvents(List<String> events) {
    // Process each event in the list concurrently using an executor service
    for (String event : events) {
      executor.execute(() -> processEvent(event));
    }
  }

  public List<Session> getSessions() {
    return new ArrayList<>(sessions.values());
  }

  private String parseSessionId(String event) {
    // Parse the session ID from the event string
    return event.substring(0, event.indexOf(':'));
  }

  private String parseEmailAddress(String event) {
    // Parse the email address from the event string
    return event.substring(event.indexOf(':') + 1);
  }

  private List<Long> parseInteractionTimestamps(String event) {
    // Parse the interaction timestamps from the event string
    String[] timestamps = event.split(",");
    List<Long> result = new ArrayList<>();
    for (String timestamp : timestamps) {
      result.add(Long.parseLong(timestamp));
    }
    return result;
  }

  private class Session {
    private String sessionId;
    private String emailAddress;
    private List<Long> interactionTimestamps;

    public Session(String sessionId, String emailAddress, List<Long> interactionTimestamps) {
      this.sessionId = sessionId;
      this.emailAddress = emailAddress;
      this.interactionTimestamps = interactionTimestamps;
    }

    public void setEmailAddress(String emailAddress) {
      this.emailAddress = emailAddress;
    }

    public void addInteractionTimestamps(List<Long> interactionTimestamps) {
      this.interactionTimestamps.addAll(interactionTimestamps);
    }
  }
}
