    srand(seed);

    // Initialize each task's fields with random values within specified ranges
    for (int i = 0; i < M; i++) {
        tasks[i].id = rand() % 10000;
        tasks[i].priority = rand() % 5;
        tasks[i].status = 'A';
        strcpy(tasks[i].key, "KEY");
        tasks[i].offset = rand() % 1000000;
        tasks[i].value = (double)rand() / RAND_MAX;
        strcpy(tasks[i].identifier, "IDENTIFIER");
    }

