#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // Check if input file is provided
    if (argc < 2) {
        printf("Usage: %s [input_file]\n", argv[0]);
        return 1;
    }

    // Open the input file
    FILE *fp = fopen(argv[1], "r");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    // Initialize variables for counting lines and memory allocation
    int line_count = 0;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    // Read the input file line by line
    while ((read = getline(&line, &len, fp)) != -1) {
        // Increment line count
        line_count++;

        // Split the line into fields using comma as delimiter
        char *fields[3];
        int field_count = 0;
        for (char *token = strtok(line, ","); token != NULL; token = strtok(NULL, ",")) {
            fields[field_count++] = token;
        }

        // Calculate the average of the last two fields
        float avg = 0.0f;
        if (field_count >= 2) {
            avg = atof(fields[field_count - 1]) + atof(fields[field_count - 2]);
            avg /= 2.0f;
        }

        // Print the line in comma-separated format with average
        printf("%s,%.2f\n", fields[0], avg);
    }

    // Free dynamically allocated memory
    free(line);

    // Print total number of lines
    printf("Total lines: %d\n", line_count);

    return 0;
}
