import subprocess
import threading
import time
import logging
import os
import json
from typing import Dict

class SensorReading:
    def __init__(self, sensor_id: int, timestamp: str, temperature: float, humidity: float, pressure: float, coordinates: tuple):
        self.sensor_id = sensor_id
        self.timestamp = timestamp
        self.temperature = temperature
        self.humidity = humidity
        self.pressure = pressure
        self.coordinates = coordinates

class SensorReadingManager:
    def __init__(self, config_file: str):
        self.config_file = config_file
        self.readings = []
        self.lock = threading.Lock()

    def add_reading(self, reading: SensorReading):
        with self.lock:
            self.readings.append(reading)

    def update_reading(self, reading: SensorReading):
        with self.lock:
            for i in range(len(self.readings)):
                if self.readings[i].sensor_id == reading.sensor_id:
                    self.readings[i] = reading
                    break

    def get_readings(self, filter_conditions=None):
        with self.lock:
            readings = []
            for reading in self.readings:
                if filter_conditions is None or self._check_filter_conditions(reading, filter_conditions):
                    readings.append(reading)
            return readings

    def _check_filter_conditions(self, reading: SensorReading, filter_conditions: Dict[str, str]):
        for key, value in filter_conditions.items():
            if not hasattr(reading, key) or getattr(reading, key) != value:
                return False
        return True

    def _update_config_file(self, config_file: str, new_password: str):
        with open(config_file, "r") as f:
            lines = f.readlines()
        for i in range(len(lines)):
            if "password" in lines[i]:
                lines[i] = "password = " + new_password + "\n"
        with open(config_file, "w") as f:
            f.writelines(lines)

    def _handle_sed_command_failure(self, error):
        logging.error("Failed to execute sed command: %s", error)
        raise Exception("Failed to update configuration file")

    def _validate_oauth_request(self, request: Dict[str, str]):
