#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Function to read a CSV file and compute the sum, average, and standard deviation of each column
void read_csv(char* filename) {
  // Open the file for reading
  FILE *file = fopen(filename, "r");
  if (file == NULL) {
    printf("Error: unable to open file %s\n", filename);
    return;
  }

  // Get the number of rows and columns in the file
  int num_rows = 0;
  int num_cols = 0;
  while (fscanf(file, "%*[^\n]") != EOF) {
    num_rows++;
  }
  rewind(file);
  char *line = NULL;
  size_t len = 0;
  ssize_t read;
  while ((read = getline(&line, &len, file)) != -1) {
    num_cols = strtok(line, ",") ? strlen(strtok(line, ",")) : 0;
  }
  free(line);

  // Allocate memory for the row and column headers
  char **row_headers = malloc(num_rows * sizeof(char*));
  if (row_headers == NULL) {
    printf("Error: unable to allocate memory for row headers\n");
    return;
  }
  char **col_headers = malloc(num_cols * sizeof(char*));
  if (col_headers == NULL) {
    printf("Error: unable to allocate memory for column headers\n");
    free(row_headers);
    return;
  }

  // Read the file and compute the sum, average, and standard deviation of each column
  int i = 0;
  while (fscanf(file, "%*[^\n]") != EOF) {
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
      // Skip empty lines and lines with missing values (represented as empty strings)
      if (strlen(line) == 0 || strcmp(line, "") == 0) {
        continue;
      }

      // Get the value for each column in the current row
      char **values = malloc(num_cols * sizeof(char*));
      int j = 0;
      while (j < num_cols) {
        values[j] = strtok(line, ",");
        line = NULL;
        len = 0;
        j++;
      }

      // Compute the sum, average, and standard deviation of each column
      for (int k = 0; k < num_cols; k++) {
        double sum = 0.0;
        int count = 0;
        while (values[k] != NULL) {
          sum += atof(values[k]);
          count++;
          values[k] = strtok(NULL, ",");
        }
        if (count > 0) {
          double average = sum / count;
          double variance = 0.0;
          for (int l = 0; l < count; l++) {
            variance += pow((atof(values[k]) - average), 2);
          }
          variance /= count - 1;
          double standard_deviation = sqrt(variance);
          printf("Column %d: sum=%f, average=%f, standard deviation=%f\n", k + 1, sum, average, standard_deviation);
        } else {
          printf("Column %d: no data\n", k + 1);
        }
      }
    }
  }

  // Free the memory allocated for the row and column headers
  free(row_headers);
  free(col_headers);
}

int main() {
  read_csv("data.csv");
  return 0;
}
```
