    }
    return ptr;
}

// Define a custom hashing function for string fields
unsigned int my_hash(const char* str) {
    unsigned int hash = 0;
    for (int i = 0; i < strlen(str); i++) {
        hash += (i + 1) * (unsigned int)str[i];
    }
    return hash % 1000003; // Use a prime number as the modulus to reduce collisions
}

// Define a data structure for managing tasks
typedef struct TaskList {
    Task* tasks;
    int size;
    int capacity;
} TaskList;

// Initialize a new task list with a given capacity
