    list->tasks = (Task*)my_malloc(capacity * sizeof(Task));
    if (list->tasks == NULL) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = capacity;
    return list;
}

// Insert a new task into the task list
