        for (int i = 0; i < list->size; i++) {
            new_tasks[i] = list->tasks[i];
        }
        // Free the old tasks array and update the task list
        free(list->tasks);
        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }
    // Insert the new task at the end of the task list
    list->tasks[list->size++] = task;
}

// Remove a task from the task list by its ID
void remove_task(TaskList* list, int id) {
    // Find the index of the task with the given ID
    int i = 0;
    while (i < list->size && list->tasks[i].id != id) {
        i++;
    }
    if (i == list->size) {
        return;
    }
    // Shift all tasks after the removed task to fill the gap
    for (int j = i + 1; j < list->size; j++) {
        list->tasks[j - 1] = list->tasks[j];
    }
    // Decrement the size of the task list
    list->size--;
}

// Update a task in the task list by its ID
void update_task(TaskList* list, int id, Task new_task) {
    // Find the index of the task with the given ID
    int i = 0;
    while (i < list->size && list->tasks[i].id != id) {
        i++;
    }
    if (i == list->size) {
        return;
    }
    // Update the fields of the task at the given index
    list->tasks[i] = new_task;
}

// Print a task list to the console
void print_task_list(TaskList* list) {
    for (int i = 0; i < list->size; i++) {
        printf("Task %d: id=%d, priority=%d, status=%c, key=%d, offset=%ld, value=%d, identifier=%s\n",
