               list->tasks[i].key, list->tasks[i].offset, list->tasks[i].value, list->tasks[i].identifier);
    }
}

// Free the memory allocated for a task list
void free_task_list(TaskList* list) {
    if (list == NULL) {
        return;
    }
    free(list->tasks);
    free(list);
}
