// Function to read the input file and parse its contents
void read_input_file(const char* input_filename, const char* output_filename, const char* rules, int max_output_size) {
    // Open the input file for reading
    FILE* input_file = fopen(input_filename, "r");
    if (input_file == NULL) {
        printf("Error opening input file: %s\n", strerror(errno));
        return;
    }

    // Open the output file for writing
    FILE* output_file = fopen(output_filename, "w");
    if (output_file == NULL) {
        printf("Error opening output file: %s\n", strerror(errno));
        return;
    }

    // Parse the rules string and create a rule list
    char** rule_list = parse_rules(rules);
    if (rule_list == NULL) {
        printf("Error parsing rules: %s\n", strerror(errno));
        return;
    }

    // Read the input file line by line and apply the rules to generate the output
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, input_file)) != -1) {
        // Apply the rules to the current line and write the result to the output file
        char* transformed_line = apply_rules(rule_list, line);
        if (transformed_line == NULL) {
            printf("Error applying rules: %s\n", strerror(errno));
            return;
        }
        fprintf(output_file, "%s", transformed_line);
        free(transformed_line);
    }

    // Close the input and output files
    fclose(input_file);
    fclose(output_file);
}

// Function to parse the rules string and create a rule list
char** parse_rules(const char* rules) {
    // Split the rules string into individual rules using whitespace as delimiter
    char** rule_list = strsplit(rules, " ");
    if (rule_list == NULL) {
        printf("Error splitting rules: %s\n", strerror(errno));
        return NULL;
    }

    // Create a list of rule structures to store the parsed rules
    struct Rule* rule_struct_list = malloc(sizeof(struct Rule) * (strlen(rules) + 1));
    if (rule_struct_list == NULL) {
        printf("Error allocating memory for rule structures: %s\n", strerror(errno));
        return NULL;
    }

    // Parse each individual rule and store it in the rule structure list
    int i = 0;
    while (rule_list[i] != NULL) {
        struct Rule* current_rule = &rule_struct_list[i];
        char* rule_name = strtok(rule_list[i], "=");
        if (rule_name == NULL) {
            printf("Error parsing rule name: %s\n", strerror(errno));
            return NULL;
        }
        current_rule->name = rule_name;
        char* rule_value = strtok(NULL, "=");
        if (rule_value == NULL) {
            printf("Error parsing rule value: %s\n", strerror(errno));
            return NULL;
        }
        current_rule->value = rule_value;
        i++;
    }

    // Return the list of rule structures
    return rule_struct_list;
}

// Function to apply the rules to a given line and generate the transformed output
char* apply_rules(const char** rule_list, const char* line) {
    // Create a new string buffer for the transformed output
    size_t output_size = strlen(line);
    char* transformed_output = malloc(sizeof(char) * (output_size + 1));
    if (transformed_output == NULL) {
        printf("Error allocating memory for transformed output: %s\n", strerror(errno));
        return NULL;
    }

    // Apply each rule to the current line and store the result in the transformed output buffer
    int i = 0;
    while (rule_list[i] != NULL) {
        struct Rule* current_rule = &rule_list[i];
        char* rule_name = current_rule->name;
        char* rule_value = current_rule->value;
        if (strcmp(rule_name, "uppercase") == 0) {
            // Convert the line to uppercase
            for (int j = 0; j < output_size; j++) {
                transformed_output[j] = toupper(line[j]);
            }
        } else if (strcmp(rule_name, "lowercase") == 0) {
            // Convert the line to lowercase
            for (int j = 0; j < output_size; j++) {
                transformed_output[j] = tolower(line[j]);
            }
        } else if (strcmp(rule_name, "reverse") == 0) {
            // Reverse the line
            for (int j = 0; j < output_size / 2; j++) {
                char temp = transformed_output[j];
                transformed_output[j] = transformed_output[output_size - j - 1];
                transformed_output[output_size - j - 1] = temp;
            }
        } else if (strcmp(rule_name, "replace") == 0) {
            // Replace all occurrences of the rule value in the line with the rule name
            for (int j = 0; j < output_size; j++) {
                if (line[j] == rule_value[0]) {
                    transformed_output[j] = rule_name[0];
                }
            }
        } else {
            // Unknown rule, skip it
            continue;
        }
        i++;
    }

    // Return the transformed output buffer
    return transformed_output;
}

// Function to split a string into an array of substrings using a given delimiter
char** strsplit(const char* str, const char* delim) {
    int num_tokens = 0;
    for (int i = 0; str[i] != '\0'; i++) {
        if (strchr(delim, str[i]) != NULL) {
            num_tokens++;
        }
    }

    // Create an array of substrings to store the tokens
    char** token_list = malloc(sizeof(char*) * (num_tokens + 1));
    if (token_list == NULL) {
        printf("Error allocating memory for token list: %s\n", strerror(errno));
        return NULL;
    }

    // Split the string into tokens using the given delimiter
    int i = 0;
    while (str[i] != '\0') {
        if (strchr(delim, str[i]) != NULL) {
            token_list[num_tokens++] = &str[i];
        }
        i++;
    }
    token_list[num_tokens] = NULL;

    // Return the list of tokens
    return token_list;
}
