        // Skip empty lines and lines with fewer than three fields
        if (strlen(line) == 0 || strtok(line, ",") == NULL) {
            continue;
        }

        // Allocate memory for the line
        char *fields = malloc(sizeof(char) * read);
        strcpy(fields, line);

        // Split the line into fields and calculate the sum of the last three fields
        int num_fields = 0;
        double sum = 0;
        char *token = strtok(line, ",");
        while (token != NULL) {
            if (num_fields < 3) {
                sum += atof(token);
            } else {
                sum += atof(token) / 3.0;
            }
            num_fields++;
            token = strtok(NULL, ",");
        }

        // Print the contents of the line in a comma-separated format
        printf("%s\n", fields);

        // Free memory for the line
        free(fields);
    }

    // Close the input file
    fclose(fp);

    // Print statistics about the processed lines
    if (stats.num_lines > 0) {
        printf("Total number of lines: %d\n", stats.num_lines);
        printf("Sum of all fields: %.2f\n", stats.sum);
        printf("Minimum value: %.2f\n", stats.min);
        printf("Maximum value: %.2f\n", stats.max);
        printf("Average value: %.2f\n", stats.avg);
    } else {
        printf("No lines were processed.\n");
    }

    // Free memory for the statistics structure
    free(stats);

    return 0;
}
```
This code uses `getline()` to read each line of the input file, and then splits the line into fields using `strtok()`. It calculates the sum of the last three fields on each line and prints the contents of the line in a comma-separated format. If the `--manpage` option is provided, it prints usage information. If the `-cs` option is provided, it prints detailed statistics about the processed lines. If the `-o` option is provided, it writes the output to a file specified by the user. If the `-v` option is provided, it prints detailed statistics about the processed lines.

