#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Define the structure to store the script objects
typedef struct {
    int id;
    char *name;
    bool enabled;
    double average;
} Script;

// Define the dynamic data structure to store the script objects
typedef struct {
    Script **scripts;
    int capacity;
    int size;
} Scripts;

// Initialize the dynamic data structure with a capacity of 1000 elements
void initScripts(Scripts *scripts) {
    scripts->scripts = (Script **)malloc(sizeof(Script *) * 1000);
    scripts->capacity = 1000;
    scripts->size = 0;
}

// Add a new script object to the dynamic data structure
void addScript(Scripts *scripts, Script *script) {
    if (scripts->size == scripts->capacity) {
        // Increase the capacity by 100 elements if necessary
        scripts->scripts = (Script **)realloc(scripts->scripts, sizeof(Script *) * (scripts->capacity + 100));
        scripts->capacity += 100;
    }
    scripts->scripts[scripts->size++] = script;
}

// Process each script object line by line and compute the average of the last two fields
void processScripts(Scripts *scripts) {
    for (int i = 0; i < scripts->size; i++) {
        Script *script = scripts->scripts[i];
        // Compute the average of the last two fields
        double average = (script->enabled ? script->average : 0.0);
        printf("Average: %f\n", average);
    }
}

// Free all allocated memory to prevent leaks
void freeScripts(Scripts *scripts) {
    for (int i = 0; i < scripts->size; i++) {
        Script *script = scripts->scripts[i];
        free(script);
    }
    free(scripts->scripts);
}

// Read an XML file containing an array of script objects and process each object line by line
void readScriptsFromXMLFile(const char *filename) {
    // Initialize the dynamic data structure with a capacity of 1000 elements
    Scripts scripts;
    initScripts(&scripts);

    // Open the XML file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Read each line of the XML file and parse it as a script object
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Parse the script object from the line
        Script *script = parseScript(line);
        if (script == NULL) {
            printf("Error: unable to parse script object\n");
            continue;
        }
        addScript(&scripts, script);
    }

    // Process each script object and compute the average of the last two fields
    processScripts(&scripts);

    // Free all allocated memory to prevent leaks
    freeScripts(&scripts);

    // Close the XML file
    fclose(file);
}

// Parse a line as a script object and return it as a Script structure
Script *parseScript(const char *line) {
    // Initialize the Script structure
    Script *script = (Script *)malloc(sizeof(Script));
    if (script == NULL) {
        printf("Error: unable to allocate memory for script\n");
        return NULL;
    }

    // Parse the script object from the line
    char *token = strtok(line, " ");
    while (token != NULL) {
        if (strcmp(token, "<script>") == 0) {
            token = strtok(NULL, " ");
            script->id = atoi(token);
            token = strtok(NULL, " ");
            script->name = token;
            token = strtok(NULL, " ");
            script->enabled = (strcmp(token, "true") == 0 ? true : false);
            token = strtok(NULL, " ");
            script->average = atof(token);
        } else if (strcmp(token, "</script>") == 0) {
            break;
        }
        token = strtok(NULL, " ");
    }

    // Return the parsed Script structure
    return script;
}

// Render the processed script objects as a footer of a web page
char *renderScriptsAsFooter(Scripts *scripts) {
    // Initialize the HTML string
    char *html = (char *)malloc(sizeof(char) * 1024);
    if (html == NULL) {
        printf("Error: unable to allocate memory for HTML\n");
        return NULL;
    }

    // Render each script object as a <script> tag with a key and innerHTML set to the script's code
    for (int i = 0; i < scripts->size; i++) {
        Script *script = scripts->scripts[i];
        char *key = malloc(sizeof(char) * 16);
        sprintf(key, "script%d", script->id);
        char *innerHTML = malloc(sizeof(char) * 256);
        sprintf(innerHTML, "%s", script->name);
        html = strcat(html, "<script id=\"");
        html = strcat(html, key);
        html = strcat(html, "\" innerHTML=\"");
        html = strcat(html, innerHTML);
        html = strcat(html, "\"></script>");
    }

    // Return the rendered HTML string
    return html;
}
