// Memory pool structure for managing memory dynamically
struct MemoryPool {
    void* buffer;
    size_t size;
};

// Function to create a new memory pool
struct MemoryPool* create_memory_pool(size_t size) {
    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    if (pool == NULL) {
        return NULL;
    }

    // Allocate memory for the buffer
    void* buffer = malloc(size);
    if (buffer == NULL) {
        free(pool);
        return NULL;
    }

    pool->buffer = buffer;
    pool->size = size;

    return pool;
}

// Function to add memory to the memory pool
void* add_memory(struct MemoryPool* pool, size_t size) {
    // Check if there is enough space in the buffer
    if (pool->size - pool->buffer_offset < size) {
        return NULL;
    }

    // Allocate memory from the buffer
    void* ptr = pool->buffer + pool->buffer_offset;
    pool->buffer_offset += size;

    return ptr;
}

// Function to free a memory pool
void free_memory_pool(struct MemoryPool* pool) {
    if (pool == NULL) {
        return;
    }

    // Free the buffer
    free(pool->buffer);

    // Free the memory pool structure
    free(pool);
}

