    return index;
}

// Function to add a connection or packet to the custom index
void add_connection(struct Index* index, void* data) {
    // Check if the index is empty
    if (index->head == NULL && index->tail == NULL) {
        index->head = (struct Node*)malloc(sizeof(struct Node));
        index->tail = index->head;
        index->head->data = data;
        index->head->next = NULL;
    } else {
        // Add the connection or packet to the end of the list
        struct Node* node = (struct Node*)malloc(sizeof(struct Node));
        node->data = data;
        node->next = NULL;
        index->tail->next = node;
        index->tail = node;
    }
}

// Function to get a connection or packet from the custom index
void* get_connection(struct Index* index, int id) {
    // Check if the index is empty
    if (index->head == NULL && index->tail == NULL) {
        return NULL;
    }

    // Loop over each node in the list until we find the connection or packet with the given ID
    struct Node* node = index->head;
    while (node != NULL) {
        if (((struct Connection*)node->data)->id == id) {
            return node->data;
        }
        node = node->next;
    }

    // Return NULL if the connection or packet with the given ID is not found
    return NULL;
}

// Function to free a custom index
void free_index(struct Index* index) {
    if (index == NULL) {
        return;
    }

    // Free each node in the list and the index structure
    struct Node* node = index->head;
    while (node != NULL) {
        struct Node* next_node = node->next;
        free(node);
        node = next_node;
    }

    free(index);
}
