    // Allocate memory for an array of struct record pointers
    Record **records = (Record **)malloc(num_records * sizeof(Record *));
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize each struct record with a random integer key and an array of long integers named offsets
    for (int i = 0; i < num_records; i++) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Error: failed to allocate memory for record %d\n", i);
            exit(1);
        }
        record->key = rand() % 100;
        record->offsets = (long *)malloc(record->key * sizeof(long));
        if (!record->offsets) {
            fprintf(stderr, "Error: failed to allocate memory for offsets of record %d\n", i);
            exit(1);
        }
        for (int j = 0; j < record->key; j++) {
            record->offsets[j] = rand() % 1000;
        }
        records[i] = record;
    }

    // Set each value in the offsets array to a random integer within the range of 0 to 999
    for (int i = 0; i < num_records; i++) {
        Record *record = records[i];
        for (int j = 0; j < record->key; j++) {
            record->offsets[j] = rand() % 1000;
        }
    }

    // Free the memory allocated for each struct record and the array of struct record pointers
    for (int i = 0; i < num_records; i++) {
        Record *record = records[i];
        free(record->offsets);
        free(record);
    }
    free(records);
}

