void process_files(int num_files, char **file_names) {
    // Initialize variables to keep track of the total number of lines and character count
    int total_lines = 0;
    long total_chars = 0;

    // Iterate over each input file
    for (int i = 0; i < num_files; i++) {
        char *file_name = file_names[i];
        FILE *file = fopen(file_name, "r");
        if (!file) {
            fprintf(stderr, "Error: failed to open file %s\n", file_name);
            continue;
        }

        // Read from the input file line by line and calculate the total number of lines and character count
        char *line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, file)) != -1) {
            total_lines++;
            total_chars += strlen(line);
        }

        // Close the input file
        fclose(file);
    }

    // Print the total number of lines and character count to standard output
    printf("Total lines: %d\n", total_lines);
    printf("Total chars: %ld\n", total_chars);
}

