    int key = 0;
    while (key == 0 || key_set[key]) {
        key = rand() % MAX_KEYS;
    }
    key_set[key] = true;
    pthread_mutex_unlock(&key_mutex);
    return key;
}

// Define the function to populate the records array with unique keys
void populate_records(int num_entries) {
    // Initialize the records array and total_keys variable
    data_entry *records = malloc(num_entries * sizeof(data_entry));
    int total_keys = 0;

    // Populate each entry in the records array with a unique key
    for (int i = 0; i < num_entries; i++) {
        records[i].pdu.rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        records[i].pdu.rnti = rand() % MAX_RNTI;
        records[i].pdu.crc_indication_rel8_tag.crflag = rand() % 2;
        records[i].record.index = i;
        records[i].record.key = generate_unique_key();
        total_keys += records[i].record.key;
    }

    // Log the allocation process for debugging
    printf("Allocated %d entries in the records array\n", num_entries);

    // Ensure thread safety through appropriate synchronization mechanisms
    pthread_mutex_lock(&records_mutex);
    records_array = records;
    pthread_mutex_unlock(&records_mutex);
}

// Define the function to calculate and store the sum of all keys in total_keys
void calculate_total_keys() {
    // Calculate the sum of all keys in the records array
    int total_keys = 0;
    for (int i = 0; i < num_entries; i++) {
        total_keys += records[i].record.key;
    }

    // Store the sum of all keys in the total_keys variable
    pthread_mutex_lock(&total_keys_mutex);
    *total_keys = total_keys;
    pthread_mutex_unlock(&total_keys_mutex);
}

// Define the function to return the records array and total_keys after all operations are completed
void get_records(data_entry **records, int *total_keys) {
    // Ensure thread safety through appropriate synchronization mechanisms
    pthread_mutex_lock(&records_mutex);
    *records = records_array;
    pthread_mutex_unlock(&records_mutex);
    pthread_mutex_lock(&total_keys_mutex);
    *total_keys = total_keys;
    pthread_mutex_unlock(&total_keys_mutex);
}

// Define the function to safely deallocate all allocated memory and reset any global state
void free_memory() {
    // Ensure thread safety through appropriate synchronization mechanisms
    pthread_mutex_lock(&records_mutex);
    free(records_array);
    records_array = NULL;
    pthread_mutex_unlock(&records_mutex);
    pthread_mutex_lock(&total_keys_mutex);
    *total_keys = 0;
    pthread_mutex_unlock(&total_keys_mutex);
}
```
This code defines a function `populate_records` that populates an array of `data_entry` structs with unique keys generated by the `generate_unique_key` function. The function also calculates and stores the sum of all keys in a separate variable using the `calculate_total_keys` function. The `get_records` function returns the populated records array and total keys, while the `free_memory` function safely deallocates all allocated memory and resets any global state.

The code also defines several mutex locks to ensure thread safety through appropriate synchronization mechanisms. These locks are used to protect access to the `records_array`, `total_keys`, and other shared variables in the function.

