#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

// Define constants for command line options
#define OPT_MANPAGE '?'
#define OPT_CHARCOUNT 'c'
#define OPT_OUTPUT 'o'
#define OPT_AGGREGATE 'a'

// Define logging levels and output destinations
#define LOG_DEBUG 0
#define LOG_INFO 1
#define LOG_WARNING 2
#define LOG_ERROR 3
#define LOG_CRITICAL 4
#define LOG_CONSOLE 0
#define LOG_FILE 1
#define LOG_BOTH 2

// Define a struct to store file information
typedef struct {
    char *filename;
    int fd;
} file_info_t;

// Define a struct to store statistics for multiple files
typedef struct {
    long line_count;
    long char_count;
    double avg_char_per_line;
} stats_t;

// Function prototypes
void parse_command_line(int argc, char **argv);
void process_file(file_info_t *file);
void print_usage();
void log_message(int level, const char *format, ...);
void cleanup();

// Global variables
char *output_filename = NULL;
bool aggregate_stats = false;
long total_line_count = 0;
long total_char_count = 0;
double avg_char_per_line = 0.0;
int log_level = LOG_INFO;
int log_output = LOG_CONSOLE;
sem_t *semaphore;
pthread_mutex_t *mutex;

int main(int argc, char **argv) {
    // Initialize semaphore and mutex for thread safety
    semaphore = sem_open("file_sem", O_CREAT, 0644, 1);
    mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(mutex, NULL);

    // Parse command line arguments and handle errors
    parse_command_line(argc, argv);

    // Create a thread for each input file
    int num_files = 0;
    file_info_t *files = (file_info_t *)malloc(sizeof(file_info_t) * argc);
    for (int i = 1; i < argc; i++) {
        files[num_files].filename = argv[i];
        files[num_files].fd = open(argv[i], O_RDONLY);
        if (files[num_files].fd == -1) {
            log_message(LOG_ERROR, "Error opening file %s: %s", argv[i], strerror(errno));
            continue;
        }
        num_files++;
    }

    // Create a thread for each input file and process it
    pthread_t *threads = (pthread_t *)malloc(sizeof(pthread_t) * num_files);
    for (int i = 0; i < num_files; i++) {
        if (pthread_create(&threads[i], NULL, process_file, &files[i])) {
            log_message(LOG_ERROR, "Error creating thread for file %s", files[i].filename);
            continue;
        }
    }

    // Wait for all threads to finish and print statistics
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);

    // Print usage information if no input files were provided
    if (num_files == 0) {
        print_usage();
    } else {
        // Print statistics for each file
        for (int i = 0; i < num_files; i++) {
            log_message(LOG_INFO, "File %s:", files[i].filename);
            log_message(LOG_INFO, "\tLines: %ld", files[i].line_count);
            log_message(LOG_INFO, "\tCharacters: %ld", files[i].char_count);
            log_message(LOG_INFO, "\tAverage characters per line: %.2f", files[i].avg_char_per_line);
        }

        // Print total statistics if requested
        if (aggregate_stats) {
            log_message(LOG_INFO, "Total:");
            log_message(LOG_INFO, "\tLines: %ld", total_line_count);
            log_message(LOG_INFO, "\tCharacters: %ld", total_char_count);
            log_message(LOG_INFO, "\tAverage characters per line: %.2f", avg_char_per_line);
        }
    }

    // Clean up resources and exit
    cleanup();
    return 0;
}

// Parse command line arguments and handle errors
void parse_command_line(int argc, char **argv) {
    int c;
    while ((c = getopt(argc, argv, "?cs:o:a")) != -1) {
        switch (c) {
            case OPT_MANPAGE:
                print_usage();
                exit(0);
            case OPT_CHARCOUNT:
                output_filename = optarg;
                break;
            case OPT_OUTPUT:
                aggregate_stats = true;
                break;
            case OPT_AGGREGATE:
                aggregate_stats = true;
                break;
            default:
                log_message(LOG_ERROR, "Invalid command line option %c", c);
                print_usage();
                exit(1);
        }
    }
}

// Process a single file and update statistics
void process_file(file_info_t *file) {
    // Open the file for reading
    if (sem_wait(semaphore)) {
        log_message(LOG_ERROR, "Error waiting on semaphore: %s", strerror(errno));
        return;
    }
    int fd = open(file->filename, O_RDONLY);
    if (fd == -1) {
        log_message(LOG_ERROR, "Error opening file %s: %s", file->filename, strerror(errno));
        sem_post(semaphore);
        return;
    }

    // Read the file line by line and update statistics
    char buffer[1024];
    long line_count = 0;
    long char_count = 0;
    while (read(fd, buffer, sizeof(buffer)) > 0) {
        line_count++;
        for (int i = 0; i < strlen(buffer); i++) {
            if (buffer[i] != '\n') {
                char_count++;
            }
        }
    }

    // Close the file and update statistics
    close(fd);
    sem_post(semaphore);
    pthread_mutex_lock(mutex);
    total_line_count += line_count;
    total_char_count += char_count;
    avg_char_per_line = (double)total_char_count / (double)total_line_count;
    pthread_mutex_unlock(mutex);
}

// Print usage information
void print_usage() {
    printf("Usage: %s [options] <input files>\n", argv[0]);
    printf("\t-? --manpage\tDisplay detailed usage information.\n");
    printf("\t-c --charcount\tPrint the total character count of all lines across all input files.\n");
    printf("\t-o <output_file>\tWrite the aggregated results (number of lines, total character count, and average character count per line) to the specified output file.\n");
    printf("\t-a --aggregate\tAggregate statistics for all input files instead of printing them individually.\n");
}

// Log a message with the specified level and destination
void log_message(int level, const char *format, ...) {
    if (level > log_level) {
        return;
    }
    va_list args;
    va_start(args, format);
    switch (log_output) {
        case LOG_CONSOLE:
            vprintf(format, args);
            break;
        case LOG_FILE:
            FILE *file = fopen("log.txt", "a");
            if (file != NULL) {
                vfprintf(file, format, args);
                fclose(file);
            }
            break;
        case LOG_BOTH:
            printf(format, args);
            FILE *file = fopen("log.txt", "a");
            if (file != NULL) {
                vfprintf(file, format, args);
                fclose(file);
            }
            break;
    }
    va_end(args);
}

// Clean up resources and exit
void cleanup() {
    // Close the semaphore and mutex
    if (sem_close(semaphore)) {
        log_message(LOG_ERROR, "Error closing semaphore: %s", strerror(errno));
    }
    free(mutex);

    // Clean up file descriptors
    for (int i = 0; i < argc; i++) {
        close(files[i].fd);
    }
}
