// Define the task structure
typedef struct Task {
    int id;
    int priority;
    char status;
    char key[10];
    int offset;
    int value;
    char identifier[20];
    // Other attributes...
} Task;

// Define the custom memory allocator
void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

// Define the custom memory pool allocator
void* my_pool_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

// Define the custom hash table managed through a dynamic resizing mechanism
typedef struct HashTable {
    int size;
    Task** tasks;
} HashTable;

void init_hash_table(HashTable* ht, int initial_size) {
    ht->size = initial_size;
    ht->tasks = (Task**)my_malloc(sizeof(Task*) * initial_size);
    for (int i = 0; i < initial_size; i++) {
        ht->tasks[i] = NULL;
    }
}

void resize_hash_table(HashTable* ht, int new_size) {
    Task** old_tasks = ht->tasks;
    ht->tasks = (Task**)my_malloc(sizeof(Task*) * new_size);
    for (int i = 0; i < new_size; i++) {
        ht->tasks[i] = NULL;
    }
    for (int i = 0; i < ht->size; i++) {
        if (old_tasks[i] != NULL) {
            insert_task(ht, old_tasks[i]);
        }
    }
    free(old_tasks);
}

void insert_task(HashTable* ht, Task* task) {
    int index = hash_function(task->key);
    if (ht->tasks[index] == NULL) {
        ht->tasks[index] = task;
    } else {
        // Handle collisions by chaining tasks together
        Task* current = ht->tasks[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = task;
    }
}

Task* get_task(HashTable* ht, char* key) {
    int index = hash_function(key);
    Task* task = ht->tasks[index];
    while (task != NULL && strcmp(task->key, key) != 0) {
        task = task->next;
    }
    return task;
}

