// Define the structure for a task
typedef struct {
    int id;
    int priority;
    char status[10];
} Task;

// Define the collection of tasks
Task *tasks = NULL;
int num_tasks = 0;

// Function to add a new task
void add_task(Task *new_task) {
    // Check if the collection is empty
    if (num_tasks == 0) {
        tasks = malloc(sizeof(Task));
        memcpy(tasks, new_task, sizeof(Task));
        num_tasks++;
    } else {
        // Reallocate memory for the collection
        Task *tmp = realloc(tasks, (num_tasks + 1) * sizeof(Task));
        if (tmp == NULL) {
            perror("realloc failed");
            exit(EXIT_FAILURE);
        }
        tasks = tmp;
        memcpy(&tasks[num_tasks], new_task, sizeof(Task));
        num_tasks++;
    }
}

// Function to update an existing task
void update_task(int id, Task *new_task) {
    // Find the index of the task with the given ID
    int i;
    for (i = 0; i < num_tasks; i++) {
        if (tasks[i].id == id) {
            break;
        }
    }
    // Check if the task was found
    if (i == num_tasks) {
        printf("Task with ID %d not found\n", id);
        return;
    }
    // Update the task
    memcpy(&tasks[i], new_task, sizeof(Task));
}

// Function to retrieve a task based on its priority
Task *get_task(int priority) {
    // Find the index of the first task with the given priority
    int i;
    for (i = 0; i < num_tasks; i++) {
        if (tasks[i].priority == priority) {
            break;
        }
    }
    // Check if a task was found
    if (i == num_tasks) {
        return NULL;
    }
    // Return the task
    return &tasks[i];
}

// Function to free all allocated memory
void free_memory() {
    // Free the memory for the collection of tasks
    free(tasks);
    tasks = NULL;
    num_tasks = 0;
}

// Function to persist the collection of tasks to disk
void persist_to_disk() {
    // Open a file for writing
    int fd = open("task_collection.dat", O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("open failed");
        exit(EXIT_FAILURE);
    }
    // Write the collection of tasks to the file
    for (int i = 0; i < num_tasks; i++) {
        write(fd, &tasks[i], sizeof(Task));
    }
    // Close the file
    close(fd);
}

// Function to load the collection of tasks from disk
void load_from_disk() {
    // Open a file for reading
    int fd = open("task_collection.dat", O_RDONLY, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("open failed");
        exit(EXIT_FAILURE);
    }
    // Read the collection of tasks from the file
    for (int i = 0; i < num_tasks; i++) {
        read(fd, &tasks[i], sizeof(Task));
    }
    // Close the file
    close(fd);
}

