        for (i = 0; i < num_tasks; i++) {
            if (tasks[i].id == id) {
                break;
            }
        }
        // Check if a task was found
        if (i == num_tasks) {
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        // Copy the task to the local variable
        memcpy(&task, &tasks[i], sizeof(Task));
        // Unlock the mutex and wait for the condition variable
        pthread_cond_wait(&cond, &mutex);
