        if (i == num_tasks) {
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        // Copy the task to the local variable
        memcpy(&task, &tasks[i], sizeof(Task));
        // Unlock the mutex and return the task
        pthread_mutex_unlock(&mutex);
        return &task;
    }
}

// Main function
int main() {
