#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>
#include <stdint.h>
#include <stdbool.h>

// Custom slab allocator with configurable chunk sizes and alignment parameters
struct SlabAllocator {
    uint32_t chunkSize; // Size of each chunk in bytes
    uint8_t alignment;  // Alignment requirement for each structure
    void* currentChunk; // Pointer to the current chunk being allocated from
    size_t usedMemory;  // Amount of memory currently used by the allocator
};

// Initialize a slab allocator with the given chunk size and alignment requirements
void initSlabAllocator(struct SlabAllocator* allocator, uint32_t chunkSize, uint8_t alignment) {
    allocator->chunkSize = chunkSize;
    allocator->alignment = alignment;
    allocator->currentChunk = NULL;
    allocator->usedMemory = 0;
}

// Allocate memory from the slab allocator for a given number of structures
void* allocateStructures(struct SlabAllocator* allocator, size_t numStructures) {
    // Calculate the total size required for the allocation
    size_t totalSize = numStructures * sizeof(struct NetworkSession);

    // Check if there is enough memory available in the current chunk
    if (allocator->currentChunk == NULL || allocator->usedMemory + totalSize > allocator->chunkSize) {
        // Allocate a new chunk if necessary
        void* newChunk = malloc(allocator->chunkSize);
        if (newChunk == NULL) {
            return NULL;
        }

        // Initialize the new chunk and update the current pointer
        allocator->currentChunk = newChunk;
        allocator->usedMemory = 0;
    }

    // Calculate the offset to align the memory allocation
    size_t alignmentOffset = (allocator->alignment - 1) & ~(uintptr_t)allocator->currentChunk;
    if (alignmentOffset != 0) {
        allocator->usedMemory += alignmentOffset;
    }

    // Update the used memory and return a pointer to the allocated memory
    void* result = (void*)((uintptr_t)allocator->currentChunk + allocator->usedMemory);
    allocator->usedMemory += totalSize;
    return result;
}

// Free a previously allocated structure from the slab allocator
void freeStructure(struct SlabAllocator* allocator, void* structure) {
    // Nothing to do since we don't have a way to deallocate individual structures
}

