        if ((read = getline(&line, &len, fp)) != -1) {
            // Check for byte order marks and multi-byte character sequences
            if (strncmp(line, bom, 3) == 0 || strncmp(line, mbcs, 2) == 0) {
                // Handle encoding issues here...
            }
        }
    }

    // Close log file
    fclose(fp);
