// Function to manage dynamic load balancing across multiple threads
void manage_load_balancing() {
    // Get current system CPU utilization
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    float cpu_util = (float)usage.ru_utime.tv_sec + (float)usage.ru_stime.tv_sec;

    // Adjust number of threads based on current workload and CPU utilization
    if (cpu_util > 0.8) {
        // Increase number of threads to handle increased workload
        num_threads++;
    } else if (cpu_util < 0.6) {
        // Decrease number of threads to reduce CPU utilization
        num_threads--;
    }
}

// Function to capture processing metrics and error logs
void log_metrics(const char* filename, struct Metrics* metrics) {
    // Open log file for writing
    FILE* fp = fopen(filename, "a");
    if (fp == NULL) {
        printf("Error: unable to open log file %s\n", filename);
        return;
