// Define the logging framework
#define LOGGING_FRAMEWORK

int runCommand(char *command, int timeout) {
    // Fork a new process to run the command in the background
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: execute the command and exit
        system(command);
        exit(0);
    } else if (pid > 0) {
        // Parent process: wait for the command to complete within the specified timeout
        int status;
        if (waitpid(pid, &status, WNOHANG | WUNTRACED) == pid && waitpid(pid, &status, 0) == pid) {
            // Command completed successfully within the timeout period
            return 0;
        } else {
            // Command failed to complete within the timeout or encountered resource constraints
            LOGGING_FRAMEWORK("Error: command did not complete within %d seconds", timeout);
            return -1;
        }
    } else {
        // Fork failed: log an error message and return -1
        LOGGING_FRAMEWORK("Error: fork() failed");
        return -1;
    }
}

int populateList(NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    // Populate the list with random RX_UE_INFORMATION_TAG and RNTI values
    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i].RNTI = rand() % 1000;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

int main(int argc, char *argv[]) {
    // Define the command to run in the background
    char *command = "sleep 5";

    // Define the timeout period (in seconds)
    int timeout = 10;

    // Define the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10);

    // Populate the list with random RX_UE_INFORMATION_TAG and RNTI values
    populateList(list, 10);

    // Run the command in the background using the fork and wait system calls
    int status = runCommand(command, timeout);

    // Check if the command completed successfully within the specified timeout period
    if (status == 0) {
        LOGGING_FRAMEWORK("Command completed successfully within %d seconds", timeout);
    } else {
        LOGGING_FRAMEWORK("Error: command did not complete within %d seconds", timeout);
    }

    // Free the list of NFAPI_CRC_INDICATION_PDU_T structures
    free(list);

    return 0;
}
