    // Initialize the mutex for synchronizing access to the data packet array
    pthread_mutex_t *mutex = pthread_mutex_init();
    if (mutex == NULL) {
        printf("Error: Failed to initialize mutex for data packet array\n");
        free(offsetArray);
        free(timestampArray);
        free(logRecords);
        return;
    }

    // Process the NFAPI_CRC_INDICATION_PDU_T structure
    processNFAPI_CRC_INDICATION_PDU_T(pdu, offsetArray, timestampArray, logRecords, loggingFramework, sem, mutex);

    // Free the memory allocated for the arrays and the semaphore
    free(offsetArray);
    free(timestampArray);
    free(logRecords);
    sem_close(sem);
    pthread_mutex_destroy(mutex);
}

