void processNFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T *pdu, long *offsetArray, int *timestampArray, LogRecord *logRecords, LoggingFramework *loggingFramework, sem_t *sem, pthread_mutex_t *mutex) {
