import subprocess
import os
import json
import time
import logging
from typing import Dict, List

class SensorReading:
    def __init__(self, sensor_id: int, timestamp: str, temperature: float, humidity: float, pressure: float, coordinates: List[float]):
        self.sensor_id = sensor_id
        self.timestamp = timestamp
        self.temperature = temperature
        self.humidity = humidity
        self.pressure = pressure
        self.coordinates = coordinates

class SensorReadingsManager:
    def __init__(self, config_file: str):
        self.config_file = config_file
        self.readings = []
        self.load_config()

    def load_config(self):
        with open(self.config_file) as f:
            self.config = json.load(f)

    def add_reading(self, reading: SensorReading):
        self.readings.append(reading)

    def update_reading(self, reading: SensorReading):
        for i in range(len(self.readings)):
            if self.readings[i].sensor_id == reading.sensor_id:
                self.readings[i] = reading
                break

    def get_readings(self, filters: Dict[str, str]) -> List[SensorReading]:
        readings = []
        for reading in self.readings:
            if all(getattr(reading, filter) == value for filter, value in filters.items()):
                readings.append(reading)
        return readings

    def filter_readings(self, filters: Dict[str, str]) -> List[SensorReading]:
        return self.get_readings(filters)

    def save_config(self):
        with open(self.config_file, 'w') as f:
            json.dump(self.config, f)

    def replace_placeholder(self, placeholder: str, value: str):
        sed_command = f"sed -i 's/{placeholder}/{value}/g' {self.config_file}"
        try:
            subprocess.run(sed_command, shell=True)
