void add_weather_station(struct WeatherStationCollection *collection, struct WeatherStation station) {
    // Check if the collection is full
    if (collection->num_stations == collection->capacity) {
        // Reallocate memory for the stations array
        collection->stations = realloc(collection->stations, (collection->capacity + 1) * sizeof(struct WeatherStation));
        // Increment the capacity of the collection
        collection->capacity++;
    }
    // Add the new station to the end of the array
    collection->stations[collection->num_stations++] = station;
}

