    // Acquire the mutex lock for thread-safe access
    pthread_mutex_lock(&mutex);

    // Check if the key array needs to be resized
    if (numElements == capacity) {
        // Resize the key array by 100 elements
        char** newKeyArray = realloc(keyArray, (capacity + 100) * sizeof(char*));
        if (newKeyArray == NULL) {
            // Handle memory allocation failure gracefully
            pthread_mutex_unlock(&mutex);
            return;
