        configArray = newConfigArray;

        // Resize the metadata sizes array by 100 elements
        int* newMetadataSizes = realloc(metadataSizes, (capacity + 100) * sizeof(int));
        if (newMetadataSizes == NULL) {
            // Handle memory allocation failure gracefully
            pthread_mutex_unlock(&mutex);
            return;
        }
        metadataSizes = newMetadataSizes;

        capacity += 100;
