#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pthread.h>

// Define the structure for sensor readings
typedef struct SensorReading {
    int id;
    time_t timestamp;
    float temperature;
    float humidity;
    float pressure;
    double latitude;
    double longitude;
} SensorReading;

// Define the array for storing sensor readings
SensorReading *readings = NULL;
size_t num_readings = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new reading
void add_reading(int id, time_t timestamp, float temperature, float humidity, float pressure, double latitude, double longitude) {
    pthread_mutex_lock(&mutex);
    SensorReading *new_reading = (SensorReading *)malloc(sizeof(SensorReading));
    new_reading->id = id;
    new_reading->timestamp = timestamp;
    new_reading->temperature = temperature;
    new_reading->humidity = humidity;
    new_reading->pressure = pressure;
    new_reading->latitude = latitude;
    new_reading->longitude = longitude;
    readings = (SensorReading *)realloc(readings, (num_readings + 1) * sizeof(SensorReading));
    readings[num_readings++] = *new_reading;
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing reading
void update_reading(int id, time_t timestamp, float temperature, float humidity, float pressure, double latitude, double longitude) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_readings; i++) {
        if (readings[i].id == id) {
            readings[i].timestamp = timestamp;
            readings[i].temperature = temperature;
            readings[i].humidity = humidity;
            readings[i].pressure = pressure;
            readings[i].latitude = latitude;
            readings[i].longitude = longitude;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve readings within a specified time range
void get_readings(time_t start, time_t end) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_readings; i++) {
        if (start <= readings[i].timestamp && readings[i].timestamp <= end) {
            printf("Reading %d: %f, %f, %f, %f, %f\n", readings[i].id, readings[i].temperature, readings[i].humidity, readings[i].pressure, readings[i].latitude, readings[i].longitude);
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to filter readings based on environmental conditions or geographic proximity
void filter_readings(float temperature_min, float temperature_max, float humidity_min, float humidity_max, float pressure_min, float pressure_max, double latitude_min, double latitude_max, double longitude_min, double longitude_max) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_readings; i++) {
        if (temperature_min <= readings[i].temperature && readings[i].temperature <= temperature_max && humidity_min <= readings[i].humidity && readings[i].humidity <= humidity_max && pressure_min <= readings[i].pressure && readings[i].pressure <= pressure_max) {
            printf("Reading %d: %f, %f, %f, %f, %f\n", readings[i].id, readings[i].temperature, readings[i].humidity, readings[i].pressure, readings[i].latitude, readings[i].longitude);
        }
