// Structure for sensor reading data
typedef struct SensorReading {
    int id;
    time_t timestamp;
    float temperature;
    float humidity;
    float pressure;
    double latitude;
    double longitude;
} SensorReading;

// Dynamic array for storing sensor readings
typedef struct SensorReadingArray {
    int size;
    int capacity;
    SensorReading* data;
} SensorReadingArray;

// Function to initialize a new dynamic array of sensor readings
SensorReadingArray* init_sensor_reading_array() {
    SensorReadingArray* arr = (SensorReadingArray*)malloc(sizeof(SensorReadingArray));
    arr->size = 0;
    arr->capacity = 16;
    arr->data = (SensorReading*)malloc(arr->capacity * sizeof(SensorReading));
    return arr;
}

// Function to add a new sensor reading to the dynamic array
void add_sensor_reading(SensorReadingArray* arr, SensorReading reading) {
    if (arr->size == arr->capacity) {
        // Double the capacity of the dynamic array if it's full
        arr->capacity *= 2;
        arr->data = (SensorReading*)realloc(arr->data, arr->capacity * sizeof(SensorReading));
    }
    arr->data[arr->size++] = reading;
}

// Function to update an existing sensor reading in the dynamic array
void update_sensor_reading(SensorReadingArray* arr, int index, SensorReading reading) {
    if (index < 0 || index >= arr->size) {
        // Out of bounds error
        return;
    }
    arr->data[index] = reading;
}

// Function to retrieve all sensor readings within a specified time range
SensorReadingArray* get_sensor_readings(SensorReadingArray* arr, time_t start, time_t end) {
    SensorReadingArray* result = init_sensor_reading_array();
    for (int i = 0; i < arr->size; i++) {
        if (arr->data[i].timestamp >= start && arr->data[i].timestamp <= end) {
            add_sensor_reading(result, arr->data[i]);
        }
    }
    return result;
}

// Function to filter sensor readings based on environmental conditions or geographic proximity
SensorReadingArray* filter_sensor_readings(SensorReadingArray* arr, float temperature_min, float temperature_max, float humidity_min, float humidity_max, double latitude_min, double latitude_max, double longitude_min, double longitude_max) {
    SensorReadingArray* result = init_sensor_reading_array();
    for (int i = 0; i < arr->size; i++) {
        if (arr->data[i].temperature >= temperature_min && arr->data[i].temperature <= temperature_max && arr->data[i].humidity >= humidity_min && arr->data[i].humidity <= humidity_max && arr->data[i].latitude >= latitude_min && arr->data[i].latitude <= latitude_max && arr->data[i].longitude >= longitude_min && arr->data[i].longitude <= longitude_max) {
            add_sensor_reading(result, arr->data[i]);
        }
    }
    return result;
}

// Function to handle concurrent access from multiple threads
void* thread_handler(void* arg) {
    SensorReadingArray* arr = (SensorReadingArray*)arg;
    while (1) {
        // Acquire lock on the dynamic array
        pthread_mutex_lock(&arr->mutex);
        // Perform operations on the dynamic array
        // Release lock on the dynamic array
        pthread_mutex_unlock(&arr->mutex);
    }
}

// Function to prevent deadlocks and handle conflicts in concurrent access
void* conflict_resolver(void* arg) {
    SensorReadingArray* arr = (SensorReadingArray*)arg;
    while (1) {
        // Acquire lock on the dynamic array
        pthread_mutex_lock(&arr->mutex);
        // Check for conflicts in concurrent access
        if (conflict_exists(arr)) {
            // Resolve conflict by retrying operation or aborting thread
        }
        // Release lock on the dynamic array
        pthread_mutex_unlock(&arr->mutex);
    }
}

