using namespace std;

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
};

vector<NFAPI_CRC_INDICATION_PDU_T> generateAndManagePokemonDataStreams(int numEntries) {
    vector<NFAPI_CRC_INDICATION_PDU_T> dataStreams(numEntries);

    // Initialize the data streams with random values
    for (int i = 0; i < numEntries; i++) {
        dataStreams[i].rxUeInformationTag = RX_UE_INFORMATION_TAG();
        dataStreams[i].rnti = RNTI();
        dataStreams[i].crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG(rand() % 2);
    }

    // Validate memory alignment and track successfully allocated structures
    for (int i = 0; i < numEntries; i++) {
        if (!dataStreams[i].rxUeInformationTag.isValid()) {
            cout << "Error: Invalid RX_UE_INFORMATION_TAG at index " << i << endl;
        } else if (!dataStreams[i].rnti.isValid()) {
            cout << "Error: Invalid RNTI at index " << i << endl;
        } else if (!dataStreams[i].crcIndicationRel8Tag.isValid()) {
            cout << "Error: Invalid CRC_INDICATION_REL8_TAG at index " << i << endl;
        }
    }

    // Log the allocation process for debugging
    cout << "Allocated " << numEntries << " data streams" << endl;

    return dataStreams;
}
