import java.util.Random;

public class Pokemon {
    private String name;
    private String type;

    public Pokemon(String name, String type) {
        this.name = name;
        this.type = type;
    }

    public String getName() {
        return name;
    }

    public String getType() {
        return type;
    }

    public static String getWeaknesses(Pokemon pokemon) {
        switch (pokemon.getType()) {
            case "Fire":
                return "Water";
            case "Water":
                return "Fire";
            default:
                return "";
        }
    }
}
