        return ERROR_MEMORY_ALLOCATION;
    }

    // Add the new reading to the 'record' array
    records[numRecords++] = *reading;

    return 0;
}

// Define the function to update an existing reading in the 'record' array
int updateReading(SensorReading* reading) {
    // Check if the 'record' array is full
    if (numRecords == MAX_RECORDS) {
        return ERROR_MEMORY_ALLOCATION;
    }

    // Find the existing reading in the 'record' array
    for (int i = 0; i < numRecords; i++) {
        if (records[i].timestamp == reading->timestamp && records[i].sensorId == reading->sensorId) {
            records[i] = *reading;
            return 0;
        }
    }

    // If the reading is not found, add it to the 'record' array
    return addNewReading(reading);
}

// Define the function to count occurrences of a specific word in the input files
int countOccurrences(char* word) {
    int count = 0;

    // Loop through each file and count the number of occurrences of the specified word
    for (int i = 0; i < numFiles; i++) {
        FILE* file = fopen(files[i], "r");
        if (!file) {
            return ERROR_FILE_OPEN;
        }

        char buffer[BUFFER_SIZE];
        while (fgets(buffer, BUFFER_SIZE, file)) {
            // Check if the word is found in the current line
            if (strstr(buffer, word) != NULL) {
                count++;
            }
        }

        fclose(file);
    }

    return count;
}

// Define the function to manage file descriptor limits
void manageFileDescriptors() {
    // Check if there are any open file descriptors that exceed the maximum limit
    for (int i = 0; i < MAX_FILES; i++) {
        if (fileDescriptors[i] > 0) {
            // Close the excessive file descriptors to prevent resource exhaustion
            close(fileDescriptors[i]);
            fileDescriptors[i] = 0;
        }
    }
}

// Define the function to manage memory usage
void manageMemoryUsage() {
    // Check if the allocated memory exceeds the threshold
    if (memoryUsage > MEMORY_USAGE_THRESHOLD) {
        // Notify the system administrator about the excessive memory usage
        printf("Excessive memory usage detected. Please check the program's performance.\n");
    }
}

// Define the function to handle memory leaks
void handleMemoryLeaks() {
    // Check if there are any memory leaks
    for (int i = 0; i < MAX_FILES; i++) {
        if (fileDescriptors[i] > 0) {
            // Close the excessive file descriptors to prevent resource exhaustion
            close(fileDescriptors[i]);
            fileDescriptors[i] = 0;
        }
    }
}

// Define the function to handle errors during processing
void handleErrors() {
    // Check if any error has occurred during processing
    if (errorCode != 0) {
        // Print an error message and exit the program
        printf("Error: %d\n", errorCode);
        exit(1);
    }
}

// Define the function to manage concurrent access to arrays from multiple threads
void manageConcurrentAccess() {
    // Use a mutex to synchronize access to the 'record' array
    pthread_mutex_t recordMutex = PTHREAD_MUTEX_INITIALIZER;

    // Use a condition variable to signal when a new reading is added or updated
    pthread_cond_t recordCondition = PTHREAD_COND_INITIALIZER;

    // Define the function to add a new reading to the 'record' array from a separate thread
    void* addNewReadingThread(void* arg) {
        SensorReading* reading = (SensorReading*)arg;

        pthread_mutex_lock(&recordMutex);

        // Add the new reading to the 'record' array
        int errorCode = addNewReading(reading);

        if (errorCode != 0) {
            printf("Error: %d\n", errorCode);
        }

        pthread_cond_signal(&recordCondition);
        pthread_mutex_unlock(&recordMutex);
    }

    // Define the function to update an existing reading in the 'record' array from a separate thread
    void* updateReadingThread(void* arg) {
        SensorReading* reading = (SensorReading*)arg;

        pthread_mutex_lock(&recordMutex);

        // Update the existing reading in the 'record' array
        int errorCode = updateReading(reading);

        if (errorCode != 0) {
            printf("Error: %d\n", errorCode);
        }

        pthread_cond_signal(&recordCondition);
        pthread_mutex_unlock(&recordMutex);
    }
}

