};

// Function to add a new task to the collection
void add_task(struct task_collection *collection, int id, int priority) {
    // Check if the collection is full
    if (collection->num_tasks == collection->capacity) {
        // Double the capacity of the collection
        collection->capacity *= 2;
        // Reallocate memory for the tasks array
        collection->tasks = realloc(collection->tasks, sizeof(struct task) * collection->capacity);
    }
    // Add the new task to the end of the collection
    collection->tasks[collection->num_tasks].id = id;
    collection->tasks[collection->num_tasks].priority = priority;
    collection->tasks[collection->num_tasks].status = 'P';
    collection->tasks[collection->num_tasks].last_active_time = time(NULL);
    // Increment the number of tasks in the collection
    collection->num_tasks++;
}

// Function to update an existing task in the collection
void update_task(struct task_collection *collection, int id, char status) {
    // Find the index of the task with the specified ID
    size_t i;
    for (i = 0; i < collection->num_tasks; i++) {
        if (collection->tasks[i].id == id) {
            break;
        }
    }
    // Check if the task was found
    if (i < collection->num_tasks) {
        // Update the status of the task
        collection->tasks[i].status = status;
        // Update the last active time of the task
        collection->tasks[i].last_active_time = time(NULL);
    } else {
        // Task not found, do nothing
    }
}

// Function to retrieve tasks based on their priority
struct task *retrieve_tasks(struct task_collection *collection, int priority) {
    struct task *tasks;
    size_t num_tasks = 0;
    // Find the first task with the specified priority
    size_t i;
    for (i = 0; i < collection->num_tasks; i++) {
        if (collection->tasks[i].priority == priority) {
            break;
        }
    }
    // Check if a task with the specified priority was found
    if (i < collection->num_tasks) {
        // Allocate memory for the tasks array
        tasks = malloc(sizeof(struct task) * (collection->num_tasks - i));
        // Copy the tasks with the specified priority to the new array
        while (i < collection->num_tasks && collection->tasks[i].priority == priority) {
            tasks[num_tasks] = collection->tasks[i];
            num_tasks++;
            i++;
        }
    } else {
        // No task with the specified priority was found, return an empty array
        tasks = malloc(sizeof(struct task) * 0);
    }
    return tasks;
}

// Function to free all allocated memory when the collection is no longer needed
void free_collection(struct task_collection *collection) {
    // Free the tasks array
    free(collection->tasks);
    // Reset the number of tasks and capacity of the collection
    collection->num_tasks = 0;
    collection->capacity = 1;
}

// Function to implement a mechanism to free all allocated memory when the collection is no longer needed
void free_collection_on_exit(struct task_collection *collection) {
    // Register a function to be called on program exit
    atexit(free_collection, collection);
}

// Function to serialize the task collection to disk at regular intervals (every 5 minutes)
void serialize_tasks(struct task_collection *collection) {
    // Open the serialization file in append mode
    int fd = open("task_serialization.dat", O_CREAT | O_RDWR, S_IRUSR | S_IWUSR);
    // Write the tasks to the serialization file
    write(fd, collection->tasks, sizeof(struct task) * collection->num_tasks);
    // Close the serialization file
    close(fd);
}

// Function to deserialize the task collection from disk
void deserialize_tasks(struct task_collection *collection) {
    // Open the serialization file in read-only mode
    int fd = open("task_serialization.dat", O_RDONLY, S_IRUSR | S_IWUSR);
    // Read the tasks from the serialization file
    read(fd, collection->tasks, sizeof(struct task) * collection->num_tasks);
    // Close the serialization file
