        service->total_delivered_messages++;

        // Check if the message has been acknowledged
        if (!message->acknowledged) {
            // Notify the user that the message has not been acknowledged
            syslog(LOG_WARNING, "Message has not been acknowledged");

            // Remove the message from the queue
            service->queue->head++;
            service->queue->size--;
        }
    }
}
