// Define a structure to hold the MME_UE_S1AP_ID and EPS_BEARER_CONTEXT
typedef struct LTE_MME_UE_S1AP_IDENTITY {
    int MME_UE_S1AP_ID;
    int EPS_BEARER_CONTEXT;
} LTE_MME_UE_S1AP_IDENTITY;

// Define a dynamic array to hold the structures
LTE_MME_UE_S1AP_IDENTITY* arr = NULL;
int arr_size = 0;

// Function to allocate memory for a new structure and populate it with a unique MME_UE_S1AP_ID and EPS_BEARER_CONTEXT identifier
void add_structure(int MME_UE_S1AP_ID, int EPS_BEARER_CONTEXT) {
    // Check if the array is full
    if (arr_size == 0) {
        arr = malloc(sizeof(LTE_MME_UE_S1AP_IDENTITY));
        arr[0].MME_UE_S1AP_ID = MME_UE_S1AP_ID;
        arr[0].EPS_BEARER_CONTEXT = EPS_BEARER_CONTEXT;
        arr_size++;
    } else {
        // Check if the array is not full and there are no free slots
        for (int i = 0; i < arr_size; i++) {
            if (arr[i].MME_UE_S1AP_ID == -1) {
                arr[i].MME_UE_S1AP_ID = MME_UE_S1AP_ID;
                arr[i].EPS_BEARER_CONTEXT = EPS_BEARER_CONTEXT;
                break;
            }
        }
    }
}

// Function to update the EPS Bearer Context based on a given identifier, considering potential concurrent access issues
void update_eps_bearer_context(int MME_UE_S1AP_ID, int EPS_BEARER_CONTEXT) {
    // Check if the array is not empty and there are no free slots
    for (int i = 0; i < arr_size; i++) {
        if (arr[i].MME_UE_S1AP_ID == MME_UE_S1AP_ID) {
            arr[i].EPS_BEARER_CONTEXT = EPS_BEARER_CONTEXT;
            break;
        }
    }
}

// Function to deallocate memory for the dynamic array
void free_array() {
    if (arr != NULL) {
        free(arr);
        arr = NULL;
        arr_size = 0;
    }
}
