    // Initialize the array of structures with random values
    for (int i = 0; i < numElements; i++) {
        arr[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        arr[i].RNTI = rand() % 65536;
        arr[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        arr[i].CRCFLAG = (rand() % 2) == 0;
    }

    // Return the pointer to the allocated array
    return arr;
}

// Define a function to free the memory allocated by manageArray
