// Define a structure to hold the LTE_MME_UE_S1AP_IDENTITY data
typedef struct {
    int MME_UE_S1AP_ID;
    int EPS_BEARER_CONTEXT;
} LTE_MME_UE_S1AP_IDENTITY;

// Define a dynamic array to hold the LTE_MME_UE_S1AP_IDENTITY structures
LTE_MME_UE_S1AP_IDENTITY* arr = NULL;
size_t arr_len = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate a new LTE_MME_UE_S1AP_IDENTITY structure and add it to the array
int allocate_LTE_MME_UE_S1AP_IDENTITY(int MME_UE_S1AP_ID, int EPS_BEARER_CONTEXT) {
    // Lock the mutex to prevent concurrent modifications
    pthread_mutex_lock(&mutex);

    // Allocate a new LTE_MME_UE_S1AP_IDENTITY structure and populate it with the given data
    LTE_MME_UE_S1AP_IDENTITY* new_entry = malloc(sizeof(LTE_MME_UE_S1AP_IDENTITY));
    new_entry->MME_UE_S1AP_ID = MME_UE_S1AP_ID;
    new_entry->EPS_BEARER_CONTEXT = EPS_BEARER_CONTEXT;

    // Add the new structure to the array
    arr = realloc(arr, (arr_len + 1) * sizeof(LTE_MME_UE_S1AP_IDENTITY));
    arr[arr_len++] = new_entry;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to update an existing LTE_MME_UE_S1AP_IDENTITY structure based on a given identifier
int update_LTE_MME_UE_S1AP_IDENTITY(int MME_UE_S1AP_ID, int EPS_BEARER_CONTEXT) {
    // Lock the mutex to prevent concurrent modifications
    pthread_mutex_lock(&mutex);

    // Find the structure with the given identifier in the array
    for (size_t i = 0; i < arr_len; i++) {
        if (arr[i]->MME_UE_S1AP_ID == MME_UE_S1AP_ID) {
            // Update the structure with the new data
            arr[i]->EPS_BEARER_CONTEXT = EPS_BEARER_CONTEXT;
            break;
        }
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to free all memory allocated for the dynamic array of LTE_MME_UE_S1AP_IDENTITY structures
void free_LTE_MME_UE_S1AP_IDENTITIES() {
    // Lock the mutex to prevent concurrent modifications
    pthread_mutex_lock(&mutex);

    // Free all memory allocated for the array and set it to NULL
    free(arr);
    arr = NULL;
    arr_len = 0;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&mutex);
}
