#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure for a payment transaction
typedef struct PaymentTransaction {
    int id;
    char customer_name[256];
    float amount;
    time_t timestamp;
    char payment_method[32];
    char card_issuer[128];
    char transaction_status[32];
} PaymentTransaction;

// Define the dynamic array for storing payment transactions
typedef struct PaymentTransactionArray {
    int size;
    int capacity;
    PaymentTransaction* transactions;
} PaymentTransactionArray;

// Function to add a new transaction to the array
void add_transaction(PaymentTransactionArray* arr, PaymentTransaction transaction) {
    // Check if the array is full and needs to be resized
    if (arr->size == arr->capacity) {
        int new_capacity = arr->capacity * 2;
        PaymentTransaction* new_transactions = realloc(arr->transactions, sizeof(PaymentTransaction) * new_capacity);
        if (!new_transactions) {
            // Handle the error case where realloc fails
            printf("Error: Failed to resize array\n");
            return;
        }
        arr->transactions = new_transactions;
        arr->capacity = new_capacity;
    }

    // Add the new transaction to the end of the array
    arr->transactions[arr->size++] = transaction;
}

// Function to update an existing transaction in the array
void update_transaction(PaymentTransactionArray* arr, int id, PaymentTransaction transaction) {
    // Find the index of the transaction with the given ID
    int index = -1;
    for (int i = 0; i < arr->size; i++) {
        if (arr->transactions[i].id == id) {
            index = i;
            break;
        }
    }

    // Check if the transaction was found and update it
    if (index != -1) {
        arr->transactions[index] = transaction;
    } else {
        printf("Error: Transaction with ID %d not found\n", id);
    }
}

// Function to retrieve transactions within a specified date range
void get_transactions(PaymentTransactionArray* arr, time_t start_time, time_t end_time) {
    // Iterate over the array and print all transactions within the date range
    for (int i = 0; i < arr->size; i++) {
        PaymentTransaction transaction = arr->transactions[i];
        if (transaction.timestamp >= start_time && transaction.timestamp <= end_time) {
            printf("Transaction ID: %d\n", transaction.id);
            printf("Customer Name: %s\n", transaction.customer_name);
            printf("Amount: %.2f\n", transaction.amount);
            printf("Timestamp: %s\n", ctime(&transaction.timestamp));
            printf("Payment Method: %s\n", transaction.payment_method);
            printf("Card Issuer: %s\n", transaction.card_issuer);
            printf("Transaction Status: %s\n", transaction.transaction_status);
        }
    }
}

// Function to filter transactions based on various criteria
void filter_transactions(PaymentTransactionArray* arr, char* payment_method, char* customer_segment) {
    // Iterate over the array and print all transactions that match the given criteria
    for (int i = 0; i < arr->size; i++) {
        PaymentTransaction transaction = arr->transactions[i];
        if (strcmp(transaction.payment_method, payment_method) == 0 && strcmp(transaction.customer_segment, customer_segment) == 0) {
            printf("Transaction ID: %d\n", transaction.id);
            printf("Customer Name: %s\n", transaction.customer_name);
            printf("Amount: %.2f\n", transaction.amount);
            printf("Timestamp: %s\n", ctime(&transaction.timestamp));
            printf("Payment Method: %s\n", transaction.payment_method);
            printf("Card Issuer: %s\n", transaction.card_issuer);
            printf("Transaction Status: %s\n", transaction.transaction_status);
        }
    }
}

// Function to handle concurrent access from multiple threads
void* thread_handler(void* arg) {
    // Get the array and the operation to perform as arguments
    PaymentTransactionArray* arr = (PaymentTransactionArray*)arg;
    char* op = (char*)malloc(sizeof(char) * 10);
    scanf("%s", op);

    // Perform the requested operation on the array
    if (strcmp(op, "add") == 0) {
        PaymentTransaction transaction;
        scanf("%d %s %.2f %ld %s %s %s", &transaction.id, transaction.customer_name, &transaction.amount, &transaction.timestamp, transaction.payment_method, transaction.card_issuer, transaction.transaction_status);
        add_transaction(arr, transaction);
    } else if (strcmp(op, "update") == 0) {
        int id;
        scanf("%d", &id);
        PaymentTransaction transaction;
        scanf("%s %s %.2f %ld %s %s %s", transaction.customer_name, &transaction.amount, &transaction.timestamp, transaction.payment_method, transaction.card_issuer, transaction.transaction_status);
        update_transaction(arr, id, transaction);
    } else if (strcmp(op, "get") == 0) {
        time_t start_time;
        scanf("%ld", &start_time);
        time_t end_time;
        scanf("%ld", &end_time);
        get_transactions(arr, start_time, end_time);
    } else if (strcmp(op, "filter") == 0) {
        char payment_method[32];
        scanf("%s", payment_method);
        char customer_segment[128];
        scanf("%s", customer_segment);
        filter_transactions(arr, payment_method, customer_segment);
    } else {
        printf("Error: Invalid operation\n");
    }

    // Free the memory allocated for the operation string
    free(op);
}

int main() {
    // Initialize the array with a default capacity of 10
    PaymentTransactionArray arr = {0, 10, NULL};

    // Create a thread pool to handle concurrent access from multiple threads
    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * 5);
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, thread_handler, &arr);
    }

    // Wait for all threads to finish before exiting the program
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory allocated for the thread pool and the array
    free(threads);
    free(arr.transactions);

    return 0;
}
