    time_t timestamp;
    float temperature;
    float humidity;
    float pressure;
    double latitude;
    double longitude;
} SensorReading;

// Define the array for storing sensor readings
SensorReading *readings = NULL;
size_t num_readings = 0;
size_t capacity = 0;

// Define the mutex and semaphore for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore = SEM_INITIALIZER(1);

// Function to add a new reading to the array
void addReading(SensorReading *reading) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the array is full and needs to be resized
    if (num_readings == capacity) {
        // Double the size of the array
        capacity *= 2;
        readings = realloc(readings, capacity * sizeof(SensorReading));
    }

    // Add the new reading to the end of the array
    readings[num_readings++] = *reading;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing reading in the array
void updateReading(SensorReading *reading) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Find the index of the reading to be updated
    size_t i = 0;
    for (i = 0; i < num_readings; i++) {
        if (readings[i].id == reading->id) {
            break;
        }
    }

    // Update the existing reading with the new values
    readings[i] = *reading;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve all readings within a specified time range
void getReadings(time_t start, time_t end) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Find the first and last indices of the time range
    size_t i = 0;
    while (i < num_readings && readings[i].timestamp < start) {
        i++;
    }
    size_t j = num_readings - 1;
    while (j >= i && readings[j].timestamp > end) {
        j--;
    }

    // Print the readings within the time range
    for (size_t k = i; k <= j; k++) {
        printf("%d %ld %.2f %.2f %.2f %.6f %.6f\n", readings[k].id, readings[k].timestamp, readings[k].temperature, readings[k].humidity, readings[k].pressure, readings[k].latitude, readings[k].longitude);
    }

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to filter readings based on environmental conditions or geographic proximity
void filterReadings(float temperature, float humidity, float pressure, double latitude, double longitude) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Find the first and last indices of the filtered readings
    size_t i = 0;
    while (i < num_readings && (temperature < 0 || readings[i].temperature < temperature)) {
        i++;
    }
    size_t j = num_readings - 1;
    while (j >= i && (humidity < 0 || readings[j].humidity < humidity)) {
        j--;
    }

    // Print the filtered readings
    for (size_t k = i; k <= j; k++) {
        printf("%d %ld %.2f %.2f %.2f %.6f %.6f\n", readings[k].id, readings[k].timestamp, readings[k].temperature, readings[k].humidity, readings[k].pressure, readings[k].latitude, readings[k].longitude);
    }

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

