void add_task(Task *new_task) {
    // Acquire the mutex for thread-safe operations
    pthread_mutex_lock(&task_mutex);

    // Allocate memory for the new task
    Task *new_task = malloc(sizeof(Task));
    if (new_task == NULL) {
        printf("Error: Failed to allocate memory for new task\n");
        return;
    }

    // Copy the data from the input task structure
    memcpy(new_task, new_task, sizeof(Task));

    // Add the new task to the collection
    tasks = realloc(tasks, (num_tasks + 1) * sizeof(Task));
    if (tasks == NULL) {
        printf("Error: Failed to allocate memory for new task\n");
        return;
    }
    tasks[num_tasks] = new_task;
    num_tasks++;

    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&task_mutex);

    // Log the addition of a new task
    log("Added task %d with priority %d and status %s\n", new_task->id, new_task->priority, new_task->status);
}

// Function to update an existing task
