    int i;
    for (i = 0; i < num_tasks; i++) {
        if (tasks[i]->id == updated_task->id) {
            break;
        }
    }

    // Check if the task was found in the collection
    if (i == num_tasks) {
        printf("Error: Task with ID %d not found\n", updated_task->id);
        return;
    }

    // Update the task in the collection
    memcpy(tasks[i], updated_task, sizeof(Task));

    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&task_mutex);

    // Log the update of a task
    log("Updated task %d with priority %d and status %s\n", updated_task->id, updated_task->priority, updated_task->status);
}

