class SensorDataManager {
public:
    struct SensorData {
        int timestamp;
        float temperature;
        float humidity;
        std::string location;
    };

    void addSensorData(const SensorData& data) {
        std::lock_guard<std::mutex> lock(dataMutex);
        sensorData.push_back(data);
    }

    void updateSensorData(int timestamp, const SensorData& data) {
        std::lock_guard<std::mutex> lock(dataMutex);
        for (auto it = sensorData.begin(); it != sensorData.end(); ++it) {
            if (it->timestamp == timestamp) {
                *it = data;
                break;
            }
        }
    }

    std::vector<SensorData> getSensorData(int startTime, int endTime) {
        std::lock_guard<std::mutex> lock(dataMutex);
        std::vector<SensorData> result;
        for (auto it = sensorData.begin(); it != sensorData.end(); ++it) {
            if (it->timestamp >= startTime && it->timestamp <= endTime) {
                result.push_back(*it);
            }
        }
        return result;
    }

    std::vector<SensorData> getRecentSensorData(int location, int numPoints) {
        std::lock_guard<std::mutex> lock(dataMutex);
        std::vector<SensorData> result;
        for (auto it = sensorData.begin(); it != sensorData.end(); ++it) {
            if (it->location == location && result.size() < numPoints) {
                result.push_back(*it);
            }
        }
        return result;
    }

    void pruneOldData(int duration) {
        std::lock_guard<std::mutex> lock(dataMutex);
        auto it = sensorData.begin();
        while (it != sensorData.end()) {
            if ((*it).timestamp < std::chrono::steady_clock::now() - duration) {
                it = sensorData.erase(it);
            } else {
                ++it;
            }
        }
    }

    void logOperation(const std::string& operation, const SensorData& data) {
        std::lock_guard<std::mutex> lock(logMutex);
        log.push_back({operation, data});
    }

    void flushLog() {
        std::lock_guard<std::mutex> lock(logMutex);
        for (auto& entry : log) {
            std::ofstream ofs("log.txt", std::ios::app);
            ofs << entry.operation << " " << entry.data.timestamp << " " << entry.data.temperature << " " << entry.data.humidity << " " << entry.data.location << "\n";
        }
    }

    void serialize(const std::string& filename) {
        std::lock_guard<std::mutex> lock(dataMutex);
        std::ofstream ofs(filename, std::ios::binary);
        for (auto it = sensorData.begin(); it != sensorData.end(); ++it) {
            ofs.write((char*)&(*it), sizeof(SensorData));
        }
    }

private:
    std::vector<SensorData> sensorData;
    std::mutex dataMutex;
    std::condition_variable dataCondVar;
    std::vector<std::pair<std::string, SensorData>> log;
    std::mutex logMutex;
};
