        return -1;
    }
    profiles[num_profiles++] = *profile;
    return 0;
}

// Function to update an existing profile
int update_profile(int id, Profile *profile) {
    for (size_t i = 0; i < num_profiles; i++) {
        if (profiles[i].id == id) {
            profiles[i] = *profile;
            return 0;
        }
    }
    return -1;
}

// Function to retrieve a profile based on its last login date
Profile *get_profile(time_t last_login) {
    for (size_t i = 0; i < num_profiles; i++) {
        if (profiles[i].last_login == last_login) {
            return &profiles[i];
        }
    }
    return NULL;
}

// Function to free all allocated memory when the collection is no longer needed
void free_memory() {
    for (size_t i = 0; i < num_profiles; i++) {
        free(profiles[i].username);
        free(profiles[i].email);
    }
    free(profiles);
}

// Function to handle concurrent access from multiple threads without causing data corruption or race conditions
void *concurrent_access(void *args) {
    int id = (int)(long)args;
    Profile *profile = get_profile(id);
    if (profile != NULL) {
        update_profile(id, profile);
    } else {
        add_profile(profile);
    }
}

// Function to periodically check and deactivate profiles that have been inactive for more than a specified duration
void periodic_check() {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < num_profiles; i++) {
        if (current_time - profiles[i].last_login > INACTIVE_DURATION) {
            profiles[i].status = false;
        }
    }
}

// Function to log each operation performed on the profile collection
void log(int level, char *message) {
