// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the maximum size limit for the allocated structures array
#define MAX_STRUCTURES 10000

// Define a global variable to track the total number of successfully allocated structures
static int num_structures = 0;

// Define a mutex lock to ensure thread safety when accessing the allocated structures array
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Define a function to allocate memory for an NFAPI_CRC_INDICATION_PDU_T structure
NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    // Allocate memory for the structure
    NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Check if allocation was successful
    if (!structure) {
        return NULL;
    }

    // Initialize the structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    structure->RX_UE_INFORMATION_TAG = 0x1234;
    structure->RNTI = 0x5678;
    structure->CRCFLAG = (uint8_t)rand() % 2;

    // Increment the total number of successfully allocated structures
    num_structures++;

    return structure;
}

// Define a function to free memory for an NFAPI_CRC_INDICATION_PDU_T structure
void free_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    // Check if the structure is NULL
    if (!structure) {
        return;
    }

    // Decrement the total number of successfully allocated structures
    num_structures--;

    // Free the memory for the structure
    free(structure);
}

// Define a function to dynamically manage an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** manage_structures(int num_entries) {
    // Validate the number of entries is within the maximum size limit
    if (num_entries > MAX_STRUCTURES) {
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T** structures = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Check if allocation was successful
    if (!structures) {
        return NULL;
    }

    // Initialize the array of structures with NULL pointers
    for (int i = 0; i < num_entries; i++) {
        structures[i] = NULL;
    }

    // Lock the mutex lock to ensure thread safety when accessing the allocated structures array
    pthread_mutex_lock(&lock);

    // Iterate over the array of structures and allocate memory for each structure
    for (int i = 0; i < num_entries; i++) {
        // Allocate memory for the structure
        NFAPI_CRC_INDICATION_PDU_T* structure = allocate_structure();

        // Check if allocation was successful
        if (!structure) {
            // Free any allocated structures and return NULL
            for (int j = 0; j < i; j++) {
                free_structure(structures[j]);
            }
            free(structures);
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        // Set the structure in the array of structures
        structures[i] = structure;
    }

    // Unlock the mutex lock to release thread safety
    pthread_mutex_unlock(&lock);

    return structures;
}

