#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a structure to represent a task
typedef struct Task {
    int id;
    int priority;
    char status[10];
    time_t creation_time;
} Task;

// Define a linked list data structure to store tasks
typedef struct TaskListNode {
    Task *task;
    struct TaskListNode *next;
} TaskListNode;

// Define a global variable to store the head of the task list
TaskListNode *head = NULL;

// Define a mutex to protect the task list from concurrent access
pthread_mutex_t task_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to add a new task to the task list
void addTask(int id, int priority, char *status) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&task_list_mutex);

    // Create a new task structure and allocate memory for it
    Task *new_task = (Task *)malloc(sizeof(Task));
    new_task->id = id;
    new_task->priority = priority;
    strcpy(new_task->status, status);
    new_task->creation_time = time(NULL);

    // Add the new task to the head of the list
    TaskListNode *new_node = (TaskListNode *)malloc(sizeof(TaskListNode));
    new_node->task = new_task;
    new_node->next = head;
    head = new_node;

    // Unlock the mutex and return
    pthread_mutex_unlock(&task_list_mutex);
}

// Define a function to update an existing task in the task list
void updateTask(int id, int priority, char *status) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&task_list_mutex);

    // Find the node containing the task with the specified ID
    TaskListNode *node = head;
    while (node != NULL && node->task->id != id) {
        node = node->next;
    }

    // If the task was found, update its priority and status
    if (node != NULL) {
        node->task->priority = priority;
        strcpy(node->task->status, status);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&task_list_mutex);
}

// Define a function to retrieve tasks from the task list based on priority or creation time
void getTasks(int priority, time_t creation_time) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&task_list_mutex);

    // Find the node containing the task with the specified priority or creation time
    TaskListNode *node = head;
    while (node != NULL && (node->task->priority < priority || node->task->creation_time < creation_time)) {
        node = node->next;
    }

    // If a task was found, print its ID and status
    if (node != NULL) {
        printf("Task ID: %d\n", node->task->id);
        printf("Status: %s\n", node->task->status);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&task_list_mutex);
}

// Define a function to free all allocated memory when the task collection is no longer needed
void freeTasks() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&task_list_mutex);

    // Free all nodes in the task list
    TaskListNode *node = head;
    while (node != NULL) {
        TaskListNode *next = node->next;
        free(node);
        node = next;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&task_list_mutex);
}

// Define a function to periodically expire tasks that are older than a specified duration
void expireTasks(int duration) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&task_list_mutex);

    // Find the node containing the task with the oldest creation time
    TaskListNode *node = head;
    while (node != NULL && node->task->creation_time >= duration) {
        node = node->next;
    }

    // If a task was found, remove it from the list and free its memory
    if (node != NULL) {
        TaskListNode *prev = head;
        while (prev->next != node) {
            prev = prev->next;
        }
        TaskListNode *next = node->next;
        free(node);
        prev->next = next;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&task_list_mutex);
}

// Define a function to log each operation performed on the task collection
void logOperation(char *operation, int id) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&task_list_mutex);

    // Print the operation and its ID to the log file
    printf("[%s] %d\n", operation, id);

    // Unlock the mutex and return
    pthread_mutex_unlock(&task_list_mutex);
}

// Define a function to serialize the current task collection state into a file format of your choice
void serializeTasks(char *filename) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&task_list_mutex);

    // Open the output file for writing
    FILE *outfile = fopen(filename, "w");

    // Write the task list to the output file
    TaskListNode *node = head;
    while (node != NULL) {
        fprintf(outfile, "%d %s %d\n", node->task->id, node->task->status, node->task->priority);
        node = node->next;
    }

    // Close the output file and return
    fclose(outfile);
    pthread_mutex_unlock(&task_list_mutex);
}
