// Struct to store information about a hash function or cipher
typedef struct {
    const char* name;
    void (*func)(const unsigned char*, size_t, unsigned char*);
    int param1;
} HashCipherInfo;

// Array of available hash functions and block ciphers
HashCipherInfo* hashCiphers = NULL;
size_t numHashCiphers = 0;

// Function to return a list of available cryptographic hash functions and block ciphers
void getAvailableHashCiphers(HashCipherInfo** hashCiphers, size_t* numHashCiphers) {
    // Check if the array is already allocated
    if (hashCiphers != NULL) {
        return;
    }

    // Get the number of available hash functions and block ciphers
    int numHashFunctions = EVP_get_digestbyname_all();
    int numBlockCiphers = EVP_get_cipherbyname_all();

    // Allocate memory for the array of hash function and block cipher information
    hashCiphers = (HashCipherInfo*)malloc(sizeof(HashCipherInfo) * (numHashFunctions + numBlockCiphers));
    if (hashCiphers == NULL) {
        return;
    }

    // Fill the array with information about each hash function and block cipher
    for (int i = 0; i < numHashFunctions; i++) {
        const EVP_MD* md = EVP_get_digestbyname(EVP_md_list[i]);
        if (md != NULL) {
            hashCiphers[numHashCiphers].name = EVP_md_nid(md);
            hashCiphers[numHashCiphers].func = md->md_update;
            hashCiphers[numHashCiphers].param1 = 0;
            numHashCiphers++;
        }
    }
    for (int i = 0; i < numBlockCiphers; i++) {
        const EVP_CIPHER* cipher = EVP_get_cipherbyname(EVP_cipher_list[i]);
        if (cipher != NULL) {
            hashCiphers[numHashCiphers].name = EVP_cipher_nid(cipher);
            hashCiphers[numHashCiphers].func = cipher->cipher;
            hashCiphers[numHashCiphers].param1 = 0;
            numHashCiphers++;
        }
    }

    // Return the array of hash function and block cipher information
    *hashCiphers = hashCiphers;
    *numHashCiphers = numHashCiphers;
}
