#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <assert.h>

// Define the data structure to store algorithm identifiers and configuration blocks
typedef struct {
    int id;
    char type[10];
    void* metadata;
} AlgorithmConfig;

// Define the data structure to store the list of available algorithms
typedef struct {
    AlgorithmConfig* configs;
    size_t num_configs;
    size_t capacity;
    pthread_mutex_t mutex;
} AlgorithmList;

// Initialize an empty algorithm list with a given capacity
void init_algorithm_list(AlgorithmList* list, size_t capacity) {
    assert(list != NULL);
    list->configs = (AlgorithmConfig*)malloc(capacity * sizeof(AlgorithmConfig));
    if (list->configs == NULL) {
        printf("Error: Failed to allocate memory for algorithm list\n");
        exit(1);
    }
    list->num_configs = 0;
    list->capacity = capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new algorithm configuration to the list
void add_algorithm_config(AlgorithmList* list, int id, char* type, void* metadata) {
    assert(list != NULL && id >= 0 && type != NULL && metadata != NULL);
    pthread_mutex_lock(&list->mutex);
    if (list->num_configs == list->capacity) {
        // Resize the list if it's full
        size_t new_capacity = list->capacity + 100;
        AlgorithmConfig* new_configs = (AlgorithmConfig*)realloc(list->configs, new_capacity * sizeof(AlgorithmConfig));
        if (new_configs == NULL) {
            printf("Error: Failed to resize algorithm list\n");
            exit(1);
        }
        list->configs = new_configs;
        list->capacity = new_capacity;
    }
    // Add the new configuration to the end of the list
    list->configs[list->num_configs].id = id;
    strcpy(list->configs[list->num_configs].type, type);
    list->configs[list->num_configs].metadata = metadata;
    list->num_configs++;
    pthread_mutex_unlock(&list->mutex);
}

// Get the algorithm configuration for a given identifier
AlgorithmConfig* get_algorithm_config(AlgorithmList* list, int id) {
    assert(list != NULL && id >= 0);
    pthread_mutex_lock(&list->mutex);
    AlgorithmConfig* config = NULL;
    for (size_t i = 0; i < list->num_configs; i++) {
        if (list->configs[i].id == id) {
            config = &list->configs[i];
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return config;
}

// Update the algorithm configuration for a given identifier
void update_algorithm_config(AlgorithmList* list, int id, char* type, void* metadata) {
    assert(list != NULL && id >= 0 && type != NULL && metadata != NULL);
    pthread_mutex_lock(&list->mutex);
    AlgorithmConfig* config = get_algorithm_config(list, id);
    if (config == NULL) {
        printf("Error: Could not find algorithm configuration for ID %d\n", id);
        exit(1);
    }
    strcpy(config->type, type);
    config->metadata = metadata;
    pthread_mutex_unlock(&list->mutex);
}

// Remove an algorithm configuration from the list
void remove_algorithm_config(AlgorithmList* list, int id) {
    assert(list != NULL && id >= 0);
    pthread_mutex_lock(&list->mutex);
    AlgorithmConfig* config = get_algorithm_config(list, id);
    if (config == NULL) {
        printf("Error: Could not find algorithm configuration for ID %d\n", id);
        exit(1);
    }
    // Shift all configurations after the removed one to the left
    for (size_t i = config - list->configs; i < list->num_configs - 1; i++) {
        list->configs[i] = list->configs[i + 1];
    }
    list->num_configs--;
    pthread_mutex_unlock(&list->mutex);
}

// Free the memory allocated for the algorithm list
void free_algorithm_list(AlgorithmList* list) {
    assert(list != NULL);
    pthread_mutex_destroy(&list->mutex);
    free(list->configs);
