Task *tasks = NULL;
int num_tasks = 0;

// Define the mutex for protecting shared resources
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to add a new task
void add_task(Task *task) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Allocate memory for the new task
    Task *new_task = (Task *)malloc(sizeof(Task));
    if (new_task == NULL) {
        printf("Error: Failed to allocate memory for new task\n");
        return;
    }

    // Copy the contents of the given task into the new task
    memcpy(new_task, task, sizeof(Task));

    // Add the new task to the collection
    tasks = (Task *)realloc(tasks, (num_tasks + 1) * sizeof(Task));
    if (tasks == NULL) {
        printf("Error: Failed to reallocate memory for task collection\n");
        return;
    }
    tasks[num_tasks++] = new_task;

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Define the function to update an existing task
void update_task(int id, Task *task) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Find the task with the given ID in the collection
    int i;
    for (i = 0; i < num_tasks; i++) {
        if (tasks[i]->id == id) {
            break;
        }
    }

    // If the task was found, update its contents
    if (i < num_tasks) {
        memcpy(tasks[i], task, sizeof(Task));
    } else {
