// Define the structure for TrafficEvent
typedef struct {
    long timestamp;
    int event_type;
    int associated_vehicle_ids[10]; // Maximum of 10 associated vehicle IDs
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} TrafficEvent;

// Define the shared memory array for TrafficEvents
TrafficEvent *traffic_events = NULL;
size_t traffic_event_count = 0;
size_t traffic_event_capacity = 0;

// Define the semaphore for synchronizing access to the shared memory array
sem_t traffic_event_sem;

// Define the function for adding a new TrafficEvent
void add_traffic_event(TrafficEvent *event) {
    // Acquire the semaphore
    sem_wait(&traffic_event_sem);

    // Check if there is enough capacity in the shared memory array
    if (traffic_event_count >= traffic_event_capacity) {
        // If not, reallocate the shared memory array with a new size
        traffic_event_capacity += 10;
        traffic_events = realloc(traffic_events, traffic_event_capacity * sizeof(TrafficEvent));
    }

    // Copy the event to the next available slot in the shared memory array
    memcpy(&traffic_events[traffic_event_count], event, sizeof(TrafficEvent));

    // Increment the count of traffic events
    traffic_event_count++;

    // Release the semaphore
    sem_post(&traffic_event_sem);
}

// Define the function for updating an existing TrafficEvent
void update_traffic_event(TrafficEvent *event) {
    // Acquire the semaphore
    sem_wait(&traffic_event_sem);

    // Find the index of the event in the shared memory array
    size_t index = 0;
    while (index < traffic_event_count && &traffic_events[index] != event) {
        index++;
    }

    // Check if the event was found
    if (index == traffic_event_count) {
        // If not, release the semaphore and return
        sem_post(&traffic_event_sem);
        return;
    }

    // Update the event in the shared memory array
    memcpy(&traffic_events[index], event, sizeof(TrafficEvent));

    // Release the semaphore
    sem_post(&traffic_event_sem);
}

// Define the function for retrieving TrafficEvents within a specified time range
void retrieve_traffic_events(long start_time, long end_time) {
    // Acquire the semaphore
    sem_wait(&traffic_event_sem);

    // Iterate over the shared memory array and find all events within the specified time range
    for (size_t i = 0; i < traffic_event_count; i++) {
        TrafficEvent *event = &traffic_events[i];
        if (event->timestamp >= start_time && event->timestamp <= end_time) {
            // Print the event details
            printf("Traffic Event: %ld, %d\n", event->timestamp, event->event_type);
        }
    }

    // Release the semaphore
    sem_post(&traffic_event_sem);
