// Define the alignment requirements for different types of structures
const int ALIGNMENT_REQUIREMENTS[4] = { 1, 2, 4, 8 };

// Define the slab allocator class
class SlabAllocator {
public:
    // Constructor
    SlabAllocator(int alignment) : alignment_(alignment), free_list_(nullptr) {}

    // Allocate memory from the slab allocator
    void* allocate(size_t size) {
        // Check if there is enough space in the current slab to satisfy the request
        if (free_list_ && free_list_->size() >= size) {
            return free_list_->allocate(size);
        }

        // If there is not enough space, allocate a new slab and add it to the list of free slabs
        void* ptr = aligned_alloc(alignment_, size);
        if (!ptr) {
            throw runtime_error("Failed to allocate memory");
        }
        free_list_ = make_shared<Slab>(ptr, size);
        return ptr;
    }

    // Deallocate memory from the slab allocator
    void deallocate(void* ptr) {
        // Check if the pointer is in the current slab
        if (free_list_ && free_list_->contains(ptr)) {
            free_list_->deallocate(ptr);
            return;
        }

        // If the pointer is not in the current slab, add it to the list of free slabs
        free_list_ = make_shared<Slab>(ptr, 0);
    }

private:
    // The alignment requirement for the slab allocator
    int alignment_;

    // The list of free slabs
    shared_ptr<Slab> free_list_;
};

// Define the slab class
class Slab {
public:
    // Constructor
    Slab(void* ptr, size_t size) : ptr_(ptr), size_(size), next_(nullptr) {}

    // Allocate memory from the slab
    void* allocate(size_t size) {
        if (size > size_) {
            return nullptr;
        }
        void* ptr = ptr_;
        ptr_ += size;
        size_ -= size;
        return ptr;
    }

    // Deallocate memory from the slab
    void deallocate(void* ptr) {
        if (ptr < ptr_ || ptr > ptr_ + size_) {
            throw runtime_error("Invalid pointer");
        }
        size_ += ptr - ptr_;
        ptr_ = ptr;
    }

    // Check if the slab contains a given pointer
    bool contains(void* ptr) {
        return ptr >= ptr_ && ptr < ptr_ + size_;
    }

private:
    // The starting address of the slab
    void* ptr_;

    // The size of the slab
    size_t size_;

    // The next slab in the list of free slabs
    shared_ptr<Slab> next_;
};

