    void parse() {
        ifstream file(filename_, ios::binary);
        if (!file.is_open()) {
            throw runtime_error("Failed to open file");
        }

        // Read the size of the audio file
        file.read((char*)&size_, sizeof(size_));

        // Read the duration of the audio file
        file.read((char*)&duration_, sizeof(duration_));

        // Read the artist name for the audio file
        string artist;
        file.read((char*)&artist, sizeof(artist));

        // Read the album name for the audio file
        string album;
        file.read((char*)&album, sizeof(album));
    }

