    AudioFileProcessor(const string& filename) : filename_(filename), size_(0), duration_(0), artist_(""), album_("") {}

    // Process the audio file and generate a report
    void process() {
        // Parse the audio file metadata
        AudioFileParser parser(filename_);
        parser.parse();

        // Update the size of the audio file
        size_ = parser.getSize();

        // Update the duration of the audio file
        duration_ = parser.getDuration();

        // Update the artist name for the audio file
        artist_ = parser.getArtist();

        // Update the album name for the audio file
        album_ = parser.getAlbum();
    }

