            fclose(file);
            free(*doubles);
            return;
        }
        *sensor_readings = (SensorReading **)realloc(*sensor_readings, sizeof(SensorReading *) * (*sensor_readings + 1));
        if (*sensor_readings == NULL) {
            printf("Error: Failed to allocate memory for sensor readings\n");
            fclose(file);
            free(*doubles);
            free(*strings);
            return;
        }
    }

    // Close the file
    fclose(file);
}

// Function to periodically clean up sensor readings that are older than a predefined threshold, ensuring that only recent data remains in memory.
void cleanupSensorReadings(double **doubles, char ***strings, SensorReading ***sensor_readings) {
    // Define the threshold for cleaning up sensor readings (in seconds)
    int threshold = 300;

    // Get the current time in seconds
    time_t now = time(NULL);

    // Iterate over the sensor readings and remove any that are older than the threshold
    for (int i = 0; i < *doubles; i++) {
        if ((*sensor_readings[i].timestamp + threshold) < now) {
            free(*doubles[i]);
            free(*strings[i]);
            free(*sensor_readings[i]);
            (*doubles)--;
            (*strings)--;
            (*sensor_readings)--;
        }
    }
}

// Function to dynamically adjust the cleanup threshold based on current memory usage, ensuring optimal performance under varying load conditions.
void adjustCleanupThreshold(double **doubles, char ***strings, SensorReading ***sensor_readings) {
    // Define the maximum amount of memory that can be used for sensor readings (in MB)
    int max_memory = 100;

    // Get the current memory usage in bytes
    size_t memory_usage = (*doubles * sizeof(double)) + (*strings * sizeof(char)) + (*sensor_readings * sizeof(SensorReading));

    // Calculate the number of sensor readings that can be stored in the maximum amount of memory
    int max_readings = (max_memory * 1024 * 1024) / sizeof(SensorReading);

    // Adjust the cleanup threshold based on the current memory usage and the maximum number of sensor readings that can be stored in the maximum amount of memory
    int adjusted_threshold = (memory_usage / max_readings) * 100;
}
