// Define the structure for a TrafficEvent
typedef struct {
    long timestamp; // Timestamp of the event in milliseconds since epoch
    int type; // Type of traffic event (e.g., "speed limit violation", "accident")
    char *vehicle_ids; // List of associated vehicle IDs (comma-separated)
    char *source_system; // Source system responsible for reporting the event
} TrafficEvent;

// Define a dynamic array to store the traffic events
typedef struct {
    int size; // Current number of elements in the array
    int capacity; // Maximum number of elements that can be stored in the array
    TrafficEvent *events; // Array of TrafficEvents
} TrafficEventArray;

// Initialize a new TrafficEventArray with a given capacity
TrafficEventArray* init_traffic_event_array(int capacity) {
    TrafficEventArray *arr = malloc(sizeof(TrafficEventArray));
    arr->size = 0;
    arr->capacity = capacity;
    arr->events = calloc(capacity, sizeof(TrafficEvent));
    return arr;
}

// Add a new TrafficEvent to the array
void add_traffic_event(TrafficEventArray *arr, long timestamp, int type, char *vehicle_ids, char *source_system) {
    // Check if the array is full and needs to be resized
    if (arr->size == arr->capacity) {
        arr->capacity *= 2;
        arr->events = realloc(arr->events, arr->capacity * sizeof(TrafficEvent));
    }

    // Add the new event to the array
    TrafficEvent *event = &arr->events[arr->size++];
    event->timestamp = timestamp;
    event->type = type;
    event->vehicle_ids = strdup(vehicle_ids);
    event->source_system = strdup(source_system);
}

// Update an existing TrafficEvent in the array
void update_traffic_event(TrafficEventArray *arr, long timestamp, int type, char *vehicle_ids, char *source_system) {
    // Find the index of the event to be updated
    int i;
    for (i = 0; i < arr->size; i++) {
        if (arr->events[i].timestamp == timestamp) {
            break;
        }
    }

    // Update the event at the found index
    TrafficEvent *event = &arr->events[i];
    event->type = type;
    free(event->vehicle_ids);
    event->vehicle_ids = strdup(vehicle_ids);
    free(event->source_system);
    event->source_system = strdup(source_system);
}

// Retrieve TrafficEvents within a specified time range
void retrieve_traffic_events(TrafficEventArray *arr, long start_time, long end_time) {
    // Iterate over the events in the array and filter those within the time range
    for (int i = 0; i < arr->size; i++) {
        TrafficEvent *event = &arr->events[i];
        if (event->timestamp >= start_time && event->timestamp <= end_time) {
            // Print the event details
            printf("Traffic Event: %ld, Type: %d, Vehicle IDs: %s, Source System: %s\n", event->timestamp, event->type, event->vehicle_ids, event->source_system);
        }
    }
}

// Free the memory allocated for the TrafficEventArray
void free_traffic_event_array(TrafficEventArray *arr) {
    for (int i = 0; i < arr->size; i++) {
        free(arr->events[i].vehicle_ids);
        free(arr->events[i].source_system);
    }
    free(arr->events);
    free(arr);
}
```
