    double *value;
    char *tag;
};

void manage_memory(int num_records, int values_size, int tags_size) {
    // Allocate memory for the array of record pointers
    struct record **records = malloc(num_records * sizeof(struct record *));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    // Allocate memory for the array of double values
    double *values = malloc(values_size * sizeof(double));
    if (values == NULL) {
        fprintf(stderr, "Failed to allocate memory for values\n");
        free(records);
        return;
    }

    // Allocate memory for the array of char tags
    char *tags = malloc(tags_size * sizeof(char));
    if (tags == NULL) {
        fprintf(stderr, "Failed to allocate memory for tags\n");
        free(records);
        free(values);
        return;
    }

    // Allocate memory for the array of entry pointers
    struct entry **entries = malloc(num_records * sizeof(struct entry *));
    if (entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for entries\n");
        free(records);
        free(values);
        free(tags);
        return;
    }

    // Initialize the values array with consecutive double values starting from 0.0
    for (int i = 0; i < values_size; i++) {
        values[i] = i * 1.0;
    }

    // Initialize the tags array with alternating uppercase and lowercase letters starting from 'A'
    char tag_char = 'A';
    for (int i = 0; i < tags_size; i++) {
        tags[i] = tag_char++;
        if (tag_char > 'Z') {
            tag_char = 'a';
        }
    }

    // Initialize the entries array with pointers to the corresponding values and tags
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(struct record));
        if (records[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for record %d\n", i);
            free(records);
            free(values);
            free(tags);
            return;
        }
        records[i]->key = rand() % 100;
        records[i]->offsets = malloc(records[i]->key * sizeof(long));
        if (records[i]->offsets == NULL) {
            fprintf(stderr, "Failed to allocate memory for offsets in record %d\n", i);
            free(records[i]);
            continue;
        }
        records[i]->value = rand() % 1000 + 1;
        for (int j = 0; j < records[i]->key; j++) {
            records[i]->offsets[j] = rand() % values_size;
        }
        entries[i] = malloc(sizeof(struct entry));
        if (entries[i] == NULL) {
            fprintf(stderr, "Failed to allocate memory for entry %d\n", i);
            free(records[i]->offsets);
            free(records[i]);
            continue;
        }
        entries[i]->value = &values[records[i]->offsets[0]];
        entries[i]->tag = &tags[records[i]->key];
    }
}
