// Define a structure to represent a measurement and its corresponding tag
typedef struct {
    double measurement;
    char tag[10];
} MeasurementTag;

// Define an array of measurements and tags
MeasurementTag *measurements = NULL;
size_t num_measurements = 0;
char **tags = NULL;
size_t num_tags = 0;

// Define a function to allocate memory for the arrays
void allocate_memory(size_t num_measurements, size_t num_tags) {
    measurements = (MeasurementTag *)malloc(num_measurements * sizeof(MeasurementTag));
    tags = (char **)malloc(num_tags * sizeof(char *));
}

// Define a function to free memory for the arrays
void free_memory() {
    if (measurements != NULL) {
        free(measurements);
        measurements = NULL;
    }
    if (tags != NULL) {
        free(tags);
        tags = NULL;
    }
}

// Define a function to initialize the arrays with default values
void init_arrays() {
    for (size_t i = 0; i < num_measurements; i++) {
        measurements[i].measurement = 0.0;
        strcpy(tags[i], "default");
    }
}

// Define a function to add a new measurement and tag
void add_measurement(double measurement, char *tag) {
    // Check if the arrays have been allocated
    if (measurements == NULL || tags == NULL) {
        allocate_memory(num_measurements + 1, num_tags + 1);
    }

    // Add the new measurement and tag to the arrays
    measurements[num_measurements].measurement = measurement;
    strcpy(tags[num_tags], tag);

    // Increment the number of measurements and tags
    num_measurements++;
    num_tags++;
}

// Define a function to get the total number of measurements
size_t get_num_measurements() {
    return num_measurements;
}

// Define a function to get the total number of tags
size_t get_num_tags() {
    return num_tags;
}

// Define a function to get the measurement at a given index
double get_measurement(size_t index) {
    if (index >= num_measurements) {
        return 0.0;
    }
    return measurements[index].measurement;
}

// Define a function to get the tag at a given index
char *get_tag(size_t index) {
    if (index >= num_tags) {
        return NULL;
    }
    return tags[index];
}

// Define a function to free all allocated memory and reset the internal state
void reset() {
    free_memory();
    num_measurements = 0;
    num_tags = 0;
}
