int handle_duplicate_identifiers(char **identifiers, int num_elements) {
    // Allocate memory for a temporary array of unique identifiers
    char **unique_identifiers = (char **)malloc(num_elements * sizeof(char *));
    if (!unique_identifiers) {
        return -1;
