    arr->data = (char **)malloc(size * sizeof(char *));
    for (int i = 0; i < size; i++) {
        arr->data[i] = (char *)malloc(1024 * sizeof(char));
    }
    arr->size = size;
}

void free_array_string(array_string_t *arr) {
    for (int i = 0; i < arr->size; i++) {
