#include <stdio.h>

// Define structure for packet info
typedef struct PacketInfo {
    PacketHeader header;
    Payload payload;
    PacketState state;
} PacketInfo;

// Define function to initialize and configure network interface
void init_network_interface(NetworkInterface *iface) {
    // Initialize list of packet info structures
    iface->packets = malloc(sizeof(PacketInfo) * INITIAL_PACKET_COUNT);
    iface->packet_count = 0;
    iface->max_packet_count = INITIAL_PACKET_COUNT;

    // Initialize packet state tracking variables
    iface->dropped_packets = 0;
}

// Define function to process a single data packet
void process_packet(NetworkInterface *iface, PacketHeader header, Payload payload) {
    // Check if list of packet info structures needs to be resized
    if (iface->packet_count >= iface->max_packet_count) {
        // Resize list by doubling its size
        iface->max_packet_count *= 2;
        iface->packets = realloc(iface->packets, sizeof(PacketInfo) * iface->max_packet_count);
    }

    // Add new packet info structure to list
    PacketInfo *new_packet = &iface->packets[iface->packet_count++];
    new_packet->header = header;
    new_packet->payload = payload;
    new_packet->state = PACKET_STATE_NEW;
}

// Define function to track and report dropped packets
void track_dropped_packets(NetworkInterface *iface) {
    // Increment dropped packet count for each packet that is dropped due to overflow
    if (iface->packet_count >= iface->max_packet_count) {
        iface->dropped_packets++;
    }
}
