        printf("Error: Failed to allocate memory for packet list\n");
        return;
    }

    // Initialize the list of PacketInfo structures
    for (int i = 0; i < num_packets; i++) {
        packet_list[i].header.size = max_packet_size;
        packet_list[i].payload.data = malloc(max_packet_size);
        if (!packet_list[i].payload.data) {
            printf("Error: Failed to allocate memory for payload data\n");
            return;
        }
        packet_list[i].state = PROCESSING;
    }

    // Allocate memory for the three arrays
    long *offset_array = (long *)malloc(num_packets * sizeof(long));
    if (!offset_array) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }
    int *key_array = (int *)malloc(num_packets * sizeof(int));
    if (!key_array) {
        printf("Error: Failed to allocate memory for key array\n");
        return;
    }
    double *value_array = (double *)malloc(num_packets * sizeof(double));
    if (!value_array) {
        printf("Error: Failed to allocate memory for value array\n");
        return;
    }

    // Initialize the three arrays
    for (int i = 0; i < num_packets; i++) {
        offset_array[i] = rand() % max_offset;
        key_array[i] = rand() % (max_key - min_key + 1) + min_key;
        value_array[i] = (double)(rand() % (INT_MAX - INT_MIN)) / RAND_MAX * (max_value - min_value) + min_value;
    }

    // Allocate memory for the array of records
    record *record_list = (record *)malloc(num_packets * sizeof(record));
    if (!record_list) {
        printf("Error: Failed to allocate memory for record list\n");
        return;
    }

    // Initialize the array of records
    for (int i = 0; i < num_packets; i++) {
        record_list[i].key = key_array[i];
        record_list[i].value = value_array[i];
        record_list[i].offset_array = offset_array;
        record_list[i].key_array = key_array;
        record_list[i].value_array = value_array;
    }

    // Initialize the logging mechanism
    FILE *log_file = fopen("network_interface.log", "w");
    if (!log_file) {
        printf("Error: Failed to open log file\n");
        return;
    }

    // Log the number of successful allocations and failures, as well as the range parameters used during each invocation
    fprintf(log_file, "Number of successful allocations: %d\n", num_packets);
    fprintf(log_file, "Number of failed allocations: 0\n");
    fprintf(log_file, "Range parameters used:\n");
