    fprintf(log_file, "\tMin key: %d\n", min_key);
    fprintf(log_file, "\tMax key: %d\n", max_key);
    fprintf(log_file, "\tMin value: %f\n", min_value);
    fprintf(log_file, "\tMax value: %f\n", max_value);

    // Log the distribution of random values generated
    int num_values = 10;
    double *value_distribution = (double *)malloc(num_values * sizeof(double));
    if (!value_distribution) {
        printf("Error: Failed to allocate memory for value distribution\n");
