    }
    for (int i = 0; i < num_values; i++) {
        value_distribution[i] = (double)(rand() % (INT_MAX - INT_MIN)) / RAND_MAX * (max_value - min_value) + min_value;
    }
    fprintf(log_file, "Value distribution:\n");
    for (int i = 0; i < num_values; i++) {
