// Define the function to add an algorithm to the list of available algorithms
void addAlgorithm(AlgorithmList* list, int id, char* type, void* config) {
    // Check if the list is full and needs to be resized
    if (list->size == list->capacity) {
        // Double the capacity of the list
        list->capacity *= 2;
        AlgorithmConfig* new_algorithms = (AlgorithmConfig*)realloc(list->algorithms, list->capacity * sizeof(AlgorithmConfig));
        if (!new_algorithms) {
            // Handle memory allocation failure gracefully by terminating the function without leaving the application in an inconsistent state
            return;
        }
        list->algorithms = new_algorithms;
    }

    // Add the algorithm to the list
    AlgorithmConfig* algorithm = &list->algorithms[list->size++];
    algorithm->id = id;
    strcpy(algorithm->type, type);
    algorithm->config = config;
}

// Define the function to remove an algorithm from the list of available algorithms
void removeAlgorithm(AlgorithmList* list, int id) {
    // Find the index of the algorithm in the list
    int i;
    for (i = 0; i < list->size; ++i) {
        if (list->algorithms[i].id == id) {
            break;
        }
    }

    // Check if the algorithm was found in the list
    if (i == list->size) {
        return;
    }

    // Remove the algorithm from the list by shifting all subsequent algorithms one position to the left
    for (int j = i + 1; j < list->size; ++j) {
        list->algorithms[j - 1] = list->algorithms[j];
    }
    --list->size;
}

// Define the function to update a configuration block for an algorithm in the list of available algorithms
void updateAlgorithmConfig(AlgorithmList* list, int id, void* config) {
    // Find the index of the algorithm in the list
    int i;
    for (i = 0; i < list->size; ++i) {
        if (list->algorithms[i].id == id) {
            break;
        }
    }

    // Check if the algorithm was found in the list
    if (i == list->size) {
        return;
    }

    // Update the configuration block for the algorithm
    list->algorithms[i].config = config;
}

// Define the function to retrieve a configuration block for an algorithm in the list of available algorithms
void* getAlgorithmConfig(AlgorithmList* list, int id) {
    // Find the index of the algorithm in the list
    int i;
    for (i = 0; i < list->size; ++i) {
        if (list->algorithms[i].id == id) {
            break;
        }
    }

    // Check if the algorithm was found in the list
    if (i == list->size) {
        return NULL;
    }

    // Return the configuration block for the algorithm
    return list->algorithms[i].config;
}
