pthread_mutex_t tasks_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to populate a user profile with random data
void populate_user_profile(UserProfile* profile) {
    // Generate random first and last name
    char* first_name = generate_random_string(10);
    char* last_name = generate_random_string(10);

    // Generate random email address
    char* email = generate_random_string(20) + "@example.com";

    // Generate random phone numbers
