    for (int i = 0; i < num_phone_numbers; i++) {
        Address* address = malloc(sizeof(Address));
        address->street = generate_random_string(10);
        address->city = generate_random_string(10);
        address->state = generate_random_string(2);
        address->zip = generate_random_string(5);
        address->next = addresses;
    }

    // Generate random preferences
    char* preferences = generate_random_string(100);

    // Assign values to the user profile structure
    profile->first_name = first_name;
    profile->last_name = last_name;
    profile->email = email;
    profile->phone_numbers = phone_numbers;
    profile->date_of_birth = date_of_birth;
    profile->addresses = addresses;
    profile->preferences = preferences;
}

