// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int id;
    char* data;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic array to store the structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** entries;
    size_t count;
    size_t capacity;
} NFAPI_CRC_INDICATION_PDU_ARRAY;

// Initialize a new array with the given initial capacity
NFAPI_CRC_INDICATION_PDU_ARRAY* nfapi_crc_indication_pdu_array_init(size_t capacity) {
    NFAPI_CRC_INDICATION_PDU_ARRAY* array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_ARRAY));
    if (!array) {
        return NULL;
    }
    array->entries = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array->entries) {
        free(array);
        return NULL;
    }
    array->count = 0;
    array->capacity = capacity;
    return array;
}

// Add a new entry to the array, growing the capacity if necessary
int nfapi_crc_indication_pdu_array_add(NFAPI_CRC_INDICATION_PDU_ARRAY* array, NFAPI_CRC_INDICATION_PDU_T* entry) {
    // Check for null pointer errors
    if (!array || !entry) {
        return -1;
    }

    // If the capacity is reached, double it and reallocate memory
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_entries = realloc(array->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_capacity);
        if (!new_entries) {
            return -1;
        }
        array->entries = new_entries;
        array->capacity = new_capacity;
    }

    // Add the entry to the end of the array
    array->entries[array->count++] = entry;
    return 0;
}

// Remove an entry from the array by its index
void nfapi_crc_indication_pdu_array_remove(NFAPI_CRC_INDICATION_PDU_ARRAY* array, size_t index) {
    // Check for null pointer errors and out-of-bounds indices
    if (!array || index >= array->count) {
        return;
    }

    // Shift all entries after the removed entry to the left
    memmove(&array->entries[index], &array->entries[index + 1], (array->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    array->count--;
}

// Free the memory allocated for the array
void nfapi_crc_indication_pdu_array_free(NFAPI_CRC_INDICATION_PDU_ARRAY* array) {
    if (!array) {
        return;
    }
    free(array->entries);
    free(array);
}
