            parameters[i] = 9;
        } else if (strcmp(algorithm, "lzma") == 0) {
            // Return the name of the lzma algorithm and its parameter (level)
            strcpy(algorithms[i], "lzma");
            parameters[i] = 6;
        }
    }

    return num_available_algorithms;
}
