// Define the custom data structure for network connection states
typedef struct {
    int id;
    time_t timestamp;
    unsigned long packet_count;
    char state;
} conn_state_t;

// Define the array of connection states, with a maximum size limit
#define MAX_CONN_STATES 1024
conn_state_t *conn_states = NULL;
size_t num_conn_states = 0;
pthread_mutex_t conn_states_lock = PTHREAD_MUTEX_INITIALIZER;

// Define the configuration option for periodic updates to connection states
int enable_periodic_updates = 1;

// Define the function to dynamically manage the array of connection states
void update_conn_states(int id, time_t timestamp, unsigned long packet_count, char state) {
    // Acquire the lock on the connection states array
    pthread_mutex_lock(&conn_states_lock);

    // Validate memory alignment to optimize cache performance and prevent data corruption
    if (((size_t)conn_states & 0x3F) != 0) {
        printf("Error: Invalid memory alignment for connection states array\n");
        pthread_mutex_unlock(&conn_states_lock);
        return;
    }

    // Handle both full and partial updates to the connection states gracefully, avoiding overflow or underflow errors
    if (id >= num_conn_states) {
        // Partial update: add a new entry to the array
        conn_state_t *new_entry = realloc(conn_states, (num_conn_states + 1) * sizeof(conn_state_t));
        if (!new_entry) {
            printf("Error: Failed to allocate memory for connection states\n");
            pthread_mutex_unlock(&conn_states_lock);
            return;
        }
        conn_states = new_entry;
        num_conn_states++;
    } else if (id < 0) {
        // Partial update: remove an entry from the array
        if (num_conn_states == 0) {
            printf("Error: Cannot remove entry from empty connection states array\n");
            pthread_mutex_unlock(&conn_states_lock);
            return;
        }
        conn_state_t *new_entry = realloc(conn_states, (num_conn_states - 1) * sizeof(conn_state_t));
