// Define a background thread function to monitor and repair the health of active connections
void *monitor_connections(void *args) {
    while (1) {
        // Acquire the lock on the connection states array
        pthread_mutex_lock(&conn_states_lock);

        // Monitor the health of each active connection, repairing any issues as needed
        for (int i = 0; i < num_conn_states; i++) {
            if (conn_states[i].state == 'C') {
                // Connection is closed: remove it from the array
                conn_state_t *new_entry = realloc(conn_states, (num_conn_states - 1) * sizeof(conn_state_t));
                if (!new_entry) {
                    printf("Error: Failed to allocate memory for connection states\n");
                    pthread_mutex_unlock(&conn_states_lock);
                    return;
                }
                conn_states = new_entry;
                num_conn_states--;
            } else {
                // Connection is open: update its timestamp and packet count
                time_t current_time = time(NULL);
                unsigned long current_packet_count = 0;
                if (external_library_available) {
                    current_packet_count = get_current_packet_count();
                } else {
                    printf("Error: External library not available for packet count monitoring\n");
                    pthread_mutex_unlock(&conn_states_lock);
                    return;
                }
                conn_states[i].timestamp = current_time;
                conn_states[i].packet_count = current_packet_count;
            }
        }

        // Release the lock on the connection states array
        pthread_mutex_unlock(&conn_states_lock);

        // Sleep for a short period of time before checking the health of active connections again
        sleep(10);
    }
}
