    }
    for (int i = 0; i < numRecords; i++) {
        fscanf(fp, "%lf %s", &(*records)[i].value, (*records)[i].path);
    }

    // Read compression algorithms from configuration file
    int numAlgorithms;
    fscanf(fp, "%d", &numAlgorithms);
    *algorithms = (CompressionAlgorithm*)malloc(sizeof(CompressionAlgorithm) * numAlgorithms);
    if (*algorithms == NULL) {
        printf("Error: unable to allocate memory for compression algorithms\n");
        return;
    }
    for (int i = 0; i < numAlgorithms; i++) {
        fscanf(fp, "%s %p", (*algorithms)[i].name, &(*algorithms)[i].compression_algorithm);
    }

    // Close configuration file
    fclose(fp);
}

// Define function for generating random values within a specified range
double generateRandomValue(double min, double max) {
    return (double)(rand() % 1000) / 1000 * (max - min) + min;
}

// Define function for initializing record structures with random values and ASCII characters
void initializeRecords(Record* records, int numRecords) {
    // Generate random values within specified range for each record's value field
    for (int i = 0; i < numRecords; i++) {
        records[i].value = generateRandomValue(1.0, 10.0);
    }

    // Fill each record's char array with random ASCII characters
    for (int i = 0; i < numRecords; i++) {
        for (int j = 0; j < 256; j++) {
            records[i].path[j] = (char)rand() % 128 + '!';
        }
    }
}

// Define function for selecting and executing compression algorithms on records
void compressRecords(Record* records, int numRecords, CompressionAlgorithm** algorithms) {
    // Loop through each record and select a random compression algorithm to apply
    for (int i = 0; i < numRecords; i++) {
        int algorithmIndex = rand() % numAlgorithms;
        while (!(*algorithms)[algorithmIndex].available) {
            algorithmIndex = (algorithmIndex + 1) % numAlgorithms;
        }
        (*algorithms)[algorithmIndex].compression_algorithm(records[i]);
    }
}

// Define function for aggregating statistics on records
void aggregateStatistics(Record* records, int numRecords) {
    // Calculate total number of lines across all log files
    long totalLines = 0;
    for (int i = 0; i < numRecords; i++) {
        totalLines += records[i].value;
    }

    // Calculate average line length for each log file
    double averageLineLength = 0.0;
    for (int i = 0; i < numRecords; i++) {
        averageLineLength += records[i].value / totalLines * strlen(records[i].path);
    }

    // Identify longest and shortest lines across all log files
    long longestLine = 0, shortestLine = INT_MAX;
    for (int i = 0; i < numRecords; i++) {
        if (records[i].value > longestLine) {
            longestLine = records[i].value;
        }
        if (records[i].value < shortestLine) {
            shortestLine = records[i].value;
        }
    }

    // Print aggregated statistics
    printf("Total number of lines: %ld\n", totalLines);
    printf("Average line length: %.2f\n", averageLineLength);
    printf("Longest line: %ld\n", longestLine);
    printf("Shortest line: %ld\n", shortestLine);
}

// Define function for processing log files and generating aggregated statistics
void processLogFiles(const char* directory) {
    // List all log files in the specified directory
    DIR* dir = opendir(directory);
    if (dir == NULL) {
        printf("Error: unable to open directory\n");
        return;
    }
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        printf("Log file: %s\n", entry->d_name);
    }
    closedir(dir);

    // Read each log file line by line and perform operations on records
    for (int i = 0; i < numRecords; i++) {
        FILE* fp = fopen(records[i].path, "r");
        if (fp == NULL) {
            printf("Error: unable to open log file\n");
            return;
        }
        while ((fgets(buffer, sizeof(buffer), fp)) != NULL) {
            // Count total number of lines across all log files
            records[i].value++;

            // Calculate average line length for each log file
            strcat(records[i].path, buffer);
        }
        fclose(fp);
    }
}

// Define function for freeing dynamically allocated memory
void freeMemory(DataPoint** dataPoints, Record** records, CompressionAlgorithm** algorithms) {
    // Free memory for data points and records
    free(*dataPoints);
    free(*records);

    // Free memory for compression algorithms
    for (int i = 0; i < numAlgorithms; i++) {
        free((*algorithms)[i].name);
    }
    free(*algorithms);
}

// Define function for returning list of available compression algorithms
CompressionAlgorithm** getAvailableAlgorithms(CompressionAlgorithm** algorithms) {
    int numAvailable = 0;
    for (int i = 0; i < numAlgorithms; i++) {
        if ((*algorithms)[i].available) {
            numAvailable++;
        }
    }
    CompressionAlgorithm** availableAlgorithms = (CompressionAlgorithm**)malloc(sizeof(CompressionAlgorithm*) * numAvailable);
    int index = 0;
    for (int i = 0; i < numAlgorithms; i++) {
        if ((*algorithms)[i].available) {
            availableAlgorithms[index++] = &(*algorithms)[i];
        }
    }
    return availableAlgorithms;
}
