    dataPoints = [DataPoint(*map(str.strip, line.split())) for _ in range(numDataPoints)]
    records = [Record(*map(float, line.split())) for _ in range(numRecords)]

    # Read compression algorithms from configuration file
    numAlgorithms = int(f.readline())
    algorithms = [CompressionAlgorithm(name=str.strip(line.split()[0]), compression_algorithm=None, available=False) for _ in range(numAlgorithms)]

    # Close configuration file
    f.close()

    return dataPoints, records, algorithms

# Define function for generating random values within a specified range
