}

// Initialize an array of records with a specified size and seed
record* initialize_records(size_t size, int seed) {
    record* records = (record*)malloc(sizeof(record) * size);
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return NULL;
