    void* buffer;
};

// Function to dynamically allocate memory for a collection of devices
Device* create_devices(size_t num_devices, ...) {
    // Calculate the total size of the device structures
    size_t total_size = sizeof(Device) * num_devices;

    // Allocate memory for the device structures and initialize the memory pool manager
    Device* devices = malloc(total_size);
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    pool->capacity = total_size;
    pool->used = 0;
    pool->buffer = devices;

    // Initialize the device structures and store them in the memory pool
    for (size_t i = 0; i < num_devices; i++) {
        Device* device = &devices[i];
        device->serial_number = rand();
        device->status = ONLINE;
        device->power_consumption = 0.0;
        device->temperature = NAN;
        device->humidity = NAN;
        device->pressure = NAN;
        pool->used += sizeof(Device);
    }

    // Return the memory pool manager and the device structures
    return devices;
}

// Function to dynamically allocate memory for a single device
Device* create_device() {
    Device* device = malloc(sizeof(Device));
    device->serial_number = rand();
    device->status = ONLINE;
    device->power_consumption = 0.0;
    device->temperature = NAN;
    device->humidity = NAN;
    device->pressure = NAN;
    return device;
}

// Function to free the memory allocated for a collection of devices
void destroy_devices(Device* devices, size_t num_devices) {
    // Free the memory pool manager and the device structures
    struct MemoryPool* pool = (struct MemoryPool*)devices - 1;
    free(pool);
    free(devices);
}

// Function to free the memory allocated for a single device
void destroy_device(Device* device) {
    // Free the device structure
    free(device);
}
