// Define a function to return a list of available compression algorithms, using standard library functions
void get_available_compression_algorithms(compression_algorithm_t **algorithms, int *num_algorithms) {
    // Use the standard library function 'getenv' to retrieve the environment variable that specifies the available compression algorithms
    char *available_algorithms = getenv("COMPRESSION_ALGORITHMS");
    if (available_algorithms == NULL) {
        printf("Error: unable to retrieve available compression algorithms\n");
        return;
    }

    // Tokenize the environment variable and count the number of available compression algorithms
    char *token = strtok(available_algorithms, ",");
    int num_algorithms = 0;
    while (token != NULL) {
        num_algorithms++;
        token = strtok(NULL, ",");
    }

    // Allocate memory for the list of available compression algorithms
    *algorithms = malloc(sizeof(compression_algorithm_t) * num_algorithms);
    if (*algorithms == NULL) {
        printf("Error: unable to allocate memory for available compression algorithms\n");
        return;
    }

    // Loop through each token and populate the list of available compression algorithms
    int i = 0;
    token = strtok(available_algorithms, ",");
    while (token != NULL) {
        (*algorithms)[i].name = token;
        (*algorithms)[i].function = NULL;
        (*algorithms)[i].available = true;
        i++;
        token = strtok(NULL, ",");
    }

    // Return the list of available compression algorithms
    *num_algorithms = num_algorithms;
}
