// Define the function to allocate memory for a doubly linked list of events
void* allocate_events(int num_events) {
    // Allocate memory for the list and its elements
    void* list = malloc(sizeof(event_t*) * num_events);
    if (list == NULL) {
        printf("Error: Failed to allocate memory for event list\n");
        exit(1);
    }
    return list;
}

// Define the function to resize the list without losing existing events
void resize_list(priority_queue_t* queue, int new_size) {
    // Reallocate memory for the list and its elements
    void* new_list = realloc(queue->events, sizeof(event_t*) * new_size);
    if (new_list == NULL) {
        printf("Error: Failed to resize event list\n");
        exit(1);
    }
    queue->events = new_list;
    queue->capacity = new_size;
}

// Define the function to populate the list with events
