#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a struct to represent a server instance
typedef struct {
    char* hostname;
    int* ports;
    char* config_file_path;
    char** supported_protocols;
    bool active;
} Server;

// Define a hash table for quick lookup of unique hostnames
#define HASH_TABLE_SIZE 1024
typedef struct {
    char* hostname;
    int count;
} HostnameHashTable[HASH_TABLE_SIZE];

// Function to dynamically allocate memory for a network of server instances
Server** create_server_network(int num_servers) {
    // Allocate memory for the array of Server pointers
    Server** servers = (Server**)malloc(num_servers * sizeof(Server*));
    if (!servers) {
        printf("Error: Failed to allocate memory for server network\n");
        return NULL;
    }

    // Initialize the hash table for quick lookup of unique hostnames
    HostnameHashTable* hash_table = (HostnameHashTable*)malloc(HASH_TABLE_SIZE * sizeof(HostnameHashTable));
    if (!hash_table) {
        printf("Error: Failed to allocate memory for hostname hash table\n");
        free(servers);
        return NULL;
    }

    // Populate each server instance with a random hostname, set a list of ports ranging from 1024 to 65535, specify a configuration file path, and fill the list of supported protocols with common network protocols like HTTP, HTTPS, SSH, and FTP
    for (int i = 0; i < num_servers; i++) {
        // Generate a random hostname using the time as a seed
        srand(time(NULL));
        char* hostname = (char*)malloc(16 * sizeof(char));
        if (!hostname) {
            printf("Error: Failed to allocate memory for hostname\n");
            free(servers);
            free(hash_table);
            return NULL;
        }
        snprintf(hostname, 16, "%08x", rand());

        // Check if the generated hostname is unique in the network
        bool unique = true;
        for (int j = 0; j < i; j++) {
            if (!strcmp(servers[j]->hostname, hostname)) {
                unique = false;
                break;
            }
        }
        if (!unique) {
            // If the generated hostname is not unique, regenerate a new one
            free(hostname);
            continue;
        }

        // Set the hostname for the current server instance
        servers[i]->hostname = hostname;

        // Allocate memory for the list of ports and set it to a random range from 1024 to 65535
        int* ports = (int*)malloc(sizeof(int) * 10);
        if (!ports) {
            printf("Error: Failed to allocate memory for port list\n");
            free(servers[i]->hostname);
            free(servers);
            free(hash_table);
            return NULL;
        }
        for (int j = 0; j < 10; j++) {
            ports[j] = rand() % (65535 - 1024 + 1) + 1024;
        }
        servers[i]->ports = ports;

        // Set the configuration file path for the current server instance
        char* config_file_path = "/etc/config.conf";
        servers[i]->config_file_path = config_file_path;

        // Allocate memory for the list of supported protocols and fill it with common network protocols like HTTP, HTTPS, SSH, and FTP
        char** supported_protocols = (char**)malloc(4 * sizeof(char*));
        if (!supported_protocols) {
            printf("Error: Failed to allocate memory for supported protocol list\n");
            free(servers[i]->ports);
            free(servers[i]->hostname);
            free(servers);
            free(hash_table);
            return NULL;
        }
        supported_protocols[0] = "HTTP";
        supported_protocols[1] = "HTTPS";
        supported_protocols[2] = "SSH";
        supported_protocols[3] = "FTP";
        servers[i]->supported_protocols = supported_protocols;

        // Set the status field indicating whether the server is active or inactive
        servers[i]->active = true;

        // Add the generated hostname to the hash table for quick lookup
        int index = (int)hostname % HASH_TABLE_SIZE;
        if (!hash_table[index].count) {
            hash_table[index].hostname = hostname;
            hash_table[index].count++;
        } else {
            // If the generated hostname is not unique, regenerate a new one
            free(hostname);
            continue;
        }
    }

    return servers;
}

// Function to free all allocated memory when the server network is no longer needed
void destroy_server_network(Server** servers) {
    // Free each server instance and its associated data structures
    for (int i = 0; i < num_servers; i++) {
        free(servers[i]->hostname);
        free(servers[i]->ports);
        free(servers[i]->config_file_path);
        free(servers[i]->supported_protocols);
    }

    // Free the array of Server pointers and the hash table for quick lookup of unique hostnames
    free(servers);
    free(hash_table);
}
