void config_list_add(config_list_t* list, const char* name, int value_type, void* current_value) {
    // Check if the list is full and needs to be resized
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        config_setting_t** new_settings = (config_setting_t**)my_alloc(new_capacity * sizeof(config_setting_t*));
        memcpy(new_settings, list->settings, list->count * sizeof(config_setting_t*));
        my_dealloc(list->settings);
        list->settings = new_settings;
        list->capacity = new_capacity;
