    // Initialize the new setting with default values
    config_setting_t* setting = (config_setting_t*)my_alloc(sizeof(config_setting_t));
    setting->name = my_strdup(name);
    setting->value_type = value_type;
    setting->current_value = current_value;

    // Add the new setting to the list
    list->settings[list->count++] = setting;
}

// Get a configuration setting by name
config_setting_t* config_list_get(config_list_t* list, const char* name) {
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(list->settings[i]->name, name) == 0) {
            return list->settings[i];
        }
    }
    return NULL;
}

// Update a configuration setting by name
void config_list_update(config_list_t* list, const char* name, int value_type, void* current_value) {
    config_setting_t* setting = config_list_get(list, name);
    if (setting != NULL) {
        setting->value_type = value_type;
        setting->current_value = current_value;
    }
}

