int manage_network_connection_pool(server_list servers, int pool_size) {
  // Initialize the connection pool with the given size
  struct connection_pool *pool = initialize_connection_pool(servers, pool_size);

  // Loop until all connections are closed or a timeout occurs
  while (1) {
    // Check if any connections have timed out
    for (int i = 0; i < pool->num_connections; i++) {
      struct connection *conn = &pool->connections[i];
      if (conn->timeout > 0 && conn->timeout <= get_current_time()) {
        // Handle timeout gracefully by closing the connection and removing it from the pool
        close_connection(conn);
        remove_connection_from_pool(pool, i--);
      }
    }

    // Check if the load on the network is high enough to resize the pool
    int current_load = get_current_network_load();
    if (current_load > pool->max_load) {
      // Resize the pool by adding new connections
      for (int i = 0; i < current_load - pool->max_load; i++) {
        struct connection *conn = create_connection(servers[i % servers.length]);
        if (!add_connection_to_pool(pool, conn)) {
          // If the resize fails due to system constraints, return an error code
          close_connection_pool(pool);
          return -1;
        }
      }
    } else if (current_load < pool->min_load) {
      // Resize the pool by closing excess connections
      for (int i = 0; i < pool->num_connections - current_load; i++) {
        struct connection *conn = &pool->connections[i];
        close_connection(conn);
        remove_connection_from_pool(pool, i--);
      }
    }

    // Sleep for a short period of time to avoid busy-looping
    sleep(100);
  }

  return 0;
}
