double calculate_average(entry_t* entries, size_t num_entries) {
    // Initialize the sum and count variables
    double sum = 0;
    int count = 0;

    // Iterate over the entries and calculate the sum and count
    for (size_t i = 0; i < num_entries; i++) {
        sum += entries[i].value;
        count++;
    }

    // Return the average value
    return sum / count;
}

// Define a function to free resources allocated by the function
void free_resources(entry_t* entries, size_t num_entries) {
    // Free the metadata and events arrays
    free(entries[0].metadata);
    free(entries[0].event);

    // Set pointers to NULL to avoid dangling pointers
    entries[0].metadata = NULL;
    entries[0].event = NULL;
}

// Define the main function that manages memory for multiple data structures under strict performance and usability constraints
