typedef struct JobPosting {
    char* title;
    char* description;
    int salaryRange[2];
    char** requiredSkills;
} JobPosting;

// Define a struct for a linked list node
typedef struct Node {
    char buffer[100];
    int index;
    struct Node* next;
} Node;

// Function to dynamically allocate memory for a job posting
JobPosting* createJobPosting() {
    JobPosting* jobPosting = (JobPosting*)malloc(sizeof(JobPosting));
    if (!jobPosting) {
        printf("Error: Failed to allocate memory for job posting\n");
        return NULL;
    }

    // Initialize the job posting fields
    jobPosting->title = malloc(100 * sizeof(char));
    jobPosting->description = malloc(100 * sizeof(char));
    jobPosting->salaryRange[0] = 0;
    jobPosting->salaryRange[1] = 0;
    jobPosting->requiredSkills = NULL;

    return jobPosting;
}

// Function to dynamically allocate memory for a linked list node
Node* createNode(char* buffer) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        printf("Error: Failed to allocate memory for linked list node\n");
        return NULL;
    }

    // Initialize the node fields
    strcpy(node->buffer, buffer);
    node->index = 0;
    node->next = NULL;

    return node;
}

// Function to add a job posting to the linked list
void addJobPosting(Node** head, JobPosting* jobPosting) {
    // Create a new node for the job posting
    Node* newNode = createNode(jobPosting->title);
    if (!newNode) {
        printf("Error: Failed to allocate memory for linked list node\n");
        return;
    }

    // Add the job posting to the linked list
    newNode->next = *head;
    *head = newNode;
}

// Function to remove a job posting from the linked list
void removeJobPosting(Node** head, JobPosting* jobPosting) {
    Node* currentNode = *head;
    Node* previousNode = NULL;

    // Find the node corresponding to the job posting
    while (currentNode != NULL && currentNode->buffer != jobPosting->title) {
        previousNode = currentNode;
        currentNode = currentNode->next;
    }

    // Remove the node from the linked list
    if (currentNode == NULL) {
        printf("Error: Job posting not found in linked list\n");
        return;
    } else if (previousNode == NULL) {
        *head = currentNode->next;
    } else {
        previousNode->next = currentNode->next;
    }
}

// Function to traverse the linked list and print relevant information
void traverseLinkedList(Node* head) {
    Node* currentNode = head;

    // Traverse the linked list and print each job posting's title and salary range
    while (currentNode != NULL) {
        printf("%s: ", currentNode->buffer);
        for (int i = 0; i < 2; i++) {
            printf("%d", currentNode->index[i]);
            if (i < 1) {
                printf("-");
            }
        }
        printf("\n");
        currentNode = currentNode->next;
    }
}

// Function to free all allocated memory when the job list and linked list are no longer needed
void freeMemory(JobPosting* jobList, Node* head) {
    // Free the memory for each job posting in the list
    while (jobList != NULL) {
        free(jobList->title);
        free(jobList->description);
        free(jobList->requiredSkills);
        jobList = jobList->next;
    }

    // Free the memory for each node in the linked list
    while (head != NULL) {
        Node* currentNode = head;
        head = head->next;
        free(currentNode);
    }
}
