    TemperatureReadings *temp_readings = (TemperatureReadings*)malloc(sizeof(TemperatureReadings));
    if (!temp_readings) {
        fprintf(stderr, "Error: Failed to allocate memory for temperature readings\n");
        return NULL;
    }

    // Initialize the array with the default value
    temp_readings->num_readings = num_readings;
    temp_readings->readings = (double*)malloc(sizeof(double) * num_readings);
    if (!temp_readings->readings) {
        fprintf(stderr, "Error: Failed to allocate memory for temperature readings\n");
        free(temp_readings);
        return NULL;
    }
    for (int i = 0; i < num_readings; i++) {
        temp_readings->readings[i] = default_value;
    }

    // Initialize the average temperature to the default value
    double avg_temp = default_value;

    // If a data file is provided, read the values from it and update the average temperature
    if (data_file) {
        FILE *fp = fopen(data_file, "r");
        if (!fp) {
            fprintf(stderr, "Error: Failed to open data file for reading\n");
            free(temp_readings->readings);
            free(temp_readings);
            return NULL;
        }
        while (fscanf(fp, "%lf", &temp) == 1) {
            temp_readings->readings[i] = temp;
            avg_temp += temp;
            i++;
        }
        fclose(fp);
    }

    // Update the average temperature if it exceeds the threshold
    if (avg_temp > threshold) {
        double new_default_value = avg_temp / num_readings;
        for (int i = 0; i < num_readings; i++) {
            temp_readings->readings[i] = new_default_value;
        }
    }

    return temp_readings;
}
