// Define the structure for scheduled events
typedef struct {
    int hour;
    int minute;
    int second;
} EventTime;

// Function to allocate and initialize an array of event times
EventTime* init_event_times(int num_events, int priority) {
    // Allocate memory for the array of event times
    EventTime *event_times = (EventTime*)malloc(sizeof(EventTime) * num_events);
    if (!event_times) {
        fprintf(stderr, "Error: Failed to allocate memory for event times\n");
        return NULL;
    }

    // Initialize the array with the default values
    for (int i = 0; i < num_events; i++) {
        event_times[i].hour = 0;
        event_times[i].minute = 0;
        event_times[i].second = 0;
    }

    // If a priority is specified, sort the events based on that priority
    if (priority) {
        qsort(event_times, num_events, sizeof(EventTime), compare_events);
    }

    return event_times;
}

// Function to compare two events based on their priorities
int compare_events(const void *a, const void *b) {
    EventTime *event1 = (EventTime*)a;
    EventTime *event2 = (EventTime*)b;
    if (event1->priority > event2->priority) {
        return 1;
    } else if (event1->priority < event2->priority) {
        return -1;
    } else {
        return 0;
    }
}
