void initialize_entries(size_t values_size, size_t tags_size, size_t entries_size) {
    // Validate input parameters
    if (values_size == 0 || tags_size == 0 || entries_size == 0) {
        return;
    }
    if (values_size + tags_size > SIZE_MAX / sizeof(struct entry)) {
        return;
