    char *tags = malloc(sizeof(char) * tags_size);
    if (values == NULL || tags == NULL) {
        return;
    }

    // Initialize values and tags arrays
    for (size_t i = 0; i < values_size; i++) {
        values[i] = i;
    }
    for (size_t i = 0; i < tags_size; i++) {
        tags[i] = (i % 2 == 0) ? 'A' + i / 2 : 'a' + i / 2;
    }

    // Allocate memory for entries array
    struct entry *entries = malloc(sizeof(struct entry) * entries_size);
    if (entries == NULL) {
        free(values);
        free(tags);
        return;
    }

    // Initialize entries array
