int manageMemory(long* offsets, int* keys, Record** records, int numRecords, int minValue, int maxValue) {
    // Check for zero-length arrays and invalid input ranges
    if (numRecords <= 0 || minValue >= maxValue) {
        return -1;
    }

    // Dynamically allocate memory for all three arrays
    offsets = malloc(sizeof(long) * numRecords);
    keys = malloc(sizeof(int) * numRecords);
    records = malloc(sizeof(Record*) * numRecords);

    // Check for allocation failures
