        return -1;
    }

    // Initialize the 'long' offsets with sequential values starting from 0
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = i * sizeof(Record);
    }

    // Initialize the 'int' keys with sequential values starting from 0
    for (int i = 0; i < numRecords; i++) {
        keys[i] = i;
    }

    // Initialize the 'int' value in each record structure with a random number within the specified range, ensuring no duplicate random numbers are generated across records
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        int randomValue = rand() % (maxValue - minValue + 1) + minValue;
        while (randomValue == records[i]->value) {
            randomValue = rand() % (maxValue - minValue + 1) + minValue;
        }
        records[i]->value = randomValue;
    }

    // Implement error checking during memory allocation to handle potential allocation failures gracefully
    if (offsets == NULL || keys == NULL || records == NULL) {
        return -1;
    }

    // Provide a mechanism to free all allocated memory when the function exits to prevent memory leaks
    atexit(freeMemory);
}

void freeMemory() {
    free(offsets);
    free(keys);
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
}
