// Function to allocate memory for each 'column' definition
void *allocate_columns(size_t num_columns, size_t column_size) {
    // Allocate memory for the array of columns
    column_t **columns = malloc(num_columns * sizeof(column_t));
    if (!columns) {
        return NULL;
    }

    // Initialize each column with its name and data type
    for (size_t i = 0; i < num_columns; i++) {
        columns[i] = malloc(sizeof(column_t));
        if (!columns[i]) {
            return NULL;
        }
        columns[i]->name = "Column";
        columns[i]->type = 0; // integer data type by default
