}

// Function to initialize a hash table for efficient row lookups based on primary keys
void *initialize_hash_table(size_t num_buckets) {
    // Allocate memory for the hash table
    hash_table_t *hash_table = malloc(sizeof(hash_table_t));
    if (!hash_table) {
        return NULL;
    }

    // Initialize the hash table with the number of buckets
    hash_table->num_buckets = num_buckets;
    hash_table->buckets = malloc(num_buckets * sizeof(void*));
    if (!hash_table->buckets) {
        return NULL;
    }

    // Initialize each bucket with a null pointer
    for (size_t i = 0; i < num_buckets; i++) {
        hash_table->buckets[i] = NULL;
    }

    return hash_table;
}

// Function to allocate memory for the data in each 'row' structure
void *allocate_data(size_t num_rows, size_t num_columns) {
    // Allocate memory for the array of rows
    row_t **rows = malloc(num_rows * sizeof(row_t));
    if (!rows) {
        return NULL;
    }

    // Initialize each row with a unique identifier and allocate memory for its data
    for (size_t i = 0; i < num_rows; i++) {
        rows[i] = malloc(sizeof(row_t));
        if (!rows[i]) {
            return NULL;
        }
        rows[i]->id = i + 1;
        rows[i]->data = malloc(num_columns * sizeof(void*));
        if (!rows[i]->data) {
            return NULL;
        }
    }

    return rows;
}

// Function to store column values in 'row' structures
void store_column_values(table_t *table, row_t *row, void **data) {
    // Loop through each column and store the data in the corresponding row
    for (size_t i = 0; i < table->num_columns; i++) {
        row->data[i] = data[i];
    }
}

// Function to handle potential allocation failures gracefully
void *handle_allocation_failure(void *ptr) {
    if (!ptr) {
        // Handle the allocation failure by returning a null pointer or raising an error
        return NULL;
    } else {
        return ptr;
    }
}

// Function to free all allocated memory when the function exits
void cleanup(table_t **tables, size_t num_tables) {
    // Loop through each table and free its memory
    for (size_t i = 0; i < num_tables; i++) {
        free(tables[i]);
    }
}
