    time_t *timestampBuffer = (time_t *)malloc(numSensors * timestampSize);
    double *valueBuffer = (double *)malloc(numSensors * numMetricsPerSensor * valueSize);

    // Check for memory allocation failures and handle them appropriately
    if (!identifierBuffer || !timestampBuffer || !valueBuffer) {
        free(identifierBuffer);
        free(timestampBuffer);
        free(valueBuffer);
        return MEMORY_ALLOCATION_FAILURE;
