        index += strlen(identifierBuffer + index) + 1;
    }

    // Initialize the timestamps with the current time for each sensor, using a high-resolution clock to ensure accurate timestamps
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        free(identifierBuffer);
        free(timestampBuffer);
        free(valueBuffer);
        return LOGGING_ERROR;
    }
    for (size_t i = 0; i < numSensors; i++) {
        timestampBuffer[i] = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
    }

    // Initialize the metric values with random numbers within a specified range, ensuring no duplicate values are generated across metrics
    srand(seed);
    for (size_t i = 0; i < numSensors * numMetricsPerSensor; i++) {
        if (valueSize == sizeof(double)) {
            valueBuffer[i] = rand() / (double)RAND_MAX * (maxValue - minValue) + minValue;
        } else {
            valueBuffer[i] = rand() % (maxValue - minValue + 1) + minValue;
        }
    }

    // Create a MetricDataPoint structure for each sensor and metric, storing the identifier, timestamp, and value in the structure
    *metrics = (MetricDataPoint *)malloc(numSensors * numMetricsPerSensor * sizeof(MetricDataPoint));
    if (!*metrics) {
        free(identifierBuffer);
        free(timestampBuffer);
        free(valueBuffer);
        return MEMORY_ALLOCATION_FAILURE;
    }
    for (size_t i = 0; i < numSensors; i++) {
        for (size_t j = 0; j < numMetricsPerSensor; j++) {
            (*metrics)[i * numMetricsPerSensor + j].identifier = identifierBuffer + i * identifierLength;
            (*metrics)[i * numMetricsPerSensor + j].timestamp = timestampBuffer[i];
            (*metrics)[i * numMetricsPerSensor + j].value = valueBuffer[i * numMetricsPerSensor + j];
        }
    }

    // Free the memory allocated for the identifier strings, timestamps, and metric values if deferred deallocation is not desired
    if (deferDeallocation) {
        free(identifierBuffer);
        free(timestampBuffer);
        free(valueBuffer);
    }

    return SUCCESS;
}
