// Define the cryptographic module for DES encryption and decryption
void des_crypt(const unsigned char *input, const unsigned char *key, int key_len, unsigned char *output) {
    EVP_CIPHER_CTX *ctx = NULL;
    int len;

    // Create the EVP_CIPHER_CTX structure for DES encryption and decryption
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return false;
    }

    // Set the cipher algorithm and mode for DES encryption and decryption
    EVP_EncryptInit(ctx, EVP_des_ecb(), key, NULL);

    // Encrypt or decrypt the input data based on the selected cipher mode
    if (key_len > 0) {
        len = EVP_EncryptUpdate(ctx, output, input, key_len);
    } else {
        len = EVP_DecryptUpdate(ctx, output, input, key_len);
    }

    // Check for any errors during encryption or decryption
    if (len < 0) {
        return false;
    }

    // Free the EVP_CIPHER_CTX structure
    EVP_CIPHER_CTX_free(ctx);

    // Return the result of the encryption or decryption
    return true;
}

