    if (key_len > 0) {
        len = EVP_EncryptUpdate(ctx, output, input, key_len);
    } else {
        len = EVP_DecryptUpdate(ctx, output, input, key_len);
    }

    // Check for any errors during encryption or decryption
    if (len < 0) {
        return false;
    }

    // Free the EVP_CIPHER_CTX structure
    EVP_CIPHER_CTX_free(ctx);

    // Return the result of the encryption or decryption
    return true;
