int select_cipher_mode(json_object *json) {
    // Get the cipher algorithm and mode from the JSON object
    int cipher_algorithm = CIPHER_ALGORITHM_DES;
    int cipher_mode = CIPHER_MODE_ECB;
    json_object *cipher_obj = json_object_object_get(json, "cipher");
    if (cipher_obj) {
