        if (!records[i].name) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return;
        }
        strcpy(records[i].name, "Name");
    }

    // Initialize the metadata fields with timestamps and flags
    for (int i = 0; i < num_records; i++) {
        records[i].metadata.timestamp = time(NULL);
        records[i].metadata.flag1 = true;
        records[i].metadata.flag2 = false;
