void optimizeAndSecureDataProcessingPipeline(int numStreams, int* streamIDs, long* timestamps, void** payloads) {
    // Initialize the array of DataRecords
    DataRecord* records = (DataRecord*)malloc(numStreams * sizeof(DataRecord));
    if (!records) {
        printf("Error: Failed to allocate memory for data records\n");
        return;
    }

    // Initialize the array of DataStreams
    DataStream* streams = (DataStream*)malloc(numStreams * sizeof(DataStream));
    if (!streams) {
        printf("Error: Failed to allocate memory for data streams\n");
        free(records);
        return;
    }

    // Initialize the mutex for synchronizing access to the DataRecords array
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        printf("Error: Failed to allocate memory for mutex\n");
        free(records);
        free(streams);
        return;
    }

    // Initialize the condition variable for signaling when a new data record is available
    pthread_cond_t* cond = (pthread_cond_t*)malloc(sizeof(pthread_cond_t));
    if (!cond) {
        printf("Error: Failed to allocate memory for condition variable\n");
        free(records);
        free(streams);
        free(mutex);
        return;
    }

    // Initialize the array of payload sizes
    size_t* payloadSizes = (size_t*)malloc(numStreams * sizeof(size_t));
    if (!payloadSizes) {
        printf("Error: Failed to allocate memory for payload sizes\n");
        free(records);
        free(streams);
        free(mutex);
        free(cond);
        return;
    }

    // Initialize the array of data streams
    for (int i = 0; i < numStreams; i++) {
        streams[i].streamID = streamIDs[i];
        streams[i].timestamp = timestamps[i];
        payloadSizes[i] = strlen(payloads[i]);
    }

    // Initialize the mutex for synchronizing access to the DataRecords array
    pthread_mutex_init(mutex, NULL);

    // Initialize the condition variable for signaling when a new data record is available
    pthread_cond_init(cond, NULL);

    // Loop until all data streams have been processed
    while (1) {
        // Acquire the mutex to access the DataRecords array
        pthread_mutex_lock(mutex);

        // Check if any new data records are available
        for (int i = 0; i < numStreams; i++) {
            if (streams[i].timestamp > 0) {
                // Add the new data record to the array of DataRecords
                records[i].streamID = streams[i].streamID;
                records[i].timestamp = streams[i].timestamp;
                records[i].payload = malloc(payloadSizes[i]);
                memcpy(records[i].payload, payloads[i], payloadSizes[i]);

                // Update the timestamp for the data stream
                streams[i].timestamp = 0;
            }
        }

        // Release the mutex to allow other threads to access the DataRecords array
        pthread_mutex_unlock(mutex);

        // Check if any new data records were added
        if (records[i].timestamp > 0) {
            // Signal that a new data record is available
            pthread_cond_signal(cond);
        } else {
            // Wait for a new data record to be available
            pthread_cond_wait(cond, mutex);
        }
    }
}
