// Define the structure for a session
typedef struct {
    char* description;
    float metric_values[3];
} session_t;

// Define the structure for an entry in the offset array
typedef struct {
    long offset;
    entry_t* entry;
} offset_t;

// Define the structure for an entry in the record array
typedef struct {
    int key;
    unsigned char status_flag;
    record_t* record;
} entry_t;

// Define the structure for a record
typedef struct {
    int value;
} record_t;

// Function to read and process a line from the text file
void process_line(char* line) {
    // Split the line into fields using comma as delimiter
    char* fields[4];
    int num_fields = split_string(line, ",", fields);

    // Check if the number of fields is valid
    if (num_fields != 4) {
        printf("Invalid number of fields in line: %s\n", line);
        return;
    }

    // Convert the last two fields to double and int, respectively
    double lat1 = atof(fields[2]);
    double lat2 = atof(fields[3]);
    int hit_count = (int)round((lat1 + lat2) / 2.0);

    // Allocate memory for the session structure
    session_t* session = malloc(sizeof(session_t));
    if (!session) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the session structure
    session->description = fields[0];
    session->metric_values[0] = lat1;
    session->metric_values[1] = lat2;
    session->metric_values[2] = hit_count;

    // Add the session to the distributed cache
    add_session(session);
}

// Function to add a session to the distributed cache
void add_session(session_t* session) {
    // Calculate the SHA-256 hash of the session ID
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)session->description, strlen(session->description), hash);

    // Create a new entry in the offset array for the session
    offset_t* offset = malloc(sizeof(offset_t));
    if (!offset) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the offset and entry structures
    offset->offset = 0;
    offset->entry = malloc(sizeof(entry_t));
    if (!offset->entry) {
        printf("Memory allocation failed\n");
        free(offset);
        return;
    }

    // Initialize the entry structure
    offset->entry->key = hash[0];
    offset->entry->status_flag = 1;
    offset->entry->record = malloc(sizeof(record_t));
    if (!offset->entry->record) {
        printf("Memory allocation failed\n");
        free(offset->entry);
        free(offset);
        return;
    }

    // Initialize the record structure
    offset->entry->record->value = session->metric_values[0];

    // Add the entry to the distributed cache
    add_entry(offset);
}

// Function to add an entry to the distributed cache
void add_entry(offset_t* offset) {
    // Check if the entry is already in the cache
    int found = 0;
    for (int i = 0; i < num_entries; i++) {
        if (strcmp(offsets[i]->entry->key, offset->entry->key) == 0) {
            found = 1;
            break;
        }
    }

    // If the entry is not in the cache, add it
    if (!found) {
        offsets = realloc(offsets, (num_entries + 1) * sizeof(offset_t*));
        if (!offsets) {
            printf("Memory allocation failed\n");
            return;
        }

        offsets[num_entries] = offset;
        num_entries++;
    }
}

// Function to update a session in the distributed cache
void update_session(char* id, char* request_body) {
    // Calculate the SHA-256 hash of the session ID
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)id, strlen(id), hash);

    // Find the entry in the offset array for the session
    int found = 0;
    for (int i = 0; i < num_entries; i++) {
        if (strcmp(offsets[i]->entry->key, hash) == 0) {
            found = 1;
            break;
        }
    }

    // If the entry is not in the cache, return an error
    if (!found) {
        printf("Session not found\n");
        return;
    }

    // Update the record structure with the new values
    offsets[i]->entry->record->value = atof(request_body);
}

// Function to clear a session in the distributed cache
void clear_session(char* id) {
    // Calculate the SHA-256 hash of the session ID
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)id, strlen(id), hash);

    // Find the entry in the offset array for the session
    int found = 0;
    for (int i = 0; i < num_entries; i++) {
        if (strcmp(offsets[i]->entry->key, hash) == 0) {
            found = 1;
            break;
        }
    }

    // If the entry is not in the cache, return an error
    if (!found) {
        printf("Session not found\n");
        return;
    }

    // Clear the record structure for the session
    offsets[i]->entry->record = NULL;
}

// Function to free all allocated memory at the end of execution
void cleanup() {
    // Free the offset array and its contents
    for (int i = 0; i < num_entries; i++) {
        free(offsets[i]);
    }
    free(offsets);

    // Free the session array and its contents
    for (int i = 0; i < num_sessions; i++) {
        free(sessions[i]);
    }
    free(sessions);
}
