#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>

// Define constants for the maximum number of files to process and the maximum file size limit
#define MAX_FILES 1000
#define MAX_FILE_SIZE 1024 * 1024 * 1024 // 1 GB

// Define a structure to hold information about each file being processed
typedef struct {
    char* filename;
    int fd;
    off_t size;
} file_info_t;

// Define a function to open and read from a file
int open_file(const char* filename) {
    // Open the file for reading
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return -1;
    }

    // Get the size of the file
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("Error getting file size");
        close(fd);
        return -1;
    }

    // Check that the file is not too large
    if (st.st_size > MAX_FILE_SIZE) {
        fprintf(stderr, "File %s is too large\n", filename);
        close(fd);
        return -1;
    }

    return fd;
}

// Define a function to read from a file and update the total line and character count
void* process_file(void* arg) {
    // Get the file information from the argument
    file_info_t* info = (file_info_t*)arg;

    // Open the file for reading
    int fd = open_file(info->filename);
    if (fd == -1) {
        return NULL;
    }

    // Read from the file and update the total line and character count
    char buffer[BUFSIZ];
    off_t offset = 0;
    while (read(fd, buffer, BUFSIZ) > 0) {
        info->size += strlen(buffer);
        offset += BUFSIZ;
    }

    // Close the file
    close(fd);

    return NULL;
}

// Define a function to print usage information if no input files are provided
void print_usage() {
    printf("Usage: %s [options] <input_files>\n", argv[0]);
    printf("\n");
    printf("Options:\n");
    printf("  -cs\tPrint the total character count of all lines.\n");
    printf("  -o <output_file>\tWrite the aggregated results to a specified output file.\n");
}

int main(int argc, char* argv[]) {
    // Check that at least one input file is provided
    if (argc < 2) {
        print_usage();
        return 1;
    }

    // Initialize the total line and character count to zero
    int total_lines = 0;
    long total_chars = 0;

    // Create a semaphore for synchronizing access to the file information array
    sem_t* sem = sem_open("file_sem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Error creating semaphore");
        return -1;
    }

    // Create an array to hold information about each file being processed
    file_info_t* files = malloc(sizeof(file_info_t) * MAX_FILES);
    if (files == NULL) {
        perror("Error allocating memory for file information");
        return -1;
    }

    // Create a thread pool to process the input files concurrently
    pthread_t* threads = malloc(sizeof(pthread_t) * MAX_FILES);
    if (threads == NULL) {
        perror("Error allocating memory for thread pool");
        return -1;
    }

    // Loop through the input files and process each one concurrently
    int i = 0;
    while (i < argc - 1) {
        // Check that the file is not too large
        if (strlen(argv[i + 1]) > MAX_FILE_SIZE) {
            fprintf(stderr, "File %s is too large\n", argv[i + 1]);
            return -1;
        }

        // Open the file for reading and add it to the array of files being processed
        int fd = open_file(argv[i + 1]);
        if (fd == -1) {
            return -1;
        }
        files[i].filename = argv[i + 1];
        files[i].fd = fd;
        files[i].size = 0;

        // Create a thread to process the file and add it to the thread pool
        pthread_create(&threads[i], NULL, process_file, &files[i]);

        i++;
    }

    // Wait for all threads to complete before continuing
    for (int i = 0; i < argc - 1; i++) {
        pthread_join(threads[i], NULL);
    }

    // Close the semaphore and free the memory used by the thread pool and file information array
    sem_close(sem);
    free(threads);
    free(files);

    // Print the total line and character count if requested
    if (strcmp(argv[argc - 1], "-cs") == 0) {
        printf("Total lines: %d\n", total_lines);
        printf("Total characters: %ld\n", total_chars);
    }

    // Write the aggregated results to an output file if requested
    if (strcmp(argv[argc - 1], "-o") == 0) {
        FILE* out = fopen(argv[argc - 2], "w");
        if (out == NULL) {
            perror("Error opening output file");
            return -1;
        }
        fprintf(out, "%d\n", total_lines);
        fprintf(out, "%ld\n", total_chars);
        fclose(out);
    }

    return 0;
}
```
