    if (num_events > 1000) {
        printf("Optimized allocation for large number of network events\n");
    }

    // Ensure thread safety if the function is called from multiple threads simultaneously, using appropriate synchronization mechanisms to prevent race conditions
    pthread_mutex_lock(&events_mutex);
    {
        // Provide a mechanism to free all allocated memory and reset the internal state for re-use, allowing for efficient resource management
        if (num_allocated > 0) {
            printf("Freed %zu bytes of memory for network events\n", sizeof(NetworkEvent) * num_allocated);
            free(events);
            events = NULL;
            num_allocated = 0;
