    size_t num_messages; // Number of messages in the topic
    message_t** messages; // Array of pointers to messages
    int subscription_model; // Subscription model for the topic (e.g., publish-subscribe, request-reply)
} topic_t;

// Define a function to dynamically allocate memory for an array of 'topic' structures
topic_t* allocate_topics(size_t num_topics) {
    // Allocate memory for the array of topics
    topic_t* topics = (topic_t*)malloc(num_topics * sizeof(topic_t));
    if (!topics) {
        fprintf(stderr, "Failed to allocate memory for %zu topics\n", num_topics);
        return NULL;
    }

    // Initialize each topic with a unique identifier and define its subscription model
    for (size_t i = 0; i < num_topics; i++) {
        topics[i].name = malloc(sizeof(char) * 16);
        if (!topics[i].name) {
            fprintf(stderr, "Failed to allocate memory for topic name\n");
            return NULL;
        }
        sprintf(topics[i].name, "topic_%zu", i);
        topics[i].subscription_model = 0; // Publish-subscribe by default
    }

    return topics;
}

// Define a function to dynamically allocate memory for an array of 'message' structures
message_t* allocate_messages(size_t num_messages) {
    // Allocate memory for the array of messages
    message_t* messages = (message_t*)malloc(num_messages * sizeof(message_t));
    if (!messages) {
        fprintf(stderr, "Failed to allocate memory for %zu messages\n", num_messages);
        return NULL;
    }

    // Initialize each message with a unique identifier and define its delivery status
    for (size_t i = 0; i < num_messages; i++) {
        messages[i].payload = malloc(sizeof(char) * 16);
        if (!messages[i].payload) {
            fprintf(stderr, "Failed to allocate memory for message payload\n");
            return NULL;
        }
        sprintf(messages[i].payload, "message_%zu", i);
        messages[i].delivery_status = 0; // Undelivered by default
    }

    return messages;
}

// Define a function to initialize each 'topic' with a unique identifier and define its subscription model
void init_topics(topic_t* topics, size_t num_topics) {
    for (size_t i = 0; i < num_topics; i++) {
        // Generate a unique identifier for the topic
        char* id = malloc(sizeof(char) * 16);
        if (!id) {
            fprintf(stderr, "Failed to allocate memory for topic ID\n");
            return;
        }
        sprintf(id, "%zu", i);
        topics[i].name = id;

        // Define the subscription model for the topic
        switch (topics[i].subscription_model) {
            case 0: // Publish-subscribe
                topics[i].messages = allocate_messages(16);
                break;
            case 1: // Request-reply
                topics[i].messages = allocate_messages(32);
                break;
        }
    }
}

// Define a function to populate each 'message' with payload data and delivery attributes
void populate_messages(message_t* messages, size_t num_messages) {
    for (size_t i = 0; i < num_messages; i++) {
        // Generate a unique identifier for the message
        char* id = malloc(sizeof(char) * 16);
        if (!id) {
            fprintf(stderr, "Failed to allocate memory for message ID\n");
            return;
        }
        sprintf(id, "%zu", i);
        messages[i].payload = id;

        // Define the delivery attributes for the message
        switch (messages[i].delivery_status) {
            case 0: // Undelivered
                messages[i].delivery_status = 1; // Delivered
                break;
            case 1: // Delivered
                messages[i].delivery_status = 2; // Acknowledged
                break;
        }
    }
}

// Define a function to store message payload data in 'message' structures
void store_messages(message_t* messages, size_t num_messages) {
    for (size_t i = 0; i < num_messages; i++) {
        // Store the message payload data in the appropriate structure
        switch (messages[i].delivery_status) {
            case 0: // Undelivered
                messages[i].payload = malloc(sizeof(char) * 16);
                if (!messages[i].payload) {
                    fprintf(stderr, "Failed to allocate memory for message payload\n");
                    return;
                }
                sprintf(messages[i].payload, "message_%zu", i);
                break;
            case 1: // Delivered
                messages[i].payload = malloc(sizeof(char) * 32);
                if (!messages[i].payload) {
                    fprintf(stderr, "Failed to allocate memory for message payload\n");
                    return;
                }
                sprintf(messages[i].payload, "message_%zu", i);
                break;
            case 2: // Acknowledged
                messages[i].payload = malloc(sizeof(char) * 64);
                if (!messages[i].payload) {
                    fprintf(stderr, "Failed to allocate memory for message payload\n");
                    return;
                }
                sprintf(messages[i].payload, "message_%zu", i);
                break;
        }
    }
}

// Define a function to implement error checking during memory allocation
void check_allocations(void* ptr) {
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory\n");
        return;
    }
}

// Define a function to free all allocated memory when the function exits
void cleanup() {
    // Free the topics array
    for (size_t i = 0; i < num_topics; i++) {
        free(topics[i].name);
        if (topics[i].messages) {
            for (size_t j = 0; j < topics[i].num_messages; j++) {
                free(topics[i].messages[j].payload);
            }
            free(topics[i].messages);
        }
    }
    free(topics);

    // Free the messages array
    for (size_t i = 0; i < num_messages; i++) {
        free(messages[i].payload);
    }
    free(messages);
}
