    char *description;
    int salary_range;
    char *required_skills;
};

// Define the linked list node for storing job postings
struct job_posting_node {
    struct job_posting *job_posting;
    struct job_posting_node *next;
};

// Define the function to add a new job posting to the list
void add_job_posting(struct job_posting_node **head, char *title, char *description, int salary_range, char *required_skills) {
    struct job_posting_node *new_node = malloc(sizeof(struct job_posting_node));
    new_node->job_posting = malloc(sizeof(struct job_posting));
    new_node->job_posting->title = title;
    new_node->job_posting->description = description;
    new_node->job_posting->salary_range = salary_range;
    new_node->job_posting->required_skills = required_skills;
    new_node->next = *head;
    *head = new_node;
}

// Define the function to remove a job posting from the list
void remove_job_posting(struct job_posting_node **head, char *title) {
    struct job_posting_node *current = *head;
    struct job_posting_node *previous = NULL;
    while (current != NULL && strcmp(current->job_posting->title, title) != 0) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current->job_posting);
    free(current);
}

// Define the function to traverse the list and print details of each job posting
void traverse_list(struct job_posting_node *head) {
    struct job_posting_node *current = head;
    while (current != NULL) {
        printf("Title: %s\n", current->job_posting->title);
        printf("Description: %s\n", current->job_posting->description);
        printf("Salary Range: %d\n", current->job_posting->salary_range);
        printf("Required Skills: %s\n", current->job_posting->required_skills);
        current = current->next;
    }
}

// Define the function to free all allocated memory when done
void free_memory(struct job_posting_node *head) {
    struct job_posting_node *current = head;
    while (current != NULL) {
        struct job_posting_node *next = current->next;
        free(current->job_posting);
        free(current);
        current = next;
    }
}

