// Define the structure for device logs
typedef struct DeviceLog {
    int device_id;
    time_t timestamp;
    char operational_status[10];
    char error_logs[50];
    double geographical_location[2];
} DeviceLog;

// Define the array for storing device logs
DeviceLog *device_logs = NULL;
size_t num_device_logs = 0;

// Define the mutex and semaphore for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t semaphore = SEM_INITIALIZER(1);

// Function to add a new log to the array
void add_log(DeviceLog *new_log) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the array is full
    if (num_device_logs == SIZE_MAX) {
        // Release the mutex lock and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Add the new log to the end of the array
    device_logs[num_device_logs++] = *new_log;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing log in the array
void update_log(int index, DeviceLog *updated_log) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index < 0 || index >= num_device_logs) {
        // Release the mutex lock and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Update the log at the specified index
    device_logs[index] = *updated_log;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve logs within a specified time window
void retrieve_logs(time_t start_time, time_t end_time) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if there are any logs in the array within the specified time window
    if (num_device_logs == 0 || start_time > device_logs[num_device_logs - 1].timestamp) {
        // Release the mutex lock and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Iterate through the logs in the array within the specified time window
    for (int i = 0; i < num_device_logs; i++) {
        if (start_time <= device_logs[i].timestamp && device_logs[i].timestamp <= end_time) {
            // Print the log at the current index
            printf("Device ID: %d\n", device_logs[i].device_id);
            printf("Timestamp: %s\n", ctime(&device_logs[i].timestamp));
            printf("Operational Status: %s\n", device_logs[i].operational_status);
            printf("Error Logs: %s\n", device_logs[i].error_logs);
            printf("Geographical Location: (%f, %f)\n", device_logs[i].geographical_location[0], device_logs[i].geographical_location[1]);
        }
    }

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

