    if (num_device_logs == 0 || !strcmp(operational_status, device_logs[num_device_logs - 1].operational_status) && fabs(geographical_location[0] - device_logs[i].geographical_location[0]) < 0.00001 && fabs(geographical_location[1] - device_logs[i].geographical_location[1]) < 0.00001) {
