// Initialize the stream state
void initialize_stream_state(struct stream_state *state) {
    // Set the initialized flag to 1
    state->initialized = 1;

    // Set the paused and resumed flags to 0
    state->paused = 0;
    state->resumed = 0;

    // Initialize the number of records to 0
    state->num_records = 0;

    // Allocate memory for the record array
    state->records = (struct record *)malloc(sizeof(struct record) * state->max_records);

    // Initialize the metadata array
    state->metadata = (struct metadata *)malloc(sizeof(struct metadata) * state->max_records);

    // Set up the mutex for thread safety
    pthread_mutex_init(&state->mutex, NULL);
}

// Free the stream state
void free_stream_state(struct stream_state *state) {
    // Check if the stream is initialized
    if (state->initialized == 1) {
        // Free the record array
        free(state->records);

        // Free the metadata array
        free(state->metadata);

        // Destroy the mutex
        pthread_mutex_destroy(&state->mutex);
    }
