        // Write the method to the output file
        int method = requests[i].method;
        if (fwrite(&method, sizeof(int), 1, output) != 1) {
            fprintf(stderr, "Error writing method\n");
            return -1;
        }

        // Write the URL to the output file
        char *url = requests[i].url;
