            return -1;
        }
        for (int j = 0; j < num_headers; j++) {
            char *header = requests[i].headers[j];
            if (fwrite(header, sizeof(char), strlen(header) + 1, output) != strlen(header) + 1) {
                fprintf(stderr, "Error writing header\n");
                return -1;
            }
        }

        // Write the body to the output file
        int body_length = requests[i].body_length;
        if (fwrite(&body_length, sizeof(int), 1, output) != 1) {
            fprintf(stderr, "Error writing body length\n");
            return -1;
        }
        void *body = requests[i].body;
        if (fwrite(body, sizeof(char), body_length, output) != body_length) {
            fprintf(stderr, "Error writing body\n");
            return -1;
        }
    }

    // Close the output file
    fclose(output);

    // Return success
