    long* offsets = malloc(sizeof(long) * max_offset);
    int* keys = malloc(sizeof(int) * max_key);
    enum Status* statuses = malloc(sizeof(enum Status) * max_records);

    // Check for allocation failures
    if (records == NULL || offsets == NULL || keys == NULL || statuses == NULL) {
        free(records);
        free(offsets);
        free(keys);
        free(statuses);
        return FAILURE;
    }

    // Initialize the arrays with random values
    srand(seed);
    for (size_t i = 0; i < max_records; i++) {
        records[i].key = rand() % max_key;
        records[i].offset = rand() % max_offset;
        statuses[i] = SUCCESS;
    }

    // Set the total number of records and failed records
    size_t num_records = max_records;
    size_t num_failed_records = 0;

    // Loop through the arrays and set random values
    for (size_t i = 0; i < max_records; i++) {
        if (statuses[i] == SUCCESS) {
            records[i].key = rand() % max_key;
            records[i].offset = rand() % max_offset;
        } else {
            num_failed_records++;
        }
    }

    // Clean up the memory
    free(records);
    free(offsets);
    free(keys);
    free(statuses);

