// Define a struct to represent a record with an integer key, an array of long integers named offsets, and an integer value
struct record {
    int key;
    long *offsets;
    int value;
};

// Define a function to manage multiple dynamically allocated arrays with varying data types and sizes
void allocate_records(int num_records, struct record **records) {
    // Allocate memory for an array of struct record pointers
    *records = (struct record **)malloc(num_records * sizeof(struct record *));
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize each struct record with a random integer key and an array of long integers named offsets
    for (int i = 0; i < num_records; i++) {
        (*records)[i] = (struct record *)malloc(sizeof(struct record));
        if ((*records)[i] == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record %d\n", i);
            exit(1);
        }
        (*records)[i]->key = rand() % 100;
        (*records)[i]->offsets = (long *)malloc((*records)[i]->key * sizeof(long));
        if ((*records)[i]->offsets == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for offsets of record %d\n", i);
            exit(1);
        }
        (*records)[i]->value = rand() % 1000;
    }
}

// Define a function to free the memory allocated by allocate_records
void free_records(int num_records, struct record **records) {
    // Free each struct record and its offsets array
    for (int i = 0; i < num_records; i++) {
        if ((*records)[i] != NULL) {
            free((*records)[i]->offsets);
            (*records)[i]->offsets = NULL;
        }
        if ((*records)[i] != NULL) {
            free(*records);
            *records = NULL;
        }
    }
}

// Define a function to read from each input file line by line, calculating the total number of lines and character count across all files
void process_files(int num_files, char **file_names) {
    // Initialize variables to keep track of the total number of lines and character count
    int total_lines = 0;
    long total_chars = 0;

    // Iterate over each input file
    for (int i = 0; i < num_files; i++) {
        // Open the current input file in read mode
        FILE *file = fopen(file_names[i], "r");
        if (file == NULL) {
            fprintf(stderr, "Error: Failed to open file %s\n", file_names[i]);
            continue;
        }

        // Read each line of the current input file and update the total number of lines and character count
        char *line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, file)) != -1) {
            total_lines++;
            total_chars += strlen(line);
        }

        // Close the current input file
        fclose(file);
    }

    // Print the total number of lines and character count to standard output
    printf("Total number of lines: %d\n", total_lines);
    printf("Total character count: %ld\n", total_chars);
}

// Define a function to write the aggregated results to an output file
void write_results(int num_records, struct record **records) {
    // Open the output file in write mode
    FILE *file = fopen("output.txt", "w");
    if (file == NULL) {
        fprintf(stderr, "Error: Failed to open output file\n");
        return;
    }

    // Write each struct record to the output file
    for (int i = 0; i < num_records; i++) {
        fprintf(file, "%d %ld %d\n", (*records)[i]->key, (*records)[i]->offsets[(*records)[i]->key], (*records)[i]->value);
    }

    // Close the output file
    fclose(file);
}

// Define a function to handle up to 1000 input files simultaneously without significant performance degradation, ensuring efficient memory usage and minimizing load on system resources
void process_files_concurrently(int num_files, char **file_names) {
    // Initialize variables to keep track of the total number of lines and character count
    int total_lines = 0;
    long total_chars = 0;

    // Create a pool of worker threads to process each input file concurrently
    pthread_t *threads = (pthread_t *)malloc(num_files * sizeof(pthread_t));
    if (threads == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for threads\n");
        return;
    }

    // Create a mutex to synchronize access to the total number of lines and character count variables
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Iterate over each input file and create a worker thread for it
    for (int i = 0; i < num_files; i++) {
        // Create a new worker thread to process the current input file
        pthread_create(&threads[i], NULL, process_file, (void *)file_names[i]);
    }

    // Wait for all worker threads to complete
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory allocated for the worker threads and mutex
    free(threads);
    pthread_mutex_destroy(&mutex);
}

