    MetaData** metadata;
    char** keys;
    int num_configs;
    int capacity;
    pthread_mutex_t mutex; // for thread safety
} ConfigManager;

// Define the function to manage dynamic memory allocation for configurations
void manageConfigurations(ConfigManager* manager, int index, void* data) {
    // Check if the input parameters are valid
    if (manager == NULL || data == NULL) {
        return;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(manager->mutex));

    // Get the current number of configurations
    int num_configs = manager->num_configs;

    // Check if the index is out of bounds
    if (index < 0 || index >= num_configs) {
        pthread_mutex_unlock(&(manager->mutex));
        return;
    }

    // Get the configuration data at the specified index
    ConfigData* config = manager->configs[index];

    // Update the configuration data
    config->offset = (long)data;

    // Unlock the mutex and return
    pthread_mutex_unlock(&(manager->mutex));
}

// Define the function to update a record based on an index
void updateRecord(ConfigManager* manager, int index, void* data) {
    // Check if the input parameters are valid
    if (manager == NULL || data == NULL) {
        return;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(manager->mutex));

    // Get the current number of configurations
    int num_configs = manager->num_configs;

    // Check if the index is out of bounds
    if (index < 0 || index >= num_configs) {
        pthread_mutex_unlock(&(manager->mutex));
        return;
    }

    // Get the configuration data at the specified index
    ConfigData* config = manager->configs[index];

    // Update the configuration data
    config->offset = (long)data;

    // Unlock the mutex and return
    pthread_mutex_unlock(&(manager->mutex));
}

// Define the function to allocate memory for the configuration manager
ConfigManager* createConfigManager(int capacity, int seed) {
    // Check if the input parameters are valid
    if (capacity <= 0 || seed < 0) {
        return NULL;
    }

    // Allocate memory for the configuration manager structure
    ConfigManager* manager = malloc(sizeof(ConfigManager));
    if (manager == NULL) {
        return NULL;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_init(&(manager->mutex), NULL);

    // Allocate memory for the configuration data array
    manager->configs = malloc(capacity * sizeof(ConfigData*));
    if (manager->configs == NULL) {
        free(manager);
        return NULL;
    }

    // Allocate memory for the metadata array
    manager->metadata = malloc(capacity * sizeof(MetaData*));
    if (manager->metadata == NULL) {
        free(manager->configs);
        free(manager);
        return NULL;
    }

    // Allocate memory for the string key array
    manager->keys = malloc(5000 * sizeof(char*));
    if (manager->keys == NULL) {
        free(manager->metadata);
        free(manager->configs);
        free(manager);
        return NULL;
    }

    // Initialize the number of configurations and capacity
    manager->num_configs = 0;
    manager->capacity = capacity;

    // Set the random seed for generating unique keys
    srand(seed);

    // Return the configuration manager structure
    return manager;
}

// Define the function to add a new configuration to the manager
int addConfig(ConfigManager* manager, int key, void* data) {
    // Check if the input parameters are valid
    if (manager == NULL || data == NULL) {
        return -1;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(manager->mutex));

    // Get the current number of configurations
    int num_configs = manager->num_configs;

    // Check if the capacity is exceeded
    if (num_configs >= manager->capacity) {
        pthread_mutex_unlock(&(manager->mutex));
        return -1;
    }

    // Allocate memory for the new configuration data
    ConfigData* config = malloc(sizeof(ConfigData));
    if (config == NULL) {
        pthread_mutex_unlock(&(manager->mutex));
        return -1;
    }

    // Initialize the configuration data
    config->offset = (long)data;
    config->key = key;
    config->metadata = NULL;

    // Allocate memory for the new metadata
    MetaData* meta = malloc(sizeof(MetaData));
    if (meta == NULL) {
        free(config);
        pthread_mutex_unlock(&(manager->mutex));
        return -1;
    }

    // Initialize the metadata
    meta->name = NULL;
    meta->type = 0;
    meta->value = NULL;

    // Add the new configuration data and metadata to the arrays
    manager->configs[num_configs] = config;
    manager->metadata[num_configs] = meta;
    manager->keys[num_configs] = NULL;

    // Increment the number of configurations
    manager->num_configs++;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&(manager->mutex));
    return 0;
}

// Define the function to remove a configuration from the manager
int removeConfig(ConfigManager* manager, int index) {
    // Check if the input parameters are valid
    if (manager == NULL || index < 0 || index >= manager->num_configs) {
        return -1;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(manager->mutex));

    // Get the configuration data at the specified index
    ConfigData* config = manager->configs[index];

    // Free the memory for the configuration data and metadata
    free(config);
    free(manager->metadata[index]);

    // Shift all configurations after the specified index to fill the gap
    for (int i = index + 1; i < manager->num_configs; i++) {
        manager->configs[i - 1] = manager->configs[i];
        manager->metadata[i - 1] = manager->metadata[i];
        manager->keys[i - 1] = manager->keys[i];
    }

    // Decrement the number of configurations
    manager->num_configs--;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&(manager->mutex));
    return 0;
}

// Define the function to get a configuration from the manager
ConfigData* getConfig(ConfigManager* manager, int index) {
    // Check if the input parameters are valid
    if (manager == NULL || index < 0 || index >= manager->num_configs) {
        return NULL;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(manager->mutex));

    // Get the configuration data at the specified index
    ConfigData* config = manager->configs[index];

    // Unlock the mutex and return the configuration data
    pthread_mutex_unlock(&(manager->mutex));
    return config;
}

// Define the function to get a metadata from the manager
MetaData* getMetadata(ConfigManager* manager, int index) {
    // Check if the input parameters are valid
    if (manager == NULL || index < 0 || index >= manager->num_configs) {
        return NULL;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(manager->mutex));

    // Get the metadata at the specified index
    MetaData* meta = manager->metadata[index];

    // Unlock the mutex and return the metadata
    pthread_mutex_unlock(&(manager->mutex));
    return meta;
}

// Define the function to get a string key from the manager
char* getKey(ConfigManager* manager, int index) {
    // Check if the input parameters are valid
    if (manager == NULL || index < 0 || index >= manager->num_configs) {
        return NULL;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(manager->mutex));

    // Get the string key at the specified index
    char* key = manager->keys[index];

    // Unlock the mutex and return the string key
    pthread_mutex_unlock(&(manager->mutex));
    return key;
}

// Define the function to set a metadata for a configuration
int setMetadata(ConfigManager* manager, int index, void* data) {
    // Check if the input parameters are valid
    if (manager == NULL || index < 0 || index >= manager->num_configs || data == NULL) {
        return -1;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(manager->mutex));

    // Get the configuration data at the specified index
    ConfigData* config = manager->configs[index];

    // Update the metadata for the configuration
    config->metadata = data;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&(manager->mutex));
    return 0;
}

// Define the function to set a string key for a configuration
int setKey(ConfigManager* manager, int index, char* key) {
    // Check if the input parameters are valid
    if (manager == NULL || index < 0 || index >= manager->num_configs || key == NULL) {
        return -1;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(manager->mutex));

    // Get the configuration data at the specified index
    ConfigData* config = manager->configs[index];

    // Update the string key for the configuration
    config->key = key;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&(manager->mutex));
    return 0;
}

// Define the function to release all allocated memory upon completion
void destroyConfigManager(ConfigManager* manager) {
    // Check if the input parameter is valid
    if (manager == NULL) {
        return;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(manager->mutex));

    // Free all allocated memory for the configuration data, metadata, and string keys
    for (int i = 0; i < manager->num_configs; i++) {
        free(manager->configs[i]);
        free(manager->metadata[i]);
        free(manager->keys[i]);
    }

    // Free the memory for the configuration data, metadata, and string keys arrays
    free(manager->configs);
    free(manager->metadata);
    free(manager->keys);

    // Destroy the mutex
    pthread_mutex_destroy(&(manager->mutex));

    // Free the memory for the configuration manager structure
    free(manager);
}
