#include <assert.h>

// Define a structure to represent a record
typedef struct {
    int key;
    long offset;
} Record;

// Define a status flag for initialization success/failure
typedef enum {
    INIT_SUCCESS,
    INIT_FAILURE
} InitStatus;

// Define a function to initialize an array of records with user-provided size limits
InitStatus initRecords(Record **records, int *numRecords, long maxSize, int keyMin, int keyMax, long offsetMin, long offsetMax) {
    // Validate the input sizes and maximum limit
    if (maxSize <= 0 || numRecords == NULL || records == NULL) {
        return INIT_FAILURE;
    }

    // Allocate memory for the arrays
    *records = malloc(sizeof(Record) * maxSize);
    if (*records == NULL) {
        return INIT_FAILURE;
    }

    // Initialize the arrays with random values within the given ranges
    srand(time(NULL));
    for (int i = 0; i < maxSize; i++) {
        (*records)[i].key = rand() % (keyMax - keyMin + 1) + keyMin;
        (*records)[i].offset = rand() % (offsetMax - offsetMin + 1) + offsetMin;
    }

    // Set the number of records initialized to the maximum size
    *numRecords = maxSize;

    return INIT_SUCCESS;
}

// Define a function to set the value of each record's int field to a random value within a given range
void setRandomValues(Record **records, int numRecords, int keyMin, int keyMax) {
    // Validate the input parameters
    if (records == NULL || numRecords <= 0) {
        return;
    }

    // Set the value of each record's int field to a random value within the given range
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        (*records)[i].key = rand() % (keyMax - keyMin + 1) + keyMin;
    }
}

