void updateStatus(Record **records, int numRecords, InitStatus *status) {
    // Validate the input parameters
    if (records == NULL || numRecords <= 0 || status == NULL) {
        return;
    }

    // Update the status flag and populate the timestamp field with the current system time
    for (int i = 0; i < numRecords; i++) {
        (*status)[i] = INIT_SUCCESS;
        (*records)[i].timestamp = time(NULL);
    }
}

// Define a function to handle cases where the user provides negative or zero sizes for the arrays and gracefully handle these inputs by returning an appropriate error code
InitStatus initRecordsWithNegativeSizes(Record **records, int *numRecords, long maxSize) {
    // Validate the input parameters
    if (maxSize <= 0 || numRecords == NULL || records == NULL) {
        return INIT_FAILURE;
    }

    // Allocate memory for the arrays with a minimum size of 1
    *records = malloc(sizeof(Record) * maxSize > 0 ? maxSize : 1);
    if (*records == NULL) {
        return INIT_FAILURE;
    }

    // Set the number of records initialized to the minimum size
    *numRecords = maxSize > 0 ? maxSize : 1;

    return INIT_SUCCESS;
}

