// Define a function to support batch processing, allowing the caller to process multiple sets of arrays concurrently, with each set having its own size and random seed
void initBatch(Record ***batch, int *numBatches, long maxSize, int keyMin, int keyMax, long offsetMin, long offsetMax) {
    // Validate the input parameters
    if (maxSize <= 0 || numBatches == NULL || batch == NULL) {
        return;
    }

    // Allocate memory for the batch of arrays
    *batch = malloc(sizeof(Record *) * maxSize);
    if (*batch == NULL) {
