        if ((*batch)[i] == NULL) {
            return;
        }
        for (int j = 0; j < maxSize; j++) {
            (*batch)[i][j].key = rand() % (keyMax - keyMin + 1) + keyMin;
            (*batch)[i][j].offset = rand() % (offsetMax - offsetMin + 1) + offsetMin;
        }
    }

    // Set the number of batches initialized to the maximum size
    *numBatches = maxSize;
}

// Define a function to serialize and deserialize the state of the function between processing batches, allowing it to resume from the last completed batch in case of interruptions
void serializeState(Record ***batch, int numBatches) {
    // Validate the input parameters
    if (batch == NULL || numBatches <= 0) {
        return;
    }

    // Serialize the state of the function by writing it to a file
    FILE *stateFile = fopen("init_state.bin", "wb");
    if (stateFile == NULL) {
        return;
    }

    // Write the state of each array in the batch to the file
    for (int i = 0; i < numBatches; i++) {
        fwrite((*batch)[i], sizeof(Record), maxSize, stateFile);
    }

    // Close the state file
    fclose(stateFile);
}

// Define a function to deserialize the state of the function from a file and resume processing from the last completed batch in case of interruptions
void deserializeState(Record ***batch, int *numBatches) {
    // Validate the input parameters
    if (batch == NULL || numBatches == NULL) {
        return;
    }

    // Deserialize the state of the function by reading it from a file
    FILE *stateFile = fopen("init_state.bin", "rb");
    if (stateFile == NULL) {
        return;
    }

    // Read the state of each array in the batch from the file
    for (int i = 0; i < *numBatches; i++) {
        fread((*batch)[i], sizeof(Record), maxSize, stateFile);
    }

    // Close the state file
    fclose(stateFile);
}
