// Define the structure to hold transaction data
struct Transaction {
    int id;
    int user_id;
    float amount;
    long timestamp;
    float average_amount;
};

// Define the array to store transactions
struct Transaction *transactions = NULL;

// Define the size of the transaction array
int transaction_size = 0;

// Define the mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to process a single transaction
void process_transaction(struct Transaction *transaction) {
    // Calculate the average transaction amount for the current day
    float average_amount = 0.0f;
    int num_transactions = 0;
    for (int i = 0; i < transaction_size; i++) {
        if (transactions[i].timestamp == transaction->timestamp) {
            average_amount += transactions[i].amount;
            num_transactions++;
        }
    }
    if (num_transactions > 0) {
        average_amount /= num_transactions;
    }

    // Update the average transaction amount for the current day
    transaction->average_amount = average_amount;

    // Validate the transaction amount against known limits and flags for suspicious activity
    if (validate_transaction(transaction)) {
        // Log successful validation
        printf("Transaction %d validated successfully\n", transaction->id);
    } else {
        // Log failed validation
        printf("Transaction %d failed validation\n", transaction->id);
    }
}

// Function to validate a single transaction
int validate_transaction(struct Transaction *transaction) {
    // Check if the transaction amount is within limits
    if (transaction->amount < 0 || transaction->amount > 10000) {
        return 0;
    }

    // Check if there are any flags for suspicious activity
    if (transaction->flags & SUSPICIOUS_ACTIVITY) {
        return 0;
    }

    // If all checks pass, the transaction is valid
    return 1;
}

// Function to add a new transaction to the array
void add_transaction(struct Transaction *transaction) {
    pthread_mutex_lock(&mutex);
    transactions = realloc(transactions, (transaction_size + 1) * sizeof(struct Transaction));
    memcpy(&transactions[transaction_size], transaction, sizeof(struct Transaction));
    transaction_size++;
    pthread_mutex_unlock(&mutex);
}

// Function to read and process a chunk of the CSV file
void process_chunk(char *chunk) {
    // Split the chunk into lines
    char *line = strtok(chunk, "\n");
    while (line != NULL) {
        // Parse the line into fields
        struct Transaction transaction;
        sscanf(line, "%d,%d,%f,%ld", &transaction.id, &transaction.user_id, &transaction.amount, &transaction.timestamp);

        // Process the transaction
        process_transaction(&transaction);

        // Move to the next line
        line = strtok(NULL, "\n");
    }
}

// Function to read and process the entire CSV file
void process_file(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Read the file in chunks and process each chunk concurrently
    char *chunk = malloc(CHUNK_SIZE * sizeof(char));
    while (fread(chunk, 1, CHUNK_SIZE, file) == CHUNK_SIZE) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, process_chunk, chunk)) {
            printf("Error: unable to create thread\n");
            return;
        }
    }

    // Wait for all threads to complete
    pthread_mutex_lock(&mutex);
    while (transaction_size > 0) {
        pthread_cond_wait(&cond, &mutex);
    }
    pthread_mutex_unlock(&mutex);
}

// Main function to read and process the CSV file
int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s filename\n", argv[0]);
        return 1;
    }

    // Initialize the transaction array
    transactions = malloc(sizeof(struct Transaction));
    transaction_size = 0;

    // Process the entire CSV file concurrently
    process_file(argv[1]);

    // Print the contents of each line in a formatted output
    for (int i = 0; i < transaction_size; i++) {
        printf("%d,%d,%f,%ld,%f\n", transactions[i].id, transactions[i].user_id, transactions[i].amount, transactions[i].timestamp, transactions[i].average_amount);
    }

    // Clean up memory
    free(transactions);
    return 0;
}
