#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// Define the data structure for a record
typedef struct {
    long index;
    int key;
} Record;

// Define the data structure for an array of records
typedef struct {
    Record* records;
    size_t num_records;
} Records;

// Define the data structure for a unique key generation function
typedef struct {
    int current_key;
    pthread_mutex_t mutex;
} UniqueKeyGen;

// Define the maximum number of retries for generating a unique key
#define RETRY_LIMIT 10

// Define the function to generate a unique key
int generate_unique_key(UniqueKeyGen* gen) {
    int key = -1;
    pthread_mutex_lock(&gen->mutex);
    for (int i = 0; i < RETRY_LIMIT; i++) {
        key = rand() % 1000000;
        if (!key_exists(gen, key)) {
            break;
        }
    }
    pthread_mutex_unlock(&gen->mutex);
    return key;
}

// Define the function to check if a key exists in the array of records
bool key_exists(UniqueKeyGen* gen, int key) {
    for (int i = 0; i < gen->num_records; i++) {
        if (gen->records[i].key == key) {
            return true;
        }
    }
    return false;
}

// Define the function to populate the records array with unique keys
void populate_records(Records* records, UniqueKeyGen* gen) {
    for (int i = 0; i < records->num_records; i++) {
        int key = generate_unique_key(gen);
        while (!key_exists(gen, key)) {
            key = generate_unique_key(gen);
        }
        records->records[i].key = key;
    }
}

// Define the function to calculate and store the sum of all keys in the array
void calculate_sum(Records* records) {
    int total_keys = 0;
    for (int i = 0; i < records->num_records; i++) {
        total_keys += records->records[i].key;
    }
    records->total_keys = total_keys;
}

// Define the function to free all allocated memory and reset the internal state
void free_memory(Records* records) {
    if (records != NULL) {
        free(records->records);
        records->num_records = 0;
        records->total_keys = 0;
    }
}

// Define the function to manage the records array and calculate the sum of all keys
void manage_records(int N, Records* records) {
    // Allocate memory for the records array
    records->records = (Record*)malloc(N * sizeof(Record));
    if (records->records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize the unique key generation function
    UniqueKeyGen gen;
    gen.current_key = 0;
    pthread_mutex_init(&gen.mutex, NULL);

    // Populate the records array with unique keys
    populate_records(records, &gen);

    // Calculate and store the sum of all keys in the array
    calculate_sum(records);

    // Free all allocated memory and reset the internal state
    free_memory(records);
