// Define a struct to represent a metric data structure
struct Metric {
    char *identifier;
    time_t timestamp;
    union {
        int value_int;
        float value_float;
    } value;
};

// Define a struct to represent a record
struct Record {
    int key;
    long offset;
    int value;
};

// Define a hash table for efficient key lookups
typedef struct HashTable {
    struct Metric *metrics[];
} HashTable;

// Function to dynamically allocate memory for the identifier strings, timestamps, and metric values based on input parameters
void allocateMemory(int numSensors, int typeOfMetric, int numRecords) {
    // Allocate memory for the identifier strings
    char *identifiers = malloc(numSensors * sizeof(char));
    if (identifiers == NULL) {
        printf("Error: Failed to allocate memory for identifiers\n");
        return;
    }

    // Initialize the identifiers with unique names starting from a base name and appending an index
    int i = 0;
    while (i < numSensors) {
        sprintf(identifiers[i], "sensor_%d", i);
        i++;
    }

    // Allocate memory for the timestamps
    time_t *timestamps = malloc(numSensors * sizeof(time_t));
    if (timestamps == NULL) {
        printf("Error: Failed to allocate memory for timestamps\n");
        return;
    }

    // Initialize the timestamps with the current time using a high-resolution clock
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long int currentTime = (long long int)ts.tv_sec * 1000 + (long long int)ts.tv_nsec / 1000000;
    for (i = 0; i < numSensors; i++) {
        timestamps[i] = currentTime;
    }

    // Allocate memory for the metric values based on the type of metric
    union {
        int *values_int;
        float *values_float;
    } values;
    if (typeOfMetric == 0) {
        values.values_int = malloc(numSensors * sizeof(int));
        if (values.values_int == NULL) {
            printf("Error: Failed to allocate memory for integer metric values\n");
            return;
        }
    } else {
        values.values_float = malloc(numSensors * sizeof(float));
        if (values.values_float == NULL) {
            printf("Error: Failed to allocate memory for floating-point metric values\n");
            return;
        }
    }

    // Initialize the metric values with random numbers within a specified range
    srand(time(NULL));
    int minValue = 0, maxValue = 100;
    if (typeOfMetric == 0) {
        for (i = 0; i < numSensors; i++) {
            values.values_int[i] = rand() % (maxValue - minValue + 1) + minValue;
        }
    } else {
        float minFloatValue = 0, maxFloatValue = 100;
        for (i = 0; i < numSensors; i++) {
            values.values_float[i] = (rand() % (maxFloatValue - minFloatValue + 1) + minFloatValue) / 100;
        }
    }

    // Allocate memory for the records and initialize their fields
    struct Record *records = malloc(numRecords * sizeof(struct Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }
    for (i = 0; i < numRecords; i++) {
        records[i].key = rand() % numSensors;
        records[i].offset = rand() % (numRecords - i) + i;
        if (typeOfMetric == 0) {
            records[i].value = values.values_int[records[i].key];
        } else {
            records[i].value = values.values_float[records[i].key];
        }
    }

    // Allocate memory for the hash table and initialize its fields
    HashTable *hashTable = malloc(sizeof(HashTable));
    if (hashTable == NULL) {
        printf("Error: Failed to allocate memory for hash table\n");
        return;
    }
    hashTable->metrics = malloc(numSensors * sizeof(struct Metric));
    if (hashTable->metrics == NULL) {
        printf("Error: Failed to allocate memory for metrics in hash table\n");
        return;
    }
    for (i = 0; i < numSensors; i++) {
        hashTable->metrics[i].identifier = identifiers[i];
        hashTable->metrics[i].timestamp = timestamps[i];
        if (typeOfMetric == 0) {
            hashTable->metrics[i].value.value_int = values.values_int[i];
        } else {
            hashTable->metrics[i].value.value_float = values.values_float[i];
        }
    }
}

// Function to free all allocated memory when the function exits
void freeMemory() {
    // Free the identifier strings, timestamps, and metric values
    free(identifiers);
