enum Status {
    OK,
    ERROR
};

// Define a function to initialize the arrays and populate the records
void init_arrays(long *offset_arr, int *key_arr, Record **record_arr, size_t num_records) {
    // Allocate memory for the offset array
    offset_arr = (long *)malloc(num_records * sizeof(long));
    if (!offset_arr) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset values using a random distribution
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        offset_arr[i] = rand() % 100;
    }

    // Allocate memory for the key array
    key_arr = (int *)malloc(num_records * sizeof(int));
    if (!key_arr) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offset_arr);
        return;
    }

    // Initialize the key values using a random distribution
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        key_arr[i] = rand() % 100;
    }

    // Allocate memory for the record array
    record_arr = (Record **)malloc(num_records * sizeof(Record));
    if (!record_arr) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offset_arr);
        free(key_arr);
        return;
    }

    // Initialize the double values using a random distribution
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        record_arr[i] = malloc(sizeof(Record));
        if (!record_arr[i]) {
            printf("Error: Failed to allocate memory for record %zu\n", i);
            free(offset_arr);
            free(key_arr);
            free(record_arr);
            return;
        }
        record_arr[i]->value = rand() % 100;
    }

    // Initialize the char arrays to a fixed length filled with random ASCII characters
    for (size_t i = 0; i < num_records; i++) {
        for (int j = 0; j < 10; j++) {
            record_arr[i]->array[j] = rand() % 26 + 'a';
        }
    }

    // Populate the status flags based on certain conditions related to the record's values
    for (size_t i = 0; i < num_records; i++) {
        if (record_arr[i]->value > 50) {
            record_arr[i]->status = OK;
        } else {
            record_arr[i]->status = ERROR;
        }
    }
}

// Define a function to free the memory allocated by init_arrays
void free_arrays(long *offset_arr, int *key_arr, Record **record_arr) {
    // Free the offset array
    if (offset_arr) {
        free(offset_arr);
    }

    // Free the key array
    if (key_arr) {
        free(key_arr);
    }

    // Free the record array
    if (record_arr) {
        for (size_t i = 0; i < num_records; i++) {
            if (record_arr[i]) {
                free(record_arr[i]);
            }
        }
        free(record_arr);
    }
}
