#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <stdarg.h>
#include <time.h>

#define MAX_CONNECTIONS 1024
#define CONNECTION_LIMIT 512
#define TIMEOUT 30
#define QUEUE_SIZE 1024
#define BUFFER_SIZE 8192
#define PRIORITY_LEVELS 3
#define MAX_TIMEZONE_OFFSET 12
#define MIN_TIMEZONE_OFFSET -12
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

typedef struct {
    int fd;
    char *ip;
    unsigned short port;
} connection_t;

typedef struct {
    int priority;
    char *destination;
} destination_t;

typedef struct {
    int fd;
    char *ip;
    unsigned short port;
    time_t timestamp;
} packet_t;

typedef struct {
    connection_t *connections[MAX_CONNECTIONS];
    pthread_mutex_t lock;
    int num_connections;
    int max_connections;
    int connection_limit;
    destination_t *destinations[PRIORITY_LEVELS];
    int num_destinations;
} network_gateway_t;

void init_network_gateway(network_gateway_t *ng) {
    ng->num_connections = 0;
    ng->max_connections = MAX_CONNECTIONS;
    ng->connection_limit = CONNECTION_LIMIT;
    ng->num_destinations = 0;
}

void add_connection(network_gateway_t *ng, int fd, char *ip, unsigned short port) {
    pthread_mutex_lock(&ng->lock);
    if (ng->num_connections < ng->max_connections) {
        connection_t *conn = malloc(sizeof(connection_t));
        conn->fd = fd;
        conn->ip = ip;
        conn->port = port;
        ng->connections[ng->num_connections++] = conn;
    } else {
        close(fd);
    }
    pthread_mutex_unlock(&ng->lock);
}

void remove_connection(network_gateway_t *ng, int fd) {
    pthread_mutex_lock(&ng->lock);
    for (int i = 0; i < ng->num_connections; i++) {
        if (ng->connections[i]->fd == fd) {
            free(ng->connections[i]);
            ng->connections[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&ng->lock);
}

void add_destination(network_gateway_t *ng, char *ip, unsigned short port, int priority) {
    pthread_mutex_lock(&ng->lock);
    if (ng->num_destinations < PRIORITY_LEVELS) {
        destination_t *dst = malloc(sizeof(destination_t));
        dst->priority = priority;
        dst->destination = ip;
        ng->destinations[ng->num_destinations++] = dst;
    } else {
        free(ip);
    }
    pthread_mutex_unlock(&ng->lock);
}

void remove_destination(network_gateway_t *ng, char *ip) {
    pthread_mutex_lock(&ng->lock);
    for (int i = 0; i < ng->num_destinations; i++) {
        if (strcmp(ng->destinations[i]->destination, ip) == 0) {
            free(ng->destinations[i]);
            ng->destinations[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&ng->lock);
}

void send_packet(network_gateway_t *ng, packet_t *packet) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return;
    }
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    inet_pton(AF_INET, packet->ip, &server_address.sin_addr);
    server_address.sin_port = htons(packet->port);
    if (connect(fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("connect");
        close(fd);
        return;
    }
    char buffer[BUFFER_SIZE];
    memset(buffer, 0, BUFFER_SIZE);
    strcpy(buffer, packet->data);
    if (send(fd, buffer, strlen(buffer), 0) < 0) {
        perror("send");
        close(fd);
        return;
    }
    close(fd);
}

void receive_packet(network_gateway_t *ng, packet_t *packet) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return;
    }
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    inet_pton(AF_INET, packet->ip, &server_address.sin_addr);
    server_address.sin_port = htons(packet->port);
    if (connect(fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("connect");
        close(fd);
        return;
    }
    char buffer[BUFFER_SIZE];
    memset(buffer, 0, BUFFER_SIZE);
    if (recv(fd, buffer, BUFFER_SIZE, 0) < 0) {
        perror("recv");
        close(fd);
        return;
    }
    packet->data = malloc(strlen(buffer));
    strcpy(packet->data, buffer);
    close(fd);
}

void handle_connection(network_gateway_t *ng, int fd) {
    char buffer[BUFFER_SIZE];
    memset(buffer, 0, BUFFER_SIZE);
    if (recv(fd, buffer, BUFFER_SIZE, 0) < 0) {
        perror("recv");
        close(fd);
        return;
    }
    packet_t *packet = malloc(sizeof(packet_t));
    memset(packet, 0, sizeof(packet_t));
