void handle_packet(network_gateway_t *ng, packet_t *packet) {
    if (packet->priority < PRIORITY_LEVELS) {
        for (int i = 0; i < ng->num_destinations; i++) {
            if (strcmp(ng->destinations[i]->destination, packet->ip) == 0 && ng->destinations[i]->port == packet->port) {
                send_packet(ng, packet);
                return;
            }
        }
    } else {
        for (int i = 0; i < ng->num_connections; i++) {
            if (strcmp(ng->connections[i]->ip, packet->ip) == 0 && ng->connections[i]->port == packet->port) {
                send_packet(ng, packet);
                return;
            }
        }
    }
}

