// Define the record structure
typedef struct {
    int value;
    char buffer[10]; // 10 is the maximum length of the string representation of an integer
} Record;

// Define the function to initialize the structures
void init_structures(int num_records, long *offsets, int *keys, Record **records) {
    // Allocate memory for the offsets and keys arrays
    offsets = (long *)malloc(num_records * sizeof(long));
    keys = (int *)malloc(num_records * sizeof(int));

    // Initialize the offsets and keys from an external data source
    // ...

    // Allocate memory for the records array
    records = (Record **)malloc(num_records * sizeof(Record *));

    // Initialize each record's integer field with a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        int rand_value = rand() % 100 + 1; // Random value between 1 and 100
        records[i] = (Record *)malloc(sizeof(Record));
        records[i]->value = rand_value;
    }

    // Initialize each record's string buffer with the string representation of its integer field
    for (int i = 0; i < num_records; i++) {
        sprintf(records[i]->buffer, "%d", records[i]->value);
    }
}

// Define the function to free the allocated memory
void free_structures(long *offsets, int *keys, Record **records) {
    // Free the offsets and keys arrays
    free(offsets);
    free(keys);

    // Free each record's string buffer
