// Define the function to read configuration parameters from a JSON file
void read_config(const char *filename, int *max_string_len, int *rand_range) {
    json_object *root = json_object_from_file(filename);
    if (!root) {
        fprintf(stderr, "Error: unable to open JSON file\n");
        exit(1);
    }

    // Read the maximum size of the string buffer from the JSON file
    json_object *max_string_len_obj = json_object_object_get(root, "max_string_len");
    if (!json_object_is_type(max_string_len_obj, json_type_int)) {
        fprintf(stderr, "Error: unable to read maximum string length from JSON file\n");
        exit(1);
    }
    *max_string_len = json_object_get_int(max_string_len_obj);

    // Read the range of random integers from the JSON file
    json_object *rand_range_obj = json_object_object_get(root, "rand_range");
    if (!json_object_is_type(rand_range_obj, json_type_int)) {
        fprintf(stderr, "Error: unable to read random integer range from JSON file\n");
        exit(1);
    }
    *rand_range = json_object_get_int(rand_range_obj);
}

// Define the function to handle allocation failures gracefully
