    exit(1);
}

// Define the function to optimize performance and memory usage
void optimize_performance(int num_records) {
    // Allocate a single block of memory for all records
    Record **records = (Record **)malloc(num_records * sizeof(Record));

    // Initialize each record's integer field with a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        int rand_value = rand() % 100 + 1; // Random value between 1 and 100
        records[i] = (Record *)malloc(sizeof(Record));
        records[i]->value = rand_value;
    }

    // Initialize each record's string buffer with the string representation of its integer field
    for (int i = 0; i < num_records; i++) {
        sprintf(records[i]->buffer, "%d", records[i]->value);
    }
}

// Define the function to ensure that all allocated memory is properly freed after use
void free_memory() {
    // Free the offsets and keys arrays
    free(offsets);
    free(keys);

    // Free each record's string buffer
