    return min + (rand() % (max - min + 1));
}

// Define a function to generate a random string of a given length
char* rand_string(int len) {
    char* str = malloc(len * sizeof(char));
    for (int i = 0; i < len; i++) {
        str[i] = 'a' + (rand() % ('z' - 'a'));
    }
    return str;
}

// Define a function to initialize a job posting with random attributes
void init_job_posting(JobPosting* posting, int min_salary, int max_salary, int title_len, int desc_len) {
    posting->salary = rand_range(min_salary, max_salary);
    posting->title = rand_string(title_len);
    posting->description = rand_string(desc_len);
}

// Define a function to allocate memory for an array of job postings
JobPosting* alloc_job_postings(int num_postings) {
    JobPosting* postings = malloc(num_postings * sizeof(JobPosting));
    if (!postings) {
        fprintf(stderr, "Error: failed to allocate memory for job postings\n");
        exit(1);
    }
    return postings;
}

// Define a function to free memory allocated for an array of job postings
void free_job_postings(JobPosting* postings) {
    if (postings) {
        free(postings);
    }
}

// Define a function to add a new job posting to the list
void add_job_posting(JobPosting** postings, int num_postings, JobPosting* new_posting) {
    if (num_postings >= 10000) {
        fprintf(stderr, "Error: maximum number of job postings exceeded\n");
        exit(1);
    }
    *postings = realloc(*postings, (num_postings + 1) * sizeof(JobPosting));
    if (!*postings) {
        fprintf(stderr, "Error: failed to allocate memory for new job posting\n");
        exit(1);
    }
    (*postings)[num_postings] = *new_posting;
}

// Define a function to retrieve a job posting from the list by index
JobPosting* get_job_posting(JobPosting** postings, int num_postings, int idx) {
    if (idx < 0 || idx >= num_postings) {
        fprintf(stderr, "Error: invalid job posting index\n");
        exit(1);
    }
    return &(*postings)[idx];
}

// Define a function to filter job postings based on salary range and location
void filter_job_postings(JobPosting** postings, int num_postings, int min_salary, int max_salary, char* location) {
    if (location == NULL || strlen(location) == 0) {
        fprintf(stderr, "Error: invalid location\n");
        exit(1);
    }
    // Initialize a new array to store the filtered job postings
    JobPosting* filtered_postings = malloc(num_postings * sizeof(JobPosting));
    if (!filtered_postings) {
        fprintf(stderr, "Error: failed to allocate memory for filtered job postings\n");
        exit(1);
    }
    // Iterate over the original array of job postings and filter based on salary range and location
    int num_filtered_postings = 0;
    for (int i = 0; i < num_postings; i++) {
        JobPosting* posting = &(*postings)[i];
        if (posting->salary >= min_salary && posting->salary <= max_salary) {
            filtered_postings[num_filtered_postings++] = *posting;
        }
    }
    // Reallocate the array to match the number of filtered job postings
    filtered_postings = realloc(filtered_postings, num_filtered_postings * sizeof(JobPosting));
    if (!filtered_postings) {
        fprintf(stderr, "Error: failed to allocate memory for filtered job postings\n");
        exit(1);
    }
    // Update the original array of job postings with the filtered list
    *postings = filtered_postings;
}

