void read_config(const char* filename, int* min_salary, int* max_salary, int* title_len, int* desc_len) {
    // Open the JSON file for reading
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: failed to open JSON configuration file\n");
        exit(1);
    }
    // Read the minimum and maximum salary ranges from the file
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        if (strncmp(line, "\"minSalary\":", strlen("\"minSalary\":")) == 0) {
            *min_salary = atoi(line + strlen("\"minSalary\":"));
        } else if (strncmp(line, "\"maxSalary\":", strlen("\"maxSalary\":")) == 0) {
            *max_salary = atoi(line + strlen("\"maxSalary\":"));
        } else if (strncmp(line, "\"titleLen\":", strlen("\"titleLen\":")) == 0) {
            *title_len = atoi(line + strlen("\"titleLen\":"));
        } else if (strncmp(line, "\"descLen\":", strlen("\"descLen\":")) == 0) {
            *desc_len = atoi(line + strlen("\"descLen\":"));
        }
    }
    // Close the JSON file
    fclose(fp);
}

