        job_posting->description[desc_length] = '\0';
    }

    // Add the job postings to the linked list of records
    for (int i = 0; i < max_size; i++) {
        RecordNode* node = malloc(sizeof(RecordNode));
        if (!node) {
            printf("Error: Failed to allocate memory for record node\n");
            return;
        }
        node->key = job_postings[i].id;
        node->offset = i * sizeof(JobPosting);
        node->next = head;
        head = node;
    }

    // Free the memory allocated for the job postings
    free(job_postings);
}

// Function to add a new job posting to the linked list of records
void addJobPosting(int id, char* title, char* description, float salary_range) {
    // Check if the job posting already exists in the linked list
    RecordNode* node = head;
    while (node != NULL) {
        if (node->key == id) {
            printf("Error: Job posting with ID %d already exists\n", id);
            return;
        }
        node = node->next;
    }

    // Allocate memory for the new job posting
    JobPosting* job_posting = malloc(sizeof(JobPosting));
    if (!job_posting) {
        printf("Error: Failed to allocate memory for new job posting\n");
        return;
    }

    // Initialize the new job posting
    job_posting->id = id;
    strcpy(job_posting->title, title);
    strcpy(job_posting->description, description);
    job_posting->salary_range = salary_range;

    // Add the new job posting to the linked list of records
    RecordNode* node = malloc(sizeof(RecordNode));
    if (!node) {
        printf("Error: Failed to allocate memory for record node\n");
        return;
    }
    node->key = id;
    node->offset = (head - 1)->offset + sizeof(JobPosting);
    node->next = head;
    head = node;
}

// Function to retrieve a job posting from the linked list of records
void getJobPosting(int id, JobPosting* job_posting) {
    // Check if the job posting exists in the linked list
    RecordNode* node = head;
    while (node != NULL) {
        if (node->key == id) {
            break;
        }
        node = node->next;
    }
    if (node == NULL) {
        printf("Error: Job posting with ID %d does not exist\n", id);
        return;
