    if (!filtered_job_postings) {
        printf("Error: Failed to allocate memory for filtered job postings\n");
        return;
    }

    // Iterate over the linked list and filter the job postings based on salary range and location
    RecordNode* node = head;
    while (node != NULL) {
        JobPosting* job_posting = (char*)head + node->offset;
        if ((job_posting->salary_range >= min_salary && job_posting->salary_range <= max_salary) || location == NULL) {
            memcpy(&filtered_job_postings[count], job_posting, sizeof(JobPosting));
            count++;
        }
        node = node->next;
    }

    // Free the memory allocated for the filtered job postings array
    free(filtered_job_postings);
}

// Function to delete a job posting from the linked list of records
void deleteJobPosting(int id) {
    // Check if the job posting exists in the linked list
    RecordNode* node = head;
    while (node != NULL) {
        if (node->key == id) {
            break;
        }
        node = node->next;
    }
    if (node == NULL) {
        printf("Error: Job posting with ID %d does not exist\n", id);
        return;
    }

    // Remove the job posting from the linked list of records
    RecordNode* prev_node = head;
    while (prev_node->next != node) {
        prev_node = prev_node->next;
    }
    free(prev_node->next);
    prev_node->next = NULL;
}
