// Define a record structure with an int key, long offset, and char status flag
typedef struct {
    int key;
    long offset;
    char status_flag;
} record;

// Function to dynamically allocate memory for two arrays: one for storing long offsets and another for storing int keys
record* allocate_memory(int num_records) {
    // Allocate memory for the array of records
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize each record's int value to a random number within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 100 + 1;
    }

    // Allocate memory for the array of long offsets
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        free(records);
        return NULL;
    }

    // Initialize each record's long offset value to a random number within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1000 + 1;
    }

    // Set each record's status flag based on the parity of its long offset value
    for (int i = 0; i < num_records; i++) {
        if ((offsets[i] % 2) == 0) {
            records[i].status_flag = 'E';
        } else {
            records[i].status_flag = 'O';
        }
    }

    // Free the memory allocated for the offsets array
    free(offsets);

    return records;
}

// Function to iterate over the records and update the status flag based on specific conditions
void update_status_flags(record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if ((records[i].offset % 2) == 0) {
            records[i].status_flag = 'E';
        } else {
            records[i].status_flag = 'O';
        }
    }
}

// Function to deallocate memory for the arrays of records and offsets
