typedef struct {
    int size;
    int capacity;
    JobPosting* job_postings;
    Record* records;
} HashTable;

// Initialize the hash table with a given size and capacity
void init_hash_table(HashTable* ht, int size, int capacity) {
    ht->size = 0;
    ht->capacity = capacity;
    ht->job_postings = (JobPosting*)malloc(sizeof(JobPosting) * capacity);
    ht->records = (Record*)malloc(sizeof(Record) * capacity);
}

// Add a job posting to the hash table
void add_job_posting(HashTable* ht, int id, char* title, char* description, int salary_range) {
