    // Increment the size of the hash table
    ht->size++;
}

// Add a record to the hash table
void add_record(HashTable* ht, int key, long offset) {
    // Check if the hash table is full
    if (ht->size == ht->capacity) {
        printf("Error: Hash table is full\n");
        return;
    }

    // Set the record's key and offset
    ht->records[ht->size].key = key;
    ht->records[ht->size].offset = offset;

    // Increment the size of the hash table
    ht->size++;
}

// Retrieve a job posting from the hash table based on its id
JobPosting* get_job_posting(HashTable* ht, int id) {
    for (int i = 0; i < ht->size; i++) {
        if (ht->job_postings[i].id == id) {
            return &ht->job_postings[i];
        }
    }
    return NULL;
}

// Retrieve a record from the hash table based on its key
Record* get_record(HashTable* ht, int key) {
    for (int i = 0; i < ht->size; i++) {
        if (ht->records[i].key == key) {
            return &ht->records[i];
        }
    }
    return NULL;
}

// Filter job postings based on salary range and location
void filter_job_postings(HashTable* ht, int min_salary, int max_salary, char* location) {
    // Create a new hash table to store the filtered job postings
    HashTable* filtered_ht = (HashTable*)malloc(sizeof(HashTable));
    init_hash_table(filtered_ht, 0, ht->capacity);

    // Iterate through the job postings in the original hash table
    for (int i = 0; i < ht->size; i++) {
        JobPosting* jp = &ht->job_postings[i];

        // Check if the salary range is within the specified limits
        if (jp->salary_range >= min_salary && jp->salary_range <= max_salary) {
            add_job_posting(filtered_ht, jp->id, jp->title, jp->description, jp->salary_range);
        }
    }
}

// Filter records based on key values
void filter_records(HashTable* ht, int min_key, int max_key) {
    // Create a new hash table to store the filtered records
    HashTable* filtered_ht = (HashTable*)malloc(sizeof(HashTable));
    init_hash_table(filtered_ht, 0, ht->capacity);

    // Iterate through the records in the original hash table
    for (int i = 0; i < ht->size; i++) {
        Record* r = &ht->records[i];

        // Check if the key is within the specified limits
        if (r->key >= min_key && r->key <= max_key) {
            add_record(filtered_ht, r->key, r->offset);
        }
    }
}

