char* generate_random_string(int len) {
    char* str = (char*)malloc(sizeof(char) * len);
    for (int i = 0; i < len; i++) {
        str[i] = 'a' + rand() % 26;
    }
    return str;
}

// Free the memory allocated to the hash table
void free_hash_table(HashTable* ht) {
    free(ht->job_postings);
    free(ht->records);
}
